INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「自分の意見を再考し」の「を」は、考え直す対象の「意見」を示すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、考え直される対象には付かない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や場所を示すので、直接の対象には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、対象の後には置けない。"}], "correct_answer": "を", "explanations": {"を": "「自分の意見を再考し」の「を」は、考え直す対象の「意見」を示すので正しい。", "が": "「が」は主語を示すので、考え直される対象には付かない。", "に": "「に」は相手や場所を示すので、直接の対象には合わない。", "へ": "「へ」は方向を示すので、対象の後には置けない。"}, "error_tags": {"が": "主格", "に": "相手の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「再考を指示した」の「を」は、指示の対象である「再考」を示すので正しい。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「再考で指示した」では指示の対象を表せず合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「再考から指示した」では指示の対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「再考より指示した」では指示の対象を表せず合わない。"}], "correct_answer": "を", "explanations": {"を": "「再考を指示した」の「を」は、指示の対象である「再考」を示すので正しい。", "で": "「で」は手段や場所を示すので、「再考で指示した」では指示の対象を表せず合わない。", "から": "「から」は起点を示すので、「再考から指示した」では指示の対象にならない。", "より": "「より」は比較を示すので、「再考より指示した」では指示の対象を表せず合わない。"}, "error_tags": {"で": "手段の格", "から": "起点の格", "より": "比較の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "以前に考えたことについて、改めて考え直すこと。", "primary_collocate": null, "pronunciation": "さいこう", "ipa": "saikoː", "syllable_count": 4, "sentences": [{"text": "前に出した結論を再考する時間がほしい。", "target_word": "再考", "complexity_tier": "T3", "furigana": "前[まえ]に出[だ]した結論[けつろん]を再考[さいこう]する時間[じかん]がほしい。", "sentence_source": "generated"}, {"text": "彼は自分の意見を再考し、考えを変えました。", "target_word": "再考", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]の意見[いけん]を再考[さいこう]し、考[かんが]えを変[か]えました。", "sentence_source": "generated"}, {"text": "昔の決定を再考するべきだという声が上がった。", "target_word": "再考", "complexity_tier": "T3", "furigana": "昔[むかし]の決定[けってい]を再考[さいこう]するべきだという声[こえ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "先生に言われて、以前の答えを再考した。", "target_word": "再考", "complexity_tier": "T3", "furigana": "先生[せんせい]に言[い]われて、以前[いぜん]の答[こた]えを再考[さいこう]した。", "sentence_source": "generated"}, {"text": "一度断った話だが、再考することにした。", "target_word": "再考", "complexity_tier": "T3", "furigana": "一度[いちど]断[ことわ]った話[はなし]だが、再考[さいこう]することにした。", "sentence_source": "generated"}, {"text": "過去の失敗を再考して、次に生かしたい。", "target_word": "再考", "complexity_tier": "T3", "furigana": "過去[かこ]の失敗[しっぱい]を再考[さいこう]して、次[つぎ]に生[い]かしたい。", "sentence_source": "generated"}, {"text": "新しい資料が出たので、前の判断を再考します。", "target_word": "再考", "complexity_tier": "T3", "furigana": "新[あたら]しい資料[しりょう]が出[で]たので、前[まえ]の判断[はんだん]を再考[さいこう]します。", "sentence_source": "generated"}, {"text": "社長は前の計画の再考を指示した。", "target_word": "再考", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は前[まえ]の計画[けいかく]の再考[さいこう]を指示[しじ]した。", "sentence_source": "generated"}, {"text": "再考しても、答えは変わらなかった。", "target_word": "再考", "complexity_tier": "T3", "furigana": "再考[さいこう]しても、答[こた]えは変[か]わらなかった。", "sentence_source": "generated"}, {"text": "昨日の発言を再考し、みんなに謝った。", "target_word": "再考", "complexity_tier": "T3", "furigana": "昨日[きのう]の発言[はつげん]を再考[さいこう]し、みんなに謝[あやま]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "再考する", "label": "辞書形"}, {"form": "再考した", "label": "過去形"}, {"form": "再考しても", "label": "譲歩形（〜ても）"}], "register": "neutral", "sense_fingerprint": "以前の結論や判断を改めて考え直すこと。過去の考えの見直し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30eead4-b8b9-4166-94ba-a26d8a550d93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再考", "is_correct": true, "explanation": "「前に出した結論を〜する時間」には、以前の結論を改めて考え直す意味の「再考」が入る。"}, {"text": "再会", "is_correct": false, "explanation": "人と会う意味になり、結論を考え直す文脈に合わない。"}, {"text": "再生", "is_correct": false, "explanation": "録音や映像を流す意味で、結論に対しては使わない。"}, {"text": "再来", "is_correct": false, "explanation": "また現れる意味で、結論を見直す文脈には入らない。"}], "explanations": {"再考": "「前に出した結論を〜する時間」には、以前の結論を改めて考え直す意味の「再考」が入る。", "再会": "人と会う意味になり、結論を考え直す文脈に合わない。", "再生": "録音や映像を流す意味で、結論に対しては使わない。", "再来": "また現れる意味で、結論を見直す文脈には入らない。"}, "sentence_index": 0, "correct_answer": "再考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生の説明を聞いて、初めて知った話を再考した。", "explanation": "ここは〈理解〉の意味。再考は以前の結論を改めることなので、初めて知った話には合わない。"}, {"text": "失敗した写真を再考して、もう一度撮った。", "explanation": "ここは〈撮り直す〉の意味。再考は考え直すことで、写真を撮り直す意味にはならない。"}, {"text": "久しぶりに故郷の友人と再考した。", "explanation": "ここは〈再会〉の意味。再考は考えを改めることで、人と会う意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再考", "is_correct": true, "explanation": "「前の判断を再考します」には、以前の判断を改めて考え直す意味の「再考」が入る。"}, {"text": "再訪", "is_correct": false, "explanation": "同じ場所を訪ねる意味で、判断の文脈には合わない。"}, {"text": "再録", "is_correct": false, "explanation": "書物などに記録し直す意味で、判断には使わない。"}, {"text": "再建", "is_correct": false, "explanation": "建物などを建て直す意味で、判断を見直す文脈には合わない。"}], "explanations": {"再考": "「前の判断を再考します」には、以前の判断を改めて考え直す意味の「再考」が入る。", "再訪": "同じ場所を訪ねる意味で、判断の文脈には合わない。", "再録": "書物などに記録し直す意味で、判断には使わない。", "再建": "建物などを建て直す意味で、判断を見直す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "再考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の天気を再考して、傘を持って出かけた。", "explanation": "ここは〈予測〉の意味。再考は以前の考えを改めることで、天気を予測する意味では使わない。"}, {"text": "机の上の本を再考して、棚に片付けた。", "explanation": "ここは〈片付ける〉の意味。再考は頭の中で考え直すことで、物を片付ける動作には使わない。"}, {"text": "彼は初めて聞いた計画を、じっくり再考した。", "explanation": "ここは〈熟慮〉の意味。再考は一度出した結論を見直すことなので、初めての計画には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社長は前の判断の再考に指示した。", "corrected_sentence": "社長は前の判断の再考を指示した。", "error_description": "「指示する」は対象に「を」を取るので、「再考に」は誤り。正しくは「再考を指示した」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39659, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は前の結論を再考しで、まとめ直した。", "corrected_sentence": "私は前の結論を再考して、まとめ直した。", "error_description": "「再考して」の「して」を「しで」と濁らせた誤り。正しくは「再考して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '428960e7-4a5a-41fe-b648-586a676def59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
