INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39660, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「農家の営み」の所属を示す（正解）"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「農家が営み」は文が成り立たない"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すが、「農家へ営み」は不自然"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「農家を営みは」では「営み」が名詞として主語にならず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「農家の営み」の所属を示す（正解）", "が": "主語を示すが、「農家が営み」は文が成り立たない", "へ": "方向を示すが、「農家へ営み」は不自然", "を": "「を」は目的語を示すが、「農家を営みは」では「営み」が名詞として主語にならず、文が成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39660, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "生き物がする、小さな仕事や活動のこと。", "primary_collocate": null, "pronunciation": "いとなみ", "ipa": "itonami", "syllable_count": 4, "sentences": [{"text": "アリの営みを、虫眼鏡でじっと観察した。", "target_word": "営み", "complexity_tier": "T3", "furigana": "アリの営[いとな]みを、虫眼鏡[むしめがね]でじっと観察[かんさつ]した。", "sentence_source": "generated"}, {"text": "鳥が巣を作る営みは、春の訪れを感じさせる。", "target_word": "営み", "complexity_tier": "T3", "furigana": "鳥[とり]が巣[す]を作[つく]る営[いとな]みは、春[はる]の訪[おとず]れを感[かん]じさせる。", "sentence_source": "generated"}, {"text": "森の小さな生き物たちの営みが、土を豊かにしている。", "target_word": "営み", "complexity_tier": "T3", "furigana": "森[もり]の小[ちい]さな生[い]き物[もの]たちの営[いとな]みが、土[つち]を豊[ゆた]かにしている。", "sentence_source": "generated"}, {"text": "毎日の営みを大切にしながら、静かに暮らしている。", "target_word": "営み", "complexity_tier": "T3", "furigana": "毎日[まいにち]の営[いとな]みを大切[たいせつ]にしながら、静[しず]かに暮[く]らしている。", "sentence_source": "generated"}, {"text": "蜂が花の蜜を集める営みは、朝早くから始まる。", "target_word": "営み", "complexity_tier": "T3", "furigana": "蜂[はち]が花[はな]の蜜[みつ]を集[あつ]める営[いとな]みは、朝早[あさはや]くから始[はじ]まる。", "sentence_source": "generated"}, {"text": "人間の営みが、海の生き物にも影響を与えている。", "target_word": "営み", "complexity_tier": "T3", "furigana": "人間[にんげん]の営[いとな]みが、海[うみ]の生[い]き物[もの]にも影響[えいきょう]を与[あた]えている。", "sentence_source": "generated"}, {"text": "池のカエルたちの営みは、夜になると賑やかだ。", "target_word": "営み", "complexity_tier": "T3", "furigana": "池[いけ]のカエルたちの営[いとな]みは、夜[よる]になると賑[にぎ]やかだ。", "sentence_source": "generated"}, {"text": "農家の営みは、季節とともに変わっていく。", "target_word": "営み", "complexity_tier": "T3", "furigana": "農家[のうか]の営[いとな]みは、季節[きせつ]とともに変[か]わっていく。", "sentence_source": "generated"}, {"text": "動物の営みを撮った写真集を、図書館で借りた。", "target_word": "営み", "complexity_tier": "T3", "furigana": "動物[どうぶつ]の営[いとな]みを撮[と]った写真集[しゃしんしゅう]を、図書館[としょかん]で借[か]りた。", "sentence_source": "generated"}, {"text": "長い年月の営みが、美しい珊瑚礁を作った。", "target_word": "営み", "complexity_tier": "T3", "furigana": "長[なが]い年月[ねんげつ]の営[いとな]みが、美[うつく]しい珊瑚礁[さんごしょう]を作[つく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "営み", "label": "基本形"}, {"form": "営みの", "label": "名詞＋の"}, {"form": "営みを", "label": "を格"}, {"form": "営みが", "label": "が格"}], "register": "literary-neutral", "sense_fingerprint": "生き物が日々行う活動・暮らしの働き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6541566-104a-41c9-9aa1-ddb22492a21a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39660, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "営み", "is_correct": true, "explanation": "「アリの営み」は小さな生き物の日々の活動を指し、観察の対象として自然につながる。"}, {"text": "値段", "is_correct": false, "explanation": "アリには値段がなく、観察する対象にならない。"}, {"text": "給料", "is_correct": false, "explanation": "アリは給料を受け取らないので、この文では成り立たない。"}, {"text": "誕生日", "is_correct": false, "explanation": "誕生日は観察するものではなく、文の意味が通らない。"}], "explanations": {"営み": "「アリの営み」は小さな生き物の日々の活動を指し、観察の対象として自然につながる。", "値段": "アリには値段がなく、観察する対象にならない。", "給料": "アリは給料を受け取らないので、この文では成り立たない。", "誕生日": "誕生日は観察するものではなく、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "営み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この番組の営みは、毎週日曜日の夜だ。", "explanation": "ここは〈放送〉の意味。電波で番組を流すことは放送と言い、営みは生き物の小さな活動を指すので合わない。"}, {"text": "工場のロボットは一晩中、部品を組み立てる営みを続けた。", "explanation": "ここは〈作業〉の意味。機械が行う仕事は作業と言い、営みは生き物がする活動を指すので合わない。"}, {"text": "毎年春の入学式という営みに、家族みんなで出席した。", "explanation": "ここは〈行事〉の意味。式典は行事と言い、営みは日々の小さな活動を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39660, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "営み", "is_correct": true, "explanation": "「池のカエルたちの営み」は生き物の日々の活動を指し、夜の賑やかさと自然につながる。"}, {"text": "支払い", "is_correct": false, "explanation": "カエルは支払いをしないので、この文では成り立たない。"}, {"text": "税金", "is_correct": false, "explanation": "カエルは税金を納めないので、文の意味が通らない。"}, {"text": "試験", "is_correct": false, "explanation": "カエルは試験を受けないので、この文には合わない。"}], "explanations": {"営み": "「池のカエルたちの営み」は生き物の日々の活動を指し、夜の賑やかさと自然につながる。", "支払い": "カエルは支払いをしないので、この文では成り立たない。", "税金": "カエルは税金を納めないので、文の意味が通らない。", "試験": "カエルは試験を受けないので、この文には合わない。"}, "sentence_index": 6, "correct_answer": "営み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この道路の営みは、来月まで続く予定だ。", "explanation": "ここは〈工事〉の意味。道路を直す作業は工事と言い、営みは生き物の活動を指すので合わない。"}, {"text": "壊れたラジオの営みを、父が直してくれた。", "explanation": "ここは〈修理〉の意味。機械を直すことは修理と言い、営みは生き物がする小さな活動を指すので合わない。"}, {"text": "昨日の試合の営みは、三対二で終わった。", "explanation": "ここは〈試合〉の意味。勝敗を争う催しは試合と言い、営みは日々の小さな活動を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39660, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "アリの営みに、朝から観察した。", "corrected_sentence": "アリの営みを、朝から観察した。", "error_description": "「観察する」の対象は「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39660, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "動物の営みを、夜になると活発になる。", "corrected_sentence": "動物の営みは、夜になると活発になる。", "error_description": "「活発になる」の主語は「営み」なので、主題・主語を示す「は」にする。「を」は目的語の印で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f111902-c57f-40b5-8d46-9239e1a44017') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
