INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かに、よりかかること。", "primary_collocate": null, "pronunciation": "いきょ", "ipa": "ikʲo", "syllable_count": 2, "sentences": [{"text": "この村の収入は、観光客に依拠している。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "この村[むら]の収入[しゅうにゅう]は、観光客[かんこうきゃく]に依拠[いきょ]している。", "sentence_source": "generated"}, {"text": "彼は親の援助に依拠して暮らしている。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "彼[かれ]は親[おや]の援助[えんじょ]に依拠[いきょ]して暮[く]らしている。", "sentence_source": "generated"}, {"text": "一つの会社に依拠した経営は、倒れたときの危険が大きい。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "一[ひと]つの会社[かいしゃ]に依拠[いきょ]した経営[けいえい]は、倒[たお]れたときの危険[きけん]が大[おお]きい。", "sentence_source": "generated"}, {"text": "この国は輸入に依拠しているため、値段が上がると困る。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "この国[くに]は輸入[ゆにゅう]に依拠[いきょ]しているため、値段[ねだん]が上[あ]がると困[こま]る。", "sentence_source": "generated"}, {"text": "他人に依拠せず、自分の力で生活したいと思う。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "他人[たにん]に依拠[いきょ]せず、自分[じぶん]の力[ちから]で生活[せいかつ]したいと思[おも]う。", "sentence_source": "generated"}, {"text": "町の経済が一つの工場に依拠していたので、閉鎖後は人が減った。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "町[まち]の経済[けいざい]が一[ひと]つの工場[こうじょう]に依拠[いきょ]していたので、閉鎖後[へいさご]は人[ひと]が減[へ]った。", "sentence_source": "generated"}, {"text": "弱い立場の人は、周りの助けに依拠せざるを得ない。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "弱[よわ]い立場[たちば]の人[ひと]は、周[まわ]りの助[たす]けに依拠[いきょ]せざるを得[え]ない。", "sentence_source": "generated"}, {"text": "病院の運営は寄付に依拠しており、毎年お金が足りない。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "病院[びょういん]の運営[うんえい]は寄付[きふ]に依拠[いきょ]しており、毎年[まいとし]お金[かね]が足[た]りない。", "sentence_source": "generated"}, {"text": "この計画は、自治体の補助金に依拠して進められている。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "この計画[けいかく]は、自治体[じちたい]の補助金[ほじょきん]に依拠[いきょ]して進[すす]められている。", "sentence_source": "generated"}, {"text": "この店は常連客に依拠していて、新しい客が少ない。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "この店[みせ]は常連客[じょうれんきゃく]に依拠[いきょ]していて、新[あたら]しい客[きゃく]が少[すく]ない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "依拠する", "label": "終止形"}, {"form": "依拠し", "label": "連用形"}, {"form": "依拠して", "label": "て形"}, {"form": "依拠した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "生活・収入・経営などを人や物にもたれかけて支えてもらう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依拠", "is_correct": true, "explanation": "「観光客に〜している」で、観光客をよりどころにして収入がある意味になり文脈に合う。"}, {"text": "撤回", "is_correct": false, "explanation": "「撤回」は発言や申し出を取り消す意味で、「観光客に撤回している」とは言わない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は答案などに点数をつける意味で、収入の話には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "「点火」は火をつける意味で、「観光客に点火している」は文が成り立たない。"}], "explanations": {"依拠": "「観光客に〜している」で、観光客をよりどころにして収入がある意味になり文脈に合う。", "撤回": "「撤回」は発言や申し出を取り消す意味で、「観光客に撤回している」とは言わない。", "採点": "「採点」は答案などに点数をつける意味で、収入の話には合わない。", "点火": "「点火」は火をつける意味で、「観光客に点火している」は文が成り立たない。"}, "sentence_index": 0, "correct_answer": "依拠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上司からの依拠が届いた。", "explanation": "ここは〈依頼〉の意味。仕事などを頼むことは依頼で、依拠（よりどころにすること）は届くものには使わないので合わない。"}, {"text": "その問題は三日で依拠した。", "explanation": "ここは〈解決〉の意味。問題が片づくことは解決で、依拠は何かをよりどころとして頼ることなので合わない。"}, {"text": "彼はゲームの依拠で、学校を休みがちだ。", "explanation": "ここは〈依存〉の意味。名詞の「依拠」に「の」を付けて「ゲームへの依存」の意で用いるのは不自然で、よりどころとして頼る依拠の義とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依拠", "is_correct": true, "explanation": "「周りの助けに〜せざるを得ない」で、助けをよりどころにするしかない意味になり文脈に合う。"}, {"text": "解散", "is_correct": false, "explanation": "「解散」は集まりを解く意味で、「助けに解散せざるを得ない」は成り立たない。"}, {"text": "反映", "is_correct": false, "explanation": "「反映」は映し出す・取り入れる意味で、助けを対象にした文には合わない。"}, {"text": "凝視", "is_correct": false, "explanation": "「凝視」はじっと見つめる意味で、「助けに凝視せざるを得ない」は不自然で合わない。"}], "explanations": {"依拠": "「周りの助けに〜せざるを得ない」で、助けをよりどころにするしかない意味になり文脈に合う。", "解散": "「解散」は集まりを解く意味で、「助けに解散せざるを得ない」は成り立たない。", "反映": "「反映」は映し出す・取り入れる意味で、助けを対象にした文には合わない。", "凝視": "「凝視」はじっと見つめる意味で、「助けに凝視せざるを得ない」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "依拠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "敵の攻撃への依拠は激しかった。", "explanation": "ここは〈抵抗〉の意味。攻撃を押し返すことは抵抗で、依拠は頼ることなので合わない。"}, {"text": "雨で道が滑って依拠した。", "explanation": "ここは〈転倒〉の意味。足を取られて倒れることは転倒で、依拠は何かに頼る意味なので合わない。"}, {"text": "地震のあと、古い壁が依拠して落ちてきた。", "explanation": "ここは〈崩落〉の意味。壁などが崩れて落ちることは崩落で、依拠は何かに頼る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この地域は農業を依拠して暮らしている。", "corrected_sentence": "この地域は農業に依拠して暮らしている。", "error_description": "「依拠」は「〜に依拠する」と「に」をとる。「を」は誤りで、「農業に依拠して」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39662, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社は一人の社長の判断に依拠くて、方針が変わりやすい。", "corrected_sentence": "この会社は一人の社長の判断に依拠していて、方針が変わりやすい。", "error_description": "「依拠」は名詞（サ変）なので、形容詞のように「〜くて」は付かない。「依拠していて」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
