INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39663, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "考えや行動の基盤として、あるものに頼ること。", "primary_collocate": null, "pronunciation": "いきょ", "ipa": "ikʲo", "syllable_count": 2, "sentences": [{"text": "この論文は、古い資料に依拠して書かれている。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "この論文[ろんぶん]は、古[ふる]い資料[しりょう]に依拠[いきょ]して書[か]かれている。", "sentence_source": "generated"}, {"text": "彼の判断は、自分の経験にだけ依拠している。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "彼[かれ]の判断[はんだん]は、自分[じぶん]の経験[けいけん]にだけ依拠[いきょ]している。", "sentence_source": "generated"}, {"text": "法律に依拠して、裁判所は判決を出した。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "法律[ほうりつ]に依拠[いきょ]して、裁判所[さいばんしょ]は判決[はんけつ]を出[だ]した。", "sentence_source": "generated"}, {"text": "噂に依拠した記事は、信用されにくい。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "噂[うわさ]に依拠[いきょ]した記事[きじ]は、信用[しんよう]されにくい。", "sentence_source": "generated"}, {"text": "調査結果に依拠して、新しい計画を立てた。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "調査結果[ちょうさけっか]に依拠[いきょ]して、新[あたら]しい計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "先生は、信頼できるデータに依拠して説明した。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "先生[せんせい]は、信頼[しんらい]できるデータに依拠[いきょ]して説明[せつめい]した。", "sentence_source": "generated"}, {"text": "この考え方は、昔の哲学者の説に依拠している。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "この考[かんが]え方[かた]は、昔[むかし]の哲学者[てつがくしゃ]の説[せつ]に依拠[いきょ]している。", "sentence_source": "generated"}, {"text": "事実に依拠しない意見は、議論の役に立たない。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "事実[じじつ]に依拠[いきょ]しない意見[いけん]は、議論[ぎろん]の役[やく]に立[た]たない。", "sentence_source": "generated"}, {"text": "報告書は、現場の聞き取りに依拠して作られた。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]は、現場[げんば]の聞[き]き取[と]りに依拠[いきょ]して作[つく]られた。", "sentence_source": "generated"}, {"text": "感情に依拠せず、数字で冷静に判断してほしい。", "target_word": "依拠", "complexity_tier": "T3", "furigana": "感情[かんじょう]に依拠[いきょ]せず、数字[すうじ]で冷静[れいせい]に判断[はんだん]してほしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "依拠する", "label": "終止形"}, {"form": "依拠し", "label": "連用形"}, {"form": "依拠して", "label": "て形"}, {"form": "依拠した", "label": "過去形"}], "register": "formal", "sense_fingerprint": "資料・法律・データなどを判断や主張の根拠にする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '304dfb6b-ca54-46db-b588-035b48c78535') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39663, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依拠", "is_correct": true, "explanation": "「古い資料に〜して書かれている」で、資料をよりどころにして書いた意味になり文脈に合う。"}, {"text": "解雇", "is_correct": false, "explanation": "「解雇」は雇用を終える意味で、「資料に解雇して書かれている」は成り立たない。"}, {"text": "点灯", "is_correct": false, "explanation": "「点灯」は明かりをつける意味で、論文の書き方を述べる文には合わない。"}, {"text": "採点", "is_correct": false, "explanation": "「採点」は点数をつける意味で、「資料に採点して書かれている」は不自然で合わない。"}], "explanations": {"依拠": "「古い資料に〜して書かれている」で、資料をよりどころにして書いた意味になり文脈に合う。", "解雇": "「解雇」は雇用を終える意味で、「資料に解雇して書かれている」は成り立たない。", "点灯": "「点灯」は明かりをつける意味で、論文の書き方を述べる文には合わない。", "採点": "「採点」は点数をつける意味で、「資料に採点して書かれている」は不自然で合わない。"}, "sentence_index": 0, "correct_answer": "依拠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先方への依拠を、部長が書面で伝えた。", "explanation": "ここは〈依頼〉の意味。仕事などを頼むことは依頼で、依拠（よりどころにすること）とは別の語なので合わない。"}, {"text": "雨のため、試合の依拠が決まった。", "explanation": "ここは〈延期〉の意味。日時を後ろにずらすことは延期で、依拠（よりどころにすること）は当てはまらないので合わない。"}, {"text": "失敗のあと、彼は依拠を深く悔やんだ。", "explanation": "ここは〈反省〉の意味。過去の行いを振り返って改めることは反省で、依拠は頼る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39663, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依拠", "is_correct": true, "explanation": "「昔の哲学者の説に〜している」で、その説をよりどころにしている意味になり文脈に合う。"}, {"text": "撤去", "is_correct": false, "explanation": "「撤去」は取り除く意味で、「説に撤去している」は文が成り立たない。"}, {"text": "配送", "is_correct": false, "explanation": "「配送」は荷物を届ける意味で、考え方と説の関係を述べる文には合わない。"}, {"text": "採寸", "is_correct": false, "explanation": "「採寸」は寸法を測る意味で、「説に採寸している」は不自然で合わない。"}], "explanations": {"依拠": "「昔の哲学者の説に〜している」で、その説をよりどころにしている意味になり文脈に合う。", "撤去": "「撤去」は取り除く意味で、「説に撤去している」は文が成り立たない。", "配送": "「配送」は荷物を届ける意味で、考え方と説の関係を述べる文には合わない。", "採寸": "「採寸」は寸法を測る意味で、「説に採寸している」は不自然で合わない。"}, "sentence_index": 6, "correct_answer": "依拠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "判断が依拠に流されてしまった。", "explanation": "ここは〈感情〉の意味。気持ちに引きずられることは感情で、依拠は根拠として頼る意味なので、流される対象にはならない。"}, {"text": "母は洋服の依拠に好き嫌いが多い。", "explanation": "ここは〈好み〉の意味。好き嫌いの傾向は好みで、依拠（根拠として頼ること）とは別の意味なので合わない。"}, {"text": "その発見は、依拠の重なりだった。", "explanation": "ここは〈偶然〉の意味。思いがけない重なりは偶然で、依拠は基盤として頼ることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その記事は、確かな資料で依拠している。", "corrected_sentence": "その記事は、確かな資料に依拠している。", "error_description": "「依拠」は「〜に依拠する」と「に」をとる。「で」は手段や場所を示すので誤りで、「確かな資料に依拠している」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "実験の結果に依拠しず、結論を出すのは早い。", "corrected_sentence": "実験の結果に依拠せず、結論を出すのは早い。", "error_description": "サ変「する」の未然形は「せ」。「依拠しず」は誤りで、「依拠せず」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b2f6f6-3c5e-4ed1-8120-85ed233afd5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「お気に入りの玩具を持って」の「を」は、持つものを表します。"}, {"text": "が", "is_correct": false, "explanation": "「玩具が持って」では玩具が主語になり、持つ対象を示せません。"}, {"text": "に", "is_correct": false, "explanation": "「玩具に持って」は「に」の意味が合わず、持つ対象として成り立ちません。"}, {"text": "で", "is_correct": false, "explanation": "「玩具で持って」は手段の「で」になり、持つ対象を示せません。"}], "correct_answer": "を", "explanations": {"を": "正解。「お気に入りの玩具を持って」の「を」は、持つものを表します。", "が": "「玩具が持って」では玩具が主語になり、持つ対象を示せません。", "に": "「玩具に持って」は「に」の意味が合わず、持つ対象として成り立ちません。", "で": "「玩具で持って」は手段の「で」になり、持つ対象を示せません。"}, "error_tags": {"が": "主語", "に": "着点・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「玩具を振って」の「を」は、振る対象を表します。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」になり、振る対象を示せません。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」になり、「振る」の対象として成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「玩具と振って」は並列・共同の意味になり、振る対象を示せません。"}], "correct_answer": "を", "explanations": {"を": "正解。「玩具を振って」の「を」は、振る対象を表します。", "から": "起点の「から」になり、振る対象を示せません。", "へ": "方向の「へ」になり、「振る」の対象として成り立ちません。", "と": "「玩具と振って」は並列・共同の意味になり、振る対象を示せません。"}, "error_tags": {"から": "起点", "へ": "方向", "と": "共同・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "あそぶときに使うものです。", "primary_collocate": null, "pronunciation": "がんぐ", "ipa": "ɡaŋɡɯ", "syllable_count": 3, "sentences": [{"text": "雨の日は、家の中で玩具を使って遊ぶ。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、家[いえ]の中[なか]で玩具[がんぐ]を使[つか]って遊[あそ]ぶ。", "sentence_source": "generated"}, {"text": "妹はお気に入りの玩具を持って、公園へ出かけた。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "妹[いもうと]はお気[き]に入[い]りの玩具[がんぐ]を持[も]って、公園[こうえん]へ出[で]かけた。", "sentence_source": "generated"}, {"text": "玩具の車を押して、男の子が廊下を走っている。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "玩具[がんぐ]の車[くるま]を押[お]して、男[おとこ]の子[こ]が廊下[ろうか]を走[はし]っている。", "sentence_source": "generated"}, {"text": "クリスマスに、サンタさんから玩具をもらった。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "クリスマスに、サンタさんから玩具[がんぐ]をもらった。", "sentence_source": "generated"}, {"text": "電車の玩具が好きで、毎日線路をつなげて遊んでいる。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の玩具[がんぐ]が好[す]きで、毎日[まいにち]線路[せんろ]をつなげて遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "遊び終わった玩具は、かごに入れてください。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "遊[あそ]び終[お]わった玩具[がんぐ]は、かごに入[い]れてください。", "sentence_source": "generated"}, {"text": "友達の家に行くと、たくさんの玩具が置いてあった。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "友達[ともだち]の家[いえ]に行[い]くと、たくさんの玩具[がんぐ]が置[お]いてあった。", "sentence_source": "generated"}, {"text": "赤ちゃんは音が鳴る玩具を振って、うれしそうに笑った。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは音[おと]が鳴[な]る玩具[がんぐ]を振[ふ]って、うれしそうに笑[わら]った。", "sentence_source": "generated"}, {"text": "この玩具は小さい部品があるので、三歳未満の子には渡せない。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "この玩具[がんぐ]は小[ちい]さい部品[ぶひん]があるので、三歳未満[さんさいみまん]の子[こ]には渡[わた]せない。", "sentence_source": "generated"}, {"text": "兄弟で玩具を取り合って、ケンカになってしまった。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "兄弟[きょうだい]で玩具[がんぐ]を取り合[とりあ]って、ケンカになってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "おもちゃ", "label": "基本形（かな表記）"}], "register": "標準（中立）", "sense_fingerprint": "あそぶときに手に持ったり動かしたりして使うもの（おもちゃ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩具", "is_correct": true, "explanation": "正解。「家の中で〜を使って遊ぶ」の空所には、遊びに使う品の「玩具」が入ります。"}, {"text": "肥料", "is_correct": false, "explanation": "「家の中で肥料を使って遊ぶ」は成り立ちません。肥料は植物を育てるためのもので、遊びには使いません。"}, {"text": "印鑑", "is_correct": false, "explanation": "「家の中で印鑑を使って遊ぶ」は不自然です。印鑑は書類に押す道具で、遊びには使いません。"}, {"text": "年金", "is_correct": false, "explanation": "「家の中で年金を使って遊ぶ」は意味が通りません。年金は生活保障のお金で、遊びに使うものではありません。"}], "explanations": {"玩具": "正解。「家の中で〜を使って遊ぶ」の空所には、遊びに使う品の「玩具」が入ります。", "肥料": "「家の中で肥料を使って遊ぶ」は成り立ちません。肥料は植物を育てるためのもので、遊びには使いません。", "印鑑": "「家の中で印鑑を使って遊ぶ」は不自然です。印鑑は書類に押す道具で、遊びには使いません。", "年金": "「家の中で年金を使って遊ぶ」は意味が通りません。年金は生活保障のお金で、遊びに使うものではありません。"}, "sentence_index": 0, "correct_answer": "玩具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は工具箱から玩具を出して、棚を直した。", "explanation": "ここは〈工具〉の意味。棚を直す作業に使う道具で、遊びの品である玩具とは合いません。"}, {"text": "祖父は朝早く、玩具を担いで畑へ向かった。", "explanation": "ここは〈農具〉の意味。畑仕事に使う道具で、遊ぶための玩具とは言いません。"}, {"text": "風邪をひいた弟に、玩具を薬として飲ませた。", "explanation": "ここは〈薬〉の意味。飲ませて病気を治すのは薬で、遊び道具の玩具は薬の代わりにはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": true, "explanation": "正解。「たくさんの〜が置いてあった」の空所には、置かれている品物の「玩具」が入ります。"}, {"text": "栄養", "is_correct": false, "explanation": "「たくさんの栄養が置いてあった」は不自然です。栄養は置いて並べるものではありません。"}, {"text": "感想", "is_correct": false, "explanation": "「たくさんの感想が置いてあった」は意味が通りません。感想は物として置くものではありません。"}, {"text": "約束", "is_correct": false, "explanation": "「たくさんの約束が置いてあった」は成り立ちません。約束は置くことができる物ではありません。"}], "explanations": {"玩具": "正解。「たくさんの〜が置いてあった」の空所には、置かれている品物の「玩具」が入ります。", "栄養": "「たくさんの栄養が置いてあった」は不自然です。栄養は置いて並べるものではありません。", "感想": "「たくさんの感想が置いてあった」は意味が通りません。感想は物として置くものではありません。", "約束": "「たくさんの約束が置いてあった」は成り立ちません。約束は置くことができる物ではありません。"}, "sentence_index": 6, "correct_answer": "玩具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕飯のおかずとして、玩具を温めて出した。", "explanation": "ここは〈食品〉の意味。温めて食卓に出すのは料理や食材で、遊ぶための玩具は食べ物ではありません。"}, {"text": "週末に、洗剤やタオルなどの玩具をまとめて買った。", "explanation": "ここは〈日用品〉の意味。洗剤やタオルは毎日の生活に使う品で、遊びのための玩具とは合いません。"}, {"text": "牛の飼料として、玩具を毎日まいた。", "explanation": "ここは〈飼料〉の意味。牛に与えるえさは飼料で、遊び道具の玩具は与えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹の玩具を壊れた。", "corrected_sentence": "妹の玩具が壊れた。", "error_description": "誤りは助詞「を」。「壊れる」は自動詞なので、主語には「が」を使い「玩具が壊れた」が正しく、「玩具を壊れた」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39664, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は新しい玩具を買いた。", "corrected_sentence": "兄は新しい玩具を買った。", "error_description": "誤りは動詞の活用形。「買う」の過去形は「買った」で、「買いた」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「新しい玩具を」は、後ろの「もらって」の対象を表す「を」です。"}, {"text": "が", "is_correct": false, "explanation": "「新しい玩具がもらって」では玩具が主語になり、「もらう」の対象として成り立ちません。"}, {"text": "に", "is_correct": false, "explanation": "「新しい玩具にもらって」は「に」の意味が合わず、もらう対象として不自然です。"}, {"text": "で", "is_correct": false, "explanation": "「新しい玩具でもらって」は手段の「で」になり、もらうものを示せません。"}], "correct_answer": "を", "explanations": {"を": "正解。「新しい玩具を」は、後ろの「もらって」の対象を表す「を」です。", "が": "「新しい玩具がもらって」では玩具が主語になり、「もらう」の対象として成り立ちません。", "に": "「新しい玩具にもらって」は「に」の意味が合わず、もらう対象として不自然です。", "で": "「新しい玩具でもらって」は手段の「で」になり、もらうものを示せません。"}, "error_tags": {"が": "主語", "に": "着点・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「玩具を棚に戻す」の「を」は、戻すものを表します。"}, {"text": "から", "is_correct": false, "explanation": "「玩具から棚に戻す」は起点の「から」になり、戻すものを示せません。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」になり、ここで戻すものを示す働きがありません。"}, {"text": "と", "is_correct": false, "explanation": "「玩具と棚に戻す」は並列の「と」になり、戻す対象として成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "正解。「玩具を棚に戻す」の「を」は、戻すものを表します。", "から": "「玩具から棚に戻す」は起点の「から」になり、戻すものを示せません。", "より": "比較の「より」になり、ここで戻すものを示す働きがありません。", "と": "「玩具と棚に戻す」は並列の「と」になり、戻す対象として成り立ちません。"}, "error_tags": {"から": "起点", "より": "比較", "と": "共同・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "遊びや楽しみのために使う道具や品物。", "primary_collocate": null, "pronunciation": "がんぐ", "ipa": "ɡaŋɡɯ", "syllable_count": 3, "sentences": [{"text": "ローマの子供は、木の馬のおもちゃで楽しい遊びをします。", "target_word": "おもちゃ", "complexity_tier": "T3", "furigana": "ローマの子供[こども]は、木[き]の馬[うま]のおもちゃで楽[たの]しい遊[あそ]びをします。", "sentence_source": "mined"}, {"text": "弟は新しい玩具をもらって、大喜びしている。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "弟[おとうと]は新[あたら]しい玩具[がんぐ]をもらって、大喜[おおよろこ]びしている。", "sentence_source": "generated"}, {"text": "部屋に散らかった玩具を、箱の中に片づけた。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "部屋[へや]に散[ち]らかった玩具[がんぐ]を、箱[はこ]の中[なか]に片[かた]づけた。", "sentence_source": "generated"}, {"text": "この玩具は電池で動くので、赤ちゃんには少し危ない。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "この玩具[がんぐ]は電池[でんち]で動[うご]くので、赤[あか]ちゃんには少[すこ]し危[あぶ]ない。", "sentence_source": "generated"}, {"text": "誕生日に、娘がロボットの玩具を欲しがった。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、娘[むすめ]がロボットの玩具[がんぐ]を欲[ほ]しがった。", "sentence_source": "generated"}, {"text": "犬はボールの玩具が大好きで、一日中かんでいる。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "犬[いぬ]はボールの玩具[がんぐ]が大好[だいす]きで、一日中[いちにちじゅう]かんでいる。", "sentence_source": "generated"}, {"text": "古い玩具が壊れたので、新しいものを買いに行った。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "古[ふる]い玩具[がんぐ]が壊[こわ]れたので、新[あたら]しいものを買[か]いに行[い]った。", "sentence_source": "generated"}, {"text": "子どもは遊び終わると、玩具を棚に戻す約束だ。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "子[こ]どもは遊[あそ]び終[お]わると、玩具[がんぐ]を棚[たな]に戻[もど]す約束[やくそく]だ。", "sentence_source": "generated"}, {"text": "店には布や木で作った玩具がたくさん並んでいた。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "店[みせ]には布[ぬの]や木[き]で作[つく]った玩具[がんぐ]がたくさん並[なら]んでいた。", "sentence_source": "generated"}, {"text": "兄から譲ってもらった玩具で、弟は毎日遊んでいる。", "target_word": "玩具", "complexity_tier": "T3", "furigana": "兄[あに]から譲[ゆず]ってもらった玩具[がんぐ]で、弟[おとうと]は毎日[まいにち]遊[あそ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "おもちゃ", "label": "基本形（かな表記）"}], "register": "標準（中立）", "sense_fingerprint": "子どもなどが遊びや楽しみのために使う道具や品物（おもちゃ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06651f95-2e1d-4d0e-b265-f10a42e27a57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "おもちゃ", "is_correct": true, "explanation": "正解。「木の馬の〜で楽しい遊び」に入るのは、遊びに使う品物を表す「おもちゃ」だけです。"}, {"text": "時計", "is_correct": false, "explanation": "「木の馬の時計で楽しい遊び」は意味が通りません。時計は時刻を知るための道具で、遊ぶための品物ではありません。"}, {"text": "財布", "is_correct": false, "explanation": "「木の馬の財布で楽しい遊び」は成り立ちません。財布はお金を入れる品物で、遊びの道具ではありません。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "「木の馬の歯ブラシで楽しい遊び」は不自然です。歯ブラシは歯を磨くための道具で、この文脈の遊びには入りません。"}], "explanations": {"おもちゃ": "正解。「木の馬の〜で楽しい遊び」に入るのは、遊びに使う品物を表す「おもちゃ」だけです。", "時計": "「木の馬の時計で楽しい遊び」は意味が通りません。時計は時刻を知るための道具で、遊ぶための品物ではありません。", "財布": "「木の馬の財布で楽しい遊び」は成り立ちません。財布はお金を入れる品物で、遊びの道具ではありません。", "歯ブラシ": "「木の馬の歯ブラシで楽しい遊び」は不自然です。歯ブラシは歯を磨くための道具で、この文脈の遊びには入りません。"}, "sentence_index": 0, "correct_answer": "おもちゃ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい家の柱に、玩具を使って補強した。", "explanation": "ここは〈建材〉の意味。柱を補強するのは木材や金物などの建材で、遊ぶための玩具は使いません。"}, {"text": "大工は仕事で使う玩具を全部そろえた。", "explanation": "ここは〈道具〉の意味。玩具は遊びのための品物で、仕事に使う道具の意味では使いません。"}, {"text": "寒い夜、母は炭の代わりに玩具をストーブにくべた。", "explanation": "ここは〈燃料〉の意味。ストーブにくべて燃やすのは炭や薪などの燃料で、遊ぶための玩具は燃料にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": true, "explanation": "正解。「古い〜が壊れたので、新しいものを買いに行った」の空所には、壊れる品物の「玩具」が入ります。"}, {"text": "天気", "is_correct": false, "explanation": "「古い天気が壊れた」は意味が通りません。天気は壊れる品物ではありません。"}, {"text": "季節", "is_correct": false, "explanation": "「古い季節が壊れた」は成り立ちません。季節は壊れる物ではなく、ここには入りません。"}, {"text": "返事", "is_correct": false, "explanation": "「古い返事が壊れた」は不自然です。返事は壊れるものではなく、買いに行く流れとも合いません。"}], "explanations": {"玩具": "正解。「古い〜が壊れたので、新しいものを買いに行った」の空所には、壊れる品物の「玩具」が入ります。", "天気": "「古い天気が壊れた」は意味が通りません。天気は壊れる品物ではありません。", "季節": "「古い季節が壊れた」は成り立ちません。季節は壊れる物ではなく、ここには入りません。", "返事": "「古い返事が壊れた」は不自然です。返事は壊れるものではなく、買いに行く流れとも合いません。"}, "sentence_index": 6, "correct_answer": "玩具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新学期に、ノートや鉛筆などの玩具を買いそろえた。", "explanation": "ここは〈文房具〉の意味。ノートや鉛筆は勉強に使う品で、遊ぶための玩具とは別物なので合いません。"}, {"text": "ガスの玩具を点検してもらった。", "explanation": "ここは〈器具〉の意味。ガスの器具は家庭で使う機械や装置で、遊ぶための玩具とは言いません。"}, {"text": "週末に、洗剤やタオルなどの玩具をまとめて買った。", "explanation": "ここは〈日用品〉の意味。洗剤やタオルは毎日の生活に使う品で、遊びの品である玩具とは合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は新しい玩具を遊んでいる。", "corrected_sentence": "妹は新しい玩具で遊んでいる。", "error_description": "誤りは助詞「を」。「遊ぶ」は遊びに使う品を「で」で示すので「玩具で遊ぶ」が正しく、「玩具を遊ぶ」は誤りです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39665, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は新しい玩具に欲しがった。", "corrected_sentence": "妹は新しい玩具を欲しがった。", "error_description": "誤りは助詞「に」。「欲しがる」の対象は「を」で示すので「玩具を欲しがった」が正しく、「玩具に欲しがった」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fc8f743-012a-41ea-8494-12b5e763474f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この坂道は」で話題を示し、後ろの「急なので」と説明が続くので自然。"}, {"text": "に", "is_correct": false, "explanation": "「坂道に急なので」では場所や対象のつながりが成り立たず、文が続かない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、ここは「急」という状態の説明なので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「坂道で急なので」は文として続かない。"}], "correct_answer": "は", "explanations": {"は": "「この坂道は」で話題を示し、後ろの「急なので」と説明が続くので自然。", "に": "「坂道に急なので」では場所や対象のつながりが成り立たず、文が続かない。", "を": "「を」は動作の対象を示すが、ここは「急」という状態の説明なので合わない。", "で": "「で」は場所や手段を示すが、「坂道で急なので」は文として続かない。"}, "error_tags": {"は": "主題", "に": "対象", "を": "対象", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「坂道の」で名詞を「ほう」に続け、比べる対象を示す。「坂道のほうが」は自然。"}, {"text": "が", "is_correct": false, "explanation": "「坂道がほうが」では名詞をつなげられず、比較の文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「坂道へほうが」では比べる文として続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すが、「坂道とほうが」では比較の意味にならない。"}], "correct_answer": "の", "explanations": {"の": "「坂道の」で名詞を「ほう」に続け、比べる対象を示す。「坂道のほうが」は自然。", "が": "「坂道がほうが」では名詞をつなげられず、比較の文が成り立たない。", "へ": "「へ」は方向を示すが、「坂道へほうが」では比べる文として続かない。", "と": "「と」は並列や引用を示すが、「坂道とほうが」では比較の意味にならない。"}, "error_tags": {"の": "修飾", "が": "主語", "へ": "方向", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "道で、上がったり下がったりする場所です。", "primary_collocate": null, "pronunciation": "さかみち", "ipa": "sakamitɕi", "syllable_count": 4, "sentences": [{"text": "毎朝、駅まで長い坂道を歩いて行く。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "まいあさ、えきまでながいさかみちをあるいていく。", "sentence_source": "generated"}, {"text": "この坂道は急なので、自転車を押して上る。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "このさかみちはきゅうなので、じてんしゃをおしてのぼる。", "sentence_source": "generated"}, {"text": "雨の日は坂道がすべりやすくて、とても危ない。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "あめのひはさかみちがすべりやすくて、とてもあぶない。", "sentence_source": "generated"}, {"text": "坂道の途中に小さなパン屋があり、いつも人が並んでいる。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "さかみちのとちゅうにちいさなぱんやがあり、いつもひとがならんでいる。", "sentence_source": "generated"}, {"text": "重い荷物を持っていたから、坂道で何度も休んだ。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "おもいにもつをもっていたから、さかみちでなんどもやすんだ。", "sentence_source": "generated"}, {"text": "家の前の坂道は、冬になると雪で歩きにくい。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "いえのまえのさかみちは、ふゆになるとゆきであるきにくい。", "sentence_source": "generated"}, {"text": "犬は坂道を元気に走って、先に公園へ着いた。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "いぬはさかみちをげんきにはしって、さきにこうえんへついた。", "sentence_source": "generated"}, {"text": "平らな道より坂道のほうが、歩くと足が疲れる。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "たいらなみちよりさかみちのほうが、あるくとあしがつかれる。", "sentence_source": "generated"}, {"text": "坂道を上ると、海がきれいに見える場所に出た。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "さかみちをのぼると、うみがきれいにみえるばしょにでた。", "sentence_source": "generated"}, {"text": "祖母は坂道がつらいので、バスで病院へ行く。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "そぼはさかみちがつらいので、ばすでびょういんへいく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "坂道", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "上り下りのある道。日常の生活の中で歩く、傾いた道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坂道", "is_correct": true, "explanation": "駅までの道の傾きを表す語。「長い坂道を歩いて行く」は自然な文になる。"}, {"text": "信号", "is_correct": false, "explanation": "交差点の交通標識で、歩いて行く対象にはならない。「長い信号を歩く」とは言わない。"}, {"text": "手紙", "is_correct": false, "explanation": "文書なので、道のように歩いて通ることはできない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、歩いて行く道の代わりにはならない。"}], "explanations": {"坂道": "駅までの道の傾きを表す語。「長い坂道を歩いて行く」は自然な文になる。", "信号": "交差点の交通標識で、歩いて行く対象にはならない。「長い信号を歩く」とは言わない。", "手紙": "文書なので、道のように歩いて通ることはできない。", "冷蔵庫": "家電で、歩いて行く道の代わりにはならない。"}, "sentence_index": 0, "correct_answer": "坂道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震のあと、非常用の坂道で三階から下りた。", "explanation": "ここは〈階段〉の意味。建物の段は〈階段〉で、坂道は地面の傾いた道を指すので合わない。"}, {"text": "床の坂道につまずいて、転んでしまった。", "explanation": "ここは〈段差〉の意味。床の高低差は〈段差〉で、坂道は道の傾きを指すので合わない。"}, {"text": "坂道を開けて、外の空気を入れた。", "explanation": "ここは〈窓〉や〈ドア〉の意味。坂道は開け閉めするものではないので、「開けて」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坂道", "is_correct": true, "explanation": "犬が走る道を表す語。「坂道を元気に走って」は自然な文になる。"}, {"text": "電話", "is_correct": false, "explanation": "通話に使う機器で、犬が走る対象にはならない。"}, {"text": "手袋", "is_correct": false, "explanation": "手にはめる衣類で、走る場所にはならない。"}, {"text": "鍋", "is_correct": false, "explanation": "料理に使う器で、犬が走る対象ではない。"}], "explanations": {"坂道": "犬が走る道を表す語。「坂道を元気に走って」は自然な文になる。", "電話": "通話に使う機器で、犬が走る対象にはならない。", "手袋": "手にはめる衣類で、走る場所にはならない。", "鍋": "料理に使う器で、犬が走る対象ではない。"}, "sentence_index": 6, "correct_answer": "坂道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地図を書くため、坂道で紙に線を引いた。", "explanation": "ここは〈鉛筆〉の意味。紙に線を引く道具は鉛筆で、坂道は道の傾きを指すので合わない。"}, {"text": "急な崖を、坂道につかまって登った。", "explanation": "ここは〈ロープ〉の意味。人がつかまるのはロープで、坂道は手で掴むものではないので合わない。"}, {"text": "寝る前に、坂道で歯を磨いた。", "explanation": "ここは〈歯ブラシ〉の意味。歯を磨く道具は歯ブラシで、坂道は道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "急な坂道を上ったると、息が切れた。", "corrected_sentence": "急な坂道を上ると、息が切れた。", "error_description": "「上る」の仮定形は「上ると」。「上ったる」は活用の誤りで、助詞の問題ではない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39666, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日は坂道を滑りやすいので、ゆっくり歩いた。", "corrected_sentence": "雨の日は坂道が滑りやすいので、ゆっくり歩いた。", "error_description": "「滑りやすい」は形容詞で、主語「坂道」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作り直す」の対象を示す「を」。坂道を作り直すので合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。作り直す行為の対象は坂道なので、主語にすると文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は方向や相手を示す。作り直す対象を表す位置には入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。対象を表す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "「作り直す」の対象を示す「を」。坂道を作り直すので合う。", "が": "「が」は主語を示す。作り直す行為の対象は坂道なので、主語にすると文が成り立たない。", "に": "「に」は方向や相手を示す。作り直す対象を表す位置には入らない。", "で": "「で」は手段や場所を示す。対象を表す位置には合わない。"}, "error_tags": {"を": "対象", "が": "主語", "に": "方向・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「坂道では」で場面を示し、後ろの「バスの音が大きくなる」に続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、ここは場面の設定なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「坂道のは」では場面を示す文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示す。「急な坂道とは」では場面の説明として続かない。"}], "correct_answer": "で", "explanations": {"で": "「坂道では」で場面を示し、後ろの「バスの音が大きくなる」に続く。", "を": "「を」は動作の対象を示すが、ここは場面の設定なので合わない。", "の": "「の」は名詞をつなぐ助詞で、「坂道のは」では場面を示す文として成り立たない。", "と": "「と」は並列や引用を示す。「急な坂道とは」では場面の説明として続かない。"}, "error_tags": {"で": "場所・場面", "を": "対象", "の": "修飾", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "傾斜のある道。勾配のある道路。", "primary_collocate": null, "pronunciation": "さかみち", "ipa": "sakamitɕi", "syllable_count": 4, "sentences": [{"text": "この坂道は傾きが大きく、車でも上るのが大変だ。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "このさかみちはかたむきがおおきく、くるまでものぼるのがたいへんだ。", "sentence_source": "generated"}, {"text": "工事で、坂道をゆるやかに作り直すことになった。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "こうじで、さかみちをゆるやかにつくりなおすことになった。", "sentence_source": "generated"}, {"text": "雪が降ると、坂道では車が止まって動けなくなる。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "ゆきがふると、さかみちではくるまがとまってうごけなくなる。", "sentence_source": "generated"}, {"text": "坂道に手すりがあるので、お年寄りも安心して歩ける。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "さかみちにてすりがあるので、おとしよりもあんしんしてあるける。", "sentence_source": "generated"}, {"text": "坂道を自転車で走るときは、ブレーキをよく確かめる。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "さかみちをじてんしゃではしるときは、ぶれーきをよくたしかめる。", "sentence_source": "generated"}, {"text": "町の中心から港まで、ずっと続く坂道がある。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "まちのちゅうしんからみなとまで、ずっとつづくさかみちがある。", "sentence_source": "generated"}, {"text": "この町は坂道が多く、荷物を運ぶ人は苦労している。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "このまちはさかみちがおおく、にもつをはこぶひとはくろうしている。", "sentence_source": "generated"}, {"text": "急な坂道では、バスのエンジンの音が大きくなる。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "きゅうなさかみちでは、ばすのえんじんのおとがおおきくなる。", "sentence_source": "generated"}, {"text": "車いすの人のために、坂道の角度を小さくした。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "くるまいすのひとのために、さかみちのかくどをちいさくした。", "sentence_source": "generated"}, {"text": "坂道の脇に水が流れる溝があるので、大雨でも道がぬれにくい。", "target_word": "坂道", "complexity_tier": "T3", "furigana": "さかみちのわきにみずがながれるみぞがあるので、おおあめでもみちがぬれにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "坂道", "label": "基本形"}], "register": "普通体", "sense_fingerprint": "傾きや勾配のある道路。道の作りや角度に注目した言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "坂道", "is_correct": true, "explanation": "傾きのある道路を指す。傾きが大きく車でも上るのが大変、という文に合う。"}, {"text": "電話", "is_correct": false, "explanation": "通話機器で、傾きという性質を持たないので「この電話は傾きが大きく」と言えない。"}, {"text": "窓", "is_correct": false, "explanation": "建物の開口部で、車が上る対象にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "家電で、傾いた道として車が上ることはない。"}], "explanations": {"坂道": "傾きのある道路を指す。傾きが大きく車でも上るのが大変、という文に合う。", "電話": "通話機器で、傾きという性質を持たないので「この電話は傾きが大きく」と言えない。", "窓": "建物の開口部で、車が上る対象にはならない。", "冷蔵庫": "家電で、傾いた道として車が上ることはない。"}, "sentence_index": 0, "correct_answer": "坂道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カレーを作るため、坂道をかき混ぜた。", "explanation": "ここは〈お玉〉の意味。鍋をかき混ぜる道具はお玉で、坂道は混ぜられないので合わない。"}, {"text": "シャツの坂道を一つ留めた。", "explanation": "ここは〈ボタン〉の意味。シャツを留める部品はボタンで、坂道は留める物ではないので合わない。"}, {"text": "坂道を右に回して締めた。", "explanation": "ここは〈ネジ〉の意味。回して締める部品はネジで、坂道は回して締めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "坂道", "is_correct": true, "explanation": "傾きのある道路を指す。坂が多いと荷物運びが大変だという文に合う。"}, {"text": "冗談", "is_correct": false, "explanation": "話の中の軽い言葉で、荷物を運ぶ苦労とは結びつかない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "口を磨く道具で、この町の特徴としては文が成り立たない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "書くための道具で、荷物運びの苦労とは関係がない。"}], "explanations": {"坂道": "傾きのある道路を指す。坂が多いと荷物運びが大変だという文に合う。", "冗談": "話の中の軽い言葉で、荷物を運ぶ苦労とは結びつかない。", "歯ブラシ": "口を磨く道具で、この町の特徴としては文が成り立たない。", "鉛筆": "書くための道具で、荷物運びの苦労とは関係がない。"}, "sentence_index": 6, "correct_answer": "坂道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "停電のとき、坂道に火をともして本を読んだ。", "explanation": "ここは〈ろうそく〉の意味。火をともす道具はろうそくで、坂道は火を灯すものではないので合わない。"}, {"text": "喉が渇いたので、坂道に水を注いで飲んだ。", "explanation": "ここは〈コップ〉の意味。水を注ぐ容器はコップで、坂道は水を入れる器ではないので合わない。"}, {"text": "自転車で、坂道を左に切って角を曲がった。", "explanation": "ここは〈ハンドル〉の意味。左に切って向きを変える操作はハンドルで、坂道は操作する物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の坂道を凍って、車がすべった。", "corrected_sentence": "朝の坂道が凍って、車がすべった。", "error_description": "「凍る」は主語に「が」をとる動詞。坂道が凍るなので「が」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39667, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坂道をゆっくり上らったので、息が切れなかった。", "corrected_sentence": "坂道をゆっくり上ったので、息が切れなかった。", "error_description": "「上る」の過去形は「上った」。「上らった」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
