INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39668, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものが、地面の上をくるくる回りながら動くこと。", "primary_collocate": null, "pronunciation": "ころがる", "ipa": "koɾoɡaɾɯ", "syllable_count": 4, "sentences": [{"text": "ボールが道路に転がっていきました。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "ボールが道路[どうろ]に転[ころ]がっていきました。", "sentence_source": "generated"}, {"text": "石が坂の下まで転がった。", "target_word": "転がった", "complexity_tier": "T3", "furigana": "石[いし]が坂[さか]の下[した]まで転[ころ]がった。", "sentence_source": "generated"}, {"text": "机から落ちたペンが床を転がっていった。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "机[つくえ]から落[お]ちたペンが床[ゆか]を転[ころ]がっていった。", "sentence_source": "generated"}, {"text": "缶がころころと転がる音が聞こえた。", "target_word": "転がる", "complexity_tier": "T3", "furigana": "缶[かん]がころころと転[ころ]がる音[おと]が聞[き]こえた。", "sentence_source": "generated"}, {"text": "風でごみ箱が倒れ、中身が外に転がりました。", "target_word": "転がりました", "complexity_tier": "T3", "furigana": "風[かぜ]でごみ箱[ばこ]が倒[たお]れ、中身[なかみ]が外[そと]に転[ころ]がりました。", "sentence_source": "generated"}, {"text": "りんごが袋から出て、地面を転がった。", "target_word": "転がった", "complexity_tier": "T3", "furigana": "りんごが袋[ふくろ]から出[で]て、地面[じめん]を転[ころ]がった。", "sentence_source": "generated"}, {"text": "丸い物は、平らな所でもすぐ転がります。", "target_word": "転がります", "complexity_tier": "T3", "furigana": "丸[まる]い物[もの]は、平[たい]らな所[ところ]でもすぐ転[ころ]がります。", "sentence_source": "generated"}, {"text": "坂道で、大きな岩が転がってきて、おどろきました。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "坂道[さかみち]で、大[おお]きな岩[いわ]が転[ころ]がってきて、おどろきました。", "sentence_source": "generated"}, {"text": "子どもが投げたボールは、草の上を転がって止まりました。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "子[こ]どもが投[な]げたボールは、草[くさ]の上[うえ]を転[ころ]がって止[と]まりました。", "sentence_source": "generated"}, {"text": "コインが転がって、机の下に入ってしまった。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "コインが転[ころ]がって、机[つくえ]の下[した]に入[はい]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転がります", "label": "丁寧形"}, {"form": "転がった", "label": "過去形"}, {"form": "転がらない", "label": "否定形"}, {"form": "転がって", "label": "て形"}, {"form": "転がれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "丸い物が地面をくるくる回って動く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39668, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転がって", "is_correct": true, "explanation": "ボールが地面をくるくる回りながら進む動きなので、ここに入ります。"}, {"text": "眠って", "is_correct": false, "explanation": "眠るは動かずに休む動作で、ボールが道路を移動する文には合いません。"}, {"text": "笑って", "is_correct": false, "explanation": "笑うは表情や声を出す動作で、ボールの移動には合いません。"}, {"text": "焼いて", "is_correct": false, "explanation": "焼くは熱で加工する動作で、ボールが移動する意味にはならないので合いません。"}], "explanations": {"転がって": "ボールが地面をくるくる回りながら進む動きなので、ここに入ります。", "眠って": "眠るは動かずに休む動作で、ボールが道路を移動する文には合いません。", "笑って": "笑うは表情や声を出す動作で、ボールの移動には合いません。", "焼いて": "焼くは熱で加工する動作で、ボールが移動する意味にはならないので合いません。"}, "sentence_index": 0, "correct_answer": "転がって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コーヒーが机の上を転がって、床にこぼれた。", "explanation": "ここは〈流れる〉の意味です。液体がこぼれて広がる動きで、回転しながら進む〈転がる〉とは違うので合いません。"}, {"text": "雲が地面を転がって、山へ消えた。", "explanation": "ここは〈漂う〉の意味です。雲が空中をゆっくり動く様子を指し、地面を回りながら進む〈転がる〉とは違うので合いません。"}, {"text": "川の水が転がっていきます。", "explanation": "ここは〈流れる〉の意味です。水が途切れず流れていく動きで、丸く回りながら進む〈転がる〉とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39668, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転がります", "is_correct": true, "explanation": "丸い物が平らな所でも回りながら動く意味になるので、ここに入ります。"}, {"text": "叫びます", "is_correct": false, "explanation": "叫ぶは声を大きく出す動作で、丸い物の動きを表さないので合いません。"}, {"text": "冷やします", "is_correct": false, "explanation": "冷やすは温度を下げる動作で、場所の移動を表さないので合いません。"}, {"text": "数えます", "is_correct": false, "explanation": "数えるは数を確かめる動作で、丸い物がすぐ動く意味にはならないので合いません。"}], "explanations": {"転がります": "丸い物が平らな所でも回りながら動く意味になるので、ここに入ります。", "叫びます": "叫ぶは声を大きく出す動作で、丸い物の動きを表さないので合いません。", "冷やします": "冷やすは温度を下げる動作で、場所の移動を表さないので合いません。", "数えます": "数えるは数を確かめる動作で、丸い物がすぐ動く意味にはならないので合いません。"}, "sentence_index": 6, "correct_answer": "転がります"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥が空を転がっていった。", "explanation": "ここは〈飛ぶ〉の意味です。鳥が翼で空を移動する動きで、物が回りながら地面を進む〈転がる〉とは違うので合いません。"}, {"text": "魚が川を転がっていった。", "explanation": "ここは〈泳ぐ〉の意味です。魚が体を動かして水中を進む動きで、回転して移動する〈転がる〉とは違うので合いません。"}, {"text": "猫が塀の上を転がっていった。", "explanation": "ここは〈歩く〉の意味です。猫が足で塀の上を進む動きで、回りながら動く〈転がる〉とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39668, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールが公園の坂を転がりていった。", "corrected_sentence": "ボールが公園の坂を転がっていった。", "error_description": "「転がりていった」は誤りです。「転がる」のて形は「転がって」なので、正しくは「転がっていった」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "転がった", "is_correct": true, "explanation": "過去形で、石がすでに坂の下まで転がったことを表すので、ここに入ります。"}, {"text": "転がって", "is_correct": false, "explanation": "て形のため文を言い切れず、「石が坂の下まで」で文が終わらないので合いません。"}, {"text": "転がらない", "is_correct": false, "explanation": "否定形で、転がらなかったという逆の意味になり、石が下まで来た事実と合いません。"}, {"text": "転がれば", "is_correct": false, "explanation": "仮定形で「転がるなら」の意味になり、実際に起きた出来事を述べる文には合いません。"}], "correct_form": "転がった", "base_form": "転がる", "form_label": "過去形", "sentence_index": 1, "explanations": {"転がった": "過去形で、石がすでに坂の下まで転がったことを表すので、ここに入ります。", "転がって": "て形のため文を言い切れず、「石が坂の下まで」で文が終わらないので合いません。", "転がらない": "否定形で、転がらなかったという逆の意味になり、石が下まで来た事実と合いません。", "転がれば": "仮定形で「転がるなら」の意味になり、実際に起きた出来事を述べる文には合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39668, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ボールが芝生の上を転がして止まりました。", "corrected_sentence": "ボールが芝生の上を転がって止まりました。", "error_description": "「転がして」は誤りです。「転がす」は他の物を動かす他動詞で、ボールが自分で動く場合は自動詞の「転がる」を使うので、正しくは「転がって」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "転がって", "is_correct": true, "explanation": "て形で、後ろの「きて」「おどろきました」へつながり、転がってくる様子を表すので、ここに入ります。"}, {"text": "転がった", "is_correct": false, "explanation": "過去形は文を言い切るため、後ろの「きて」とつながらないので合いません。"}, {"text": "転がろう", "is_correct": false, "explanation": "意向形で「転がろう」という誘いや決意の意味になり、出来事の描写には合いません。"}, {"text": "転がれ", "is_correct": false, "explanation": "命令形で、転がれと命じる意味になるので、ここには合いません。"}], "correct_form": "転がって", "base_form": "転がる", "form_label": "て形", "sentence_index": 7, "explanations": {"転がって": "て形で、後ろの「きて」「おどろきました」へつながり、転がってくる様子を表すので、ここに入ります。", "転がった": "過去形は文を言い切るため、後ろの「きて」とつながらないので合いません。", "転がろう": "意向形で「転がろう」という誘いや決意の意味になり、出来事の描写には合いません。", "転がれ": "命令形で、転がれと命じる意味になるので、ここには合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
