INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39669, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が回転しながら、ある場所から別の場所へ移動する。", "primary_collocate": null, "pronunciation": "ころがる", "ipa": "koɾoɡaɾɯ", "syllable_count": 4, "sentences": [{"text": "樽が坂を転がって、川に落ちました。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "樽[たる]が坂[さか]を転[ころ]がって、川[かわ]に落[お]ちました。", "sentence_source": "generated"}, {"text": "ころんだ拍子に、りんごがかごから転がって出た。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "ころんだ拍子[ひょうし]に、りんごがかごから転[ころ]がって出[で]た。", "sentence_source": "generated"}, {"text": "ボールがゴールまで転がっていった。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "ボールがゴールまで転[ころ]がっていった。", "sentence_source": "generated"}, {"text": "雪玉は転がるたびに大きくなります。", "target_word": "転がる", "complexity_tier": "T3", "furigana": "雪玉[ゆきだま]は転[ころ]がるたびに大[おお]きくなります。", "sentence_source": "generated"}, {"text": "丸太が山の上から転がって落ちた。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "丸太[まるた]が山[やま]の上[うえ]から転[ころ]がって落[お]ちた。", "sentence_source": "generated"}, {"text": "ビー玉が机の端まで転がった。", "target_word": "転がった", "complexity_tier": "T3", "furigana": "ビー玉[だま]が机[つくえ]の端[はし]まで転[ころ]がった。", "sentence_source": "generated"}, {"text": "風で空き缶が道の向こうへ転がっていった。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "風[かぜ]で空[あ]き缶[かん]が道[みち]の向[む]こうへ転[ころ]がっていった。", "sentence_source": "generated"}, {"text": "玉は、床の上を転がってかべに当たった。", "target_word": "転がって", "complexity_tier": "T3", "furigana": "玉[たま]は、床[ゆか]の上[うえ]を転[ころ]がってかべに当[あ]たった。", "sentence_source": "generated"}, {"text": "重い石は、押しても少ししか転がらない。", "target_word": "転がらない", "complexity_tier": "T3", "furigana": "重[おも]い石[いし]は、押[お]しても少[すこ]ししか転[ころ]がらない。", "sentence_source": "generated"}, {"text": "転がった卵は、台所の隅で止まった。", "target_word": "転がった", "complexity_tier": "T3", "furigana": "転[ころ]がった卵[たまご]は、台所[だいどころ]の隅[すみ]で止[と]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転がります", "label": "丁寧形"}, {"form": "転がった", "label": "過去形"}, {"form": "転がらない", "label": "否定形"}, {"form": "転がって", "label": "て形"}, {"form": "転がれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "物が回転しながら別の場所へ移る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39669, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転がって", "is_correct": true, "explanation": "樽が坂を回りながら移動して川に落ちたという流れに合うので、ここに入ります。"}, {"text": "眠って", "is_correct": false, "explanation": "眠るは動かずに休む動作で、樽が坂を移動する文には合いません。"}, {"text": "笑って", "is_correct": false, "explanation": "笑うは表情や声を出す動作で、樽の移動を表さないので合いません。"}, {"text": "叫んで", "is_correct": false, "explanation": "叫ぶは声を大きく出す動作で、樽が坂を移動する意味にはならないので合いません。"}], "explanations": {"転がって": "樽が坂を回りながら移動して川に落ちたという流れに合うので、ここに入ります。", "眠って": "眠るは動かずに休む動作で、樽が坂を移動する文には合いません。", "笑って": "笑うは表情や声を出す動作で、樽の移動を表さないので合いません。", "叫んで": "叫ぶは声を大きく出す動作で、樽が坂を移動する意味にはならないので合いません。"}, "sentence_index": 0, "correct_answer": "転がって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空気が部屋を転がっていった。", "explanation": "ここは〈流れる〉の意味です。空気が流れていく動きで、回転しながら進む〈転がる〉とは違うので合いません。"}, {"text": "雨水が道を転がっていった。", "explanation": "ここは〈流れる〉の意味です。水が途切れず流れていく動きで、回転しながら進む〈転がる〉の定義には合いません。"}, {"text": "家族の仲が、テーブルの上を転がっていった。", "explanation": "ここは〈移動する〉の意味です。人の関係は場所を移る動きではないうえ、物が回転して進む〈転がる〉とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39669, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転がって", "is_correct": true, "explanation": "風で缶が回りながら道の向こうへ移動した意味になるので、ここに入ります。"}, {"text": "焼いて", "is_correct": false, "explanation": "焼くは熱で加工する動作で、缶が道を移動する意味にはならないので合いません。"}, {"text": "凍って", "is_correct": false, "explanation": "凍るは温度で固まる変化で、移動を表さないので合いません。"}, {"text": "冷やして", "is_correct": false, "explanation": "冷やすは温度を下げる動作で、缶の移動を表さないので合いません。"}], "explanations": {"転がって": "風で缶が回りながら道の向こうへ移動した意味になるので、ここに入ります。", "焼いて": "焼くは熱で加工する動作で、缶が道を移動する意味にはならないので合いません。", "凍って": "凍るは温度で固まる変化で、移動を表さないので合いません。", "冷やして": "冷やすは温度を下げる動作で、缶の移動を表さないので合いません。"}, "sentence_index": 6, "correct_answer": "転がって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鳥が空を転がっていった。", "explanation": "ここは〈飛ぶ〉の意味です。鳥が翼で空を移動する動きで、物が回りながら地面を進む〈転がる〉とは違うので合いません。"}, {"text": "魚が川を転がっていった。", "explanation": "ここは〈泳ぐ〉の意味です。魚が体を動かして水中を進む動きで、回転して移動する〈転がる〉とは違うので合いません。"}, {"text": "猫が塀の上を転がっていった。", "explanation": "ここは〈歩く〉の意味です。猫が足で塀の上を進む動きで、回りながら動く〈転がる〉とは違うので合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39669, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ボールが道が転がって、溝に落ちました。", "corrected_sentence": "ボールが道を転がって、溝に落ちました。", "error_description": "「道が転がって」は誤りです。転がる経路は「道を」で示すので、正しくは「道を転がって」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "転がって", "is_correct": true, "explanation": "て形で、後ろの「出た」へつながり、りんごが転がって外へ出た様子を表すので、ここに入ります。"}, {"text": "転がります", "is_correct": false, "explanation": "丁寧形で文を言い切るため、後ろの「出た」とつながらず、ここには合いません。"}, {"text": "転がらない", "is_correct": false, "explanation": "否定形で、転がらなかったという意味になり、りんごが出た事実と逆になります。"}, {"text": "転がれば", "is_correct": false, "explanation": "仮定形で「転がるなら」の意味になり、前後の出来事とつながらないので合いません。"}], "correct_form": "転がって", "base_form": "転がる", "form_label": "て形", "sentence_index": 1, "explanations": {"転がって": "て形で、後ろの「出た」へつながり、りんごが転がって外へ出た様子を表すので、ここに入ります。", "転がります": "丁寧形で文を言い切るため、後ろの「出た」とつながらず、ここには合いません。", "転がらない": "否定形で、転がらなかったという意味になり、りんごが出た事実と逆になります。", "転がれば": "仮定形で「転がるなら」の意味になり、前後の出来事とつながらないので合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39669, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "玉が床の上を転がったて、棚に当たった。", "corrected_sentence": "玉が床の上を転がって、棚に当たった。", "error_description": "「転がったて」は誤りです。て形は「転がって」なので、正しくは「転がって、棚に当たった」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "転がって", "is_correct": true, "explanation": "て形で、後ろの「かべに当たった」へつながり、床の上を転がってぶつかった流れを表すので、ここに入ります。"}, {"text": "転がった", "is_correct": false, "explanation": "過去形は文を言い切るため、後ろの「かべに当たった」とつながらないので合いません。"}, {"text": "転がろう", "is_correct": false, "explanation": "意向形で「転がろう」という意味になり、玉が実際に動いた出来事には合いません。"}, {"text": "転がれ", "is_correct": false, "explanation": "命令形で、玉に転がれと命じる意味になり、描写文には合いません。"}], "correct_form": "転がって", "base_form": "転がる", "form_label": "て形", "sentence_index": 7, "explanations": {"転がって": "て形で、後ろの「かべに当たった」へつながり、床の上を転がってぶつかった流れを表すので、ここに入ります。", "転がった": "過去形は文を言い切るため、後ろの「かべに当たった」とつながらないので合いません。", "転がろう": "意向形で「転がろう」という意味になり、玉が実際に動いた出来事には合いません。", "転がれ": "命令形で、玉に転がれと命じる意味になり、描写文には合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「山を下った」の「を」は通る経路を示す。山を通って下ったので合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語。「山が下った」では人が移動する文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「山で下った」では経路が示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「山と下った」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「山を下った」の「を」は通る経路を示す。山を通って下ったので合う。", "が": "「が」は主語。「山が下った」では人が移動する文として不自然。", "で": "「で」は場所や手段を示すが、「山で下った」では経路が示せない。", "と": "「と」は相手や並列を示すが、「山と下った」では文が成り立たない。"}, "error_tags": {"を": "経路", "が": "主語", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上る", "is_correct": true, "explanation": "「下る」の対義語。高い方へ向かう移動で、下る動きの反対になる。"}, {"text": "歩く", "is_correct": false, "explanation": "移動はするが上下の方向を示さないので、対義語ではない。"}, {"text": "走る", "is_correct": false, "explanation": "速さを示す移動で、方向の反対語にはならない。"}, {"text": "眠る", "is_correct": false, "explanation": "動きを伴わないので、対義語にならない。"}], "correct_answer": "上る", "explanations": {"上る": "「下る」の対義語。高い方へ向かう移動で、下る動きの反対になる。", "歩く": "移動はするが上下の方向を示さないので、対義語ではない。", "走る": "速さを示す移動で、方向の反対語にはならない。", "眠る": "動きを伴わないので、対義語にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「下るの」で動作を名詞化し、「下ることがつらい」という意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「下るにがつらい」では名詞化されず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「下るへがつらい」では文として続かない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「下るからがつらい」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「下るの」で動作を名詞化し、「下ることがつらい」という意味になる。", "に": "「下るにがつらい」では名詞化されず、文が成り立たない。", "へ": "「へ」は方向を示すが、「下るへがつらい」では文として続かない。", "から": "「から」は起点を示すが、「下るからがつらい」では意味が通らない。"}, "error_tags": {"の": "名詞化", "に": "対象", "へ": "方向", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上る", "is_correct": true, "explanation": "「下る」の対義語。高い方へ向かう動きで、下れば（下る）の反対になる。"}, {"text": "進む", "is_correct": false, "explanation": "前へ動く意味で、上下の方向を示さないので対義語ではない。"}, {"text": "休む", "is_correct": false, "explanation": "活動を止める意味で、移動の方向とは関係しないので対義語ではない。"}, {"text": "沈む", "is_correct": false, "explanation": "下へ動く意味を持つ語で、下るの反対ではないので対義語ではない。"}], "correct_answer": "上る", "explanations": {"上る": "「下る」の対義語。高い方へ向かう動きで、下れば（下る）の反対になる。", "進む": "前へ動く意味で、上下の方向を示さないので対義語ではない。", "休む": "活動を止める意味で、移動の方向とは関係しないので対義語ではない。", "沈む": "下へ動く意味を持つ語で、下るの反対ではないので対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "高いところから低いところへ動くこと。", "primary_collocate": null, "pronunciation": "くだる", "ipa": "kudaɾɯ", "syllable_count": 3, "sentences": [{"text": "山の頂上から、細い道をゆっくり下る。", "target_word": "下る", "complexity_tier": "T3", "furigana": "やまのちょうじょうから、ほそいみちをゆっくりくだる。", "sentence_source": "generated"}, {"text": "日が暮れる前に、急いで山を下った。", "target_word": "下った", "complexity_tier": "T3", "furigana": "ひがくれるまえに、いそいでやまをくだった。", "sentence_source": "generated"}, {"text": "疲れていたので、坂を下る足が重かった。", "target_word": "下る", "complexity_tier": "T3", "furigana": "つかれていたので、さかをくだるあしがおもかった。", "sentence_source": "generated"}, {"text": "登山者たちは、霧の中を一列になって下っていた。", "target_word": "下って", "complexity_tier": "T3", "furigana": "とざんしゃたちは、きりのなかをいちれつになってくだっていた。", "sentence_source": "generated"}, {"text": "谷へ下ると、きれいな川が流れていた。", "target_word": "下る", "complexity_tier": "T3", "furigana": "たにへくだると、きれいなかわがながれていた。", "sentence_source": "generated"}, {"text": "頂上で昼ご飯を食べてから、反対側の道を下ることにした。", "target_word": "下る", "complexity_tier": "T3", "furigana": "ちょうじょうでひるごはんをたべてから、はんたいがわのみちをくだることにした。", "sentence_source": "generated"}, {"text": "雨が降りだしたので、友達は急いで坂を下るように言った。", "target_word": "下る", "complexity_tier": "T3", "furigana": "あめがふりだしたので、ともだちはいそいでさかをくだるようにいった。", "sentence_source": "generated"}, {"text": "膝が痛くて、長い坂を下るのがつらい。", "target_word": "下る", "complexity_tier": "T3", "furigana": "ひざがいたくて、ながいさかをくだるのがつらい。", "sentence_source": "generated"}, {"text": "子どもたちは丘を元気に下って、川へ走っていった。", "target_word": "下って", "complexity_tier": "T3", "furigana": "こどもたちはおかをげんきにくだって、かわへはしっていった。", "sentence_source": "generated"}, {"text": "地図を見ながら、山道を下れば駅に着く。", "target_word": "下れば", "complexity_tier": "T3", "furigana": "ちずをみながら、やまみちをくだればえきにつく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下る", "label": "基本形"}, {"form": "下らない", "label": "否定形"}, {"form": "下ります", "label": "丁寧形"}, {"form": "下って", "label": "て形"}, {"form": "下った", "label": "過去形"}, {"form": "下れば", "label": "仮定形"}, {"form": "下ろう", "label": "意向形"}], "register": "普通体", "sense_fingerprint": "人が山や坂など高い所から低い所へ進んで行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下る", "is_correct": true, "explanation": "高い所から低い所へ移動する動詞で、山の道を下りる文に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "食事の動詞で、細い道を移動する文には合わない。"}, {"text": "包む", "is_correct": false, "explanation": "物を包む動作で、道を進む文には合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "寝る動作で、道をゆっくり移動する文には合わない。"}], "explanations": {"下る": "高い所から低い所へ移動する動詞で、山の道を下りる文に合う。", "食べる": "食事の動詞で、細い道を移動する文には合わない。", "包む": "物を包む動作で、道を進む文には合わない。", "眠る": "寝る動作で、道をゆっくり移動する文には合わない。"}, "sentence_index": 0, "correct_answer": "下る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車を下って、ホームに出た。", "explanation": "ここは〈降りる〉の意味。乗り物から出る動作は〈降りる〉で、下るは高い所から低い所へ進むことに使う。"}, {"text": "気温が一気に下って、雪が降り出した。", "explanation": "ここは〈下がる〉の意味。気温や数値が減るのは〈下がる〉で、下るは人や物の移動に使う。"}, {"text": "高い棚から荷物を下って、床へ置いた。", "explanation": "ここは〈降ろす〉の意味。荷物を移す他動詞は〈降ろす〉で、下るは自動詞なので「荷物を下る」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下る", "is_correct": true, "explanation": "坂を移動する動詞で、急いで坂を下るように言う文に合う。"}, {"text": "焼く", "is_correct": false, "explanation": "熱を加える動作で、坂を対象にはできない。"}, {"text": "編む", "is_correct": false, "explanation": "糸を組む動作で、坂には使わない。"}, {"text": "乾かす", "is_correct": false, "explanation": "水気を取る動作で、坂を対象にはできない。"}], "explanations": {"下る": "坂を移動する動詞で、急いで坂を下るように言う文に合う。", "焼く": "熱を加える動作で、坂を対象にはできない。", "編む": "糸を組む動作で、坂には使わない。", "乾かす": "水気を取る動作で、坂を対象にはできない。"}, "sentence_index": 6, "correct_answer": "下る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "重い箱を棚から下って、床へ置いた。", "explanation": "ここは〈降ろす〉の意味。物を移す他動詞は〈降ろす〉で、下るは自動詞なので「箱を下る」とは言えない。"}, {"text": "雨が静かに下っている。", "explanation": "ここは〈降る〉の意味。雨は空から落ちてくるので〈降る〉を使い、下るは地上を移動する動きに使う。"}, {"text": "体重が一気に下って、すっかりやせた。", "explanation": "ここは〈減る〉か〈下がる〉の意味。重さが少なくなるのは〈減る〉で、下るは移動を表す語なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨で滑りやすいので、ゆっくり坂で下った。", "corrected_sentence": "雨で滑りやすいので、ゆっくり坂を下った。", "error_description": "「下る」は道を通る動作なので、経路を示す「を」が必要。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下った", "is_correct": true, "explanation": "過去形で、「急いで山を下った」と過去の出来事を述べる文に合う。"}, {"text": "下り", "is_correct": false, "explanation": "連用形なので文末に置けず、「山を下り。」は文として成り立たない。"}, {"text": "下って", "is_correct": false, "explanation": "て形で、文末には置けず「下った」の代わりにならない。"}, {"text": "下ります", "is_correct": false, "explanation": "丁寧形で、普通体の文に入れると文体が合わない。"}], "correct_form": "下った", "base_form": "下る", "form_label": "過去形", "sentence_index": 1, "explanations": {"下った": "過去形で、「急いで山を下った」と過去の出来事を述べる文に合う。", "下り": "連用形なので文末に置けず、「山を下り。」は文として成り立たない。", "下って": "て形で、文末には置けず「下った」の代わりにならない。", "下ります": "丁寧形で、普通体の文に入れると文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39670, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨が上がったので、山道を下いて町へ戻った。", "corrected_sentence": "雨が上がったので、山道を下って町へ戻った。", "error_description": "「下る」のて形は「下って」。「下いて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下る", "is_correct": true, "explanation": "基本形で、「坂を下ること」を名詞化して「〜のがつらい」に続く。"}, {"text": "下れ", "is_correct": false, "explanation": "命令形で、「坂を下れのがつらい」とは続かない。"}, {"text": "下ろう", "is_correct": false, "explanation": "意向形で、「〜ろうのがつらい」とは続かない。"}, {"text": "下れば", "is_correct": false, "explanation": "仮定形で、「下ればのがつらい」とは続けられない。"}], "correct_form": "下る", "base_form": "下る", "form_label": "基本形", "sentence_index": 7, "explanations": {"下る": "基本形で、「坂を下ること」を名詞化して「〜のがつらい」に続く。", "下れ": "命令形で、「坂を下れのがつらい」とは続かない。", "下ろう": "意向形で、「〜ろうのがつらい」とは続かない。", "下れば": "仮定形で、「下ればのがつらい」とは続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「川を下っていく」の「を」は通る経路を示す。いかだが川を通って進むので合う。"}, {"text": "か", "is_correct": false, "explanation": "「か」は選択を示すが、「川か下っていく」では文が続かない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、「川の下っていく」では動詞に続かない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すが、「川と下っていく」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「川を下っていく」の「を」は通る経路を示す。いかだが川を通って進むので合う。", "か": "「か」は選択を示すが、「川か下っていく」では文が続かない。", "の": "「の」は名詞をつなぐ助詞で、「川の下っていく」では動詞に続かない。", "と": "「と」は相手や並列を示すが、「川と下っていく」では文が成り立たない。"}, "error_tags": {"を": "経路", "が": "主語", "の": "修飾", "と": "相手・並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上る", "is_correct": true, "explanation": "「下る」の対義語。低い方から高い方へ向かう動きで、下って来た動きの反対になる。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移す動作で、上下の方向を示さないので対義語ではない。"}, {"text": "止まる", "is_correct": false, "explanation": "動きをやめる意味で、方向の反対語ではないので対義語ではない。"}, {"text": "積む", "is_correct": false, "explanation": "物を載せる動作で、移動の方向とは関係がないので対義語ではない。"}], "correct_answer": "上る", "explanations": {"上る": "「下る」の対義語。低い方から高い方へ向かう動きで、下って来た動きの反対になる。", "運ぶ": "物を移す動作で、上下の方向を示さないので対義語ではない。", "止まる": "動きをやめる意味で、方向の反対語ではないので対義語ではない。", "積む": "物を載せる動作で、移動の方向とは関係がないので対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「低い方へ」の「へ」は向かう方向を示す。低い方へ下りていく動きに合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、方向を表す位置には入らない。"}, {"text": "より", "is_correct": false, "explanation": "「低い方より下り」では比較の意味になり、雨水の動きとして成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「低い方から下り」では起点の意味になり、下りていく向きと合わない。"}], "correct_answer": "へ", "explanations": {"へ": "「低い方へ」の「へ」は向かう方向を示す。低い方へ下りていく動きに合う。", "で": "「で」は場所や手段を示すが、方向を表す位置には入らない。", "より": "「低い方より下り」では比較の意味になり、雨水の動きとして成り立たない。", "から": "「低い方から下り」では起点の意味になり、下りていく向きと合わない。"}, "error_tags": {"へ": "方向", "で": "場所・手段", "より": "比較", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上る", "is_correct": true, "explanation": "「下る」の対義語。低い方から高い方へ向かう動きで、下っていく動きの反対になる。"}, {"text": "運ぶ", "is_correct": false, "explanation": "物を移す動作で、上下の方向を示さないので対義語ではない。"}, {"text": "休む", "is_correct": false, "explanation": "活動を止める意味で、移動の方向とは関係しないので対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "動きを伴わないので、対義語にならない。"}], "correct_answer": "上る", "explanations": {"上る": "「下る」の対義語。低い方から高い方へ向かう動きで、下っていく動きの反対になる。", "運ぶ": "物を移す動作で、上下の方向を示さないので対義語ではない。", "休む": "活動を止める意味で、移動の方向とは関係しないので対義語ではない。", "眠る": "動きを伴わないので、対義語にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が高い位置から低い位置へ移動する。", "primary_collocate": null, "pronunciation": "くだる", "ipa": "kudaɾɯ", "syllable_count": 3, "sentences": [{"text": "船は川を下って、夕方に海の近くの町へ着いた。", "target_word": "下って", "complexity_tier": "T3", "furigana": "ふねはかわをくだって、ゆうがたにうみのちかくのまちへついた。", "sentence_source": "generated"}, {"text": "いかだは流れに乗って、ゆっくり川を下っていく。", "target_word": "下って", "complexity_tier": "T3", "furigana": "いかだはながれにのって、ゆっくりかわをくだっていく。", "sentence_source": "generated"}, {"text": "山の雪どけ水は、谷を下って川に集まる。", "target_word": "下って", "complexity_tier": "T3", "furigana": "やまのゆきどけみずは、たにをくだってかわにあつまる。", "sentence_source": "generated"}, {"text": "荷物を積んだトラックが、山道を下ってきた。", "target_word": "下って", "complexity_tier": "T3", "furigana": "にもつをつんだとらっくが、やまみちをくだってきた。", "sentence_source": "generated"}, {"text": "木の葉が小川を下って、池に流れこんだ。", "target_word": "下って", "complexity_tier": "T3", "furigana": "このはがおがわをくだって、いけにながれこんだ。", "sentence_source": "generated"}, {"text": "観光客を乗せた舟が、ゆるやかな川を下る。", "target_word": "下る", "complexity_tier": "T3", "furigana": "かんこうきゃくをのせたふねが、ゆるやかなかわをくだる。", "sentence_source": "generated"}, {"text": "岩が斜面を下って、道の前で止まった。", "target_word": "下って", "complexity_tier": "T3", "furigana": "いわがしゃめんをくだって、みちのまえでとまった。", "sentence_source": "generated"}, {"text": "雨水は低い方へ下り、やがて池になった。", "target_word": "下り", "complexity_tier": "T3", "furigana": "あまみずはひくいほうへくだり、やがていけになった。", "sentence_source": "generated"}, {"text": "この川を下る船は、朝と夕方に出ている。", "target_word": "下る", "complexity_tier": "T3", "furigana": "このかわをくだるふねは、あさとゆうがたにでている。", "sentence_source": "generated"}, {"text": "電車は山の駅から、ゆっくり海のほうへ下っていく。", "target_word": "下って", "complexity_tier": "T3", "furigana": "でんしゃはやまのえきから、ゆっくりうみのほうへくだっていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下る", "label": "基本形"}, {"form": "下らない", "label": "否定形"}, {"form": "下ります", "label": "丁寧形"}, {"form": "下って", "label": "て形"}, {"form": "下った", "label": "過去形"}, {"form": "下れば", "label": "仮定形"}, {"form": "下ろう", "label": "意向形"}], "register": "普通体", "sense_fingerprint": "船・水・乗り物などの物が川や斜面を低い方へ進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下って", "is_correct": true, "explanation": "川の流れに沿って低い方へ進む動詞で、船が川を移動する文に合う。"}, {"text": "磨いて", "is_correct": false, "explanation": "表面をこする動作で、船が川を進む文には合わない。"}, {"text": "包んで", "is_correct": false, "explanation": "包装の動作で、川を移動する意味にはならない。"}, {"text": "焼いて", "is_correct": false, "explanation": "熱を加える動作で、船の移動とは結びつかない。"}], "explanations": {"下って": "川の流れに沿って低い方へ進む動詞で、船が川を移動する文に合う。", "磨いて": "表面をこする動作で、船が川を進む文には合わない。", "包んで": "包装の動作で、川を移動する意味にはならない。", "焼いて": "熱を加える動作で、船の移動とは結びつかない。"}, "sentence_index": 0, "correct_answer": "下って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "足が氷で下って、転んでしまった。", "explanation": "ここは〈滑る〉の意味。足が表面を滑る動きは〈滑る〉で、下るは物が高い所から低い所へ移ることに使う。"}, {"text": "値段が一気に下って、客が増えた。", "explanation": "ここは〈下がる〉の意味。値段や数値が減るのは〈下がる〉で、下るは物の移動に使うので合わない。"}, {"text": "荷物を棚から下って、床へ置いた。", "explanation": "ここは〈降ろす〉の意味。荷物を移す他動詞は〈降ろす〉で、下るは自動詞なので「荷物を下る」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下って", "is_correct": true, "explanation": "斜面を低い方へ移動する動詞で、岩が斜面を転がり落ちてくる文に合う。"}, {"text": "煮て", "is_correct": false, "explanation": "加熱する動作で、岩が斜面を移動する文には合わない。"}, {"text": "数えて", "is_correct": false, "explanation": "数を数える動作で、移動の文には合わない。"}, {"text": "編んで", "is_correct": false, "explanation": "糸を組む動作で、岩の移動には合わない。"}], "explanations": {"下って": "斜面を低い方へ移動する動詞で、岩が斜面を転がり落ちてくる文に合う。", "煮て": "加熱する動作で、岩が斜面を移動する文には合わない。", "数えて": "数を数える動作で、移動の文には合わない。", "編んで": "糸を組む動作で、岩の移動には合わない。"}, "sentence_index": 6, "correct_answer": "下って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本棚が地震で下って、本が散らばった。", "explanation": "ここは〈倒れる〉の意味。立っているものが横に倒れるのは〈倒れる〉で、下るは高い所から低い所へ移ることに使う。"}, {"text": "貯金が一気に下って、家計が苦しくなった。", "explanation": "ここは〈減る〉の意味。金額や量が少なくなるのは〈減る〉で、下るは移動を表すので合わない。"}, {"text": "木箱を棚から下って、床へ置いた。", "explanation": "ここは〈降ろす〉の意味。物を移す他動詞は〈降ろす〉で、下るは自動詞なので「箱を下る」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "荷を積んだ舟が、川で下っていく。", "corrected_sentence": "荷を積んだ舟が、川を下っていく。", "error_description": "「下る」は通る経路を示すので「を」が必要。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下って", "is_correct": true, "explanation": "て形で、「下っていく」と続けて動きの進行を表す。"}, {"text": "下る", "is_correct": false, "explanation": "基本形なので、「下るていく」とは続けられず文が成り立たない。"}, {"text": "下れば", "is_correct": false, "explanation": "仮定形で条件を表す。「下ればいく」では進行の意味にならない。"}, {"text": "下らない", "is_correct": false, "explanation": "否定形なので、「下らないでいく」では動きの意味が反対になる。"}], "correct_form": "下って", "base_form": "下る", "form_label": "て形", "sentence_index": 1, "explanations": {"下って": "て形で、「下っていく」と続けて動きの進行を表す。", "下る": "基本形なので、「下るていく」とは続けられず文が成り立たない。", "下れば": "仮定形で条件を表す。「下ればいく」では進行の意味にならない。", "下らない": "否定形なので、「下らないでいく」では動きの意味が反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39671, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "丸い石が谷を下いて、川に落ちた。", "corrected_sentence": "丸い石が谷を下って、川に落ちた。", "error_description": "「下る」のて形は「下って」。「下いて」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下り", "is_correct": true, "explanation": "連用形で、「低い方へ下り、池になった」と動作を続けて述べる形に合う。"}, {"text": "下ろう", "is_correct": false, "explanation": "意向形で、「下ろう、池になった」では文として続かない。"}, {"text": "下ります", "is_correct": false, "explanation": "丁寧形で、普通体の文に入れると文体が合わない。"}, {"text": "下れ", "is_correct": false, "explanation": "命令形で、「下れ、池になった」では文の意味が合わない。"}], "correct_form": "下り", "base_form": "下る", "form_label": "連用形", "sentence_index": 7, "explanations": {"下り": "連用形で、「低い方へ下り、池になった」と動作を続けて述べる形に合う。", "下ろう": "意向形で、「下ろう、池になった」では文として続かない。", "下ります": "丁寧形で、普通体の文に入れると文体が合わない。", "下れ": "命令形で、「下れ、池になった」では文の意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「はしごを下りる」の目的語を示す。下りる動作の対象（移動する場所）を表す。"}, {"text": "が", "is_correct": false, "explanation": "「はしごが」だと、はしごが主語になり、人が下りる文脈に合わない。"}, {"text": "に", "is_correct": false, "explanation": "「はしごに」は到達点を示し、はしごを降りていく文脈と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「はしごと」は並列や同伴を表し、降りる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「はしごを下りる」の目的語を示す。下りる動作の対象（移動する場所）を表す。", "が": "「はしごが」だと、はしごが主語になり、人が下りる文脈に合わない。", "に": "「はしごに」は到達点を示し、はしごを降りていく文脈と合わない。", "と": "「はしごと」は並列や同伴を表し、降りる対象を示せない。"}, "error_tags": {"が": "主語", "に": "到達点", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上る", "is_correct": true, "explanation": "「下りる」の対義語。高い所へ体を移して登る動きを表し、この意味で対になる。"}, {"text": "残る", "is_correct": false, "explanation": "その場にとどまる意味で、上下の移動の対義語にはならない。"}, {"text": "届く", "is_correct": false, "explanation": "目的の場所に到達する意味で、下りるの対義語にはならない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "列を作って横に並ぶ意味で、上下の動きを表さない。"}], "correct_answer": "上る", "explanations": {"上る": "「下りる」の対義語。高い所へ体を移して登る動きを表し、この意味で対になる。", "残る": "その場にとどまる意味で、上下の移動の対義語にはならない。", "届く": "目的の場所に到達する意味で、下りるの対義語にはならない。", "並ぶ": "列を作って横に並ぶ意味で、上下の動きを表さない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「改札へ下りていった」と移動の方向を示す。下りる動作の向かう先を表す。"}, {"text": "を", "is_correct": false, "explanation": "「改札を下りていった」は改札を通る意味になり、下りる方向を示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「改札の」は名詞同士をつなぐ助詞で、下りる方向を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や、文章語で起点を表す。「改札より」は下りる先の方向を示せず、ここでは合わない。"}], "correct_answer": "へ", "explanations": {"へ": "「改札へ下りていった」と移動の方向を示す。下りる動作の向かう先を表す。", "を": "「改札を下りていった」は改札を通る意味になり、下りる方向を示せず不自然。", "の": "「改札の」は名詞同士をつなぐ助詞で、下りる方向を示せない。", "より": "「より」は比較や、文章語で起点を表す。「改札より」は下りる先の方向を示せず、ここでは合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較・起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上る", "is_correct": true, "explanation": "「下りる」の対義語。下の場所から上へ移動する動きを表し、この意味で対になる。"}, {"text": "眠る", "is_correct": false, "explanation": "横になって休む意味で、上下の移動の対義語にはならない。"}, {"text": "数える", "is_correct": false, "explanation": "数を数える意味で、移動の対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物を場所に据える意味で、移動の対義語にはならない。"}], "correct_answer": "上る", "explanations": {"上る": "「下りる」の対義語。下の場所から上へ移動する動きを表し、この意味で対になる。", "眠る": "横になって休む意味で、上下の移動の対義語にはならない。", "数える": "数を数える意味で、移動の対義語ではない。", "置く": "物を場所に据える意味で、移動の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "高いところから低いところへ、体を動かしながら行くことです。", "primary_collocate": null, "pronunciation": "おりる", "ipa": "oɾiɾɯ", "syllable_count": 3, "sentences": [{"text": "朝、二階から階段を下りて、台所へ行った。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "あさ、にかいからかいだんをおりて、だいどころへいった。", "sentence_source": "generated"}, {"text": "はしごをゆっくり下りるとき、足元をよく見た。", "target_word": "下りる", "complexity_tier": "T3", "furigana": "はしごをゆっくりおりるとき、あしもとをよくみた。", "sentence_source": "generated"}, {"text": "猫が高い木から下りられなくて、鳴いていた。", "target_word": "下りられなくて", "complexity_tier": "T3", "furigana": "ねこがたかいきからおりられなくて、ないていた。", "sentence_source": "generated"}, {"text": "ロープをつかんで、一人ずつ崖を下りた。", "target_word": "下りた", "complexity_tier": "T3", "furigana": "ろーぷをつかんで、ひとりずつがけをおりた。", "sentence_source": "generated"}, {"text": "駅のホームへ下りる階段は、とても長い。", "target_word": "下りる", "complexity_tier": "T3", "furigana": "えきのほーむへおりるかいだんは、とてもながい。", "sentence_source": "generated"}, {"text": "山を下りた後で、温泉に入って休んだ。", "target_word": "下りた", "complexity_tier": "T3", "furigana": "やまをおりたあとで、おんせんにはいってやすんだ。", "sentence_source": "generated"}, {"text": "子どもは滑り台の上から、すぐに下りてきた。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "こどもはすべりだいのうえから、すぐにおりてきた。", "sentence_source": "generated"}, {"text": "疲れた足で、地下の改札へ下りていった。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "つかれたあしで、ちかのかいさつへおりていった。", "sentence_source": "generated"}, {"text": "屋根に上った父が、無事に下りてほっとした。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "やねにのぼったちちが、ぶじにおりてほっとした。", "sentence_source": "generated"}, {"text": "暗い地下室へ下りると、ひんやりした空気を感じた。", "target_word": "下りる", "complexity_tier": "T3", "furigana": "くらいちかしつへおりると、ひんやりしたくうきをかんじた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下りる", "label": "基本形"}, {"form": "下りない", "label": "否定形"}, {"form": "下ります", "label": "丁寧形"}, {"form": "下りて", "label": "て形"}, {"form": "下りた", "label": "過去形"}, {"form": "下りれば", "label": "仮定形"}, {"form": "下りよう", "label": "意向形"}], "register": "普通体", "sense_fingerprint": "人や動物が階段・はしご・木など高い所から体を動かして低い所へ行く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下りて", "is_correct": true, "explanation": "て形。「階段を下りて、台所へ行った」と動作を続けて述べる形で、この空欄に入る。"}, {"text": "下りない", "is_correct": false, "explanation": "否定形。「階段を下りない、台所へ行った」は動作の順序が成り立たず、文が接続しない。"}, {"text": "下りよう", "is_correct": false, "explanation": "意向形。「下りよう、台所へ行った」と接続できず、朝の行動の流れに合わない。"}, {"text": "下ります", "is_correct": false, "explanation": "丁寧形は読点で続けられず、普通体の文脈にも合わない。"}], "explanations": {"下りて": "て形。「階段を下りて、台所へ行った」と動作を続けて述べる形で、この空欄に入る。", "下りない": "否定形。「階段を下りない、台所へ行った」は動作の順序が成り立たず、文が接続しない。", "下りよう": "意向形。「下りよう、台所へ行った」と接続できず、朝の行動の流れに合わない。", "下ります": "丁寧形は読点で続けられず、普通体の文脈にも合わない。"}, "sentence_index": 0, "correct_answer": "下りて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い朝、池の水面に氷が下りた。", "explanation": "ここは〈張る〉の意味。水面に氷が広がる時は〈張る〉を使い、下りるは人や乗り物が高い所から低い所へ移る時に使うので合わない。"}, {"text": "寒い夜は、室内の気温が下りる。", "explanation": "ここは〈下がる〉の意味。温度や数値が低くなる時は〈下がる〉を使い、下りるは人や物が移動する時に使うので合わない。"}, {"text": "夕方から雨が下りてきた。", "explanation": "ここは〈降る〉の意味。雨や雪は〈降る〉を使い、下りるは移動する人や物に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下りて", "is_correct": true, "explanation": "て形。「すぐに下りてきた」と、降りてくる動作を続けて述べる形で、この空欄に入る。"}, {"text": "下りた", "is_correct": false, "explanation": "過去形は「下りたきた」と続かず、て形でなければ動詞の連結が成り立たない。"}, {"text": "下りれば", "is_correct": false, "explanation": "仮定形は「下りればきた」と続かず、文が成り立たない。"}, {"text": "下りられる", "is_correct": false, "explanation": "可能形は「下りられるきた」と接続せず、文として不自然。"}], "explanations": {"下りて": "て形。「すぐに下りてきた」と、降りてくる動作を続けて述べる形で、この空欄に入る。", "下りた": "過去形は「下りたきた」と続かず、て形でなければ動詞の連結が成り立たない。", "下りれば": "仮定形は「下りればきた」と続かず、文が成り立たない。", "下りられる": "可能形は「下りられるきた」と接続せず、文として不自然。"}, "sentence_index": 6, "correct_answer": "下りて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "速達の手紙が、今朝ようやく下りた。", "explanation": "ここは〈届く〉の意味。物が目的地に着く時は〈届く〉を使い、〈下りる〉は人や乗り物が高い所から低い所へ移る意味なので合わない。"}, {"text": "ボールが棚から下りた。", "explanation": "ここは〈落ちる〉の意味。物が意図せず低い方へ移る時は〈落ちる〉を使い、下りるは人が体を動かして移る時に使うので合わない。"}, {"text": "屋根の雨どいから、水がぽたぽた下りた。", "explanation": "ここは〈滴る〉の意味。水が垂れ落ちる時は〈滴る〉を使い、〈下りる〉は人や乗り物が移動する時に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、友人の家の階段が下りて、居間に入った。", "corrected_sentence": "夕方、友人の家の階段を下りて、居間に入った。", "error_description": "「階段が下りて」は階段が主語になり不自然。「下りる」は人が移動する動詞なので、移動する場所は「を」で示す。誤りは「が」で、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下りる", "is_correct": true, "explanation": "基本形。「はしごをゆっくり下りるとき」と連体修飾の「とき」に続く形で、この空欄に入る。"}, {"text": "下りよう", "is_correct": false, "explanation": "意向形は「とき」に続かず、「下りようとき」は成り立たない。"}, {"text": "下りて", "is_correct": false, "explanation": "て形は「とき」に続けられず、「下りてとき」は文法的に成り立たない。"}, {"text": "下ります", "is_correct": false, "explanation": "丁寧形は普通体の文脈で「とき」の前に置けず、語形が合わない。"}], "correct_form": "下りる", "base_form": "下りる", "form_label": "基本形", "sentence_index": 1, "explanations": {"下りる": "基本形。「はしごをゆっくり下りるとき」と連体修飾の「とき」に続く形で、この空欄に入る。", "下りよう": "意向形は「とき」に続かず、「下りようとき」は成り立たない。", "下りて": "て形は「とき」に続けられず、「下りてとき」は文法的に成り立たない。", "下ります": "丁寧形は普通体の文脈で「とき」の前に置けず、語形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39672, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "登山の帰りに、山小屋の急な坂道を下りる、宿に戻った。", "corrected_sentence": "登山の帰りに、山小屋の急な坂道を下りて、宿に戻った。", "error_description": "「下りる、」と辞書形のまま読点で続けるのは不自然。次の動作へ続けるには「下りて」（て形）が必要。誤りは辞書形で、正しくはて形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下りて", "is_correct": true, "explanation": "て形。「改札へ下りていった」と移動を続けて述べる形で、この空欄に入る。"}, {"text": "下りなかった", "is_correct": false, "explanation": "過去否定形は「改札へ下りなかったいった」と続かず、語形が合わない。"}, {"text": "下りさせる", "is_correct": false, "explanation": "使役形は「下りさせていった」となり、主語の動作として成り立たない。"}, {"text": "下りている", "is_correct": false, "explanation": "ている形は「下りているいった」となり、「いった」と続かない。"}], "correct_form": "下りて", "base_form": "下りる", "form_label": "て形", "sentence_index": 7, "explanations": {"下りて": "て形。「改札へ下りていった」と移動を続けて述べる形で、この空欄に入る。", "下りなかった": "過去否定形は「改札へ下りなかったいった」と続かず、語形が合わない。", "下りさせる": "使役形は「下りさせていった」となり、主語の動作として成り立たない。", "下りている": "ている形は「下りているいった」となり、「いった」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「シャッターが（主語）下りて」と、シャッターを動く主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「シャッターを下りて」は目的語にできず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "「シャッターに下りて」は到達点を示し、シャッターの動きとして合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「シャッターへ下りて」は方向を示すが、シャッターの動きには合わない。"}], "correct_answer": "が", "explanations": {"が": "「シャッターが（主語）下りて」と、シャッターを動く主語として示す。", "を": "「シャッターを下りて」は目的語にできず、不自然。", "に": "「シャッターに下りて」は到達点を示し、シャッターの動きとして合わない。", "へ": "「シャッターへ下りて」は方向を示すが、シャッターの動きには合わない。"}, "error_tags": {"を": "目的語", "に": "到達点", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上がる", "is_correct": true, "explanation": "「下りる」の対義語。幕や遮断機などが上へ戻る意味で対になる。"}, {"text": "残る", "is_correct": false, "explanation": "その場にとどまる意味で、上下の動きの対義語にはならない。"}, {"text": "届く", "is_correct": false, "explanation": "目的の場所に到達する意味で、下りるの対義語にはならない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "列を作って横に並ぶ意味で、上下の動きを表さない。"}], "correct_answer": "上がる", "explanations": {"上がる": "「下りる」の対義語。幕や遮断機などが上へ戻る意味で対になる。", "残る": "その場にとどまる意味で、上下の動きの対義語にはならない。", "届く": "目的の場所に到達する意味で、下りるの対義語にはならない。", "並ぶ": "列を作って横に並ぶ意味で、上下の動きを表さない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「下りると」の条件を示す「と」。カーテンが下りた時に拍手が起きる関係を表す。"}, {"text": "で", "is_correct": false, "explanation": "「下りるで、」は手段の意味になり、条件の文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「下りるの、」は名詞化する形で、続く主節の文型と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「下りるより、」は比較の意味になり、条件の関係として成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「下りると」の条件を示す「と」。カーテンが下りた時に拍手が起きる関係を表す。", "で": "「下りるで、」は手段の意味になり、条件の文脈に合わない。", "の": "「下りるの、」は名詞化する形で、続く主節の文型と合わない。", "より": "「下りるより、」は比較の意味になり、条件の関係として成り立たない。"}, "error_tags": {"で": "手段・場所", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上がる", "is_correct": true, "explanation": "「下りる」の対義語。ゴンドラが上へ戻る動きを表し、この意味で対になる。"}, {"text": "眠る", "is_correct": false, "explanation": "横になって休む意味で、上下の移動の対義語にはならない。"}, {"text": "数える", "is_correct": false, "explanation": "数を数える意味で、移動の対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物を場所に据える意味で、移動の対義語にはならない。"}], "correct_answer": "上がる", "explanations": {"上がる": "「下りる」の対義語。ゴンドラが上へ戻る動きを表し、この意味で対になる。", "眠る": "横になって休む意味で、上下の移動の対義語にはならない。", "数える": "数を数える意味で、移動の対義語ではない。", "置く": "物を場所に据える意味で、移動の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある物が、場所を高い方から低い方へと移動することを言います。", "primary_collocate": null, "pronunciation": "おりる", "ipa": "oɾiɾɯ", "syllable_count": 3, "sentences": [{"text": "電車が来るので、踏切の遮断機が下りた。", "target_word": "下りた", "complexity_tier": "T3", "furigana": "でんしゃがくるので、ふみきりのしゃだんきがおりた。", "sentence_source": "generated"}, {"text": "店のシャッターが下りて、中が見えなくなった。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "みせのしゃったーがおりて、なかがみえなくなった。", "sentence_source": "generated"}, {"text": "劇が終わり、ゆっくり幕が下りた。", "target_word": "下りた", "complexity_tier": "T3", "furigana": "げきがおわり、ゆっくりまくがおりた。", "sentence_source": "generated"}, {"text": "夜になると、窓のブラインドが自動で下りる。", "target_word": "下りる", "complexity_tier": "T3", "furigana": "よるになると、まどのぶらいんどがじどうでおりる。", "sentence_source": "generated"}, {"text": "駐車場の出口で、バーが下りて車が止まった。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "ちゅうしゃじょうのでぐちで、ばーがおりてくるまがとまった。", "sentence_source": "generated"}, {"text": "エレベーターは、五階から一階まで下りてきた。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "えれべーたーは、ごかいからいっかいまでおりてきた。", "sentence_source": "generated"}, {"text": "荷物を入れたかごが、ひもでゆっくり下りていった。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "にもつをいれたかごが、ひもでゆっくりおりていった。", "sentence_source": "generated"}, {"text": "舞台のカーテンが下りると、客席から拍手が起きた。", "target_word": "下りる", "complexity_tier": "T3", "furigana": "ぶたいのかーてんがおりると、きゃくせきからはくしゅがおきた。", "sentence_source": "generated"}, {"text": "非常口のシャッターが下りてきて、廊下が行き止まりになった。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "ひじょうぐちのしゃったーがおりてきて、ろうかがいきどまりになった。", "sentence_source": "generated"}, {"text": "ゴンドラが山のふもとの駅へ、静かに下りてきた。", "target_word": "下りて", "complexity_tier": "T3", "furigana": "ごんどらがやまのふもとのえきへ、しずかにおりてきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下りる", "label": "基本形"}, {"form": "下りない", "label": "否定形"}, {"form": "下ります", "label": "丁寧形"}, {"form": "下りて", "label": "て形"}, {"form": "下りた", "label": "過去形"}, {"form": "下りれば", "label": "仮定形"}, {"form": "下りよう", "label": "意向形"}], "register": "普通体", "sense_fingerprint": "遮断機・シャッター・幕などの物が上から下へ動いて来る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下りた", "is_correct": true, "explanation": "過去形。「踏切の遮断機が下りた」と、遮断機が下がった結果を述べる。"}, {"text": "下りれば", "is_correct": false, "explanation": "仮定形は文を結べず、「遮断機が下りれば。」で文が完結しない。"}, {"text": "下りよう", "is_correct": false, "explanation": "意向形は意志を持つ主語が必要で、遮断機には当てはまらない。"}, {"text": "下りさせる", "is_correct": false, "explanation": "使役形は人が主語の場合に自然で、遮断機が使役される文は成り立たない。"}], "explanations": {"下りた": "過去形。「踏切の遮断機が下りた」と、遮断機が下がった結果を述べる。", "下りれば": "仮定形は文を結べず、「遮断機が下りれば。」で文が完結しない。", "下りよう": "意向形は意志を持つ主語が必要で、遮断機には当てはまらない。", "下りさせる": "使役形は人が主語の場合に自然で、遮断機が使役される文は成り立たない。"}, "sentence_index": 0, "correct_answer": "下りた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花火が夜空に下りた。", "explanation": "ここは〈上がる〉の意味。打ち上げ花火が空へ上がる時は〈上がる〉を使い、下りるは高い所から低い所へ移る時に使うので合わない。"}, {"text": "夜になると、気温が下りる。", "explanation": "ここは〈下がる〉の意味。温度や数値が低くなる時は〈下がる〉を使い、下りるは物が上から低い方へ動く時に使うので合わない。"}, {"text": "汗が額から下りた。", "explanation": "ここは〈滴る〉の意味。液体が垂れ落ちる時は〈滴る〉を使い、下りるは物が上から下へ動く時に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下りて", "is_correct": true, "explanation": "て形。「ひもでゆっくり下りていった」と、移動の経過を続けて述べる形で、この空欄に入る。"}, {"text": "下りない", "is_correct": false, "explanation": "否定形は「下りないいった」と続かず、移動の経過を表せない。"}, {"text": "下ります", "is_correct": false, "explanation": "丁寧形は「下りますいった」と続かず、文として成り立たない。"}, {"text": "下りられる", "is_correct": false, "explanation": "可能形は「下りられるいった」となり、接続しない。"}], "explanations": {"下りて": "て形。「ひもでゆっくり下りていった」と、移動の経過を続けて述べる形で、この空欄に入る。", "下りない": "否定形は「下りないいった」と続かず、移動の経過を表せない。", "下ります": "丁寧形は「下りますいった」と続かず、文として成り立たない。", "下りられる": "可能形は「下りられるいった」となり、接続しない。"}, "sentence_index": 6, "correct_answer": "下りて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試験の結果が掲示板に下りた。", "explanation": "ここは〈出る〉の意味。結果や発表が出される時は〈出る〉を使い、〈下りる〉は人や乗り物が高い所から低い所へ移る時に使うので合わない。"}, {"text": "手紙が郵便受けに下りた。", "explanation": "ここは〈届く〉の意味。物が目的地に到達する時は〈届く〉を使い、〈下りる〉は高い所から低い所へ動く意味なので合わない。"}, {"text": "強風で大木が根元から下りた。", "explanation": "ここは〈倒れる〉の意味。木が根元から傾いて横になる時は〈倒れる〉を使い、〈下りる〉は人や乗り物が移動する時に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "閉店時間になると、店の入り口のシャッターをゆっくり下りる。", "corrected_sentence": "閉店時間になると、店の入り口のシャッターがゆっくり下りる。", "error_description": "「シャッター」は自分で下がる物で、動きの主語になるので「が」で示す。「を」は通る道や動作の対象を示すため、ここでは合わない。誤りは「を」で、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "下りて", "is_correct": true, "explanation": "て形。「店のシャッターが下りて、中が見えなくなった」と続く形で、この空欄に入る。"}, {"text": "下りよう", "is_correct": false, "explanation": "意向形は文を続けられず、「下りよう、中が」では成り立たない。"}, {"text": "下りる", "is_correct": false, "explanation": "基本形を読点で続けると不自然で、文の流れが成り立たない。"}, {"text": "下ります", "is_correct": false, "explanation": "丁寧形は普通体の文中で読点に続けられず、語形が合わない。"}], "correct_form": "下りて", "base_form": "下りる", "form_label": "て形", "sentence_index": 1, "explanations": {"下りて": "て形。「店のシャッターが下りて、中が見えなくなった」と続く形で、この空欄に入る。", "下りよう": "意向形は文を続けられず、「下りよう、中が」では成り立たない。", "下りる": "基本形を読点で続けると不自然で、文の流れが成り立たない。", "下ります": "丁寧形は普通体の文中で読点に続けられず、語形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39673, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "重い荷物を載せたかごが、ひもでゆっくり下りる、止まった。", "corrected_sentence": "重い荷物を載せたかごが、ひもでゆっくり下りて、止まった。", "error_description": "「下りる、」と辞書形のまま読点で続けるのは不自然で、文が続かない。読点で続けるには「下りて」（て形）が必要。誤りは辞書形で、正しくはて形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "下りる", "is_correct": true, "explanation": "基本形。「舞台のカーテンが下りると」と条件の「と」に続く形で、この空欄に入る。"}, {"text": "下りれば", "is_correct": false, "explanation": "仮定形は「下りればと」と続かず、条件の「と」と重なって不自然。"}, {"text": "下りよう", "is_correct": false, "explanation": "意向形は「下りようと」となり意志の文脈になるため、カーテンの出来事には合わない。"}, {"text": "下りさせる", "is_correct": false, "explanation": "使役形はカーテンに人の動作を与える形で、カーテンが主語の文に合わない。"}], "correct_form": "下りる", "base_form": "下りる", "form_label": "基本形", "sentence_index": 7, "explanations": {"下りる": "基本形。「舞台のカーテンが下りると」と条件の「と」に続く形で、この空欄に入る。", "下りれば": "仮定形は「下りればと」と続かず、条件の「と」と重なって不自然。", "下りよう": "意向形は「下りようと」となり意志の文脈になるため、カーテンの出来事には合わない。", "下りさせる": "使役形はカーテンに人の動作を与える形で、カーテンが主語の文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "まで", "options": [{"text": "まで", "is_correct": true, "explanation": "「終わりまで行く」は到達点を示し、この文脈に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「この道の終わりが行くと」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「終わりで行くと」は文脈に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐので、「終わりの行くと」は文として続かない。"}], "correct_answer": "まで", "explanations": {"まで": "「終わりまで行く」は到達点を示し、この文脈に合う。", "が": "「が」は主語を示すので、「この道の終わりが行くと」は文として成り立たない。", "で": "「で」は場所や手段を示すが、「終わりで行くと」は文脈に合わない。", "の": "「の」は名詞をつなぐので、「終わりの行くと」は文として続かない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「商店街の終わりに古い本屋がある」は存在する場所を示し、正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は対象を示すので、「商店街の終わりを、古い本屋がある」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を示すが、存在を表す「ある」とは合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、存在の場所を表す文脈には合わない。"}], "correct_answer": "に", "explanations": {"に": "「商店街の終わりに古い本屋がある」は存在する場所を示し、正しい。", "を": "「を」は対象を示すので、「商店街の終わりを、古い本屋がある」は成り立たない。", "へ": "「へ」は向かう方向を示すが、存在を表す「ある」とは合わない。", "より": "「より」は比較を示すので、存在の場所を表す文脈には合わない。"}, "error_tags": {"を": "対象", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かが続かなくなる場所。", "primary_collocate": null, "pronunciation": "おわり", "ipa": "owaɾi", "syllable_count": 3, "sentences": [{"text": "長い行列の終わりに、新しい客が並んだ。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "長[なが]い行列[ぎょうれつ]の終[お]わりに、新[あたら]しい客[きゃく]が並[なら]んだ。", "sentence_source": "generated"}, {"text": "この道の終わりまで行くと、先は海で進めなくなる。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "この道[みち]の終[お]わりまで行[い]くと、先[さき]は海[うみ]で進[すす]めなくなる。", "sentence_source": "generated"}, {"text": "廊下の終わりまで歩くと、非常口が見えた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "廊下[ろうか]の終[お]わりまで歩[ある]くと、非常口[ひじょうぐち]が見[み]えた。", "sentence_source": "generated"}, {"text": "線の終わりに小さな点を書いて、印をつけた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "線[せん]の終[お]わりに小[ちい]さな点[てん]を書[か]いて、印[しるし]をつけた。", "sentence_source": "generated"}, {"text": "ロープの終わりをしっかり結んでから、崖を下りた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "ロープの終[お]わりをしっかり結[むす]んでから、崖[がけ]を下[お]りた。", "sentence_source": "generated"}, {"text": "滑走路の終わりが見えたとき、飛行機はやっと止まった。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "滑走路[かっそうろ]の終[お]わりが見[み]えたとき、飛行機[ひこうき]はやっと止[と]まった。", "sentence_source": "generated"}, {"text": "森の終わりに出ると、広い草原が広がっていた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "森[もり]の終[お]わりに出[で]ると、広[ひろ]い草原[そうげん]が広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "商店街の終わりに、古い本屋がある。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "商店街[しょうてんがい]の終[お]わりに、古[ふる]い本屋[ほんや]がある。", "sentence_source": "generated"}, {"text": "長いトンネルの終わりに、白い光が見えてきた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "長[なが]いトンネルの終[お]わりに、白[しろ]い光[ひかり]が見[み]えてきた。", "sentence_source": "generated"}, {"text": "砂浜の終わりには、大きな岩が並んでいる。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "砂浜[すなはま]の終[お]わりには、大[おお]きな岩[いわ]が並[なら]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終わり", "label": "基本形"}], "register": "中立", "sense_fingerprint": "道・列・線など、空間的に続いてきたものが途切れる場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "終わり", "is_correct": true, "explanation": "「長い行列の終わりに」は行列の最後の位置を表し、空所にそのまま入る。"}, {"text": "台所", "is_correct": false, "explanation": "台所は家の中の部屋で、「行列の台所に並んだ」は場所として成り立たない。"}, {"text": "屋根", "is_correct": false, "explanation": "屋根は建物の上部で、行列の位置として使えない。"}, {"text": "応接間", "is_correct": false, "explanation": "応接間は客を通す部屋で、行列の位置を表せない。"}], "explanations": {"終わり": "「長い行列の終わりに」は行列の最後の位置を表し、空所にそのまま入る。", "台所": "台所は家の中の部屋で、「行列の台所に並んだ」は場所として成り立たない。", "屋根": "屋根は建物の上部で、行列の位置として使えない。", "応接間": "応接間は客を通す部屋で、行列の位置を表せない。"}, "sentence_index": 0, "correct_answer": "終わり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子猫は、自分の終わりを追いかけてくるくる回った。", "explanation": "ここは〈しっぽ〉（体の後ろに伸びる部分）の意味。終わりは続いていたものが止まる地点を指すが、動物の尾は〈しっぽ〉と言う。"}, {"text": "会議の終わりに、みんなで拍手した。", "explanation": "ここは〈終了〉（会議が終わる時点）の意味。場所の端ではなく、時間の区切りを指す。"}, {"text": "来週の終わりまでに、報告書を出してください。", "explanation": "ここは〈期限〉（区切りとなる時点）の意味。場所の端ではなく、時間の区切りを指す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "終わり", "is_correct": true, "explanation": "「森の終わりに出ると」は森の端で外に出ることを表し、空所にそのまま入る。"}, {"text": "機械", "is_correct": false, "explanation": "機械は道具や装置のことで、「森の機械に出る」は意味をなさない。"}, {"text": "香り", "is_correct": false, "explanation": "香りは匂いのことで、「森の香りに出る」は場所として成り立たない。"}, {"text": "手帳", "is_correct": false, "explanation": "手帳は書き込みに使う帳面で、森の位置を表せない。"}], "explanations": {"終わり": "「森の終わりに出ると」は森の端で外に出ることを表し、空所にそのまま入る。", "機械": "機械は道具や装置のことで、「森の機械に出る」は意味をなさない。", "香り": "香りは匂いのことで、「森の香りに出る」は場所として成り立たない。", "手帳": "手帳は書き込みに使う帳面で、森の位置を表せない。"}, "sentence_index": 6, "correct_answer": "終わり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会議は終わりが遅く、夜九時まで続いた。", "explanation": "ここは〈終了時刻〉（会議が終わる時刻）の意味。場所の端ではなく、時間を指す。"}, {"text": "この夏の終わりに、家族でキャンプへ行った。", "explanation": "ここは〈時期〉（夏の区切りの時点）の意味。場所の端ではなく、時間の区切りを指す。"}, {"text": "この店は終わりが早く、朝一番に開いた。", "explanation": "ここは〈開店〉（店を開ける時刻）の意味。終わりは続いていたものが止まる地点で、店が開く時点は〈開店〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "倉庫の終わりで非常口が見えた。", "corrected_sentence": "倉庫の終わりに非常口が見えた。", "error_description": "見える場所を示すには「に」を使う。「で」は動作や出来事が行われる場所なので、見えたものの位置にはならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39674, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道は長く、終わりを遠くて、先が見えない。", "corrected_sentence": "この道は長く、終わりが遠くて、先が見えない。", "error_description": "「遠い」は主語に「が」を取る形容詞。「を」を付けると、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始まり", "is_correct": true, "explanation": "「始まり」は物事が始まる時点で、時間的な終わりの対義語。"}, {"text": "途中", "is_correct": false, "explanation": "「途中」は進行している最中を指し、終わりの対義語ではない。"}, {"text": "準備", "is_correct": false, "explanation": "「準備」は物事を始める前の用意で、終わりの対義語ではない。"}, {"text": "中身", "is_correct": false, "explanation": "「中身」は容器や物の内部のことで、時間の対義語にはならない。"}], "correct_answer": "始まり", "explanations": {"始まり": "「始まり」は物事が始まる時点で、時間的な終わりの対義語。", "途中": "「途中」は進行している最中を指し、終わりの対義語ではない。", "準備": "「準備」は物事を始める前の用意で、終わりの対義語ではない。", "中身": "「中身」は容器や物の内部のことで、時間の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「年の終わりに」は時点を示し、正しい。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐので、「年の終わりの、家族で」は文として続かない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「年の終わりが家族で大そうじをする」は時間が動作主になり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すが、「年の終わりと、家族で大そうじ」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「年の終わりに」は時点を示し、正しい。", "の": "「の」は名詞をつなぐので、「年の終わりの、家族で」は文として続かない。", "が": "「が」は主語を示すが、「年の終わりが家族で大そうじをする」は時間が動作主になり不自然。", "と": "「と」は並列や共同を示すが、「年の終わりと、家族で大そうじ」は文として成り立たない。"}, "error_tags": {"の": "連体修飾", "が": "主語", "と": "並列・共同"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "始め", "is_correct": true, "explanation": "「始め」は時間の初めを表し、時間的な終わりの対義語。"}, {"text": "中断", "is_correct": false, "explanation": "「中断」は途中で止めることで、終わりの対義語ではない。"}, {"text": "余韻", "is_correct": false, "explanation": "「余韻」は終わったあとに残る響きで、対義語ではない。"}, {"text": "合間", "is_correct": false, "explanation": "「合間」は物事と物事の間の時間で、始めや終わりの対義語にはならない。"}], "correct_answer": "始め", "explanations": {"始め": "「始め」は時間の初めを表し、時間的な終わりの対義語。", "中断": "「中断」は途中で止めることで、終わりの対義語ではない。", "余韻": "「余韻」は終わったあとに残る響きで、対義語ではない。", "合間": "「合間」は物事と物事の間の時間で、始めや終わりの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が続いたあと、最後になること。その地点。", "primary_collocate": null, "pronunciation": "おわり", "ipa": "owaɾi", "syllable_count": 3, "sentences": [{"text": "夏休みの終わりが近づいて、宿題を急いでやっている。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの終[お]わりが近[ちか]づいて、宿題[しゅくだい]を急[いそ]いでやっている。", "sentence_source": "generated"}, {"text": "映画の終わりで、主人公は故郷に帰っていった。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "映画[えいが]の終[お]わりで、主人公[しゅじんこう]は故郷[こきょう]に帰[かえ]っていった。", "sentence_source": "generated"}, {"text": "試合の終わりを告げる笛が、静かな会場に鳴り響いた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "試合[しあい]の終[お]わりを告[つ]げる笛[ふえ]が、静[しず]かな会場[かいじょう]に鳴[な]り響[ひび]いた。", "sentence_source": "generated"}, {"text": "月の終わりには、家賃を払わなければならない。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "月[つき]の終[お]わりには、家賃[やちん]を払[はら]わなければならない。", "sentence_source": "generated"}, {"text": "話の終わりに、先生は大切なことをもう一度言った。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "話[はなし]の終[お]わりに、先生[せんせい]は大切[たいせつ]なことをもう一度[いちど]言[い]った。", "sentence_source": "generated"}, {"text": "長かった工事もようやく終わりが見えてきた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "長[なが]かった工事[こうじ]もようやく終[お]わりが見[み]えてきた。", "sentence_source": "generated"}, {"text": "いつまでも終わりが来ない会議に、みんな疲れてきた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "いつまでも終[お]わりが来[こ]ない会議[かいぎ]に、みんな疲[つか]れてきた。", "sentence_source": "generated"}, {"text": "年の終わりに、家族で大そうじをするのが毎年の習慣だ。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "年[とし]の終[お]わりに、家族[かぞく]で大[おお]そうじをするのが毎年[まいとし]の習慣[しゅうかん]だ。", "sentence_source": "generated"}, {"text": "手紙の終わりに、「お体を大切に」と書き添えた。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "手紙[てがみ]の終[お]わりに、「お体[からだ]を大切[たいせつ]に」と書[か]き添[そ]えた。", "sentence_source": "generated"}, {"text": "授業の終わりのチャイムが鳴ると、生徒たちは急に元気になった。", "target_word": "終わり", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の終[お]わりのチャイムが鳴[な]ると、生徒[せいと]たちは急[きゅう]に元気[げんき]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "終わり", "label": "基本形"}], "register": "中立", "sense_fingerprint": "休み・試合・話など、時間的に続いてきた物事が最後になること、またその時点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 告げる (Zipf 3.68), 笛 (Zipf 3.78), 鳴り響い (Zipf 2.59)','sentence 8 above tier T1: contains vocabulary far above tier T1: 書き添え (Zipf 2.18)']::text[], 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "終わり", "is_correct": true, "explanation": "「夏休みの終わりが近づいて」は休みの最後の時期を表し、空所にそのまま入る。"}, {"text": "水着", "is_correct": false, "explanation": "水着は泳ぐときに着る服で、「夏休みの水着が近づいて」は意味が通らない。"}, {"text": "冷房", "is_correct": false, "explanation": "冷房は部屋を冷やす設備で、時期の終わりを表せない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、「夏休みの天井が近づいて」は成り立たない。"}], "explanations": {"終わり": "「夏休みの終わりが近づいて」は休みの最後の時期を表し、空所にそのまま入る。", "水着": "水着は泳ぐときに着る服で、「夏休みの水着が近づいて」は意味が通らない。", "冷房": "冷房は部屋を冷やす設備で、時期の終わりを表せない。", "天井": "天井は部屋の上の面で、「夏休みの天井が近づいて」は成り立たない。"}, "sentence_index": 0, "correct_answer": "終わり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋根の終わりに、古い煙突が立っている。", "explanation": "ここは空間の端（屋根の端）を指す意味。時間の区切りとしての終わりではない。"}, {"text": "この池は終わりが浅く、子どもでも歩いて渡れる。", "explanation": "ここは空間の端（池の浅いほうの端）を指す意味。時間の区切りとしての終わりではない。"}, {"text": "この鉛筆は終わりが細く、字がきれいに書ける。", "explanation": "ここは〈先〉（とがった先端）の意味。鉛筆の先は〈先〉と言い、終わりとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "終わり", "is_correct": true, "explanation": "「いつまでも終わりが来ない会議」は会議が終わらないことを表し、空所にそのまま入る。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は扉を開ける道具で、「いつまでも鍵が来ない会議」は成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は壁の開口部で、会議の進み具合を表せない。"}, {"text": "紙袋", "is_correct": false, "explanation": "紙袋は物を入れる袋で、「いつまでも紙袋が来ない」は意味をなさない。"}], "explanations": {"終わり": "「いつまでも終わりが来ない会議」は会議が終わらないことを表し、空所にそのまま入る。", "鍵": "鍵は扉を開ける道具で、「いつまでも鍵が来ない会議」は成り立たない。", "窓": "窓は壁の開口部で、会議の進み具合を表せない。", "紙袋": "紙袋は物を入れる袋で、「いつまでも紙袋が来ない」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "終わり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鍋は終わりが丸く、熱が均一に伝わる。", "explanation": "ここは〈底〉（容器の下の面）の意味。終わりは続いていたものが止まる地点だが、鍋の底は〈底〉と言う。"}, {"text": "谷の終わりは険しく、人が登ることができない。", "explanation": "ここは空間の端（谷の行き止まり）を指す意味。時間の区切りとしての終わりではない。"}, {"text": "この海岸は終わりに小さな灯台が立ち、船の目印になっている。", "explanation": "ここは〈岬〉（海に突き出た陸地）の意味。終わりは続いていたものが止まる地点だが、海に突き出た陸は〈岬〉と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬休みの終わりを近づいて、学生たちは宿題を急いでいた。", "corrected_sentence": "冬休みの終わりが近づいて、学生たちは宿題を急いでいた。", "error_description": "「近づく」は自動詞なので主語には「が」を付ける。「を」は他動詞の目的語を示すため、「近づく」とは結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "週末の旅行は楽しかったが、終わりを寂しく、みんな落ち込んだ。", "corrected_sentence": "週末の旅行は楽しかったが、終わりが寂しく、みんな落ち込んだ。", "error_description": "「寂しい」は主語に「が」を取る形容詞。「を」を付けると、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「エレベーターが（主語）止まってしまい」と、エレベーターを止まる主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「エレベーターを止まって」は目的語を取る形で、止まる動作には不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、止まる動詞の主語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や同伴を表し、停止の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「エレベーターが（主語）止まってしまい」と、エレベーターを止まる主語として示す。", "を": "「エレベーターを止まって」は目的語を取る形で、止まる動作には不自然。", "の": "「の」は名詞をつなぐ助詞で、止まる動詞の主語を示せない。", "と": "「と」は並列や同伴を表し、停止の主語を示せない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "動く", "is_correct": true, "explanation": "「止まる」の対義語。機械などが動き出す意味で、この意味で対になる。"}, {"text": "残る", "is_correct": false, "explanation": "その場にとどまる意味で、動作の対義語にはならない。"}, {"text": "届く", "is_correct": false, "explanation": "目的の場所に到達する意味で、止まるの対義語にはならない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "列を作って横に並ぶ意味で、動きの対義語にはならない。"}], "correct_answer": "動く", "explanations": {"動く": "「止まる」の対義語。機械などが動き出す意味で、この意味で対になる。", "残る": "その場にとどまる意味で、動作の対義語にはならない。", "届く": "目的の場所に到達する意味で、止まるの対義語にはならない。", "並ぶ": "列を作って横に並ぶ意味で、動きの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「時計が（主語）止まっている」と、時計を止まる主語として示す。"}, {"text": "へ", "is_correct": false, "explanation": "「時計へ止まっている」は方向を示し、止まる主語を表せない。"}, {"text": "から", "is_correct": false, "explanation": "「時計から止まっている」は起点を示し、止まっている主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、止まる主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「時計が（主語）止まっている」と、時計を止まる主語として示す。", "へ": "「時計へ止まっている」は方向を示し、止まる主語を表せない。", "から": "「時計から止まっている」は起点を示し、止まっている主語を示せない。", "より": "「より」は比較の助詞で、止まる主語にはならない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "動く", "is_correct": true, "explanation": "「止まる」の対義語。画面などが動き出す意味で、この意味で対になる。"}, {"text": "眠る", "is_correct": false, "explanation": "横になって休む意味で、動作の対義語にはならない。"}, {"text": "数える", "is_correct": false, "explanation": "数を数える意味で、止まるの対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物を場所に据える意味で、止まるの対義語にはならない。"}], "correct_answer": "動く", "explanations": {"動く": "「止まる」の対義語。画面などが動き出す意味で、この意味で対になる。", "眠る": "横になって休む意味で、動作の対義語にはならない。", "数える": "数を数える意味で、止まるの対義語ではない。", "置く": "物を場所に据える意味で、止まるの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が動かなくなること。", "primary_collocate": null, "pronunciation": "とまる", "ipa": "tomaɾɯ", "syllable_count": 3, "sentences": [{"text": "電池が切れて、壁の時計が止まった。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "電池(でんち)が切(き)れて、壁(かべ)の時計(とけい)が止(と)まった。", "sentence_source": "generated"}, {"text": "停電でエレベーターが止まってしまい、中に閉じ込められた。", "target_word": "止まって", "complexity_tier": "T3", "furigana": "停電(ていでん)でエレベーターが止(と)まってしまい、中(なか)に閉(と)じ込(こ)められた。", "sentence_source": "generated"}, {"text": "機械が急に止まったので、工場の人が原因を調べた。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "機械(きかい)が急(きゅう)に止(と)まったので、工場(こうじょう)の人(ひと)が原因(げんいん)を調(しら)べた。", "sentence_source": "generated"}, {"text": "この扇風機は古くて、すぐ止まるので使えない。", "target_word": "止まる", "complexity_tier": "T3", "furigana": "この扇風機(せんぷうき)は古(ふる)くて、すぐ止(と)まるので使(つか)えない。", "sentence_source": "generated"}, {"text": "水道が止まって、顔を洗えなかった。", "target_word": "止まって", "complexity_tier": "T3", "furigana": "水道(すいどう)が止(と)まって、顔(かお)を洗(あら)えなかった。", "sentence_source": "generated"}, {"text": "ゼンマイが切れると、おもちゃの車は止まります。", "target_word": "止まります", "complexity_tier": "T3", "furigana": "ゼンマイが切(き)れると、おもちゃの車(くるま)は止(と)まります。", "sentence_source": "generated"}, {"text": "雪で電車が止まり、会社に行けなかった。", "target_word": "止まり", "complexity_tier": "T3", "furigana": "雪(ゆき)で電車(でんしゃ)が止(と)まり、会社(かいしゃ)に行(い)けなかった。", "sentence_source": "generated"}, {"text": "時計が止まっていることに気づかず、約束に遅れた。", "target_word": "止まっている", "complexity_tier": "T3", "furigana": "時計(とけい)が止(と)まっていることに気(き)づかず、約束(やくそく)に遅(おく)れた。", "sentence_source": "generated"}, {"text": "風がやんで、庭の風車が止まった。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "風(かぜ)がやんで、庭(にわ)の風車(かざぐるま)が止(と)まった。", "sentence_source": "generated"}, {"text": "パソコンの画面が止まって、何も操作できない。", "target_word": "止まって", "complexity_tier": "T3", "furigana": "パソコンの画面(がめん)が止(と)まって、何(なに)も操作(そうさ)できない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "止まる", "label": "辞書形"}, {"form": "止まらない", "label": "否定形"}, {"form": "止まります", "label": "丁寧形"}, {"form": "止まって", "label": "て形"}, {"form": "止まった", "label": "過去形"}, {"form": "止まれば", "label": "仮定形"}, {"form": "止まろう", "label": "意志形"}], "register": "中立（口語・文章どちらでも可）", "sense_fingerprint": "機械・時計・設備などが動作をやめて動かなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "止まった", "is_correct": true, "explanation": "過去形。「壁の時計が止まった」と、時計が動かなくなった結果を述べる。"}, {"text": "止まって", "is_correct": false, "explanation": "て形は文を終えられず、「壁の時計が止まって。」と文が切れない。"}, {"text": "止まれば", "is_correct": false, "explanation": "仮定形は条件を示すだけで、文を完結できない。"}, {"text": "止まろう", "is_correct": false, "explanation": "意向形は意志を持つ主語が必要で、時計には当てはまらない。"}], "explanations": {"止まった": "過去形。「壁の時計が止まった」と、時計が動かなくなった結果を述べる。", "止まって": "て形は文を終えられず、「壁の時計が止まって。」と文が切れない。", "止まれば": "仮定形は条件を示すだけで、文を完結できない。", "止まろう": "意向形は意志を持つ主語が必要で、時計には当てはまらない。"}, "sentence_index": 0, "correct_answer": "止まった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は縁側の椅子に止まって、新聞を広げた。", "explanation": "ここは〈座る〉の意味。椅子に腰掛ける場合は〈座る〉を使い、〈止まる〉は動いていた物が動かなくなる時に使うので合わない。"}, {"text": "夜、廊下の電灯が止まった。", "explanation": "ここは〈消える〉の意味。明かりが消える場合は〈消える〉を使い、〈止まる〉は動いていた物が動かなくなる時に使うので合わない。"}, {"text": "書店で、ふと一冊の本に目が止まった。", "explanation": "ここは〈注意を引かれる〉の意味。目が何かに引かれる時の言い方で、〈止まる〉の動かなくなる意味とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "止まり", "is_correct": true, "explanation": "連用形。「雪で電車が止まり、会社に行けなかった」と理由を続けて述べる形で、この空欄に入る。"}, {"text": "止まる", "is_correct": false, "explanation": "辞書形は「止まる、」と読点で続けると不自然で、文の流れが合わない。"}, {"text": "止まります", "is_correct": false, "explanation": "丁寧形は普通体の文中で読点につながらず、語形が合わない。"}, {"text": "止まれ", "is_correct": false, "explanation": "命令形は「止まれ、」と続かず、雪の結果を述べる文に合わない。"}], "explanations": {"止まり": "連用形。「雪で電車が止まり、会社に行けなかった」と理由を続けて述べる形で、この空欄に入る。", "止まる": "辞書形は「止まる、」と読点で続けると不自然で、文の流れが合わない。", "止まります": "丁寧形は普通体の文中で読点につながらず、語形が合わない。", "止まれ": "命令形は「止まれ、」と続かず、雪の結果を述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "止まり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い夜、ゼリーがすっかり止まった。", "explanation": "ここは〈固まる〉の意味。ゼリーが冷えて固まる場合は〈固まる〉を使い、〈止まる〉は動いていた物が動かなくなる意味なので合わない。"}, {"text": "山道が急に止まった。", "explanation": "ここは〈途切れる〉の意味。道や線が途中で終わる時は〈途切れる〉を使い、〈止まる〉は動いていた物が動かなくなる時に使うので合わない。"}, {"text": "洗濯物がすっかり止まった。", "explanation": "ここは〈乾く〉の意味。水分が抜けて乾く場合は〈乾く〉を使い、〈止まる〉は動きが止まる意味で、この場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポンプを急に止まり、水が出なくなった。", "corrected_sentence": "ポンプが急に止まり、水が出なくなった。", "error_description": "「止まる」は自動詞で目的語の「を」を取らない。ポンプは止まる主語なので「が」を使う。誤りは「を」で、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "止まって", "is_correct": true, "explanation": "て形。「止まってしまい」と続けて、結果を述べる形で、この空欄に入る。"}, {"text": "止まった", "is_correct": false, "explanation": "過去形は「止まったしまい」と続かず、しまう表現に接続しない。"}, {"text": "止まらない", "is_correct": false, "explanation": "否定形は「止まらないしまい」と続かず、語形が合わない。"}, {"text": "止まれば", "is_correct": false, "explanation": "仮定形は「止まればしまい」と続かず、文が成り立たない。"}], "correct_form": "止まって", "base_form": "止まる", "form_label": "て形", "sentence_index": 1, "explanations": {"止まって": "て形。「止まってしまい」と続けて、結果を述べる形で、この空欄に入る。", "止まった": "過去形は「止まったしまい」と続かず、しまう表現に接続しない。", "止まらない": "否定形は「止まらないしまい」と続かず、語形が合わない。", "止まれば": "仮定形は「止まればしまい」と続かず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39676, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷蔵庫のモーターが止まる、中の食品が傷み始めた。", "corrected_sentence": "冷蔵庫のモーターが止まって、中の食品が傷み始めた。", "error_description": "「止まる、」と辞書形のまま読点で続けるのは不自然。読点で続けるには「止まって」（て形）が必要。誤りは辞書形で、正しくはて形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "止まっている", "is_correct": true, "explanation": "ている形。止まった状態が続いていることを示し、「止まっていることに気づかず」と名詞節を作る。"}, {"text": "止まって", "is_correct": false, "explanation": "て形は「止まってことに」と続かず、名詞節が作れない。"}, {"text": "止まれば", "is_correct": false, "explanation": "仮定形は「止まればことに」と続かず、名詞の前に置けない。"}, {"text": "止まろう", "is_correct": false, "explanation": "意向形は「止まろうことに」となり、気づいた事実の内容にならない。"}], "correct_form": "止まっている", "base_form": "止まる", "form_label": "ている形", "sentence_index": 7, "explanations": {"止まっている": "ている形。止まった状態が続いていることを示し、「止まっていることに気づかず」と名詞節を作る。", "止まって": "て形は「止まってことに」と続かず、名詞節が作れない。", "止まれば": "仮定形は「止まればことに」と続かず、名詞の前に置けない。", "止まろう": "意向形は「止まろうことに」となり、気づいた事実の内容にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「犬が（主語）急に止まって」と、犬を止まる主語として示す。"}, {"text": "を", "is_correct": false, "explanation": "「犬を止まって」は目的語を示すが、止まる動作の主語を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「犬へ止まって」は方向を示し、止まる主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "「犬と止まって」は並列や同伴を表し、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「犬が（主語）急に止まって」と、犬を止まる主語として示す。", "を": "「犬を止まって」は目的語を示すが、止まる動作の主語を表せない。", "へ": "「犬へ止まって」は方向を示し、止まる主語にならない。", "と": "「犬と止まって」は並列や同伴を表し、主語を示せない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "進む", "is_correct": true, "explanation": "「止まる」の対義語。車や人が前へ動いていく意味で、この意味で対になる。"}, {"text": "残る", "is_correct": false, "explanation": "その場にとどまる意味で、進む動きの対義語にはならない。"}, {"text": "届く", "is_correct": false, "explanation": "目的の場所に到達する意味で、止まるの対義語にはならない。"}, {"text": "並ぶ", "is_correct": false, "explanation": "列を作って横に並ぶ意味で、進む・止まるの対義語にはならない。"}], "correct_answer": "進む", "explanations": {"進む": "「止まる」の対義語。車や人が前へ動いていく意味で、この意味で対になる。", "残る": "その場にとどまる意味で、進む動きの対義語にはならない。", "届く": "目的の場所に到達する意味で、止まるの対義語にはならない。", "並ぶ": "列を作って横に並ぶ意味で、進む・止まるの対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「壁の前で止まった」と、止まった場所を示す。"}, {"text": "の", "is_correct": false, "explanation": "「壁の前の」は名詞を修飾し、止まる場所を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「壁の前より」は比較の意味になり、止まった場所を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「前が止まった」は前が主語になり、ボールが止まる文として不自然。"}], "correct_answer": "で", "explanations": {"で": "「壁の前で止まった」と、止まった場所を示す。", "の": "「壁の前の」は名詞を修飾し、止まる場所を示せない。", "より": "「壁の前より」は比較の意味になり、止まった場所を示せない。", "が": "「前が止まった」は前が主語になり、ボールが止まる文として不自然。"}, "error_tags": {"の": "連体修飾", "より": "比較", "が": "主語"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "進む", "is_correct": true, "explanation": "「止まる」の対義語。前へ動いていく意味で、この意味で対になる。"}, {"text": "眠る", "is_correct": false, "explanation": "横になって休む意味で、進む・止まるの対義語にはならない。"}, {"text": "数える", "is_correct": false, "explanation": "数を数える意味で、止まるの対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物を場所に据える意味で、止まるの対義語にはならない。"}], "correct_answer": "進む", "explanations": {"進む": "「止まる」の対義語。前へ動いていく意味で、この意味で対になる。", "眠る": "横になって休む意味で、進む・止まるの対義語にはならない。", "数える": "数を数える意味で、止まるの対義語ではない。", "置く": "物を場所に据える意味で、止まるの対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物が、それ以上動いたり進んだりしなくなる。", "primary_collocate": null, "pronunciation": "とまる", "ipa": "tomaɾɯ", "syllable_count": 3, "sentences": [{"text": "信号が赤になったので、車が止まった。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "信号(しんごう)が赤(あか)になったので、車(くるま)が止(と)まった。", "sentence_source": "generated"}, {"text": "犬が急に止まって、散歩の道で動かなくなった。", "target_word": "止まって", "complexity_tier": "T3", "furigana": "犬(いぬ)が急(きゅう)に止(と)まって、散歩(さんぽ)の道(みち)で動(うご)かなくなった。", "sentence_source": "generated"}, {"text": "ショーウィンドウの前で、思わず足が止まった。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "ショーウィンドウの前(まえ)で、思(おも)わず足(あし)が止(と)まった。", "sentence_source": "generated"}, {"text": "標識があるので、車は必ずここで止まります。", "target_word": "止まります", "complexity_tier": "T3", "furigana": "標識(ひょうしき)があるので、車(くるま)は必(かなら)ずここで止(と)まります。", "sentence_source": "generated"}, {"text": "バスが止まるまで、席に座っていてください。", "target_word": "止まる", "complexity_tier": "T3", "furigana": "バスが止(と)まるまで、席(せき)に座(すわ)っていてください。", "sentence_source": "generated"}, {"text": "走っていた子どもが、先生の声で止まった。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "走(はし)っていた子(こ)どもが、先生(せんせい)の声(こえ)で止(と)まった。", "sentence_source": "generated"}, {"text": "坂の途中で自転車が止まらず、壁にぶつかった。", "target_word": "止まらず", "complexity_tier": "T3", "furigana": "坂(さか)の途中(とちゅう)で自転車(じてんしゃ)が止(と)まらず、壁(かべ)にぶつかった。", "sentence_source": "generated"}, {"text": "ボールが転がって、壁の前で止まった。", "target_word": "止まった", "complexity_tier": "T3", "furigana": "ボールが転(ころ)がって、壁(かべ)の前(まえ)で止(と)まった。", "sentence_source": "generated"}, {"text": "電車が駅に止まると、たくさんの人が降りた。", "target_word": "止まる", "complexity_tier": "T3", "furigana": "電車(でんしゃ)が駅(えき)に止(と)まると、たくさんの人(ひと)が降(お)りた。", "sentence_source": "generated"}, {"text": "急いでいたが、踏切の前で止まるしかなかった。", "target_word": "止まる", "complexity_tier": "T3", "furigana": "急(いそ)いでいたが、踏切(ふみきり)の前(まえ)で止(と)まるしかなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "止まる", "label": "辞書形"}, {"form": "止まらない", "label": "否定形"}, {"form": "止まります", "label": "丁寧形"}, {"form": "止まって", "label": "て形"}, {"form": "止まった", "label": "過去形"}, {"form": "止まれば", "label": "仮定形"}, {"form": "止まろう", "label": "意志形"}], "register": "中立（口語・文章どちらでも可）", "sense_fingerprint": "人・乗り物・ボールなどが進むのをやめてその場にとどまる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "止まった", "is_correct": true, "explanation": "過去形。「車が止まった」と、信号を受けて停止した結果を述べる。"}, {"text": "止まって", "is_correct": false, "explanation": "て形は文を終えられず、「車が止まって。」と文が切れない。"}, {"text": "止まれば", "is_correct": false, "explanation": "仮定形は条件を示すだけで、文を完結できない。"}, {"text": "止まろう", "is_correct": false, "explanation": "意向形は意志を持つ主語が必要で、車の停止の事実を述べられない。"}], "explanations": {"止まった": "過去形。「車が止まった」と、信号を受けて停止した結果を述べる。", "止まって": "て形は文を終えられず、「車が止まって。」と文が切れない。", "止まれば": "仮定形は条件を示すだけで、文を完結できない。", "止まろう": "意向形は意志を持つ主語が必要で、車の停止の事実を述べられない。"}, "sentence_index": 0, "correct_answer": "止まった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い朝、バターがすっかり止まった。", "explanation": "ここは〈固まる〉の意味。バターが冷えて固体になる時は〈固まる〉を使い、〈止まる〉は進んでいたものが進まなくなる時に使うので合わない。"}, {"text": "彼は椅子に止まって、本を読み始めた。", "explanation": "ここは〈座る〉の意味。椅子に腰掛ける場合は〈座る〉を使い、〈止まる〉は進んでいたものが進むのをやめる時に使うので合わない。"}, {"text": "店先の新作に目が止まった。", "explanation": "ここは〈注意を引かれる〉の意味。目が何かに引かれる時の言い方で、〈止まる〉の進むのをやめる意味とは別なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "止まらず", "is_correct": true, "explanation": "否定の連用形。「止まらず、壁にぶつかった」と、止まらないまま起きた結果を続けて述べる。"}, {"text": "止まる", "is_correct": false, "explanation": "辞書形は「止まる、壁に」と続かず、結果を述べる文の流れに合わない。"}, {"text": "止まれ", "is_correct": false, "explanation": "命令形は「止まれ、」と続かず、ぶつかった結果を述べる文に合わない。"}, {"text": "止まらせる", "is_correct": false, "explanation": "使役形は「自転車を止まらせる」の形で、自転車が主語の文では不自然。"}], "explanations": {"止まらず": "否定の連用形。「止まらず、壁にぶつかった」と、止まらないまま起きた結果を続けて述べる。", "止まる": "辞書形は「止まる、壁に」と続かず、結果を述べる文の流れに合わない。", "止まれ": "命令形は「止まれ、」と続かず、ぶつかった結果を述べる文に合わない。", "止まらせる": "使役形は「自転車を止まらせる」の形で、自転車が主語の文では不自然。"}, "sentence_index": 6, "correct_answer": "止まらず"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "強風で大木が止まった。", "explanation": "ここは〈倒れる〉の意味。木が根元から倒れる場合は〈倒れる〉を使い、〈止まる〉は進んでいたものが進むのをやめる時に使うので合わない。"}, {"text": "猫が日なたで止まって眠っている。", "explanation": "ここは〈寝る〉の意味。眠る場合は〈寝る〉を使い、〈止まる〉は進んでいたものが進まなくなる意味で、眠りの説明には合わない。"}, {"text": "屋根の雪が、ドサッと止まった。", "explanation": "ここは〈落ちる〉の意味。雪や物が高い所から落下する場合は〈落ちる〉を使い、〈止まる〉は進むのをやめる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "踏切の前で車を止まり、電車を待った。", "corrected_sentence": "踏切の前で車が止まり、電車を待った。", "error_description": "「止まる」は自動詞で目的語の「を」を取らない。車が止まる主語なので「が」を使う。誤りは「を」で、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "止まって", "is_correct": true, "explanation": "て形。「犬が急に止まって」と続け、動かなくなった結果を述べる形で、この空欄に入る。"}, {"text": "止まる", "is_correct": false, "explanation": "辞書形は読点で続けると不自然で、「止まる、散歩の道で」と文が続かない。"}, {"text": "止まります", "is_correct": false, "explanation": "丁寧形は普通体の文中で読点につながらず、語形が合わない。"}, {"text": "止まろう", "is_correct": false, "explanation": "意向形は意志の主語が必要で、犬の急な停止には当てはまらない。"}], "correct_form": "止まって", "base_form": "止まる", "form_label": "て形", "sentence_index": 1, "explanations": {"止まって": "て形。「犬が急に止まって」と続け、動かなくなった結果を述べる形で、この空欄に入る。", "止まる": "辞書形は読点で続けると不自然で、「止まる、散歩の道で」と文が続かない。", "止まります": "丁寧形は普通体の文中で読点につながらず、語形が合わない。", "止まろう": "意向形は意志の主語が必要で、犬の急な停止には当てはまらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39677, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "坂の途中で自転車が止まりて、少し休んだ。", "corrected_sentence": "坂の途中で自転車が止まって、少し休んだ。", "error_description": "「止まりて」は誤った活用形。て形は「止まって」が正しく、「止まりて」は文法的に成り立たない。誤りは活用、正しくは「止まって」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "止まった", "is_correct": true, "explanation": "過去形。「ボールが転がって、壁の前で止まった」と、停止した結果を述べる形で、この空欄に入る。"}, {"text": "止まって", "is_correct": false, "explanation": "て形は文を終えられず、「壁の前で止まって。」と文が切れない。"}, {"text": "止まれば", "is_correct": false, "explanation": "仮定形は条件を示すだけで、文を完結できない。"}, {"text": "止まろう", "is_correct": false, "explanation": "意向形は意志を持つ主語が必要で、ボールには当てはまらない。"}], "correct_form": "止まった", "base_form": "止まる", "form_label": "過去形", "sentence_index": 7, "explanations": {"止まった": "過去形。「ボールが転がって、壁の前で止まった」と、停止した結果を述べる形で、この空欄に入る。", "止まって": "て形は文を終えられず、「壁の前で止まって。」と文が切れない。", "止まれば": "仮定形は条件を示すだけで、文を完結できない。", "止まろう": "意向形は意志を持つ主語が必要で、ボールには当てはまらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "条件の「と」。転がすと、続けて机の端まで進んだという結果が述べられる"}, {"text": "に", "is_correct": false, "explanation": "「転がすに」では接続せず、文が成立しない"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、動詞の後には続けられない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、動詞の直後には置けない"}], "correct_answer": "と", "explanations": {"と": "条件の「と」。転がすと、続けて机の端まで進んだという結果が述べられる", "に": "「転がすに」では接続せず、文が成立しない", "へ": "方向を表すが、動詞の後には続けられない", "の": "連体修飾の「の」で、動詞の直後には置けない"}, "error_tags": {"に": "接続不可", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所の「で」。テーブルの上で転がしたという場所を示す"}, {"text": "が", "is_correct": false, "explanation": "「テーブルの上が転がして」では主語が成立せず、文の意味が通らない"}, {"text": "と", "is_correct": false, "explanation": "「テーブルの上と転がして」では並列にも動作の相手にもならない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、動詞の直前には置けない"}], "correct_answer": "で", "explanations": {"で": "場所の「で」。テーブルの上で転がしたという場所を示す", "が": "「テーブルの上が転がして」では主語が成立せず、文の意味が通らない", "と": "「テーブルの上と転がして」では並列にも動作の相手にもならない", "の": "連体修飾の「の」で、動詞の直前には置けない"}, "error_tags": {"が": "主語", "と": "並列・引用", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものを、手で動かして、そのままにしないで、ころころと動かすことです。", "primary_collocate": null, "pronunciation": "ころがす", "ipa": "koɾoɡasɯ", "syllable_count": 4, "sentences": [{"text": "子どもが床でボールを転がして遊んでいる。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "子(こ)どもが床(ゆか)でボールを転(ころ)がして遊(あそ)んでいる。", "sentence_source": "generated"}, {"text": "手でビー玉を転がすと、机の端まで進んだ。", "target_word": "転がす", "complexity_tier": "T3", "furigana": "手(て)でビー玉(だま)を転(ころ)がすと、机(つくえ)の端(はし)まで進(すす)んだ。", "sentence_source": "generated"}, {"text": "猫が好きな毛糸の玉を転がしてあげた。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "猫(ねこ)が好(す)きな毛糸(けいと)の玉(たま)を転(ころ)がしてあげた。", "sentence_source": "generated"}, {"text": "弟は雪玉を転がして、大きな雪だるまを作った。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "弟(おとうと)は雪玉(ゆきだま)を転(ころ)がして、大(おお)きな雪(ゆき)だるまを作(つく)った。", "sentence_source": "generated"}, {"text": "赤ちゃんの前でボールを転がすと、笑って追いかけた。", "target_word": "転がす", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんの前(まえ)でボールを転(ころ)がすと、笑(わら)って追(お)いかけた。", "sentence_source": "generated"}, {"text": "彼は坂の上から古いタイヤを転がした。", "target_word": "転がした", "complexity_tier": "T3", "furigana": "彼(かれ)は坂(さか)の上(うえ)から古(ふる)いタイヤを転(ころ)がした。", "sentence_source": "generated"}, {"text": "決められなくて、机の上で鉛筆を転がして答えを選んだ。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "決(き)められなくて、机(つくえ)の上(うえ)で鉛筆(えんぴつ)を転(ころ)がして答(こた)えを選(えら)んだ。", "sentence_source": "generated"}, {"text": "祖母は丸いみかんをテーブルの上で転がしてくれた。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "祖母(そぼ)は丸(まる)いみかんをテーブルの上(うえ)で転(ころ)がしてくれた。", "sentence_source": "generated"}, {"text": "犬のために、公園でボールを転がしました。", "target_word": "転がしました", "complexity_tier": "T3", "furigana": "犬(いぬ)のために、公園(こうえん)でボールを転(ころ)がしました。", "sentence_source": "generated"}, {"text": "重い樽は持てないので、横にして転がすことにした。", "target_word": "転がす", "complexity_tier": "T3", "furigana": "重(おも)い樽(たる)は持(も)てないので、横(よこ)にして転(ころ)がすことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転がす", "label": "辞書形"}, {"form": "転がさない", "label": "否定形"}, {"form": "転がします", "label": "丁寧形"}, {"form": "転がして", "label": "て形"}, {"form": "転がした", "label": "過去形"}, {"form": "転がせば", "label": "仮定形"}, {"form": "転がそう", "label": "意志形"}], "register": "中立（口語・文章どちらでも可）", "sense_fingerprint": "丸いものなどを手で押してころころと動かす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転がす", "is_correct": false, "explanation": "辞書形のため、「遊んでいる」へ続く動作の連なりが作れず文が成立しない"}, {"text": "転がして", "is_correct": true, "explanation": "「〜て」で動作を続け、「遊んでいる」とつながる"}, {"text": "転がした", "is_correct": false, "explanation": "過去形で、「遊んでいる」の進行と接続しない"}, {"text": "転がせ", "is_correct": false, "explanation": "命令形で、「遊んでいる」へ続く文にならない"}], "explanations": {"転がす": "辞書形のため、「遊んでいる」へ続く動作の連なりが作れず文が成立しない", "転がして": "「〜て」で動作を続け、「遊んでいる」とつながる", "転がした": "過去形で、「遊んでいる」の進行と接続しない", "転がせ": "命令形で、「遊んでいる」へ続く文にならない"}, "sentence_index": 0, "correct_answer": "転がして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアを転がして開けた。", "explanation": "ここは〈押す〉の意味。転がすは丸いものをころころ動かす語で、ドアを開けるのには使わない。"}, {"text": "ハンドルを転がして車の向きを変えた。", "explanation": "ここは〈回す〉の意味。ハンドルは回して操作するもので、転がすとは言わない。"}, {"text": "太鼓を転がして合図した。", "explanation": "ここは〈叩く〉の意味。太鼓は叩いて鳴らすもので、転がすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転がします", "is_correct": false, "explanation": "丁寧形で、「〜て」の連なりとして「答えを選んだ」に続かない"}, {"text": "転がせ", "is_correct": false, "explanation": "命令形で、回想の文の流れに合わない"}, {"text": "転がしません", "is_correct": false, "explanation": "否定の丁寧形で、文の意味が通らない"}, {"text": "転がして", "is_correct": true, "explanation": "「〜て」で動作を続け、「答えを選んだ」とつながる"}], "explanations": {"転がします": "丁寧形で、「〜て」の連なりとして「答えを選んだ」に続かない", "転がせ": "命令形で、回想の文の流れに合わない", "転がしません": "否定の丁寧形で、文の意味が通らない", "転がして": "「〜て」で動作を続け、「答えを選んだ」とつながる"}, "sentence_index": 6, "correct_answer": "転がして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "包丁を転がして研いだ。", "explanation": "ここは〈研ぐ〉の意味。包丁は砥石で研ぐもので、転がして研ぐとは言わない。"}, {"text": "コップに水を転がして注いだ。", "explanation": "ここは〈注ぐ〉の意味。液体は転がすものではないので、注ぐ動作に転がすは合わない。"}, {"text": "テーブルを布で転がして拭いた。", "explanation": "ここは〈拭く〉の意味。布で拭く動作を転がすで表すのは不自然で、拭くを使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猫は毛糸の玉で転がして遊んでいる。", "corrected_sentence": "猫は毛糸の玉を転がして遊んでいる。", "error_description": "目的語の助詞の誤り。『転がす』は『〜を転がす』なので『で』を『を』にする。『で』は手段や場所を表し、ここには合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "転がす", "is_correct": true, "explanation": "辞書形（『転がすと』という条件の形）"}, {"text": "転がさない", "is_correct": false, "explanation": "否定形になり、ビー玉を転がして進んだという文の流れと合わない"}, {"text": "転がして", "is_correct": false, "explanation": "て形で、「と」に続けると文が成立しない"}, {"text": "転がそう", "is_correct": false, "explanation": "意志形で、起きた出来事を述べる文に合わない"}], "correct_form": "転がす", "base_form": "転がす", "form_label": "辞書形", "sentence_index": 1, "explanations": {"転がす": "辞書形（『転がすと』という条件の形）", "転がさない": "否定形になり、ビー玉を転がして進んだという文の流れと合わない", "転がして": "て形で、「と」に続けると文が成立しない", "転がそう": "意志形で、起きた出来事を述べる文に合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは柔らかい鞠を転がって、廊下の端まで届けた。", "corrected_sentence": "子どもは柔らかい鞠を転がして、廊下の端まで届けた。", "error_description": "自動詞『転がる』の誤り。『鞠を』と目的語があるので、他動詞『転がす』のて形『転がして』にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "転がして", "is_correct": true, "explanation": "て形（『〜してくれた』へ続く形）"}, {"text": "転がします", "is_correct": false, "explanation": "丁寧形で、「〜してくれた」の文と形が合わない"}, {"text": "転がせ", "is_correct": false, "explanation": "命令形で、祖母の行為を述べる文に合わない"}, {"text": "転がしません", "is_correct": false, "explanation": "否定の丁寧形で、行為を述べる文の意味と合わない"}], "correct_form": "転がして", "base_form": "転がす", "form_label": "て形", "sentence_index": 7, "explanations": {"転がして": "て形（『〜してくれた』へ続く形）", "転がします": "丁寧形で、「〜してくれた」の文と形が合わない", "転がせ": "命令形で、祖母の行為を述べる文に合わない", "転がしません": "否定の丁寧形で、行為を述べる文の意味と合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39679, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。ボールを転がしながら進んだという関係を示す"}, {"text": "に", "is_correct": false, "explanation": "「ボールに転がしながら」では目的語の関係が崩れ、意味が通らない"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、目的語の位置に置けない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、目的語の位置には合わない"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。ボールを転がしながら進んだという関係を示す", "に": "「ボールに転がしながら」では目的語の関係が崩れ、意味が通らない", "へ": "方向を表すが、目的語の位置に置けない", "の": "連体修飾の「の」で、目的語の位置には合わない"}, "error_tags": {"に": "接続不可", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
