INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39679, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を回転させながら、ある場所から別の場所へ動かすこと。手や足などを使って、物体を転がす動作を指す。", "primary_collocate": null, "pronunciation": "ころがす", "ipa": "koɾoɡasɯ", "syllable_count": 4, "sentences": [{"text": "重い丸太は持ち上げずに、転がして運んだ。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "重(おも)い丸太(まるた)は持(も)ち上(あ)げずに、転(ころ)がして運(はこ)んだ。", "sentence_source": "generated"}, {"text": "サッカーの練習で、足でボールを転がしながら進んだ。", "target_word": "転がしながら", "complexity_tier": "T3", "furigana": "サッカーの練習(れんしゅう)で、足(あし)でボールを転(ころ)がしながら進(すす)んだ。", "sentence_source": "generated"}, {"text": "倉庫の中で、大きなタイヤを転がして外へ出した。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "倉庫(そうこ)の中(なか)で、大(おお)きなタイヤを転(ころ)がして外(そと)へ出(だ)した。", "sentence_source": "generated"}, {"text": "引っ越しの日、丸い樽を転がして部屋の隅へ動かした。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "引(ひ)っ越(こ)しの日(ひ)、丸(まる)い樽(たる)を転(ころ)がして部屋(へや)の隅(すみ)へ動(うご)かした。", "sentence_source": "generated"}, {"text": "子どもたちは雪の玉を転がして、校庭の端まで運んだ。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "子(こ)どもたちは雪(ゆき)の玉(たま)を転(ころ)がして、校庭(こうてい)の端(はし)まで運(はこ)んだ。", "sentence_source": "generated"}, {"text": "彼はドラム缶を足で転がして、トラックの前まで運んだ。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "彼(かれ)はドラム缶(かん)を足(あし)で転(ころ)がして、トラックの前(まえ)まで運(はこ)んだ。", "sentence_source": "generated"}, {"text": "石が丸いので、転がすと楽に動かせる。", "target_word": "転がす", "complexity_tier": "T3", "furigana": "石(いし)が丸(まる)いので、転(ころ)がすと楽(らく)に動(うご)かせる。", "sentence_source": "generated"}, {"text": "店員は大きなボールを転がして、棚の前に並べた。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "店員(てんいん)は大(おお)きなボールを転(ころ)がして、棚(たな)の前(まえ)に並(なら)べた。", "sentence_source": "generated"}, {"text": "力が弱いので、重い丸い石を転がして動かした。", "target_word": "転がして", "complexity_tier": "T3", "furigana": "力(ちから)が弱(よわ)いので、重(おも)い丸(まる)い石(いし)を転(ころ)がして動(うご)かした。", "sentence_source": "generated"}, {"text": "平らな道では、大きなタイヤを転がすと一人でも運べる。", "target_word": "転がす", "complexity_tier": "T3", "furigana": "平(たい)らな道(みち)では、大(おお)きなタイヤを転(ころ)がすと一人(ひとり)でも運(はこ)べる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "転がす", "label": "辞書形"}, {"form": "転がさない", "label": "否定形"}, {"form": "転がします", "label": "丁寧形"}, {"form": "転がして", "label": "て形"}, {"form": "転がした", "label": "過去形"}, {"form": "転がせば", "label": "仮定形"}, {"form": "転がそう", "label": "意志形"}], "register": "中立（口語・文章どちらでも可）", "sense_fingerprint": "手や足で物を回転させて別の場所へ移動させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39679, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "転がして", "is_correct": true, "explanation": "「〜て」で手段を示し、「運んだ」へ続く"}, {"text": "転がす", "is_correct": false, "explanation": "辞書形のため、「運んだ」へ続く形になっていない"}, {"text": "転がした", "is_correct": false, "explanation": "過去形で、「運んだ」と続けると文の形が崩れる"}, {"text": "転がせば", "is_correct": false, "explanation": "仮定形で、「持ち上げずに」の後の動作描写に合わない"}], "explanations": {"転がして": "「〜て」で手段を示し、「運んだ」へ続く", "転がす": "辞書形のため、「運んだ」へ続く形になっていない", "転がした": "過去形で、「運んだ」と続けると文の形が崩れる", "転がせば": "仮定形で、「持ち上げずに」の後の動作描写に合わない"}, "sentence_index": 0, "correct_answer": "転がして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "引き戸を転がして開けた。", "explanation": "ここは〈押す〉の意味。引き戸は押して開けるもので、転がすとは言わない。"}, {"text": "ネジを転がして締めた。", "explanation": "ここは〈回す〉の意味。ネジは回して締めるもので、転がして締めるとは言わない。"}, {"text": "太鼓を転がして合図した。", "explanation": "ここは〈叩く〉の意味。太鼓は叩いて鳴らすもので、転がすとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39679, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "転がす", "is_correct": true, "explanation": "辞書形で『転がすと』の条件の形になり、『楽に動かせる』へ続く"}, {"text": "転がして", "is_correct": false, "explanation": "て形は『と』に続けられず、条件の文にならない"}, {"text": "転がせ", "is_correct": false, "explanation": "命令形で、『と』に続く条件の文脈に合わない"}, {"text": "転がさせ", "is_correct": false, "explanation": "使役の形で、『と』に続けると意味が通らない"}], "explanations": {"転がす": "辞書形で『転がすと』の条件の形になり、『楽に動かせる』へ続く", "転がして": "て形は『と』に続けられず、条件の文にならない", "転がせ": "命令形で、『と』に続く条件の文脈に合わない", "転がさせ": "使役の形で、『と』に続けると意味が通らない"}, "sentence_index": 6, "correct_answer": "転がす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "包丁を転がして研いだ。", "explanation": "ここは〈研ぐ〉の意味。包丁は砥石で研ぐもので、転がして研ぐとは言わない。"}, {"text": "コップに水を転がして注いだ。", "explanation": "ここは〈注ぐ〉の意味。液体は転がすものではないので、注ぐ動作に転がすは合わない。"}, {"text": "テーブルを布で転がして拭いた。", "explanation": "ここは〈拭く〉の意味。布で拭く動作を転がすで表すのは不自然で、拭くを使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39679, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は古い樽を転がすて、倉庫の奥へ運んだ。", "corrected_sentence": "祖父は古い樽を転がして、倉庫の奥へ運んだ。", "error_description": "て形の誤り。『転がすて』ではなく『転がして』が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "転がしながら", "is_correct": true, "explanation": "ながら形（同時進行を表す形）"}, {"text": "転がさない", "is_correct": false, "explanation": "否定形で、ボールを転がして進んだという文と合わない"}, {"text": "転がした", "is_correct": false, "explanation": "過去形で、同時進行の『ながら』の形になっていない"}, {"text": "転がせば", "is_correct": false, "explanation": "仮定形で、同時進行の文脈に合わない"}], "correct_form": "転がしながら", "base_form": "転がす", "form_label": "ながら形（同時進行）", "sentence_index": 1, "explanations": {"転がしながら": "ながら形（同時進行を表す形）", "転がさない": "否定形で、ボールを転がして進んだという文と合わない", "転がした": "過去形で、同時進行の『ながら』の形になっていない", "転がせば": "仮定形で、同時進行の文脈に合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39679, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは小さな鈴に転がして遊んだ。", "corrected_sentence": "子どもは小さな鈴を転がして遊んだ。", "error_description": "目的語の助詞の誤り。『転がす』は『〜を転がす』なので『に』を『を』にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "転がして", "is_correct": true, "explanation": "て形（『〜して、並べた』と動作を続ける形）"}, {"text": "転がします", "is_correct": false, "explanation": "丁寧形で、続く『並べた』と文の形が合わない"}, {"text": "転がそう", "is_correct": false, "explanation": "意志形で、起きた出来事を述べる文に合わない"}, {"text": "転がせ", "is_correct": false, "explanation": "命令形で、店員の行為を述べる文に合わない"}], "correct_form": "転がして", "base_form": "転がす", "form_label": "て形", "sentence_index": 7, "explanations": {"転がして": "て形（『〜して、並べた』と動作を続ける形）", "転がします": "丁寧形で、続く『並べた』と文の形が合わない", "転がそう": "意志形で、起きた出来事を述べる文に合わない", "転がせ": "命令形で、店員の行為を述べる文に合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大嫌い", "is_correct": true, "explanation": "「大好き」の反対で、同じ強さで好みの反対を表す語。"}, {"text": "大切", "is_correct": false, "explanation": "大事にする意味で、好きの反対語ではない。"}, {"text": "大丈夫", "is_correct": false, "explanation": "問題ないことを表し、好き嫌いとは関係ない。"}, {"text": "大変", "is_correct": false, "explanation": "大きな困難を表し、好みの反対語ではない。"}], "correct_answer": "大嫌い", "explanations": {"大嫌い": "「大好き」の反対で、同じ強さで好みの反対を表す語。", "大切": "大事にする意味で、好きの反対語ではない。", "大丈夫": "問題ないことを表し、好き嫌いとは関係ない。", "大変": "大きな困難を表し、好みの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大嫌い", "is_correct": true, "explanation": "「大好き」の反対で、同じ強さで好みの反対を表す語。"}, {"text": "大人気", "is_correct": false, "explanation": "多くの人に好まれることを表し、個人の好みの反対語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "物事を恐れない性格を表し、好きの反対語ではない。"}, {"text": "大ざっぱ", "is_correct": false, "explanation": "細かくないさまを表し、好き嫌いとは関係ない。"}], "correct_answer": "大嫌い", "explanations": {"大嫌い": "「大好き」の反対で、同じ強さで好みの反対を表す語。", "大人気": "多くの人に好まれることを表し、個人の好みの反対語ではない。", "大胆": "物事を恐れない性格を表し、好きの反対語ではない。", "大ざっぱ": "細かくないさまを表し、好き嫌いとは関係ない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "大好きは、何かをとても好きなことです。", "primary_collocate": null, "pronunciation": "だいすき", "ipa": "daisɯki", "syllable_count": 4, "sentences": [{"text": "私は犬が大好きです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "私[わたし]は犬[いぬ]が大好[だいす]きです。", "sentence_source": "generated"}, {"text": "妹は甘いお菓子が大好きで、毎日食べます。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "妹[いもうと]は甘[あま]いお菓子[かし]が大好[だいす]きで、毎日[まいにち]食[た]べます。", "sentence_source": "generated"}, {"text": "田中さんは大好きな歌手のコンサートに行きました。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "田中[たなか]さんは大好[だいす]きな歌手[かしゅ]のコンサートに行[い]きました。", "sentence_source": "generated"}, {"text": "弟は電車が大好きなので、駅でいつも写真を撮ります。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "弟[おとうと]は電車[でんしゃ]が大好[だいす]きなので、駅[えき]でいつも写真[しゃしん]を撮[と]ります。", "sentence_source": "generated"}, {"text": "母の作るカレーが大好きです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "母[はは]の作[つく]るカレーが大好[だいす]きです。", "sentence_source": "generated"}, {"text": "私は雨の日に本を読むのが大好きです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "私[わたし]は雨[あめ]の日[ひ]に本[ほん]を読[よ]むのが大好[だいす]きです。", "sentence_source": "generated"}, {"text": "祖父は釣りが大好きで、休みの日は海へ行きます。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "祖父[そふ]は釣[つ]りが大好[だいす]きで、休[やす]みの日[ひ]は海[うみ]へ行[い]きます。", "sentence_source": "generated"}, {"text": "子どもたちは先生のことが大好きです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "子[こ]どもたちは先生[せんせい]のことが大好[だいす]きです。", "sentence_source": "generated"}, {"text": "大好きな色は青なので、青い鞄を買いました。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "大好[だいす]きな色[いろ]は青[あお]なので、青[あお]い鞄[かばん]を買[か]いました。", "sentence_source": "generated"}, {"text": "彼女は猫が大好きだから、家に三匹もいます。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は猫[ねこ]が大好[だいす]きだから、家[いえ]に三匹[さんびき]もいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大好きだ", "label": "終止形"}, {"form": "大好きな", "label": "連体形"}, {"form": "大好きで", "label": "連用形（で）"}, {"form": "大好きに", "label": "連用形（に）"}], "register": "中立（丁寧体）", "sense_fingerprint": "人・物・事をとても好きだという気持ちの状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大好き", "is_correct": true, "explanation": "形状詞の基本形。「犬が大好きです」で好みの対象を表せる。"}, {"text": "大好評", "is_correct": false, "explanation": "評判が良いことを表す語で、動物の好みは表せないので「犬が大好評です」は不自然。"}, {"text": "大好物", "is_correct": false, "explanation": "好きな食べ物を指す語で、犬は対象にならない。"}, {"text": "大好演", "is_correct": false, "explanation": "演技の出来を褒める語で、「犬」とは合わない。"}], "explanations": {"大好き": "形状詞の基本形。「犬が大好きです」で好みの対象を表せる。", "大好評": "評判が良いことを表す語で、動物の好みは表せないので「犬が大好評です」は不自然。", "大好物": "好きな食べ物を指す語で、犬は対象にならない。", "大好演": "演技の出来を褒める語で、「犬」とは合わない。"}, "sentence_index": 0, "correct_answer": "大好き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の会議の参加者は大好きで、三十人でした。", "explanation": "ここは〈大勢〉の意味。〈大好き〉は好きの気持ちを表し、人数の多さは表さないので、ここでは合わない。"}, {"text": "この箱の大好きは十キロです。", "explanation": "ここは〈重さ〉の意味。〈大好き〉は好きの強さを表す語で、箱の重さは表さないので合わない。"}, {"text": "この料理は少し大好きです。", "explanation": "ここは〈ふつうの好み〉の意味。〈大好き〉は程度が非常に強いので、「少し」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大好き", "is_correct": true, "explanation": "「釣りが大好きで」の形。好みの対象を表す正しい用法。"}, {"text": "大忙し", "is_correct": false, "explanation": "忙しい様子を表し、釣りの好みは表せない。"}, {"text": "大食漢", "is_correct": false, "explanation": "大食いの人を指す名詞で、釣りには当てはまらない。"}, {"text": "大勝利", "is_correct": false, "explanation": "勝ったことを指す語で、ここでは意味が通らない。"}], "explanations": {"大好き": "「釣りが大好きで」の形。好みの対象を表す正しい用法。", "大忙し": "忙しい様子を表し、釣りの好みは表せない。", "大食漢": "大食いの人を指す名詞で、釣りには当てはまらない。", "大勝利": "勝ったことを指す語で、ここでは意味が通らない。"}, "sentence_index": 6, "correct_answer": "大好き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新製品は大好きで、店の前に行列ができています。", "explanation": "ここは〈大好評〉の意味。人気の高さは〈大好評〉で表し、個人の好みを表す〈大好き〉は合わない。"}, {"text": "この薬は頭痛が大好きです。", "explanation": "ここは〈大嫌い〉の意味。頭痛は好む対象ではないので、好きの気持ちを表す〈大好き〉は合わない。"}, {"text": "試験の日程は大好きで、来週に決まりました。", "explanation": "ここは〈日取り〉の意味。〈大好き〉は好きの気持ちを表すので、日取りの説明には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は猫を大好きです。", "corrected_sentence": "私は猫が大好きです。", "error_description": "格助詞の誤り。「大好き」は「〜が大好き」と「が」をとるので、「を」は誤り。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大好き", "is_correct": true, "explanation": "文中の「大好きで」の語幹にあたる形。連用形「で」の前の部分。"}, {"text": "大好きだ", "is_correct": false, "explanation": "終止形。「で」が続く文では使えない。"}, {"text": "大好きな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、ここでは使えない。"}, {"text": "大好きに", "is_correct": false, "explanation": "連用形「に」。「で」の位置には合わない。"}], "correct_form": "大好き", "base_form": "大好き", "form_label": "連用形（で）", "sentence_index": 1, "explanations": {"大好き": "文中の「大好きで」の語幹にあたる形。連用形「で」の前の部分。", "大好きだ": "終止形。「で」が続く文では使えない。", "大好きな": "連体形。名詞を修飾する形で、ここでは使えない。", "大好きに": "連用形「に」。「で」の位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39680, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は釣りが大好き、週末は海へ行きます。", "corrected_sentence": "祖父は釣りが大好きで、週末は海へ行きます。", "error_description": "連用形の誤り。「大好き」の後には「で」が必要で、「、」だけでは文がつながらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大好き", "is_correct": true, "explanation": "「〜が大好きです」の「大好き」にあたる語幹の形。"}, {"text": "大好きで", "is_correct": false, "explanation": "連用形「で」。「です」の位置には入らない。"}, {"text": "大好きだった", "is_correct": false, "explanation": "過去の形。現在の好みを表す文では使えない。"}, {"text": "大好きでした", "is_correct": false, "explanation": "丁寧な過去形。現在の好みを表す文では使えない。"}], "correct_form": "大好き", "base_form": "大好き", "form_label": "丁寧形", "sentence_index": 7, "explanations": {"大好き": "「〜が大好きです」の「大好き」にあたる語幹の形。", "大好きで": "連用形「で」。「です」の位置には入らない。", "大好きだった": "過去の形。現在の好みを表す文では使えない。", "大好きでした": "丁寧な過去形。現在の好みを表す文では使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大嫌い", "is_correct": true, "explanation": "「大好き」の反対で、同じ強さで好みの反対を表す語。"}, {"text": "大切", "is_correct": false, "explanation": "大事にする意味で、好きの反対語ではない。"}, {"text": "大丈夫", "is_correct": false, "explanation": "問題ないことを表し、好き嫌いとは関係ない。"}, {"text": "大変", "is_correct": false, "explanation": "大きな困難を表し、好みの反対語ではない。"}], "correct_answer": "大嫌い", "explanations": {"大嫌い": "「大好き」の反対で、同じ強さで好みの反対を表す語。", "大切": "大事にする意味で、好きの反対語ではない。", "大丈夫": "問題ないことを表し、好き嫌いとは関係ない。", "大変": "大きな困難を表し、好みの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大嫌い", "is_correct": true, "explanation": "「大好き」の反対で、同じ強さで好みの反対を表す語。"}, {"text": "大人気", "is_correct": false, "explanation": "多くの人に好まれることを表し、個人の好みの反対語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "物事を恐れない性格を表し、好きの反対語ではない。"}, {"text": "大ざっぱ", "is_correct": false, "explanation": "細かくないさまを表し、好き嫌いとは関係ない。"}], "correct_answer": "大嫌い", "explanations": {"大嫌い": "「大好き」の反対で、同じ強さで好みの反対を表す語。", "大人気": "多くの人に好まれることを表し、個人の好みの反対語ではない。", "大胆": "物事を恐れない性格を表し、好きの反対語ではない。", "大ざっぱ": "細かくないさまを表し、好き嫌いとは関係ない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "大好きは、非常に好きであること、またはその気持ちを表す語。", "primary_collocate": null, "pronunciation": "だいすき", "ipa": "daisɯki", "syllable_count": 4, "sentences": [{"text": "手紙に「あなたが大好きです」と書きました。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "手紙[てがみ]に「あなたが大好[だいす]きです」と書[か]きました。", "sentence_source": "generated"}, {"text": "大好きな友達と旅行ができて、楽しかったです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "大好[だいす]きな友達[ともだち]と旅行[りょこう]ができて、楽[たの]しかったです。", "sentence_source": "generated"}, {"text": "彼は音楽が大好きで、毎晩ギターを弾いています。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "彼[かれ]は音楽[おんがく]が大好[だいす]きで、毎晩[まいばん]ギターを弾[ひ]いています。", "sentence_source": "generated"}, {"text": "大好きな先生が学校をやめるので、悲しいです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "大好[だいす]きな先生[せんせい]が学校[がっこう]をやめるので、悲[かな]しいです。", "sentence_source": "generated"}, {"text": "私は海が大好きだから、夏はよく泳ぎに行きます。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "私[わたし]は海[うみ]が大好[だいす]きだから、夏[なつ]はよく泳[およ]ぎに行[い]きます。", "sentence_source": "generated"}, {"text": "大好きなゲームをしているとき、時間を忘れます。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "大好[だいす]きなゲームをしているとき、時間[じかん]を忘[わす]れます。", "sentence_source": "generated"}, {"text": "娘は絵を描くことが大好きで、毎日描いています。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "娘[むすめ]は絵[え]を描[か]くことが大好[だいす]きで、毎日[まいにち]描[か]いています。", "sentence_source": "generated"}, {"text": "大好きな人にプレゼントを渡すとき、少し緊張しました。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "大好[だいす]きな人[ひと]にプレゼントを渡[わた]すとき、少[すこ]し緊張[きんちょう]しました。", "sentence_source": "generated"}, {"text": "私は子どものころから、この町が大好きでした。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "私[わたし]は子[こ]どものころから、この町[まち]が大好[だいす]きでした。", "sentence_source": "generated"}, {"text": "大好きなケーキを食べたので、今日は幸せです。", "target_word": "大好き", "complexity_tier": "T3", "furigana": "大好[だいす]きなケーキを食[た]べたので、今日[きょう]は幸[しあわ]せです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大好きだ", "label": "終止形"}, {"form": "大好きな", "label": "連体形"}, {"form": "大好きで", "label": "連用形（で）"}, {"form": "大好きでした", "label": "丁寧な過去形"}], "register": "中立（丁寧体）", "sense_fingerprint": "非常に好きであること、またはその気持ちを表す語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大好き", "is_correct": true, "explanation": "「あなたが大好きです」で好意の対象を表す正しい用法。"}, {"text": "大好評", "is_correct": false, "explanation": "評判が良いことを表す語で、人への気持ちは表せない。"}, {"text": "大好物", "is_correct": false, "explanation": "好きな食べ物を指す語で、人には使えない。"}, {"text": "大好演", "is_correct": false, "explanation": "演技の出来を褒める語で、この文の「あなた」とは合わない。"}], "explanations": {"大好き": "「あなたが大好きです」で好意の対象を表す正しい用法。", "大好評": "評判が良いことを表す語で、人への気持ちは表せない。", "大好物": "好きな食べ物を指す語で、人には使えない。", "大好演": "演技の出来を褒める語で、この文の「あなた」とは合わない。"}, "sentence_index": 0, "correct_answer": "大好き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬の大好きは五百円です。", "explanation": "ここは〈値段〉の意味。〈大好き〉は好きの強さを表す語で、金額は表さないので合わない。"}, {"text": "この箱の大好きは縦三十センチです。", "explanation": "ここは〈大きさ〉の意味。〈大好き〉は好きの強さを表すので、箱の寸法は表さない。"}, {"text": "先生が少し大好きです。", "explanation": "ここは〈ふつうの好み〉の意味。〈大好き〉は程度が非常に強いので、「少し」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大好き", "is_correct": true, "explanation": "「絵を描くことが大好きで」の形。好みを表す正しい用法。"}, {"text": "大食漢", "is_correct": false, "explanation": "大食いの人を指す名詞で、絵には当てはまらない。"}, {"text": "大勝利", "is_correct": false, "explanation": "勝ったことを指す語で、ここでは意味が通らない。"}, {"text": "大忙し", "is_correct": false, "explanation": "忙しい様子を表し、絵を描く好みは表せない。"}], "explanations": {"大好き": "「絵を描くことが大好きで」の形。好みを表す正しい用法。", "大食漢": "大食いの人を指す名詞で、絵には当てはまらない。", "大勝利": "勝ったことを指す語で、ここでは意味が通らない。", "大忙し": "忙しい様子を表し、絵を描く好みは表せない。"}, "sentence_index": 6, "correct_answer": "大好き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この新製品は大好きで、店の前に行列ができています。", "explanation": "ここは〈大好評〉の意味。人気の高さは〈大好評〉で表し、個人の好みを表す〈大好き〉は合わない。"}, {"text": "この薬は頭痛が大好きです。", "explanation": "ここは〈大嫌い〉の意味。頭痛は好む対象ではないので、好きの気持ちを表す〈大好き〉は合わない。"}, {"text": "この注文の大好きは三日です。", "explanation": "ここは〈届くまでの日数〉の意味。〈大好き〉は好きの強さを表すので、日数は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は音楽を大好きです。", "corrected_sentence": "彼は音楽が大好きです。", "error_description": "格助詞の誤り。「大好き」は「〜が大好き」と「が」をとるので、「を」は誤り。正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "大好き", "is_correct": true, "explanation": "「大好きな友達」の連体形の語幹にあたる形。"}, {"text": "大好きだ", "is_correct": false, "explanation": "終止形。名詞を修飾する文では使えない。"}, {"text": "大好きに", "is_correct": false, "explanation": "連用形「に」。名詞を修飾する位置には合わない。"}, {"text": "大好きでした", "is_correct": false, "explanation": "丁寧な過去形。名詞を修飾する位置には合わない。"}], "correct_form": "大好き", "base_form": "大好き", "form_label": "連体形", "sentence_index": 1, "explanations": {"大好き": "「大好きな友達」の連体形の語幹にあたる形。", "大好きだ": "終止形。名詞を修飾する文では使えない。", "大好きに": "連用形「に」。名詞を修飾する位置には合わない。", "大好きでした": "丁寧な過去形。名詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39681, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "娘は絵を描くことが大好き、毎晩描いています。", "corrected_sentence": "娘は絵を描くことが大好きで、毎晩描いています。", "error_description": "連用形の誤り。「大好き」の後には「で」が必要で、「、」だけでは文がつながらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "大好き", "is_correct": true, "explanation": "「大好きな人」の連体形の語幹にあたる形。"}, {"text": "大好きで", "is_correct": false, "explanation": "連用形「で」。名詞を修飾する位置には合わない。"}, {"text": "大好きだった", "is_correct": false, "explanation": "過去の形。現在の好みを述べる文では使えない。"}, {"text": "大好きな", "is_correct": false, "explanation": "連体形の語尾まで含んだ形で、語幹の位置には合わない。"}], "correct_form": "大好き", "base_form": "大好き", "form_label": "連体形", "sentence_index": 7, "explanations": {"大好き": "「大好きな人」の連体形の語幹にあたる形。", "大好きで": "連用形「で」。名詞を修飾する位置には合わない。", "大好きだった": "過去の形。現在の好みを述べる文では使えない。", "大好きな": "連体形の語尾まで含んだ形で、語幹の位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
