INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39682, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「B」は、アルファベットの二番目の文字です。", "primary_collocate": null, "pronunciation": "びー", "ipa": "biː", "syllable_count": 2, "sentences": [{"text": "アルファベットでAの次に来る文字は「B」だ。", "target_word": "B", "complexity_tier": "T3", "furigana": "アルファベットでAの次[つぎ]に来[く]る文字[もじ]は「B」だ。", "sentence_source": "generated"}, {"text": "私の名前は「B」から始まるので、名簿では前のほうに載る。", "target_word": "B", "complexity_tier": "T3", "furigana": "私[わたし]の名前[なまえ]は「B」から始[はじ]まるので、名簿[めいぼ]では前[まえ]のほうに載[の]る。", "sentence_source": "generated"}, {"text": "辞書で「B」から始まる単語を探すには、Aの次の部分を開く。", "target_word": "B", "complexity_tier": "T3", "furigana": "辞書[じしょ]で「B」から始[はじ]まる単語[たんご]を探[さが]すには、Aの次[つぎ]の部分[ぶぶん]を開[ひら]く。", "sentence_source": "generated"}, {"text": "黒板にAと「B」を書いて、文字の順番を子どもに教えた。", "target_word": "B", "complexity_tier": "T3", "furigana": "黒板[こくばん]にAと「B」を書[か]いて、文字[もじ]の順番[じゅんばん]を子[こ]どもに教[おし]えた。", "sentence_source": "generated"}, {"text": "小文字のbは、大文字の「B」と形が少し違う。", "target_word": "B", "complexity_tier": "T3", "furigana": "小文字[こもじ]のbは、大文字[おおもじ]の「B」と形[かたち]が少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "アルファベットの歌で、Aのあとに歌われるのは「B」だ。", "target_word": "B", "complexity_tier": "T3", "furigana": "アルファベットの歌[うた]で、Aのあとに歌[うた]われるのは「B」だ。", "sentence_source": "generated"}, {"text": "縦の線に丸い山を二つ付けると、「B」の形になる。", "target_word": "B", "complexity_tier": "T3", "furigana": "縦[たて]の線[せん]に丸[まる]い山[やま]を二[ふた]つ付[つ]けると、「B」の形[かたち]になる。", "sentence_source": "generated"}, {"text": "二番目の棚には、「B」と書かれた札が貼ってある。", "target_word": "B", "complexity_tier": "T3", "furigana": "二番目[にばんめ]の棚[たな]には、「B」と書[か]かれた札[ふだ]が貼[は]ってある。", "sentence_source": "generated"}, {"text": "「アルファベットの二番目の文字は『B』です」と先生が説明した。", "target_word": "B", "complexity_tier": "T3", "furigana": "「アルファベットの二番目[にばんめ]の文字[もじ]は『B』です」と先生[せんせい]が説明[せつめい]した。", "sentence_source": "generated"}, {"text": "名簿はAの人が先で、「B」の人が二番目に呼ばれた。", "target_word": "B", "complexity_tier": "T3", "furigana": "名簿[めいぼ]はAの人[ひと]が先[さき]で、「B」の人[ひと]が二番目[にばんめ]に呼[よ]ばれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "B", "label": "大文字"}, {"form": "b", "label": "小文字"}], "register": "中立", "sense_fingerprint": "アルファベットの順番で二番目にあたる文字(大文字)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39682, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "B", "is_correct": true, "explanation": "アルファベットでAの次に来る文字はBで、ここに入るのはこれだけ。"}, {"text": "A", "is_correct": false, "explanation": "Aは一番目の文字なので、Aの次に来る文字にはならない。"}, {"text": "1", "is_correct": false, "explanation": "数字であり、アルファベットの文字の順番には入らない。"}, {"text": "☆", "is_correct": false, "explanation": "記号で、アルファベットの文字ではないので合わない。"}], "explanations": {"B": "アルファベットでAの次に来る文字はBで、ここに入るのはこれだけ。", "A": "Aは一番目の文字なので、Aの次に来る文字にはならない。", "1": "数字であり、アルファベットの文字の順番には入らない。", "☆": "記号で、アルファベットの文字ではないので合わない。"}, "sentence_index": 0, "correct_answer": "B"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に「B」が飛んでいて、怖かった。", "explanation": "ここは〈蜂〉の意味。「B」は文字の記号で、虫の名前としては使わない。"}, {"text": "寒い夜は、「B」に乗って家まで帰った。", "explanation": "ここは〈バス〉の意味。「B」は文字で、乗り物の名前としては使わない。"}, {"text": "雨が降ってきたので、「B」を広げて歩いた。", "explanation": "ここは〈傘〉の意味。「B」は文字で、雨具の名前としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39682, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "B", "is_correct": true, "explanation": "縦線と二つの丸い山でできる文字で、説明の形と一致する。"}, {"text": "E", "is_correct": false, "explanation": "横線を三本並べた文字で、丸い山はない。"}, {"text": "I", "is_correct": false, "explanation": "縦線だけの文字で、丸い山を付けた形ではない。"}, {"text": "P", "is_correct": false, "explanation": "丸い山が一つだけの文字で、「二つ付けると」とは合わない。"}], "explanations": {"B": "縦線と二つの丸い山でできる文字で、説明の形と一致する。", "E": "横線を三本並べた文字で、丸い山はない。", "I": "縦線だけの文字で、丸い山を付けた形ではない。", "P": "丸い山が一つだけの文字で、「二つ付けると」とは合わない。"}, "sentence_index": 6, "correct_answer": "B"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舌先を上の歯の裏に付けて出す音は、「B」で表す。", "explanation": "舌先で出す音はDで表す。Bは唇を閉じて出す音なので、ここでは合わない。"}, {"text": "夕方の公園で、「B」を追いかけて子どもたちが走り回った。", "explanation": "ここは〈ボール〉の意味。「B」は文字で、遊び道具の名前ではない。"}, {"text": "毎朝「B」を一本食べてから学校へ行く。", "explanation": "ここは〈バナナ〉の意味。「B」は文字で、果物の名前としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39682, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黒板に「B」を書かれた。", "corrected_sentence": "黒板に「B」を書いた。", "error_description": "能動の「書いた」を受け身の「書かれた」にした。「B」は自分で書く対象なので、受け身の形では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39682, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ローマ字では「B」が書く。", "corrected_sentence": "ローマ字では「B」と書く。", "error_description": "書く対象を示す「と」を主語の「が」にした。「B」は書かれるものなので「と」が正しく、「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
