INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39683, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「B」は、英語のアルファベットの2番目の文字で、音を表す記号です。", "primary_collocate": null, "pronunciation": "びー", "ipa": "biː", "syllable_count": 2, "sentences": [{"text": "英語の「B」は、唇を閉じてから息を出して発音する。", "target_word": "B", "complexity_tier": "T3", "furigana": "英語[えいご]の「B」は、唇[くちびる]を閉[と]じてから息[いき]を出[だ]して発音[はつおん]する。", "sentence_source": "generated"}, {"text": "「ベッド」の最初の音は、英語では「B」で表す。", "target_word": "B", "complexity_tier": "T3", "furigana": "「ベッド」の最初[さいしょ]の音[おと]は、英語[えいご]では「B」で表[あらわ]す。", "sentence_source": "generated"}, {"text": "日本語のバ行の子音は、ローマ字で「B」と書く。", "target_word": "B", "complexity_tier": "T3", "furigana": "日本語[にほんご]のバ行[ぎょう]の子音[しいん]は、ローマ字[じ]で「B」と書[か]く。", "sentence_source": "generated"}, {"text": "辞書の発音記号では、「B」は濁った唇の音を表す。", "target_word": "B", "complexity_tier": "T3", "furigana": "辞書[じしょ]の発音記号[はつおんきごう]では、「B」は濁[にご]った唇[くちびる]の音[おと]を表[あらわ]す。", "sentence_source": "generated"}, {"text": "「B」の音は、のどを震わせて出すので、手を当てると分かる。", "target_word": "B", "complexity_tier": "T3", "furigana": "「B」の音[おと]は、のどを震[ふる]わせて出[だ]すので、手[て]を当[あ]てると分[わ]かる。", "sentence_source": "generated"}, {"text": "「ボール」をローマ字で書くと、最初の音を表すのは「B」だ。", "target_word": "B", "complexity_tier": "T3", "furigana": "「ボール」をローマ字[じ]で書[か]くと、最初[さいしょ]の音[おと]を表[あらわ]すのは「B」だ。", "sentence_source": "generated"}, {"text": "Pと「B」は唇の使い方が同じだが、声を出すかどうかが違う。", "target_word": "B", "complexity_tier": "T3", "furigana": "Pと「B」は唇[くちびる]の使[つか]い方[かた]が同[おな]じだが、声[こえ]を出[だ]すかどうかが違[ちが]う。", "sentence_source": "generated"}, {"text": "外国人の名前を聞いたとき、「B」の音がはっきり聞こえなかった。", "target_word": "B", "complexity_tier": "T3", "furigana": "外国人[がいこくじん]の名前[なまえ]を聞[き]いたとき、「B」の音[おと]がはっきり聞[き]こえなかった。", "sentence_source": "generated"}, {"text": "英語の綴りでは、「B」は語末で発音されない場合もある。", "target_word": "B", "complexity_tier": "T3", "furigana": "英語[えいご]の綴[つづ]りでは、「B」は語末[ごまつ]で発音[はつおん]されない場合[ばあい]もある。", "sentence_source": "generated"}, {"text": "子どもに「『B』はブ、と唇を閉じて出す音だよ」と教えた。", "target_word": "B", "complexity_tier": "T3", "furigana": "子[こ]どもに「『B』はブ、と唇[くちびる]を閉[と]じて出[だ]す音[おと]だよ」と教[おし]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "B", "label": "大文字"}, {"form": "b", "label": "小文字"}], "register": "中立", "sense_fingerprint": "英語で唇を閉じて出す有声の音を表す文字・記号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): バ (Zipf 3.68), 子音 (Zipf 2.87), ローマ字 (Zipf 3.37)','sentence 3 above tier T1: 3 words above tier T1 (max 2): 辞書 (Zipf 3.98), 記号 (Zipf 3.85), 濁っ (Zipf 2.99)','sentence 4 above tier T1: 3 words above tier T1 (max 2): のど (Zipf 3.82), 震わせ (Zipf 2.77), 当てる (Zipf 3.92)']::text[], 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39683, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "B", "is_correct": true, "explanation": "唇を閉じて息を出す音で、両唇の有声音はBを指す。"}, {"text": "D", "is_correct": false, "explanation": "舌先を歯茎に当てて出す音で、唇は使わない。"}, {"text": "G", "is_correct": false, "explanation": "のどの奥で出す音で、唇を閉じる音ではない。"}, {"text": "T", "is_correct": false, "explanation": "舌先で出す無声音で、唇の動きとは関係ない。"}], "explanations": {"B": "唇を閉じて息を出す音で、両唇の有声音はBを指す。", "D": "舌先を歯茎に当てて出す音で、唇は使わない。", "G": "のどの奥で出す音で、唇を閉じる音ではない。", "T": "舌先で出す無声音で、唇の動きとは関係ない。"}, "sentence_index": 0, "correct_answer": "B"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この鉛筆は「B」なので、やわらかくて字が濃く書ける。", "explanation": "ここは〈鉛筆の濃さ〉（やわらかく濃い芯の種類）の意味。音を表す記号ではない。"}, {"text": "窓の外で「B」が鳴いていて、なかなか眠れなかった。", "explanation": "ここは〈蜂〉の意味。「B」は音を表す記号で、虫の名前ではない。"}, {"text": "雨が降ってきたので、「B」を広げて歩いた。", "explanation": "ここは〈傘〉の意味。「B」は音を表す記号で、雨具の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39683, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "B", "is_correct": true, "explanation": "唇を閉じて声を出す音で、Pと唇の使い方が同じなのはBの方。"}, {"text": "K", "is_correct": false, "explanation": "のどの奥で出す音で、唇は使わない。"}, {"text": "N", "is_correct": false, "explanation": "鼻に抜ける音で、唇を閉じて出す音ではない。"}, {"text": "S", "is_correct": false, "explanation": "歯の間から息を出す音で、唇とは関係ない。"}], "explanations": {"B": "唇を閉じて声を出す音で、Pと唇の使い方が同じなのはBの方。", "K": "のどの奥で出す音で、唇は使わない。", "N": "鼻に抜ける音で、唇を閉じて出す音ではない。", "S": "歯の間から息を出す音で、唇とは関係ない。"}, "sentence_index": 6, "correct_answer": "B"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "文房具店で「B」の鉛筆を三本買った。", "explanation": "ここは〈鉛筆の濃さ〉（芯の種類）の意味。音を表す記号ではない。"}, {"text": "夕方の公園で、「B」を追いかけて子どもたちが走り回った。", "explanation": "ここは〈ボール〉の意味。「B」は音を表す記号で、遊び道具の名前ではない。"}, {"text": "毎朝「B」を一本食べてから学校へ行く。", "explanation": "ここは〈バナナ〉の意味。「B」は音を表す記号で、果物の名前ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39683, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "唇を閉じて、英語の「B」に発音する。", "corrected_sentence": "唇を閉じて、英語の「B」を発音する。", "error_description": "「発音する」の対象を示す「を」を「に」にした。「発音する」は「を」で対象を取るので、「に」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39683, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "「B」が音は、唇を閉じて出す。", "corrected_sentence": "「B」の音は、唇を閉じて出す。", "error_description": "「音」を修飾する連体修飾の「の」を主語の「が」にした。「B」が音を修飾する形が必要で、「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。吊り革を掴んだという関係を示す"}, {"text": "に", "is_correct": false, "explanation": "「吊り革に掴んだ」では目的語の関係が成立しない"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、掴むの目的語には使えない"}, {"text": "と", "is_correct": false, "explanation": "「吊り革と掴んだ」では並列にも目的語にもならない"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。吊り革を掴んだという関係を示す", "に": "「吊り革に掴んだ」では目的語の関係が成立しない", "へ": "方向を表すが、掴むの目的語には使えない", "と": "「吊り革と掴んだ」では並列にも目的語にもならない"}, "error_tags": {"に": "接続不可", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "対義語。掴む（握って離さない）の反対で、握っていたものを手から離すこと"}, {"text": "押す", "is_correct": false, "explanation": "力を加えて動かす動作で、掴むの対義語ではない"}, {"text": "叩く", "is_correct": false, "explanation": "強く打つ動作で、掴むの対義語ではない"}, {"text": "包む", "is_correct": false, "explanation": "周りを覆う動作で、掴むの対義語ではない"}], "correct_answer": "放す", "explanations": {"放す": "対義語。掴む（握って離さない）の反対で、握っていたものを手から離すこと", "押す": "力を加えて動かす動作で、掴むの対義語ではない", "叩く": "強く打つ動作で、掴むの対義語ではない", "包む": "周りを覆う動作で、掴むの対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。猫の首の後ろを掴んだという関係を示す"}, {"text": "が", "is_correct": false, "explanation": "「首の後ろが掴んで」では主語と動詞が成立しない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、動詞の直前には置けない"}, {"text": "と", "is_correct": false, "explanation": "「首の後ろと掴んで」では並列にも引用にもならず、文が成立しない"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。猫の首の後ろを掴んだという関係を示す", "が": "「首の後ろが掴んで」では主語と動詞が成立しない", "の": "連体修飾の「の」で、動詞の直前には置けない", "と": "「首の後ろと掴んで」では並列にも引用にもならず、文が成立しない"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "並列・引用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "対義語。掴む（握って離さない）の反対で、腕を掴んでいたものを離すこと"}, {"text": "投げる", "is_correct": false, "explanation": "物を放り出す動作で、掴むの対義語ではない"}, {"text": "撫でる", "is_correct": false, "explanation": "軽く触れる動作で、掴むの対義語ではない"}, {"text": "描く", "is_correct": false, "explanation": "絵や線を書く動作で、掴むの対義語ではない"}], "correct_answer": "放す", "explanations": {"放す": "対義語。掴む（握って離さない）の反対で、腕を掴んでいたものを離すこと", "投げる": "物を放り出す動作で、掴むの対義語ではない", "撫でる": "軽く触れる動作で、掴むの対義語ではない", "描く": "絵や線を書く動作で、掴むの対義語ではない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手で物をしっかり持つこと。", "primary_collocate": null, "pronunciation": "つかむ", "ipa": "tsɯkamɯ", "syllable_count": 3, "sentences": [{"text": "転びそうになって、手すりをしっかり掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "転(ころ)びそうになって、手(て)すりをしっかり掴(つか)んだ。", "sentence_source": "generated"}, {"text": "電車が揺れたので、吊り革を掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "電車(でんしゃ)が揺(ゆ)れたので、吊(つ)り革(かわ)を掴(つか)んだ。", "sentence_source": "generated"}, {"text": "子どもが母親の手を掴んで、離さなかった。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "子(こ)どもが母親(ははおや)の手(て)を掴(つか)んで、離(はな)さなかった。", "sentence_source": "generated"}, {"text": "魚は滑るので、素手では掴むのが難しい。", "target_word": "掴む", "complexity_tier": "T3", "furigana": "魚(さかな)は滑(すべ)るので、素手(すで)では掴(つか)むのが難(むずか)しい。", "sentence_source": "generated"}, {"text": "彼は落ちてきたボールを片手で掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "彼(かれ)は落(お)ちてきたボールを片手(かたて)で掴(つか)んだ。", "sentence_source": "generated"}, {"text": "風が強いから、帽子をしっかり掴んでいてください。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "風(かぜ)が強(つよ)いから、帽子(ぼうし)をしっかり掴(つか)んでいてください。", "sentence_source": "generated"}, {"text": "川に落ちた人は、投げられたロープを掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "川(かわ)に落(お)ちた人(ひと)は、投(な)げられたロープを掴(つか)んだ。", "sentence_source": "generated"}, {"text": "猫の首の後ろを掴んで、そっと持ち上げた。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "猫(ねこ)の首(くび)の後(うし)ろを掴(つか)んで、そっと持(も)ち上(あ)げた。", "sentence_source": "generated"}, {"text": "荷物の持ち手を掴んだまま、彼は階段を上った。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "荷物(にもつ)の持(も)ち手(て)を掴(つか)んだまま、彼(かれ)は階段(かいだん)を上(のぼ)った。", "sentence_source": "generated"}, {"text": "犯人は逃げようとしたが、警官が腕を掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "犯人(はんにん)は逃(に)げようとしたが、警官(けいかん)が腕(うで)を掴(つか)んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掴む", "label": "辞書形"}, {"form": "掴まない", "label": "否定形"}, {"form": "掴みます", "label": "丁寧形"}, {"form": "掴んで", "label": "て形"}, {"form": "掴んだ", "label": "過去形"}, {"form": "掴めば", "label": "仮定形"}, {"form": "掴もう", "label": "意志形"}], "register": "中立（口語・文章どちらでも可）", "sense_fingerprint": "手で物や体の一部をしっかり握って離さない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掴んだ", "is_correct": true, "explanation": "過去形で、転びそうになった後の出来事として文が成立する"}, {"text": "掴め", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文に合わない"}, {"text": "掴まって", "is_correct": false, "explanation": "自動詞「掴まる」の形で、「を」と合わず文が終わらない"}, {"text": "掴めば", "is_correct": false, "explanation": "仮定形で、文が結果を述べず終わらない"}], "explanations": {"掴んだ": "過去形で、転びそうになった後の出来事として文が成立する", "掴め": "命令形で、過去の出来事を述べる文に合わない", "掴まって": "自動詞「掴まる」の形で、「を」と合わず文が終わらない", "掴めば": "仮定形で、文が結果を述べず終わらない"}, "sentence_index": 0, "correct_answer": "掴んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ご飯をしゃもじで掴んで茶碗に入れた。", "explanation": "ここは〈掬う〉の意味。ご飯はしゃもじで掬うもので、掴むとは言わない。"}, {"text": "コップで水を掴んだ。", "explanation": "ここは〈汲む〉の意味。水は液体で掴めないので、掴むとは言わない。"}, {"text": "顔の前の煙を手で掴んだ。", "explanation": "ここは〈払う〉の意味。煙は手で掴めないので、掴むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掴んだ", "is_correct": true, "explanation": "過去形で、ロープを掴んだ出来事として文が成立する"}, {"text": "掴まれ", "is_correct": false, "explanation": "受身の命令形で、過去の出来事の叙述に合わない"}, {"text": "掴まって", "is_correct": false, "explanation": "自動詞『掴まる』の形で、『を』と合わず文が終わらない"}, {"text": "掴みなさい", "is_correct": false, "explanation": "丁寧な命令で、物語の叙述に合わない"}], "explanations": {"掴んだ": "過去形で、ロープを掴んだ出来事として文が成立する", "掴まれ": "受身の命令形で、過去の出来事の叙述に合わない", "掴まって": "自動詞『掴まる』の形で、『を』と合わず文が終わらない", "掴みなさい": "丁寧な命令で、物語の叙述に合わない"}, "sentence_index": 6, "correct_answer": "掴んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "深呼吸して、空気を掴んだ。", "explanation": "ここは〈吸う〉の意味。空気は掴めないので、掴むとは言わない。"}, {"text": "丘の上で景色を掴んだ。", "explanation": "ここは〈眺める〉の意味。景色は掴めないので、掴むとは言わない。"}, {"text": "うちわで風を掴んだ。", "explanation": "ここは〈送る〉の意味。風は掴めないので、掴むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが祖母の袖に掴んで、ついていった。", "corrected_sentence": "子どもが祖母の袖を掴んで、ついていった。", "error_description": "目的語の助詞の誤り。『掴む』は『〜を掴む』なので『に』を『を』にする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掴んだ", "is_correct": true, "explanation": "過去形（電車が揺れた後の出来事を述べる形）"}, {"text": "掴ませ", "is_correct": false, "explanation": "使役の連用形で、文が完結せず動作の描写にならない"}, {"text": "掴んで", "is_correct": false, "explanation": "て形で、文を終えられず『〜た』の文と合わない"}, {"text": "掴めば", "is_correct": false, "explanation": "仮定形で、実際に起きた出来事の描写に合わない"}], "correct_form": "掴んだ", "base_form": "掴む", "form_label": "過去形", "sentence_index": 1, "explanations": {"掴んだ": "過去形（電車が揺れた後の出来事を述べる形）", "掴ませ": "使役の連用形で、文が完結せず動作の描写にならない", "掴んで": "て形で、文を終えられず『〜た』の文と合わない", "掴めば": "仮定形で、実際に起きた出来事の描写に合わない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39684, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は手すりを掴んて、階段を上った。", "corrected_sentence": "彼は手すりを掴んで、階段を上った。", "error_description": "て形の誤り。『掴んて』の『て』を『で』にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掴んで", "is_correct": true, "explanation": "て形（『そっと持ち上げた』へ続く形）"}, {"text": "掴め", "is_correct": false, "explanation": "命令形で、「そっと持ち上げた」へ続く文にならない"}, {"text": "掴まれ", "is_correct": false, "explanation": "受身の命令形で、文の流れに合わない"}, {"text": "掴ませ", "is_correct": false, "explanation": "使役の語幹で、文が完結せず動作の描写にならない"}], "correct_form": "掴んで", "base_form": "掴む", "form_label": "て形", "sentence_index": 7, "explanations": {"掴んで": "て形（『そっと持ち上げた』へ続く形）", "掴め": "命令形で、「そっと持ち上げた」へ続く文にならない", "掴まれ": "受身の命令形で、文の流れに合わない", "掴ませ": "使役の語幹で、文が完結せず動作の描写にならない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。木の枝を掴んだという関係を示す"}, {"text": "が", "is_correct": false, "explanation": "「木の枝が掴んで」では主語と動詞が成立しない"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、掴むの目的語には使えない"}, {"text": "と", "is_correct": false, "explanation": "「木の枝と掴んで」では目的語の関係にならない"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。木の枝を掴んだという関係を示す", "が": "「木の枝が掴んで」では主語と動詞が成立しない", "へ": "方向を表すが、掴むの目的語には使えない", "と": "「木の枝と掴んで」では目的語の関係にならない"}, "error_tags": {"が": "主語", "へ": "方向", "と": "並列・引用"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "対義語。掴む（握って離さない）の反対で、握っていたものを手から離すこと"}, {"text": "押す", "is_correct": false, "explanation": "力を加えて動かす動作で、掴むの対義語ではない"}, {"text": "叩く", "is_correct": false, "explanation": "強く打つ動作で、掴むの対義語ではない"}, {"text": "包む", "is_correct": false, "explanation": "周りを覆う動作で、掴むの対義語ではない"}], "correct_answer": "放す", "explanations": {"放す": "対義語。掴む（握って離さない）の反対で、握っていたものを手から離すこと", "押す": "力を加えて動かす動作で、掴むの対義語ではない", "叩く": "強く打つ動作で、掴むの対義語ではない", "包む": "周りを覆う動作で、掴むの対義語ではない"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の「を」。荷物を掴んで走ったという関係を示す"}, {"text": "に", "is_correct": false, "explanation": "「荷物に掴んで」では目的語の関係が成立しない"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」で、動詞の直前には置けない"}, {"text": "と", "is_correct": false, "explanation": "「荷物と掴んで」では並列にも引用にもならず、文が成立しない"}], "correct_answer": "を", "explanations": {"を": "目的語の「を」。荷物を掴んで走ったという関係を示す", "に": "「荷物に掴んで」では目的語の関係が成立しない", "の": "連体修飾の「の」で、動詞の直前には置けない", "と": "「荷物と掴んで」では並列にも引用にもならず、文が成立しない"}, "error_tags": {"に": "接続不可", "の": "連体修飾", "と": "並列・引用"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "対義語。掴む（握って離さない）の反対で、リードを握って離さないことの反対"}, {"text": "投げる", "is_correct": false, "explanation": "物を放り出す動作で、掴むの対義語ではない"}, {"text": "撫でる", "is_correct": false, "explanation": "軽く触れる動作で、掴むの対義語ではない"}, {"text": "描く", "is_correct": false, "explanation": "絵や線を書く動作で、掴むの対義語ではない"}], "correct_answer": "放す", "explanations": {"放す": "対義語。掴む（握って離さない）の反対で、リードを握って離さないことの反対", "投げる": "物を放り出す動作で、掴むの対義語ではない", "撫でる": "軽く触れる動作で、掴むの対義語ではない", "描く": "絵や線を書く動作で、掴むの対義語ではない"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手で物をしっかりとつかむ。", "primary_collocate": null, "pronunciation": "つかむ", "ipa": "tsɯkamɯ", "syllable_count": 3, "sentences": [{"text": "赤ちゃんが私の指を小さな手で掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "赤(あか)ちゃんが私(わたし)の指(ゆび)を小(ちい)さな手(て)で掴(つか)んだ。", "sentence_source": "generated"}, {"text": "木の枝を掴んで、急な坂を登った。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "木(き)の枝(えだ)を掴(つか)んで、急(きゅう)な坂(さか)を登(のぼ)った。", "sentence_source": "generated"}, {"text": "人混みではぐれないよう、友達の袖を掴んだ。", "target_word": "掴んだ", "complexity_tier": "T3", "furigana": "人混(ひとご)みではぐれないよう、友達(ともだち)の袖(そで)を掴(つか)んだ。", "sentence_source": "generated"}, {"text": "鳥は鋭い爪で、枝をしっかり掴む。", "target_word": "掴む", "complexity_tier": "T3", "furigana": "鳥(とり)は鋭(するど)い爪(つめ)で、枝(えだ)をしっかり掴(つか)む。", "sentence_source": "generated"}, {"text": "彼女は私の肩を掴んで、大声で呼び止めた。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は私(わたし)の肩(かた)を掴(つか)んで、大声(おおごえ)で呼(よ)び止(と)めた。", "sentence_source": "generated"}, {"text": "崖の途中で、岩を掴んで体を支えた。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "崖(がけ)の途中(とちゅう)で、岩(いわ)を掴(つか)んで体(からだ)を支(ささ)えた。", "sentence_source": "generated"}, {"text": "手が濡れていて、コップをうまく掴めなかった。", "target_word": "掴めなかった", "complexity_tier": "T3", "furigana": "手(て)が濡(ぬ)れていて、コップをうまく掴(つか)めなかった。", "sentence_source": "generated"}, {"text": "荷物を掴んで走り、なんとかバスに間に合った。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "荷物(にもつ)を掴(つか)んで走(はし)り、なんとかバスに間(ま)に合(あ)った。", "sentence_source": "generated"}, {"text": "泳げない弟は、浮き輪を掴んで水に入った。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "泳(およ)げない弟(おとうと)は、浮(う)き輪(わ)を掴(つか)んで水(みず)に入(はい)った。", "sentence_source": "generated"}, {"text": "犬が走り出さないよう、リードを強く掴んで道を渡った。", "target_word": "掴んで", "complexity_tier": "T3", "furigana": "犬(いぬ)が走(はし)り出(だ)さないよう、リードを強(つよ)く掴(つか)んで道(みち)を渡(わた)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "掴む", "label": "辞書形"}, {"form": "掴まない", "label": "否定形"}, {"form": "掴みます", "label": "丁寧形"}, {"form": "掴んで", "label": "て形"}, {"form": "掴んだ", "label": "過去形"}, {"form": "掴めば", "label": "仮定形"}, {"form": "掴もう", "label": "意志形"}], "register": "中立（口語・文章どちらでも可）", "sense_fingerprint": "指や手のひらで対象を握って体を支えたり引き止めたりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26510e11-c7ed-4a43-97f6-44129069f932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掴んだ", "is_correct": true, "explanation": "過去形で、赤ちゃんが指を掴んだ出来事として文が成立する"}, {"text": "掴んで", "is_correct": false, "explanation": "て形のため、文を終えられず叙述として成立しない"}, {"text": "掴め", "is_correct": false, "explanation": "命令形で、出来事の叙述に合わない"}, {"text": "掴もう", "is_correct": false, "explanation": "意志形で、起きた出来事を述べる文に合わない"}], "explanations": {"掴んだ": "過去形で、赤ちゃんが指を掴んだ出来事として文が成立する", "掴んで": "て形のため、文を終えられず叙述として成立しない", "掴め": "命令形で、出来事の叙述に合わない", "掴もう": "意志形で、起きた出来事を述べる文に合わない"}, "sentence_index": 0, "correct_answer": "掴んだ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ピアノの鍵盤を掴んで、曲を弾いた。", "explanation": "ここは〈弾く〉の意味。鍵盤は指で弾くもので、掴むとは言わない。"}, {"text": "深く空気を掴んだ。", "explanation": "ここは〈吸う〉の意味。空気は掴めないので、掴むとは言わない。"}, {"text": "顔の前の煙を掴んだ。", "explanation": "ここは〈払う〉の意味。煙は掴めないので、掴むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掴めなかった", "is_correct": true, "explanation": "過去の否定形で、手が濡れていて掴めなかったという文脈に合う"}, {"text": "掴まれ", "is_correct": false, "explanation": "受身の命令形で、コップの状況を述べる文に合わない"}, {"text": "掴まって", "is_correct": false, "explanation": "自動詞『掴まる』の形で、『を』と合わず文が終わらない"}, {"text": "掴みなさい", "is_correct": false, "explanation": "丁寧な命令で、状況の叙述に合わない"}], "explanations": {"掴めなかった": "過去の否定形で、手が濡れていて掴めなかったという文脈に合う", "掴まれ": "受身の命令形で、コップの状況を述べる文に合わない", "掴まって": "自動詞『掴まる』の形で、『を』と合わず文が終わらない", "掴みなさい": "丁寧な命令で、状況の叙述に合わない"}, "sentence_index": 6, "correct_answer": "掴めなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丘の上で景色を掴んだ。", "explanation": "ここは〈眺める〉の意味。景色は掴めないので、掴むとは言わない。"}, {"text": "うちわで風を掴んだ。", "explanation": "ここは〈送る〉の意味。風は掴めないので、掴むとは言わない。"}, {"text": "井戸から水を掴んだ。", "explanation": "ここは〈汲む〉の意味。水は液体で掴めないので、掴むとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもが母親の袖を掴むで、ついていった。", "corrected_sentence": "子どもが母親の袖を掴んで、ついていった。", "error_description": "て形の誤り。『掴むで』の『む』を『ん』にして『掴んで』とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "掴んで", "is_correct": true, "explanation": "て形（『木の枝を掴んで、坂を登った』と動作を続ける形）"}, {"text": "掴め", "is_correct": false, "explanation": "命令形で、「急な坂を登った」へ続く文にならない"}, {"text": "掴んだ", "is_correct": false, "explanation": "過去形で、『登った』へ続く動作の連なりにならない"}, {"text": "掴まって", "is_correct": false, "explanation": "自動詞「掴まる」の形で、「木の枝を」と合わず文が成立しない"}], "correct_form": "掴んで", "base_form": "掴む", "form_label": "て形", "sentence_index": 1, "explanations": {"掴んで": "て形（『木の枝を掴んで、坂を登った』と動作を続ける形）", "掴め": "命令形で、「急な坂を登った」へ続く文にならない", "掴んだ": "過去形で、『登った』へ続く動作の連なりにならない", "掴まって": "自動詞「掴まる」の形で、「木の枝を」と合わず文が成立しない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39685, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父はバスの吊り革に掴んで、足を踏ん張った。", "corrected_sentence": "祖父はバスの吊り革を掴んで、足を踏ん張った。", "error_description": "目的語の助詞の誤り。『掴む』は『〜を掴む』なので『に』を『を』にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "掴んで", "is_correct": true, "explanation": "て形（『走り、間に合った』へ続く形）"}, {"text": "掴む", "is_correct": false, "explanation": "辞書形で、『走り』へ続く動作の連なりにならない"}, {"text": "掴まれ", "is_correct": false, "explanation": "受身の命令形で、荷物を持って走った文脈に合わない"}, {"text": "掴ませ", "is_correct": false, "explanation": "使役の語幹で、文が完結せず動作の描写にならない"}], "correct_form": "掴んで", "base_form": "掴む", "form_label": "て形", "sentence_index": 7, "explanations": {"掴んで": "て形（『走り、間に合った』へ続く形）", "掴む": "辞書形で、『走り』へ続く動作の連なりにならない", "掴まれ": "受身の命令形で、荷物を持って走った文脈に合わない", "掴ませ": "使役の語幹で、文が完結せず動作の描写にならない"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ff7ee02-2c3f-4cc4-ad3f-52deda1877c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
