INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39686, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ロボットの手」の所有を表す「の」で、正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語の印で、ここでは「手は」と続く名詞の所有関係を表せないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手や場所を表すので、「ロボット」と「手」をつなぐ関係には合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表すので、「ロボット」と「手」をつなぐ関係には合わない。"}], "correct_answer": "の", "explanations": {"の": "「ロボットの手」の所有を表す「の」で、正しい。", "を": "目的語の印で、ここでは「手は」と続く名詞の所有関係を表せないので合わない。", "に": "相手や場所を表すので、「ロボット」と「手」をつなぐ関係には合わない。", "で": "手段や場所を表すので、「ロボット」と「手」をつなぐ関係には合わない。"}, "error_tags": {"を": "目的語", "に": "相手・位置", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人の代わりに動く機械のことです。", "primary_collocate": null, "pronunciation": "ろぼっと", "ipa": "ɾobotto", "syllable_count": 4, "sentences": [{"text": "工場では、ロボットが人の代わりに重い荷物を運びます。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、ロボットが人[ひと]の代[か]わりに重[おも]い荷物[にもつ]を運[はこ]びます。", "sentence_source": "generated"}, {"text": "このロボットは、話しかけると返事をします。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "このロボットは、話[はな]しかけると返事[へんじ]をします。", "sentence_source": "generated"}, {"text": "兄はロボットの部品を集めて、自分で組み立てました。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "兄[あに]はロボットの部品[ぶひん]を集[あつ]めて、自分[じぶん]で組[く]み立[た]てました。", "sentence_source": "generated"}, {"text": "病院で、ロボットが薬を届ける仕事をしています。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "病院[びょういん]で、ロボットが薬[くすり]を届[とど]ける仕事[しごと]をしています。", "sentence_source": "generated"}, {"text": "ロボットは疲れないので、夜も止まらずに働けます。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "ロボットは疲[つか]れないので、夜[よる]も止[と]まらずに働[はたら]けます。", "sentence_source": "generated"}, {"text": "店の入口に立つロボットが、お客さんに挨拶をします。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "店[みせ]の入口[いりぐち]に立[た]つロボットが、お客[きゃく]さんに挨拶[あいさつ]をします。", "sentence_source": "generated"}, {"text": "掃除をするロボットのおかげで、家の中がいつもきれいです。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "掃除[そうじ]をするロボットのおかげで、家[いえ]の中[なか]がいつもきれいです。", "sentence_source": "generated"}, {"text": "ロボットの手は人の手より力が強いですが、やわらかい物をつかむのは苦手です。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "ロボットの手[て]は人[ひと]の手[て]より力[ちから]が強[つよ]いですが、やわらかい物[もの]をつかむのは苦手[にがて]です。", "sentence_source": "generated"}, {"text": "学校のクラブで、ボールを投げるロボットを作っています。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "学校[がっこう]のクラブで、ボールを投[な]げるロボットを作[つく]っています。", "sentence_source": "generated"}, {"text": "このレストランでは、ロボットが料理をテーブルまで運んでくれます。", "target_word": "ロボット", "complexity_tier": "T3", "furigana": "このレストランでは、ロボットが料理[りょうり]をテーブルまで運[はこ]んでくれます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロボット", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "人に代わって作業や仕事をする機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39686, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "人の代わりに働く機械なので、「人の代わりに重い荷物を運ぶ」に合う。"}, {"text": "ハンガー", "is_correct": false, "explanation": "ハンガーは衣類を掛ける道具で、重い荷物を人の代わりに運ぶことはできない。"}, {"text": "荷物", "is_correct": false, "explanation": "運ばれるもので、運ぶ主語にはならないので合わない。"}, {"text": "工具", "is_correct": false, "explanation": "道具は自分で運ばないので、主語として合わない。"}], "explanations": {"ロボット": "人の代わりに働く機械なので、「人の代わりに重い荷物を運ぶ」に合う。", "ハンガー": "ハンガーは衣類を掛ける道具で、重い荷物を人の代わりに運ぶことはできない。", "荷物": "運ばれるもので、運ぶ主語にはならないので合わない。", "工具": "道具は自分で運ばないので、主語として合わない。"}, "sentence_index": 0, "correct_answer": "ロボット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ロボットは、ひな祭りに飾る大切な物です。", "explanation": "ここは〈人形〉（ひな人形など、飾る人形）の意味。飾る人形は〈人形〉で、人の代わりに動く〈ロボット〉とは言わない。"}, {"text": "今日のお弁当は、ごはんとおかずのロボットです。", "explanation": "ここは〈弁当〉の意味。食べ物には〈ロボット〉を使わないので合わない。"}, {"text": "昨夜はロボットで、遠くの友だちと長く話しました。", "explanation": "ここは〈電話〉の意味。通話の道具には〈電話〉を使い、〈ロボット〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39686, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ロボット", "is_correct": true, "explanation": "掃除をする働き手として、家の中をきれいにする文に合う。"}, {"text": "料理", "is_correct": false, "explanation": "食べ物を作ることで、掃除をするものではないので合わない。"}, {"text": "写真", "is_correct": false, "explanation": "写し取ったものなので、掃除をするものではないので合わない。"}, {"text": "花", "is_correct": false, "explanation": "咲く植物で、掃除をするものではないので文に合わない。"}], "explanations": {"ロボット": "掃除をする働き手として、家の中をきれいにする文に合う。", "料理": "食べ物を作ることで、掃除をするものではないので合わない。", "写真": "写し取ったものなので、掃除をするものではないので合わない。", "花": "咲く植物で、掃除をするものではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "ロボット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このロボットは、温泉が自慢です。", "explanation": "ここは〈旅館〉の意味。宿には〈旅館〉を使い、〈ロボット〉とは言わない。"}, {"text": "このロボットは、熱が続くのが特徴です。", "explanation": "ここは〈病気〉の意味。熱が続く状態は〈病気〉で表し、〈ロボット〉とは言わない。"}, {"text": "今日のロボットは、晴れのち曇りです。", "explanation": "ここは〈天気〉の意味。空模様は〈天気〉で表し、〈ロボット〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39686, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この工場のロボットを、重い箱を運びます。", "corrected_sentence": "この工場のロボットは、重い箱を運びます。", "error_description": "「ロボットを」の「を」が誤り。主語には「は」を使う（正：ロボットは）。「運ぶ」はすでに「箱を」を目的語に取っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39686, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ロボットは重い荷物を運べれます。", "corrected_sentence": "ロボットは重い荷物を運べます。", "error_description": "「運べる」の可能形に「れる」を重ねた二重の可能表現で誤り。「運べます」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「アームは」で、新しいアームを主題として示す。ここは話題の提示なので、格助詞ではなく「は」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「アームに軽い金属でできている」では場所や相手の意味になり、主題の文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「アームで軽い金属でできている」では手段の意味になり、アームが材料を持つ文として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「アームから」は起点を示すが、この文ではアームの材質を説明しているので合わない。"}], "correct_answer": "は", "explanations": {"は": "「アームは」で、新しいアームを主題として示す。ここは話題の提示なので、格助詞ではなく「は」が入る。", "に": "「アームに軽い金属でできている」では場所や相手の意味になり、主題の文として成り立たない。", "で": "「アームで軽い金属でできている」では手段の意味になり、アームが材料を持つ文として不自然。", "から": "「アームから」は起点を示すが、この文ではアームの材質を説明しているので合わない。"}, "error_tags": {"に": "対象の格", "で": "手段・材料の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "腕のような形をしていて、物をつかんだり動かしたりする機械の部品です。", "primary_collocate": null, "pronunciation": "あーむ", "ipa": "aːmu", "syllable_count": 3, "sentences": [{"text": "工場のロボットのアームが、重い箱をゆっくり持ち上げた。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "工場(こうじょう)のロボットのアームが、重(おも)い箱(はこ)をゆっくり持(も)ち上(あ)げた。", "sentence_source": "generated"}, {"text": "ゲームセンターでは、アームが景品をつかむ前に落としてしまった。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "ゲームセンターでは、アームが景品(けいひん)をつかむ前(まえ)に落(お)としてしまった。", "sentence_source": "generated"}, {"text": "工事現場のクレーンはアームを長く伸ばして、ビルの上に材料を運んだ。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "工事現場(こうじげんば)のクレーンはアームを長(なが)く伸(の)ばして、ビルの上(うえ)に材料(ざいりょう)を運(はこ)んだ。", "sentence_source": "generated"}, {"text": "この機械はアームが三つ付いているので、細かい作業ができる。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "この機械(きかい)はアームが三(みっ)つ付(つ)いているので、細(こま)かい作業(さぎょう)ができる。", "sentence_source": "generated"}, {"text": "手術用の機械は、アームの動きがとても正確だ。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "手術用(しゅじゅつよう)の機械(きかい)は、アームの動(うご)きがとても正確(せいかく)だ。", "sentence_source": "generated"}, {"text": "アームが故障して、工場の生産が止まってしまった。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "アームが故障(こしょう)して、工場(こうじょう)の生産(せいさん)が止(と)まってしまった。", "sentence_source": "generated"}, {"text": "宇宙ステーションでは、アームを使って荷物を外に出す。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "宇宙(うちゅう)ステーションでは、アームを使(つか)って荷物(にもつ)を外(そと)に出(だ)す。", "sentence_source": "generated"}, {"text": "新しいアームは軽い金属でできているので、速く動く。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "新(あたら)しいアームは軽(かる)い金属(きんぞく)でできているので、速(はや)く動(うご)く。", "sentence_source": "generated"}, {"text": "車を作る工場では、溶接用のアームが一日中動いている。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "車(くるま)を作(つく)る工場(こうじょう)では、溶接用(ようせつよう)のアームが一日中(いちにちじゅう)動(うご)いている。", "sentence_source": "generated"}, {"text": "アームの先に付ける道具を替えれば、いろいろな物をつかめる。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "アームの先(さき)に付(つ)ける道具(どうぐ)を替(か)えれば、いろいろな物(もの)をつかめる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アーム", "label": "基本形"}], "register": "中立", "sense_fingerprint": "ロボットやクレーンなどに付いた、物をつかみ動かす腕状の機械部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アーム", "is_correct": true, "explanation": "機械の腕を表すアームが、重い箱を持ち上げる主語として自然に入る。"}, {"text": "ドア", "is_correct": false, "explanation": "扉を指すので、重い箱を持ち上げる機械の主語にならない。"}, {"text": "タイヤ", "is_correct": false, "explanation": "車輪は箱を持ち上げる部品ではないので、文脈に合わない。"}, {"text": "ノズル", "is_correct": false, "explanation": "液体や気体を噴き出す部品で、物をつかんで持ち上げる働きはない。"}], "explanations": {"アーム": "機械の腕を表すアームが、重い箱を持ち上げる主語として自然に入る。", "ドア": "扉を指すので、重い箱を持ち上げる機械の主語にならない。", "タイヤ": "車輪は箱を持ち上げる部品ではないので、文脈に合わない。", "ノズル": "液体や気体を噴き出す部品で、物をつかんで持ち上げる働きはない。"}, "sentence_index": 0, "correct_answer": "アーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は車のアームを右に回して、駐車場に入った。", "explanation": "ここは〈ハンドル〉の意味。車の向きを変えるのはハンドルを回すことで、機械の腕のアームは合わない。"}, {"text": "彼は階段で転んで、アームを骨折してしまった。", "explanation": "ここは人の〈腕〉の意味。アームは機械の部品を指すので、人の体の部位には使わない。"}, {"text": "彼女はおにぎりをアームで握って、子どもに渡した。", "explanation": "ここは〈手〉の意味。人がおにぎりを握るのは手で、機械の腕のアームとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アーム", "is_correct": true, "explanation": "宇宙ステーションで荷物を外に出す道具として、機械の腕のアームが自然に入る。"}, {"text": "カーテン", "is_correct": false, "explanation": "布で窓を覆う物で、荷物を外に出す道具にはならない。"}, {"text": "マイク", "is_correct": false, "explanation": "音を拾う機器で、荷物を運び出す働きはない。"}, {"text": "座布団", "is_correct": false, "explanation": "座る時に敷く布製品で、荷物を外に出す文脈には合わない。"}], "explanations": {"アーム": "宇宙ステーションで荷物を外に出す道具として、機械の腕のアームが自然に入る。", "カーテン": "布で窓を覆う物で、荷物を外に出す道具にはならない。", "マイク": "音を拾う機器で、荷物を運び出す働きはない。", "座布団": "座る時に敷く布製品で、荷物を外に出す文脈には合わない。"}, "sentence_index": 6, "correct_answer": "アーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアニストは、アームを一本ずつ動かして難しい曲を弾いた。", "explanation": "ここは〈指〉の意味。一本ずつ動かすのは人の指で、機械の腕のアームとは合わない。"}, {"text": "彼はアームで針金をはさんで、きれいに曲げた。", "explanation": "ここは〈ペンチ〉の意味。手で持つ工具で針金をはさんで曲げるもので、機械の部品のアームは使わない。"}, {"text": "台所で、アームをひねって水を出した。", "explanation": "ここは〈蛇口〉の意味。水を出すのは蛇口をひねることで、機械の腕のアームは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロボットのアームに重い箱をゆっくり持ち上げた。", "corrected_sentence": "ロボットのアームで重い箱をゆっくり持ち上げた。", "error_description": "誤りは「アームに」。持ち上げる手段を表すのは「で」なので、正しくは「アームで」。「に」では手段が示せず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39688, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業員はリモコンでロボットのアームに動かし、部品を棚に置いた。", "corrected_sentence": "作業員はリモコンでロボットのアームを動かし、部品を棚に置いた。", "error_description": "誤りは「アームに」。「動かす」の対象は「を」で示すので、正しくは「アームを」。「に」では動かす対象にならず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「アームは」で、荷物を運ぶアームを主題として示す。人の腕との比較の話題なので「は」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「アームを」だと、アームが比較される対象ではなく動作の目的語になり、文の意味が崩れる。"}, {"text": "に", "is_correct": false, "explanation": "「アームに人の腕より力が強い」では方向や相手の意味になり、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「アームで人の腕より力が強い」では手段の意味になり、比較の文として合わない。"}], "correct_answer": "は", "explanations": {"は": "「アームは」で、荷物を運ぶアームを主題として示す。人の腕との比較の話題なので「は」が入る。", "を": "「アームを」だと、アームが比較される対象ではなく動作の目的語になり、文の意味が崩れる。", "に": "「アームに人の腕より力が強い」では方向や相手の意味になり、文として成り立たない。", "で": "「アームで人の腕より力が強い」では手段の意味になり、比較の文として合わない。"}, "error_tags": {"を": "目的語の格", "に": "方向・相手の格", "で": "手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「アームが」で、急に止まったアームが主語になる。原因となった主体を示すので「が」が入る。"}, {"text": "の", "is_correct": false, "explanation": "「アームの急に止まった」では所有や修飾の関係になり、文の主語として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「アームへ急に止まった」は方向を示してしまい、止まった主体の文として合わない。"}, {"text": "と", "is_correct": false, "explanation": "「アームと急に止まった」は並列や共同になり、この文では一つの主体が止まったことを表すので合わない。"}], "correct_answer": "が", "explanations": {"が": "「アームが」で、急に止まったアームが主語になる。原因となった主体を示すので「が」が入る。", "の": "「アームの急に止まった」では所有や修飾の関係になり、文の主語として成り立たない。", "へ": "「アームへ急に止まった」は方向を示してしまい、止まった主体の文として合わない。", "と": "「アームと急に止まった」は並列や共同になり、この文では一つの主体が止まったことを表すので合わない。"}, "error_tags": {"の": "所有・連体の格", "へ": "方向の格", "と": "並列・共同の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "機械の腕。物を掴んだり、動かしたりするために使われる部分。", "primary_collocate": null, "pronunciation": "あーむ", "ipa": "aːmu", "syllable_count": 3, "sentences": [{"text": "掃除ロボットのアームが、床の小さなごみをはさんで取った。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "掃除(そうじ)ロボットのアームが、床(ゆか)の小(ちい)さなごみをはさんで取(と)った。", "sentence_source": "generated"}, {"text": "荷物を運ぶアームは、人の腕よりずっと力が強い。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "荷物(にもつ)を運(はこ)ぶアームは、人(ひと)の腕(うで)よりずっと力(ちから)が強(つよ)い。", "sentence_source": "generated"}, {"text": "学生たちは、段ボールでアームの模型を作って動かし方を学んだ。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "学生(がくせい)たちは、段(だん)ボールでアームの模型(もけい)を作(つく)って動(うご)かし方(かた)を学(まな)んだ。", "sentence_source": "generated"}, {"text": "食品工場ではアームがパンを一つずつ袋に入れている。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "食品工場(しょくひんこうじょう)ではアームがパンを一(ひと)つずつ袋(ふくろ)に入(い)れている。", "sentence_source": "generated"}, {"text": "アームの角度を変えると、高い所の物も取れる。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "アームの角度(かくど)を変(か)えると、高(たか)い所(ところ)の物(もの)も取(と)れる。", "sentence_source": "generated"}, {"text": "工場のアームは、疲れないので夜も同じ作業を続けられる。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "工場(こうじょう)のアームは、疲(つか)れないので夜(よる)も同(おな)じ作業(さぎょう)を続(つづ)けられる。", "sentence_source": "generated"}, {"text": "先生はアームの仕組みを、図を使って説明した。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "先生(せんせい)はアームの仕組(しく)みを、図(ず)を使(つか)って説明(せつめい)した。", "sentence_source": "generated"}, {"text": "アームが急に止まったので、作業員は電源を切って調べた。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "アームが急(きゅう)に止(と)まったので、作業員(さぎょういん)は電源(でんげん)を切(き)って調(しら)べた。", "sentence_source": "generated"}, {"text": "海の底を調べる機械は、アームで岩の一部を持ち帰った。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "海(うみ)の底(そこ)を調(しら)べる機械(きかい)は、アームで岩(いわ)の一部(いちぶ)を持(も)ち帰(かえ)った。", "sentence_source": "generated"}, {"text": "アームの先の指のような部品が、卵を割らずにつかんだ。", "target_word": "アーム", "complexity_tier": "T3", "furigana": "アームの先(さき)の指(ゆび)のような部品(ぶひん)が、卵(たまご)を割(わ)らずにつかんだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アーム", "label": "基本形"}], "register": "中立", "sense_fingerprint": "機械の腕の部分。物を掴む・動かすために使う可動部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '852b6540-6d18-4275-929f-d9e83b2c18f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アーム", "is_correct": true, "explanation": "掃除ロボットの機械の腕として、床のごみをはさんで取る主語に合う。"}, {"text": "ドア", "is_correct": false, "explanation": "扉を指すので、床のごみをはさんで取る動作の主語にならない。"}, {"text": "タイヤ", "is_correct": false, "explanation": "車輪はごみをはさんで取る部品ではないので、文脈に合わない。"}, {"text": "ノズル", "is_correct": false, "explanation": "空気や水を噴き出す部品で、はさんで取る働きはないので合わない。"}], "explanations": {"アーム": "掃除ロボットの機械の腕として、床のごみをはさんで取る主語に合う。", "ドア": "扉を指すので、床のごみをはさんで取る動作の主語にならない。", "タイヤ": "車輪はごみをはさんで取る部品ではないので、文脈に合わない。", "ノズル": "空気や水を噴き出す部品で、はさんで取る働きはないので合わない。"}, "sentence_index": 0, "correct_answer": "アーム"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は試合でアームを強く振って、ボールを打ち返した。", "explanation": "ここは〈ラケット〉の意味。ボールを打ち返すのは道具のラケットを振ることで、機械の腕のアームは合わない。"}, {"text": "彼女はアームを上げて、教室で質問した。", "explanation": "ここは人の〈腕〉の意味。アームは機械の部品を指すので、人の腕を指すときには使わない。"}, {"text": "彼女はアームで髪を結び直した。", "explanation": "ここは〈手〉の意味。人が髪を結ぶのは手で、機械の腕のアームとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アーム", "is_correct": true, "explanation": "機械の仕組みを説明する対象として、機械の腕のアームが自然に入る。"}, {"text": "エプロン", "is_correct": false, "explanation": "料理の時に着る衣類で、機械の仕組みを図で説明する対象にはならない。"}, {"text": "コップ", "is_correct": false, "explanation": "飲み物を入れる器で、仕組みを図で説明する文脈には合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座る時に敷く布製品で、仕組みを図で説明する対象にはならない。"}], "explanations": {"アーム": "機械の仕組みを説明する対象として、機械の腕のアームが自然に入る。", "エプロン": "料理の時に着る衣類で、機械の仕組みを図で説明する対象にはならない。", "コップ": "飲み物を入れる器で、仕組みを図で説明する文脈には合わない。", "座布団": "座る時に敷く布製品で、仕組みを図で説明する対象にはならない。"}, "sentence_index": 6, "correct_answer": "アーム"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアニストは、アームを一本ずつ動かして鍵盤を押さえた。", "explanation": "ここは〈指〉の意味。一本ずつ動かすのは人の指で、機械の腕のアームとは合わない。"}, {"text": "大工は、アームで釘を抜いた。", "explanation": "ここは〈釘抜き〉の意味。手で扱う工具で釘を抜くもので、機械の部品のアームは使わない。"}, {"text": "大工は、アームを高く振り上げて板を打った。", "explanation": "ここは〈金づち〉の意味。板を打つのは金づちを振り上げることで、機械の腕のアームは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "掃除ロボットのアームに、床の小さなごみをはさんで取った。", "corrected_sentence": "掃除ロボットのアームで、床の小さなごみをはさんで取った。", "error_description": "誤りは「アームに」。ごみを取る手段を表すのは「で」なので、正しくは「アームで」。「に」では手段が示せず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39689, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業員は、止まったアームに手で動かして調べた。", "corrected_sentence": "作業員は、止まったアームを手で動かして調べた。", "error_description": "誤りは「アームに」。手で動かす対象は「を」で示すので、正しくは「アームを」。「に」では動かす対象にならず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffd27e7e-563d-497b-a472-0425c93e5dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「製作に関わる」と、関わる対象を示す「に」。"}, {"text": "を", "is_correct": false, "explanation": "「関わる」は「を」を取らないので、「を」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "名詞に続く「の」は後ろに名詞が要るため、「製作の、」で文が終わらず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は「関わる」の対象を示せず、合わない。"}], "correct_answer": "に", "explanations": {"に": "「製作に関わる」と、関わる対象を示す「に」。", "を": "「関わる」は「を」を取らないので、「を」は不自然。", "の": "名詞に続く「の」は後ろに名詞が要るため、「製作の、」で文が終わらず不自然。", "へ": "方向の「へ」は「関わる」の対象を示せず、合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「製作を仕事にする」と、仕事にする対象を示す「を」。"}, {"text": "に", "is_correct": false, "explanation": "「製作に仕事にしている」は不自然で、対象を示すには「を」を使う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「仕事にする」の対象を示せず、合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列・引用の「と」では「製作と仕事にする」の形にならず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「製作を仕事にする」と、仕事にする対象を示す「を」。", "に": "「製作に仕事にしている」は不自然で、対象を示すには「を」を使う。", "へ": "方向を示す「へ」は「仕事にする」の対象を示せず、合わない。", "と": "並列・引用の「と」では「製作と仕事にする」の形にならず、不自然。"}, "error_tags": {"に": "結果・位置", "へ": "方向", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを作ること。", "primary_collocate": null, "pronunciation": "せいさく", "ipa": "seːsakɯ", "syllable_count": 4, "sentences": [{"text": "兄は映画の製作に三年もかかりました。", "target_word": "製作", "complexity_tier": "T3", "furigana": "兄[あに]は映画[えいが]の製作[せいさく]に三年[さんねん]もかかりました。", "sentence_source": "generated"}, {"text": "この番組の製作には、多くの人が関わっています。", "target_word": "製作", "complexity_tier": "T3", "furigana": "この番組[ばんぐみ]の製作[せいさく]には、多[おお]くの人[ひと]が関[かか]わっています。", "sentence_source": "generated"}, {"text": "新しい人形の製作を始めたので、毎晩遅くまで作業しています。", "target_word": "製作", "complexity_tier": "T3", "furigana": "新[あたら]しい人形[にんぎょう]の製作[せいさく]を始[はじ]めたので、毎晩[まいばん]遅[おそ]くまで作業[さぎょう]しています。", "sentence_source": "generated"}, {"text": "製作が遅れたため、発売日が来月に変わりました。", "target_word": "製作", "complexity_tier": "T3", "furigana": "製作[せいさく]が遅[おく]れたため、発売日[はつばいび]が来月[らいげつ]に変[か]わりました。", "sentence_source": "generated"}, {"text": "学生たちは文化祭で使う看板の製作に取りかかった。", "target_word": "製作", "complexity_tier": "T3", "furigana": "学生[がくせい]たちは文化祭[ぶんかさい]で使[つか]う看板[かんばん]の製作[せいさく]に取[と]りかかった。", "sentence_source": "generated"}, {"text": "この会社はアニメの製作で有名です。", "target_word": "製作", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]はアニメの製作[せいさく]で有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "製作にかかるお金が足りなくて、計画は中止になった。", "target_word": "製作", "complexity_tier": "T3", "furigana": "製作[せいさく]にかかるお金[かね]が足[た]りなくて、計画[けいかく]は中止[ちゅうし]になった。", "sentence_source": "generated"}, {"text": "彼は家具の製作を仕事にしている。", "target_word": "製作", "complexity_tier": "T3", "furigana": "彼[かれ]は家具[かぐ]の製作[せいさく]を仕事[しごと]にしている。", "sentence_source": "generated"}, {"text": "監督はドラマの製作を発表した。", "target_word": "製作", "complexity_tier": "T3", "furigana": "監督[かんとく]はドラマの製作[せいさく]を発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "製作に使う材料は、近くの店で買いました。", "target_word": "製作", "complexity_tier": "T3", "furigana": "製作[せいさく]に使[つか]う材料[ざいりょう]は、近[ちか]くの店[みせ]で買[か]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "製作する", "label": "辞書形"}, {"form": "製作した", "label": "過去形"}, {"form": "製作して", "label": "て形"}, {"form": "製作しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "映画・番組・家具などのものを作り上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6cbcb1a-123e-4953-a136-6a5ab5f54d90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "製作", "is_correct": true, "explanation": "映画を作る工程を表し、「映画の製作に三年かかった」と合う。"}, {"text": "寿命", "is_correct": false, "explanation": "映画の寿命は作る作業ではなく、「三年かかる」の対象として意味が通らない。"}, {"text": "病気", "is_correct": false, "explanation": "映画が病気になるという意味にはならず、「映画の病気」は文として成り立たない。"}, {"text": "性格", "is_correct": false, "explanation": "映画に性格はなく、三年かかる対象として不自然。"}], "explanations": {"製作": "映画を作る工程を表し、「映画の製作に三年かかった」と合う。", "寿命": "映画の寿命は作る作業ではなく、「三年かかる」の対象として意味が通らない。", "病気": "映画が病気になるという意味にはならず、「映画の病気」は文として成り立たない。", "性格": "映画に性格はなく、三年かかる対象として不自然。"}, "sentence_index": 0, "correct_answer": "製作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週までに会議用の報告書を製作してください。", "explanation": "報告書などの文書は「作成」を使う。「製作」は映画・番組・家具など形のあるものを作る語。"}, {"text": "壊れた冷蔵庫を製作して、また使えるようにした。", "explanation": "壊れたものを直すのは「修理」。「製作」は新しく作ることで、直す意味では使わない。"}, {"text": "来月のイベントの日程を製作した。", "explanation": "ここは〈計画を立てる・組む〉の意味。「製作」は形のあるものを作る語で、日程には「立てる」「組む」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "製作", "is_correct": true, "explanation": "作品を作るためのお金を指し、「製作にかかるお金」と自然に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気にお金がかかるという意味にはならず、文が通らない。"}, {"text": "好み", "is_correct": false, "explanation": "好みにお金がかかるという文は不自然。"}, {"text": "気分", "is_correct": false, "explanation": "気分にお金がかかるという意味にはならない。"}], "explanations": {"製作": "作品を作るためのお金を指し、「製作にかかるお金」と自然に合う。", "天気": "天気にお金がかかるという意味にはならず、文が通らない。", "好み": "好みにお金がかかるという文は不自然。", "気分": "気分にお金がかかるという意味にはならない。"}, "sentence_index": 6, "correct_answer": "製作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は地元の米を製作して売っている。", "explanation": "農作物を育てて大量に作るのは「生産」。「製作」は作品や品物を組み立てて作る語。"}, {"text": "夕食を製作して、家族みんなで食べた。", "explanation": "食事を作るのは「料理」。「製作」は映画や大きな品物などに使う。"}, {"text": "庭で野菜を製作して育てている。", "explanation": "植物を育てるのは「栽培」。「製作」は物を作る語で、育てる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "映画の製作を、多くのお金がかかる。", "corrected_sentence": "映画の製作には、多くのお金がかかる。", "error_description": "「製作」に続く「には」を「を」にした。「を」では文が成り立たず、「製作にかかる」が正しい形。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39690, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい映画の製作を開いた。", "corrected_sentence": "新しい映画の製作を始めた。", "error_description": "「製作」と組む動詞を「始めた」から「開いた」に変えた。「開く」は会や店などに使い、「製作」とは結びつかない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fbf320b-0cb2-42c6-9cd2-1c05b82378f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「解説を読んで」の目的語を表す。「読む」は対象を「を」で示す。"}, {"text": "に", "is_correct": false, "explanation": "「解説に読んで」は文が成り立たず、「読む」の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「読む」の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は「解説の読んで」の形を作れず、動詞の目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「解説を読んで」の目的語を表す。「読む」は対象を「を」で示す。", "に": "「解説に読んで」は文が成り立たず、「読む」の対象を示せない。", "へ": "方向を表す「へ」は「読む」の目的語にならない。", "の": "連体修飾の「の」は「解説の読んで」の形を作れず、動詞の目的語にならない。"}, "error_tags": {"に": "位置・相手の格", "へ": "方向の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作り方を」の「を」。「作り方」が「解説する」の対象であることを示す。"}, {"text": "と", "is_correct": false, "explanation": "「作り方と丁寧に解説していた」は並列の意味になり、対象を示さない。"}, {"text": "の", "is_correct": false, "explanation": "「作り方の丁寧に解説していた」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「解説する」の対象にならず、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「作り方を」の「を」。「作り方」が「解説する」の対象であることを示す。", "と": "「作り方と丁寧に解説していた」は並列の意味になり、対象を示さない。", "の": "「作り方の丁寧に解説していた」は文が成り立たない。", "へ": "方向を表す「へ」は「解説する」の対象にならず、意味が通らない。"}, "error_tags": {"と": "並列・相手の格", "の": "連体修飾の格", "へ": "方向の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものを説明すること。", "primary_collocate": null, "pronunciation": "かいせつ", "ipa": "kaisetsɯ", "syllable_count": 4, "sentences": [{"text": "先生の解説はとても分かりやすかったので、全員がすぐに理解できた。", "target_word": "解説", "complexity_tier": "T3", "furigana": "先生[せんせい]の解説[かいせつ]はとても分[わ]かりやすかったので、全員[ぜんいん]がすぐに理解[りかい]できた。", "sentence_source": "generated"}, {"text": "美術館で絵の解説を読んでから、もう一度作品を見た。", "target_word": "解説", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で絵[え]の解説[かいせつ]を読[よ]んでから、もう一度[いちど]作品[さくひん]を見[み]た。", "sentence_source": "generated"}, {"text": "この問題は難しいので、あとで先生が解説します。", "target_word": "解説", "complexity_tier": "T3", "furigana": "この問題[もんだい]は難[むずか]しいので、あとで先生[せんせい]が解説[かいせつ]します。", "sentence_source": "generated"}, {"text": "説明書の解説が短すぎて、使い方がよく分からなかった。", "target_word": "解説", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の解説[かいせつ]が短[みじか]すぎて、使[つか]い方[かた]がよく分[わ]からなかった。", "sentence_source": "generated"}, {"text": "試合のあとで、監督が負けた理由を解説した。", "target_word": "解説", "complexity_tier": "T3", "furigana": "試合[しあい]のあとで、監督[かんとく]が負[ま]けた理由[りゆう]を解説[かいせつ]した。", "sentence_source": "generated"}, {"text": "図を使って解説すると、子どもにも仕組みが伝わる。", "target_word": "解説", "complexity_tier": "T3", "furigana": "図[ず]を使[つか]って解説[かいせつ]すると、子[こ]どもにも仕組[しく]みが伝[つた]わる。", "sentence_source": "generated"}, {"text": "解説を聞いても分からなかったので、もう一度質問した。", "target_word": "解説", "complexity_tier": "T3", "furigana": "解説[かいせつ]を聞[き]いても分[わ]からなかったので、もう一度[いちど]質問[しつもん]した。", "sentence_source": "generated"}, {"text": "料理番組では、料理人が作り方を丁寧に解説していた。", "target_word": "解説", "complexity_tier": "T3", "furigana": "料理番組[りょうりばんぐみ]では、料理人[りょうりにん]が作[つく]り方[かた]を丁寧[ていねい]に解説[かいせつ]していた。", "sentence_source": "generated"}, {"text": "参考書には、答えだけでなく詳しい解説も付いている。", "target_word": "解説", "complexity_tier": "T3", "furigana": "参考書[さんこうしょ]には、答[こた]えだけでなく詳[くわ]しい解説[かいせつ]も付[つ]いている。", "sentence_source": "generated"}, {"text": "ニュースの解説を見ると、難しい政治の話も理解しやすい。", "target_word": "解説", "complexity_tier": "T3", "furigana": "ニュースの解説[かいせつ]を見[み]ると、難[むずか]しい政治[せいじ]の話[はなし]も理解[りかい]しやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解説する", "label": "サ変動詞 終止形"}, {"form": "解説した", "label": "過去形"}, {"form": "解説して", "label": "て形"}, {"form": "解説しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "ものごとを人にわかるように説明すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解説", "is_correct": true, "explanation": "「説明すること」。先生の説明が分かりやすかった、という文に合う。"}, {"text": "服装", "is_correct": false, "explanation": "「身につけるもの」。「分かりやすかった」の主語にはならない。"}, {"text": "給料", "is_correct": false, "explanation": "「働いて受け取るお金」。分かりやすいという評価は当てはまらない。"}, {"text": "握手", "is_correct": false, "explanation": "「手をにぎること」。「分かりやすかった」の主語にはならない。"}], "explanations": {"解説": "「説明すること」。先生の説明が分かりやすかった、という文に合う。", "服装": "「身につけるもの」。「分かりやすかった」の主語にはならない。", "給料": "「働いて受け取るお金」。分かりやすいという評価は当てはまらない。", "握手": "「手をにぎること」。「分かりやすかった」の主語にはならない。"}, "sentence_index": 0, "correct_answer": "解説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事で失敗が続いたので、彼は会社から解説された。", "explanation": "「解説」は説明すること。会社が人を辞めさせることは解雇で、解説は当てはまらない。"}, {"text": "古くなった家を解説して、材木を売った。", "explanation": "「解説」は説明すること。建物をこわして部品に分けることは解体で、解説は当てはまらない。"}, {"text": "会議が長引いたので、主催者は会を解説した。", "explanation": "「解説」は説明すること。集まりを終わらせることは解散で、解説は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解説", "is_correct": true, "explanation": "「説明すること」。説明が分からなかったので質問した、という文に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "「ぶらぶら歩くこと」。分からなかった話には結びつかない。"}, {"text": "清掃", "is_correct": false, "explanation": "「掃除すること」。聞いても分からなかった対象にはならない。"}, {"text": "出荷", "is_correct": false, "explanation": "「商品を送り出すこと」。聞いても分からなかった対象にはならない。"}], "explanations": {"解説": "「説明すること」。説明が分からなかったので質問した、という文に合う。", "散歩": "「ぶらぶら歩くこと」。分からなかった話には結びつかない。", "清掃": "「掃除すること」。聞いても分からなかった対象にはならない。", "出荷": "「商品を送り出すこと」。聞いても分からなかった対象にはならない。"}, "sentence_index": 6, "correct_answer": "解説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷凍のエビを解説して、夕飯で焼いた。", "explanation": "「解説」は説明すること。冷凍品をとかすことは解凍で、解説は当てはまらない。"}, {"text": "囚人を解説して、自由にした。", "explanation": "「解説」は説明すること。とらわれた人を自由にすることは解放で、解説は当てはまらない。"}, {"text": "ドアを解説して、部屋に入った。", "explanation": "「解説」は説明すること。鍵を開けることは解錠で、解説は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しいルールの解説が読んで、手続きを覚えた。", "corrected_sentence": "新しいルールの解説を読んで、手続きを覚えた。", "error_description": "助詞の誤り。「読む」の目的語は「解説を」。「解説が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39692, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生が難しい部分を丁寧に解説すた。", "corrected_sentence": "先生が難しい部分を丁寧に解説した。", "error_description": "活用の誤り。サ変動詞「解説する」の過去形は「解説した」。「解説すた」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「友だちに解説した」の「に」。解説を受ける相手を表す。"}, {"text": "を", "is_correct": false, "explanation": "「友だちを解説した」は、人を対象にして説明するという意味にならず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「友だちの解説した」は文の構造が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「友だちで解説した」は手段や場所を表すが、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「友だちに解説した」の「に」。解説を受ける相手を表す。", "を": "「友だちを解説した」は、人を対象にして説明するという意味にならず不自然。", "の": "「友だちの解説した」は文の構造が成り立たない。", "で": "「友だちで解説した」は手段や場所を表すが、意味が通らない。"}, "error_tags": {"を": "対象の格", "の": "連体修飾の格", "で": "場所・手段の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「写真つきで」の「で」。様子や方法を表し、写真を添えて解説する、という意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「写真つきに解説」は文が成り立たず、様子を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「写真つきを解説」は、写真を対象として説明するという意味にならず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「写真つきと解説」は並列の意味になり、様子を表すことができない。"}], "correct_answer": "で", "explanations": {"で": "「写真つきで」の「で」。様子や方法を表し、写真を添えて解説する、という意味になる。", "に": "「写真つきに解説」は文が成り立たず、様子を表せない。", "を": "「写真つきを解説」は、写真を対象として説明するという意味にならず不自然。", "と": "「写真つきと解説」は並列の意味になり、様子を表すことができない。"}, "error_tags": {"に": "位置・相手の格", "を": "対象の格", "と": "並列・相手の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の内容や意味を、わかるように述べること。", "primary_collocate": null, "pronunciation": "かいせつ", "ipa": "kaisetsɯ", "syllable_count": 4, "sentences": [{"text": "博物館のガイドが、展示品の歴史を解説してくれた。", "target_word": "解説", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]のガイドが、展示品[てんじひん]の歴史[れきし]を解説[かいせつ]してくれた。", "sentence_source": "generated"}, {"text": "彼は映画の結末の意味を、友だちに解説した。", "target_word": "解説", "complexity_tier": "T3", "furigana": "彼[かれ]は映画[えいが]の結末[けつまつ]の意味[いみ]を、友[とも]だちに解説[かいせつ]した。", "sentence_source": "generated"}, {"text": "法律の条文は難しいので、専門家の解説が必要だ。", "target_word": "解説", "complexity_tier": "T3", "furigana": "法律[ほうりつ]の条文[じょうぶん]は難[むずか]しいので、専門家[せんもんか]の解説[かいせつ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "詩の意味を解説する本を買って、何度も読んだ。", "target_word": "解説", "complexity_tier": "T3", "furigana": "詩[し]の意味[いみ]を解説[かいせつ]する本[ほん]を買[か]って、何度[なんど]も読[よ]んだ。", "sentence_source": "generated"}, {"text": "天気予報士が、台風の進路について解説している。", "target_word": "解説", "complexity_tier": "T3", "furigana": "天気予報士[てんきよほうし]が、台風[たいふう]の進路[しんろ]について解説[かいせつ]している。", "sentence_source": "generated"}, {"text": "解説のおかげで、古い言葉の意味がやっと分かった。", "target_word": "解説", "complexity_tier": "T3", "furigana": "解説[かいせつ]のおかげで、古[ふる]い言葉[ことば]の意味[いみ]がやっと分[わ]かった。", "sentence_source": "generated"}, {"text": "先輩が仕事の流れを解説してくれたので、新人は安心した。", "target_word": "解説", "complexity_tier": "T3", "furigana": "先輩[せんぱい]が仕事[しごと]の流[なが]れを解説[かいせつ]してくれたので、新人[しんじん]は安心[あんしん]した。", "sentence_source": "generated"}, {"text": "この本は、歌舞伎の見どころを写真つきで解説している。", "target_word": "解説", "complexity_tier": "T3", "furigana": "この本[ほん]は、歌舞伎[かぶき]の見[み]どころを写真[しゃしん]つきで解説[かいせつ]している。", "sentence_source": "generated"}, {"text": "理科の授業で、先生が実験の結果を解説した。", "target_word": "解説", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、先生[せんせい]が実験[じっけん]の結果[けっか]を解説[かいせつ]した。", "sentence_source": "generated"}, {"text": "テレビの解説を聞きながら、野球の試合を見た。", "target_word": "解説", "complexity_tier": "T3", "furigana": "テレビの解説[かいせつ]を聞[き]きながら、野球[やきゅう]の試合[しあい]を見[み]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "解説する", "label": "サ変動詞 終止形"}, {"form": "解説した", "label": "過去形"}, {"form": "解説して", "label": "て形"}, {"form": "解説しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "物事の内容や意味をわかりやすく述べ伝えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解説", "is_correct": true, "explanation": "「内容や意味をわかるように述べること」。展示品の歴史を説明してくれた、という文に合う。"}, {"text": "清掃", "is_correct": false, "explanation": "「掃除すること」。歴史を説明するという内容とは結びつかない。"}, {"text": "販売", "is_correct": false, "explanation": "「売ること」。展示品の歴史を売るという意味にはならない。"}, {"text": "出荷", "is_correct": false, "explanation": "「商品を送り出すこと」。歴史の説明としては成り立たない。"}], "explanations": {"解説": "「内容や意味をわかるように述べること」。展示品の歴史を説明してくれた、という文に合う。", "清掃": "「掃除すること」。歴史を説明するという内容とは結びつかない。", "販売": "「売ること」。展示品の歴史を売るという意味にはならない。", "出荷": "「商品を送り出すこと」。歴史の説明としては成り立たない。"}, "sentence_index": 0, "correct_answer": "解説"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "時計を解説して、中の部品を確かめた。", "explanation": "「解説」は説明すること。機械をばらすことは分解で、解説は当てはまらない。"}, {"text": "仕事が遅れた社員を、社長が解説した。", "explanation": "「解説」は説明すること。人を辞めさせることは解雇で、解説は当てはまらない。"}, {"text": "古い車を解説して、部品を売った。", "explanation": "「解説」は説明すること。車をこわして部品に分けることは解体で、解説は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解説", "is_correct": true, "explanation": "「内容や意味をわかるように述べること」。先輩が仕事の流れを説明してくれた、という文に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "「楽器などで音楽を奏でること」。仕事の流れを表すことにはならない。"}, {"text": "散歩", "is_correct": false, "explanation": "「ぶらぶら歩くこと」。仕事の流れを説明するという意味にはならない。"}, {"text": "焼却", "is_correct": false, "explanation": "「燃やして処分すること」。仕事の流れには結びつかない。"}], "explanations": {"解説": "「内容や意味をわかるように述べること」。先輩が仕事の流れを説明してくれた、という文に合う。", "演奏": "「楽器などで音楽を奏でること」。仕事の流れを表すことにはならない。", "散歩": "「ぶらぶら歩くこと」。仕事の流れを説明するという意味にはならない。", "焼却": "「燃やして処分すること」。仕事の流れには結びつかない。"}, "sentence_index": 6, "correct_answer": "解説"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫の冷凍ピザを解説して、そのまま焼いた。", "explanation": "「解説」は説明すること。冷凍品をとかすことは解凍で、解説は当てはまらない。"}, {"text": "捕まえていた鳥を解説して、空に返した。", "explanation": "「解説」は説明すること。とらわれた生き物を放すことは解放で、解説は当てはまらない。"}, {"text": "金庫を解説して、お金を取り出した。", "explanation": "「解説」は説明すること。鍵を開けることは解錠で、解説は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生が難しい計算の手順を、解説に教えた。", "corrected_sentence": "先生が難しい計算の手順を、解説して教えた。", "error_description": "て形の誤り。「解説して教えた」の「して」を「に」にしている。サ変動詞「解説する」のて形は「解説して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39693, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、雨の仕組みを図で解説しなった。", "corrected_sentence": "先生は、雨の仕組みを図で解説しなかった。", "error_description": "否定過去形の誤り。正しくは「解説しなかった」。「解説しなった」は「か」が抜けていて誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "つまらない", "is_correct": true, "explanation": "『面白い』の対義語。楽しさやわくわくを感じさせない様子を表す。"}, {"text": "暗い", "is_correct": false, "explanation": "光や雰囲気の暗さを表す語で、面白さの対義語ではない。"}, {"text": "冷たい", "is_correct": false, "explanation": "温度や態度の冷たさを表す語で、面白さとは無関係。"}, {"text": "遠い", "is_correct": false, "explanation": "距離を表す語で、面白さの対義語ではない。"}], "correct_answer": "つまらない", "explanations": {"つまらない": "『面白い』の対義語。楽しさやわくわくを感じさせない様子を表す。", "暗い": "光や雰囲気の暗さを表す語で、面白さの対義語ではない。", "冷たい": "温度や態度の冷たさを表す語で、面白さとは無関係。", "遠い": "距離を表す語で、面白さの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "つまらない", "is_correct": true, "explanation": "『面白い』の対義語。楽しさやわくわくを感じさせない様子を表す。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す語で、面白さの対義語ではない。"}, {"text": "熱い", "is_correct": false, "explanation": "温度を表す語で、面白さとは無関係。"}, {"text": "薄い", "is_correct": false, "explanation": "厚さや濃さを表す語で、面白さの対義語ではない。"}], "correct_answer": "つまらない", "explanations": {"つまらない": "『面白い』の対義語。楽しさやわくわくを感じさせない様子を表す。", "硬い": "硬さを表す語で、面白さの対義語ではない。", "熱い": "温度を表す語で、面白さとは無関係。", "薄い": "厚さや濃さを表す語で、面白さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "何かがとても楽しくて、わくわくする感じのこと。", "primary_collocate": null, "pronunciation": "おもしろい", "ipa": "omoɕiɾoi", "syllable_count": 5, "sentences": [{"text": "昨日見た映画は、わくわくして本当に面白かった。", "target_word": "面白かった", "complexity_tier": "T3", "furigana": "昨日[きのう]見[み]た映画[えいが]は、わくわくして本当[ほんとう]に面白[おもしろ]かった。", "sentence_source": "generated"}, {"text": "友だちと遊ぶゲームは、いつも面白い。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "友[とも]だちと遊[あそ]ぶゲームは、いつも面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "遊園地のジェットコースターは、こわいけれど面白い。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "遊園地[ゆうえんち]のジェットコースターは、こわいけれど面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "兄が話す冗談は面白くて、みんなが笑ってしまう。", "target_word": "面白くて", "complexity_tier": "T3", "furigana": "兄[あに]が話[はな]す冗談[じょうだん]は面白[おもしろ]くて、みんなが笑[わら]ってしまう。", "sentence_source": "generated"}, {"text": "このクイズ番組は面白いので、毎週見ています。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "このクイズ番組[ばんぐみ]は面白[おもしろ]いので、毎週[まいしゅう]見[み]ています。", "sentence_source": "generated"}, {"text": "サッカーの試合は最後まで点が入って、面白かった。", "target_word": "面白かった", "complexity_tier": "T3", "furigana": "サッカーの試合[しあい]は最後[さいご]まで点[てん]が入[はい]って、面白[おもしろ]かった。", "sentence_source": "generated"}, {"text": "面白い本を読んでいると、時間があっという間に過ぎる。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "面白[おもしろ]い本[ほん]を読[よ]んでいると、時間[じかん]があっという間[ま]に過[す]ぎる。", "sentence_source": "generated"}, {"text": "運動会のリレーは、とても面白くて盛り上がった。", "target_word": "面白くて", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]のリレーは、とても面白[おもしろ]くて盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "今日の授業は面白くなかったから、眠くなってしまった。", "target_word": "面白くなかった", "complexity_tier": "T3", "furigana": "今日[きょう]の授業[じゅぎょう]は面白[おもしろ]くなかったから、眠[ねむ]くなってしまった。", "sentence_source": "generated"}, {"text": "公園で新しい遊びを考えたら、思ったより面白かった。", "target_word": "面白かった", "complexity_tier": "T3", "furigana": "公園[こうえん]で新[あたら]しい遊[あそ]びを考[かんが]えたら、思[おも]ったより面白[おもしろ]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "面白い", "label": "基本形"}, {"form": "面白く", "label": "連用形"}, {"form": "面白かった", "label": "過去形"}, {"form": "面白くない", "label": "否定形"}, {"form": "面白ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "遊び・映画・冗談などが、とても楽しくてわくわくさせる様子（笑える・盛り上がる楽しさ）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面白かった", "is_correct": true, "explanation": "過去形で『わくわくして本当に面白かった。』と文を終えられ、映画の感想として成り立つ。"}, {"text": "面白く", "is_correct": false, "explanation": "連用形は文を終えられず、『本当に面白く。』では文が途切れる。"}, {"text": "面白くて", "is_correct": false, "explanation": "て形は文を終えられず、『本当に面白くて。』では文が完結しない。"}, {"text": "面白かったら", "is_correct": false, "explanation": "条件の『〜たら』形で、後続の文がないと文が完結しない。"}], "explanations": {"面白かった": "過去形で『わくわくして本当に面白かった。』と文を終えられ、映画の感想として成り立つ。", "面白く": "連用形は文を終えられず、『本当に面白く。』では文が途切れる。", "面白くて": "て形は文を終えられず、『本当に面白くて。』では文が完結しない。", "面白かったら": "条件の『〜たら』形で、後続の文がないと文が完結しない。"}, "sentence_index": 0, "correct_answer": "面白かった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアの向こうから面白い足音がしたので、すぐに鍵をかけた。", "explanation": "ここは〈怪しい・不審だ〉の意味。不審な物音を『面白い』とは言わず『怪しい』と言うので合わない。"}, {"text": "助けてくれて、本当に面白い。", "explanation": "ここは〈ありがたい〉の意味。感謝の気持ちを『面白い』とは言わないので合わない。"}, {"text": "祖母が亡くなったと聞いて、面白かった。", "explanation": "ここは〈悲しい〉の意味。死別の悲しみを『面白い』とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面白い", "is_correct": true, "explanation": "連体形で『本』を直接修飾でき、『面白い本を読んでいると』として文が成り立つ。"}, {"text": "甘い", "is_correct": false, "explanation": "味の甘さを表す語で、『甘い本』では本の内容の説明として成り立たない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "触感を表す語で、本の内容を表す修飾としては成り立たない。"}, {"text": "寒い", "is_correct": false, "explanation": "気温を表す語で、『寒い本』は本の内容の説明として成り立たない。"}], "explanations": {"面白い": "連体形で『本』を直接修飾でき、『面白い本を読んでいると』として文が成り立つ。", "甘い": "味の甘さを表す語で、『甘い本』では本の内容の説明として成り立たない。", "柔らかい": "触感を表す語で、本の内容を表す修飾としては成り立たない。", "寒い": "気温を表す語で、『寒い本』は本の内容の説明として成り立たない。"}, "sentence_index": 6, "correct_answer": "面白い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合格の知らせを聞いて、本当に面白かった。", "explanation": "ここは〈嬉しい〉の意味。合格の喜びは『面白い』ではなく『嬉しい』と言うので合わない。"}, {"text": "隣の部屋が面白くて、眠れなかった。", "explanation": "ここは〈騒がしい〉の意味。物音のうるささを『面白い』とは言わず『うるさい』と言うので合わない。"}, {"text": "このスープは面白くて、もう一杯飲みたい。", "explanation": "ここは〈美味しい〉の意味。味の良さを『面白い』とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "映画は予想以上に面白いで、もう一度見たくなった。", "corrected_sentence": "映画は予想以上に面白くて、もう一度見たくなった。", "error_description": "正しくは『面白くて』。連用形『面白く』に『て』が続いた形で、『面白いで』は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "面白い", "is_correct": true, "explanation": "基本形で文末に置け、『いつも面白い。』の述語として成り立つ。"}, {"text": "面白くて", "is_correct": false, "explanation": "て形は文を終えられず、『いつも面白くて。』では文が途切れる。"}, {"text": "面白くなければ", "is_correct": false, "explanation": "条件を表す形で、後続が必要なため文末では成立しない。"}, {"text": "面白かったり", "is_correct": false, "explanation": "『〜たり』は並列を表す形で、単独では文が完結しない。"}], "correct_form": "面白い", "base_form": "面白い", "form_label": "基本形", "sentence_index": 1, "explanations": {"面白い": "基本形で文末に置け、『いつも面白い。』の述語として成り立つ。", "面白くて": "て形は文を終えられず、『いつも面白くて。』では文が途切れる。", "面白くなければ": "条件を表す形で、後続が必要なため文末では成立しない。", "面白かったり": "『〜たり』は並列を表す形で、単独では文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39694, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日の映画館は、思いのほか面白くかった。", "corrected_sentence": "雨の日の映画館は、思いのほか面白かった。", "error_description": "正しくは『面白かった』。形容詞の過去形は『面白かった』で、『面白くかった』は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "面白くて", "is_correct": true, "explanation": "連用形に『て』が続いた形で、『とても面白くて盛り上がった。』と文の中で理由を表せる。"}, {"text": "面白かった", "is_correct": false, "explanation": "過去形は『盛り上がった』に直接続かず、『面白かった盛り上がった』は成り立たない。"}, {"text": "面白くない", "is_correct": false, "explanation": "否定形は『盛り上がった』と結び付かず、『面白くない盛り上がった』は不自然。"}, {"text": "面白い", "is_correct": false, "explanation": "基本形は連用・て形の代わりにならず、「とても面白い盛り上がった」と続かない。"}], "correct_form": "面白くて", "base_form": "面白い", "form_label": "て形", "sentence_index": 7, "explanations": {"面白くて": "連用形に『て』が続いた形で、『とても面白くて盛り上がった。』と文の中で理由を表せる。", "面白かった": "過去形は『盛り上がった』に直接続かず、『面白かった盛り上がった』は成り立たない。", "面白くない": "否定形は『盛り上がった』と結び付かず、『面白くない盛り上がった』は不自然。", "面白い": "基本形は連用・て形の代わりにならず、「とても面白い盛り上がった」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
