INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39695, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "つまらない", "is_correct": true, "explanation": "『面白い』の対義語。興味を引かず、楽しさを感じさせない様子を表す。"}, {"text": "甘い", "is_correct": false, "explanation": "味の甘さを表す語で、面白さとは無関係。"}, {"text": "遠い", "is_correct": false, "explanation": "距離や関係の遠さを表す語で、面白さの対義語ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬さを表す語で、面白さの対義語ではない。"}], "correct_answer": "つまらない", "explanations": {"つまらない": "『面白い』の対義語。興味を引かず、楽しさを感じさせない様子を表す。", "甘い": "味の甘さを表す語で、面白さとは無関係。", "遠い": "距離や関係の遠さを表す語で、面白さの対義語ではない。", "硬い": "硬さを表す語で、面白さの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39695, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "関心を引きつけられて、楽しさや興味を感じさせる様子。普通とは違うおもしろさがある。", "primary_collocate": null, "pronunciation": "おもしろい", "ipa": "omoɕiɾoi", "syllable_count": 5, "sentences": [{"text": "手紙の書簡体の物語は、おもしろい小説です。", "target_word": "おもしろい", "complexity_tier": "T3", "furigana": "手紙[てがみ]の書簡体[しょかんたい]の物語[ものがたり]は、おもしろい小説[しょうせつ]です。", "sentence_source": "mined"}, {"text": "先生の話は、普通の授業とは違って面白い。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "先生[せんせい]の話[はなし]は、普通[ふつう]の授業[じゅぎょう]とは違[ちが]って面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "この絵は形が変わっていて、見れば見るほど面白い。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "この絵[え]は形[かたち]が変[か]わっていて、見[み]れば見[み]るほど面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "彼の考え方は他の人と違うので、話していて面白いです。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "彼[かれ]の考[かんが]え方[かた]は他[ほか]の人[ひと]と違[ちが]うので、話[はな]していて面白[おもしろ]いです。", "sentence_source": "generated"}, {"text": "この小説は、最初の一行から読者を引きつける面白い作品だ。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、最初[さいしょ]の一行[いちぎょう]から読者[どくしゃ]を引[ひ]きつける面白[おもしろ]い作品[さくひん]だ。", "sentence_source": "generated"}, {"text": "面白い形の石を見つけたので、机に飾っています。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "面白[おもしろ]い形[かたち]の石[いし]を見[み]つけたので、机[つくえ]に飾[かざ]っています。", "sentence_source": "generated"}, {"text": "その研究は、結果が予想と逆だったので面白かった。", "target_word": "面白かった", "complexity_tier": "T3", "furigana": "その研究[けんきゅう]は、結果[けっか]が予想[よそう]と逆[ぎゃく]だったので面白[おもしろ]かった。", "sentence_source": "generated"}, {"text": "町の古い言い伝えを調べるのは、とても面白い。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "町[まち]の古[ふる]い言[い]い伝[つた]えを調[しら]べるのは、とても面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "面白い意見が出たため、会議は予定より長くなった。", "target_word": "面白い", "complexity_tier": "T3", "furigana": "面白[おもしろ]い意見[いけん]が出[で]たため、会議[かいぎ]は予定[よてい]より長[なが]くなった。", "sentence_source": "generated"}, {"text": "外国の祭りは、日本とやり方が違っていて面白かった。", "target_word": "面白かった", "complexity_tier": "T3", "furigana": "外国[がいこく]の祭[まつ]りは、日本[にほん]とやり方[かた]が違[ちが]っていて面白[おもしろ]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "面白い", "label": "基本形"}, {"form": "面白く", "label": "連用形"}, {"form": "面白かった", "label": "過去形"}, {"form": "面白くない", "label": "否定形"}, {"form": "面白ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "普通とは違う点が関心を引きつけ、興味深さや楽しさを感じさせる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b09cdd42-7420-4776-b53c-9df05b93ebf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39695, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "おもしろい", "is_correct": true, "explanation": "連体形で『小説』を直接修飾でき、『おもしろい小説です』として文が成り立つ。"}, {"text": "おもしろく", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、『おもしろく小説です』は成り立たない。"}, {"text": "おもしろくて", "is_correct": false, "explanation": "て形は名詞の前に置けず、『小説』を修飾できない。"}, {"text": "おもしろければ", "is_correct": false, "explanation": "仮定形は後続の文が必要で、名詞を修飾する形ではない。"}], "explanations": {"おもしろい": "連体形で『小説』を直接修飾でき、『おもしろい小説です』として文が成り立つ。", "おもしろく": "連用形は名詞を直接修飾できず、『おもしろく小説です』は成り立たない。", "おもしろくて": "て形は名詞の前に置けず、『小説』を修飾できない。", "おもしろければ": "仮定形は後続の文が必要で、名詞を修飾する形ではない。"}, "sentence_index": 0, "correct_answer": "おもしろい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜道で面白い人影を見かけたので、すぐに警察へ連絡した。", "explanation": "ここは〈怪しい・不審だ〉の意味。不審な人影を『面白い』とは言わず『怪しい』と言うので合わない。"}, {"text": "この手続きは面白くて、時間がかかる。", "explanation": "ここは〈面倒〉の意味。煩わしい手続きは『面白い』とは言わないので合わない。"}, {"text": "助けてくれて、本当に面白い。", "explanation": "ここは〈ありがたい〉の意味。感謝の気持ちを『面白い』とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39695, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面白かった", "is_correct": true, "explanation": "過去形で『予想と逆だったので面白かった。』と文を終えられ、研究への評価として自然。"}, {"text": "美味しかった", "is_correct": false, "explanation": "味の感想を表す語で、研究結果の評価には合わない。"}, {"text": "柔らかかった", "is_correct": false, "explanation": "触感を表す語で、研究結果の性質には合わない。"}, {"text": "速かった", "is_correct": false, "explanation": "速さを表す語で、結果が予想と逆だった理由には当てはまらない。"}], "explanations": {"面白かった": "過去形で『予想と逆だったので面白かった。』と文を終えられ、研究への評価として自然。", "美味しかった": "味の感想を表す語で、研究結果の評価には合わない。", "柔らかかった": "触感を表す語で、研究結果の性質には合わない。", "速かった": "速さを表す語で、結果が予想と逆だった理由には当てはまらない。"}, "sentence_index": 6, "correct_answer": "面白かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "合格の知らせを聞いて、本当に面白かった。", "explanation": "ここは〈嬉しい〉の意味。合格の喜びは『面白い』ではなく『嬉しい』と言うので合わない。"}, {"text": "祖母が亡くなったと聞いて、面白かった。", "explanation": "ここは〈悲しい〉の意味。死別の悲しみを『面白い』とは言わないので合わない。"}, {"text": "あと一歩で優勝を逃して、本当に面白かった。", "explanation": "ここは〈惜しい〉の意味。優勝を逃した悔しさは『面白い』ではなく『惜しい』と言うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39695, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この本は、読み始めると面白いで手が止まらない。", "corrected_sentence": "この本は、読み始めると面白くて手が止まらない。", "error_description": "正しくは『面白くて』。『面白い』の連用形『面白く』に『て』が続いた形で、『面白いで』は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "面白い", "is_correct": true, "explanation": "基本形で文末に置け、『違って面白い。』の述語として成り立つ。"}, {"text": "面白く", "is_correct": false, "explanation": "連用形は文を終えられず、『違って面白く。』では文が途切れる。"}, {"text": "面白ければ", "is_correct": false, "explanation": "仮定形は『〜ば』に続く形で、文末では成立しない。"}, {"text": "面白かったり", "is_correct": false, "explanation": "『〜たり』は並列を表す形で、単独では文が完結しない。"}], "correct_form": "面白い", "base_form": "面白い", "form_label": "基本形", "sentence_index": 1, "explanations": {"面白い": "基本形で文末に置け、『違って面白い。』の述語として成り立つ。", "面白く": "連用形は文を終えられず、『違って面白く。』では文が途切れる。", "面白ければ": "仮定形は『〜ば』に続く形で、文末では成立しない。", "面白かったり": "『〜たり』は並列を表す形で、単独では文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39695, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その映画の結末は意外で、本当に面白いかった。", "corrected_sentence": "その映画の結末は意外で、本当に面白かった。", "error_description": "正しくは『面白かった』。形容詞の過去形は『面白かった』で、『面白いかった』は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "面白い", "is_correct": true, "explanation": "基本形で文末に置け、『調べるのは、とても面白い。』の述語として成り立つ。"}, {"text": "面白かったら", "is_correct": false, "explanation": "『〜たら』は条件を表す形で、後続の文がないと文が完結しない。"}, {"text": "面白くなければ", "is_correct": false, "explanation": "条件を表す形で、後続が必要なため文末では成立しない。"}, {"text": "面白くなかったら", "is_correct": false, "explanation": "条件の『〜たら』形で、文を終えられない。"}], "correct_form": "面白い", "base_form": "面白い", "form_label": "基本形", "sentence_index": 7, "explanations": {"面白い": "基本形で文末に置け、『調べるのは、とても面白い。』の述語として成り立つ。", "面白かったら": "『〜たら』は条件を表す形で、後続の文がないと文が完結しない。", "面白くなければ": "条件を表す形で、後続が必要なため文末では成立しない。", "面白くなかったら": "条件の『〜たら』形で、文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62be08b-44dc-4a57-a5de-3543ebd23134') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本屋を覗く」で、覗くの対象（場所）を示す正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主格。「本屋が覗いて」では店が主体になり、覗く動作の対象を示せない。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す。「本屋と覗いて」では対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「本屋へ覗いて」は、覗く対象を表す用法として不自然。"}], "correct_answer": "を", "explanations": {"を": "「本屋を覗く」で、覗くの対象（場所）を示す正しい格助詞。", "が": "主格。「本屋が覗いて」では店が主体になり、覗く動作の対象を示せない。", "と": "共同や引用を示す。「本屋と覗いて」では対象を示せない。", "へ": "方向を示す。「本屋へ覗いて」は、覗く対象を表す用法として不自然。"}, "error_tags": {"が": "主格", "と": "共同", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「画面を覗く」で、覗くの対象を示す正しい格助詞。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す。「私の画面に覗いて」は対象を示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「私の画面の覗いて」は文法上続かない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「私の画面より覗いて」は覗く対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「画面を覗く」で、覗くの対象を示す正しい格助詞。", "に": "位置や相手を示す。「私の画面に覗いて」は対象を示せず不自然。", "の": "連体修飾の助詞。「私の画面の覗いて」は文法上続かない。", "より": "比較を示す。「私の画面より覗いて」は覗く対象を表せない。"}, "error_tags": {"に": "位置", "の": "連体", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ちょっと見ること。", "primary_collocate": null, "pronunciation": "のぞく", "ipa": "nozokɯ", "syllable_count": 3, "sentences": [{"text": "部屋のドアが開いていたので、中をちょっと覗いた。", "target_word": "覗いた", "complexity_tier": "T3", "furigana": "部屋[へや]のドアが開[あ]いていたので、中[なか]をちょっと覗[のぞ]いた。", "sentence_source": "generated"}, {"text": "帰りに本屋を覗いて、新しい雑誌を買った。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "帰[かえ]りに本屋[ほんや]を覗[のぞ]いて、新[あたら]しい雑誌[ざっし]を買[か]った。", "sentence_source": "generated"}, {"text": "窓から外を覗くと、雪が降っていた。", "target_word": "覗く", "complexity_tier": "T3", "furigana": "窓[まど]から外[そと]を覗[のぞ]くと、雪[ゆき]が降[ふ]っていた。", "sentence_source": "generated"}, {"text": "時間があるので、友だちの店を覗いてみよう。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "時間[じかん]があるので、友[とも]だちの店[みせ]を覗[のぞ]いてみよう。", "sentence_source": "generated"}, {"text": "顕微鏡を覗くと、小さな虫が動いていた。", "target_word": "覗く", "complexity_tier": "T3", "furigana": "顕微鏡[けんびきょう]を覗[のぞ]くと、小[ちい]さな虫[むし]が動[うご]いていた。", "sentence_source": "generated"}, {"text": "時間がなくて、展覧会をちょっと覗いただけで帰った。", "target_word": "覗いた", "complexity_tier": "T3", "furigana": "時間[じかん]がなくて、展覧会[てんらんかい]をちょっと覗[のぞ]いただけで帰[かえ]った。", "sentence_source": "generated"}, {"text": "箱のふたを開けて、中を覗いてみたが、何も入っていなかった。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "箱[はこ]のふたを開[あ]けて、中[なか]を覗[のぞ]いてみたが、何[なに]も入[はい]っていなかった。", "sentence_source": "generated"}, {"text": "弟が私の画面を覗いて、「何を見ているの」と聞いた。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "弟[おとうと]が私[わたし]の画面[がめん]を覗[のぞ]いて、「何[なに]を見[み]ているの」と聞[き]いた。", "sentence_source": "generated"}, {"text": "井戸の底を覗くと、水が光っていた。", "target_word": "覗く", "complexity_tier": "T3", "furigana": "井戸[いど]の底[そこ]を覗[のぞ]くと、水[みず]が光[ひか]っていた。", "sentence_source": "generated"}, {"text": "隣の教室を覗いたら、先生が授業の準備をしていた。", "target_word": "覗いた", "complexity_tier": "T3", "furigana": "隣[となり]の教室[きょうしつ]を覗[のぞ]いたら、先生[せんせい]が授業[じゅぎょう]の準備[じゅんび]をしていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覗く", "label": "終止形"}, {"form": "覗いた", "label": "過去形"}, {"form": "覗いて", "label": "て形"}, {"form": "覗かない", "label": "否定形"}, {"form": "覗こう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "ちょっと立ち寄って、または少しだけ見ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覗いた", "is_correct": true, "explanation": "過去形で、「ドアが開いていたので、中をちょっと覗いた。」と文を結べる正解。"}, {"text": "覗い", "is_correct": false, "explanation": "連用形の語幹だけで、文を終えられない。"}, {"text": "覗き", "is_correct": false, "explanation": "名詞形（のぞき）。動詞として文末に置けず、「中をちょっと覗き」では文が成立しない。"}, {"text": "覗かせ", "is_correct": false, "explanation": "使役の語幹。「覗かせ」で文が終わらず、文として成り立たない。"}], "explanations": {"覗いた": "過去形で、「ドアが開いていたので、中をちょっと覗いた。」と文を結べる正解。", "覗い": "連用形の語幹だけで、文を終えられない。", "覗き": "名詞形（のぞき）。動詞として文末に置けず、「中をちょっと覗き」では文が成立しない。", "覗かせ": "使役の語幹。「覗かせ」で文が終わらず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "覗いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ごみを覗くと、部屋はきれいになった。", "explanation": "ここは同音の〈除く〉（取り除く）の意味。覗くは隙間などから中を見ることで、ごみを取り除くとは言えない。"}, {"text": "窓辺で、夕焼けの海を覗きながら一日を過ごした。", "explanation": "広く海を眺める場面には眺めるが適し、覗くは狭い隙間から見る動作なので合わない。"}, {"text": "高い塔から町全体を覗いて、景色を楽しんだ。", "explanation": "町全体を広く見渡すことには見渡すが適し、覗くは狭い所から見る動作なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覗いて", "is_correct": true, "explanation": "て形で「覗いてみたが」と続き、箱の中を見た後の結果を述べる正しい形。"}, {"text": "覗い", "is_correct": false, "explanation": "連用形の語幹だけで、「〜てみたが」に続かない。"}, {"text": "覗く", "is_correct": false, "explanation": "終止形。「中を覗くてみたが」の形になり、接続が成り立たない。"}, {"text": "覗こう", "is_correct": false, "explanation": "意志形。「覗こうてみたが」は接続が成り立たず、過去の行動の文脈とも合わない。"}], "explanations": {"覗いて": "て形で「覗いてみたが」と続き、箱の中を見た後の結果を述べる正しい形。", "覗い": "連用形の語幹だけで、「〜てみたが」に続かない。", "覗く": "終止形。「中を覗くてみたが」の形になり、接続が成り立たない。", "覗こう": "意志形。「覗こうてみたが」は接続が成り立たず、過去の行動の文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "覗いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生の機嫌を覗いてから、そっと用件を切り出した。", "explanation": "相手の機嫌をそっと探ることには窺うが適し、覗くは隙間から見る動作なので合わない。"}, {"text": "母は朝、子どもの熱を覗いてから登校させた。", "explanation": "体温を量ることには測るが適し、覗くは見る動作なので熱を量る意味はない。"}, {"text": "彼は夜、歌声を覗いて、静かに聴き入った。", "explanation": "音に耳を傾けることには聴くが適し、覗くは見る動作なので音を聴く意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窓から外を覗いと、雪が静かに降っていた。", "corrected_sentence": "窓から外を覗くと、雪が静かに降っていた。", "error_description": "誤りは「覗いと」。覗くの活用形に「覗いと」はなく、条件の「と」に続く形は辞書形の「覗くと」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "覗いて", "is_correct": true, "explanation": "て形。「本屋を覗いて、雑誌を買った」と動作を続けて並べる正しい形。"}, {"text": "覗いた", "is_correct": false, "explanation": "過去形。文中で「覗いた、雑誌を買った」とは続けられず、ここでは動作をつなぐ形が必要。"}, {"text": "覗かない", "is_correct": false, "explanation": "否定形。「覗かないで買った」なら別の意味になり、本屋に立ち寄った事実と合わない。"}, {"text": "覗こう", "is_correct": false, "explanation": "意志形。過去の事実を述べる文脈と合わない。"}], "correct_form": "覗いて", "base_form": "覗く", "form_label": "て形", "sentence_index": 1, "explanations": {"覗いて": "て形。「本屋を覗いて、雑誌を買った」と動作を続けて並べる正しい形。", "覗いた": "過去形。文中で「覗いた、雑誌を買った」とは続けられず、ここでは動作をつなぐ形が必要。", "覗かない": "否定形。「覗かないで買った」なら別の意味になり、本屋に立ち寄った事実と合わない。", "覗こう": "意志形。過去の事実を述べる文脈と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39696, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "隣の部屋を覗んだら、弟がぐっすり寝ていた。", "corrected_sentence": "隣の部屋を覗いたら、弟がぐっすり寝ていた。", "error_description": "誤りは「覗んだ」。覗くの過去形は「覗いた」で、「覗んだ」は活用の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "覗いて", "is_correct": true, "explanation": "て形。「画面を覗いて、聞いた」と動作を続けて述べる正しい形。"}, {"text": "覗く", "is_correct": false, "explanation": "終止形。文中で「覗く、聞いた」と続けると、動作の順序が成り立たない。"}, {"text": "覗ける", "is_correct": false, "explanation": "可能形。「画面を覗ける」は能力を表し、弟が実際に見た出来事と合わない。"}, {"text": "覗き", "is_correct": false, "explanation": "連用形の語幹。動詞として文を続けられない。"}], "correct_form": "覗いて", "base_form": "覗く", "form_label": "て形", "sentence_index": 7, "explanations": {"覗いて": "て形。「画面を覗いて、聞いた」と動作を続けて述べる正しい形。", "覗く": "終止形。文中で「覗く、聞いた」と続けると、動作の順序が成り立たない。", "覗ける": "可能形。「画面を覗ける」は能力を表し、弟が実際に見た出来事と合わない。", "覗き": "連用形の語幹。動詞として文を続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手紙を覗く」で、覗くの対象を示す正しい格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「手紙へ覗く」は覗く対象を表す用法として不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の助詞。「手紙の覗くのは」となり、文の構造が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「手紙より覗く」は対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「手紙を覗く」で、覗くの対象を示す正しい格助詞。", "へ": "方向を示す。「手紙へ覗く」は覗く対象を表す用法として不自然。", "の": "連体修飾の助詞。「手紙の覗くのは」となり、文の構造が成り立たない。", "より": "比較を示す。「手紙より覗く」は対象を表せない。"}, "error_tags": {"へ": "方向", "の": "連体", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「部屋の中を覗いた」で、覗く対象を示す正しい格助詞。"}, {"text": "が", "is_correct": false, "explanation": "主格。「中が覗いた」では部屋の内部が主体になり、覗く行為の対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示す。「中に覗いた」は覗く対象を表す用法として不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す。「中と覗いた」では対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「部屋の中を覗いた」で、覗く対象を示す正しい格助詞。", "が": "主格。「中が覗いた」では部屋の内部が主体になり、覗く行為の対象を示せない。", "に": "位置や相手を示す。「中に覗いた」は覗く対象を表す用法として不自然。", "と": "共同や引用を示す。「中と覗いた」では対象を示せない。"}, "error_tags": {"が": "主格", "に": "位置", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "隙間や物の陰から、こっそりと中をのぞき見ること。また、ちょっと見ること。", "primary_collocate": null, "pronunciation": "のぞく", "ipa": "nozokɯ", "syllable_count": 3, "sentences": [{"text": "子どもが、ドアの隙間から客の様子をこっそり覗いていた。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "子[こ]どもが、ドアの隙間[すきま]から客[きゃく]の様子[ようす]をこっそり覗[のぞ]いていた。", "sentence_source": "generated"}, {"text": "人の手紙を覗くのは、失礼なことだ。", "target_word": "覗く", "complexity_tier": "T3", "furigana": "人[ひと]の手紙[てがみ]を覗[のぞ]くのは、失礼[しつれい]なことだ。", "sentence_source": "generated"}, {"text": "カーテンの陰から外を覗いて、誰が来たのか確かめた。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "カーテンの陰[かげ]から外[そと]を覗[のぞ]いて、誰[だれ]が来[き]たのか確[たし]かめた。", "sentence_source": "generated"}, {"text": "姉の日記を覗いたことがばれて、ひどく怒られた。", "target_word": "覗いた", "complexity_tier": "T3", "furigana": "姉[あね]の日記[にっき]を覗[のぞ]いたことがばれて、ひどく怒[おこ]られた。", "sentence_source": "generated"}, {"text": "犬が塀の穴から隣の庭を覗いている。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "犬[いぬ]が塀[へい]の穴[あな]から隣[となり]の庭[にわ]を覗[のぞ]いている。", "sentence_source": "generated"}, {"text": "他人の携帯を覗くなんて、信頼を失うよ。", "target_word": "覗く", "complexity_tier": "T3", "furigana": "他人[たにん]の携帯[けいたい]を覗[のぞ]くなんて、信頼[しんらい]を失[うしな]うよ。", "sentence_source": "generated"}, {"text": "猫が箱の陰から顔を出して、こちらを覗いていた。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "猫[ねこ]が箱[はこ]の陰[かげ]から顔[かお]を出[だ]して、こちらを覗[のぞ]いていた。", "sentence_source": "generated"}, {"text": "彼は不安そうに、ふすまの隙間から部屋の中を覗いた。", "target_word": "覗いた", "complexity_tier": "T3", "furigana": "彼[かれ]は不安[ふあん]そうに、ふすまの隙間[すきま]から部屋[へや]の中[なか]を覗[のぞ]いた。", "sentence_source": "generated"}, {"text": "試験中に隣の答案を覗くのは、不正行為だ。", "target_word": "覗く", "complexity_tier": "T3", "furigana": "試験中[しけんちゅう]に隣[となり]の答案[とうあん]を覗[のぞ]くのは、不正行為[ふせいこうい]だ。", "sentence_source": "generated"}, {"text": "木の陰から覗いていた男は、警察に呼び止められた。", "target_word": "覗いて", "complexity_tier": "T3", "furigana": "木[き]の陰[かげ]から覗[のぞ]いていた男[おとこ]は、警察[けいさつ]に呼[よ]び止[と]められた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "覗く", "label": "終止形"}, {"form": "覗いた", "label": "過去形"}, {"form": "覗いて", "label": "て形"}, {"form": "覗かない", "label": "否定形"}, {"form": "覗こう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "隙間や物の陰からこっそり中を見ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30c131d8-6c46-402f-b1a0-1841ff6000bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "覗いて", "is_correct": true, "explanation": "て形。「覗いていた」の「覗いて」にあたり、こっそり見ていた様子を述べる正しい形。"}, {"text": "覗い", "is_correct": false, "explanation": "連用形の語幹。「覗いいた」となり、活用として成り立たない。"}, {"text": "覗き", "is_correct": false, "explanation": "名詞形（のぞき）。「覗きいた」となり、動詞として続かない。"}, {"text": "覗こう", "is_correct": false, "explanation": "意志形。「覗こういた」となり、子どもの行動を述べる文と合わない。"}], "explanations": {"覗いて": "て形。「覗いていた」の「覗いて」にあたり、こっそり見ていた様子を述べる正しい形。", "覗い": "連用形の語幹。「覗いいた」となり、活用として成り立たない。", "覗き": "名詞形（のぞき）。「覗きいた」となり、動詞として続かない。", "覗こう": "意志形。「覗こういた」となり、子どもの行動を述べる文と合わない。"}, "sentence_index": 0, "correct_answer": "覗いて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ごみの中から必要なものを覗いて、残りは捨てた。", "explanation": "ここは同音の〈除く〉（取り除く）の意味。覗くは中を見ることで、必要なものを取り除く意味にはならない。"}, {"text": "祖父は毎晩、庭の草花を覗いて、大きな声で叱った。", "explanation": "注意して叱ることには叱るが適し、覗くは見る動作なので叱る意味はない。"}, {"text": "仕事の書類を覗いて、みんなの前で褒めた。", "explanation": "人をほめることには褒めるが適し、覗くは見る動作なのでほめる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "覗いて", "is_correct": true, "explanation": "て形。「覗いていた」の「覗いて」にあたり、猫がこちらを見ていた様子を述べる正しい形。"}, {"text": "覗く", "is_correct": false, "explanation": "終止形。「覗くいた」となり、「ていた」の形に接続しない。"}, {"text": "覗かせ", "is_correct": false, "explanation": "使役の語幹。「覗かせいた」となり、猫の行動の文として成り立たない。"}, {"text": "覗か", "is_correct": false, "explanation": "未然形。「覗かいた」となり、動詞として続かない。"}], "explanations": {"覗いて": "て形。「覗いていた」の「覗いて」にあたり、猫がこちらを見ていた様子を述べる正しい形。", "覗く": "終止形。「覗くいた」となり、「ていた」の形に接続しない。", "覗かせ": "使役の語幹。「覗かせいた」となり、猫の行動の文として成り立たない。", "覗か": "未然形。「覗かいた」となり、動詞として続かない。"}, "sentence_index": 6, "correct_answer": "覗いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の品物を覗いて、一つずつ撫でた。", "explanation": "物をなでることには撫でるが適し、覗くは見る動作なので触れる意味はない。"}, {"text": "先生は生徒の答案を覗いて、握りつぶした。", "explanation": "紙を握りつぶすことには握りつぶすが適し、覗くは見る動作なので合わない。"}, {"text": "子犬は、飼い主の顔を覗いて、重い荷物を運んだ。", "explanation": "物を運ぶことには運ぶが適し、覗くは見る動作なので運ぶ意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアの隙間から、おばあさんが客の様子をこっそり覗んでいた。", "corrected_sentence": "ドアの隙間から、おばあさんが客の様子をこっそり覗いていた。", "error_description": "誤りは「覗んでいた」。覗くのて形は「覗いて」で、「覗んで」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "覗く", "is_correct": true, "explanation": "終止形（辞書形）。「人の手紙を覗くのは、失礼だ」と行為を一般論として述べる形。"}, {"text": "覗い", "is_correct": false, "explanation": "連用形の語幹。「覗いのは」と名詞句を作れず、文が成り立たない。"}, {"text": "覗いて", "is_correct": false, "explanation": "て形。「覗いてのは」と続かず、文の主語を作れない。"}, {"text": "覗こう", "is_correct": false, "explanation": "意志形。「覗こうのは」と続かず、一般論の文として成り立たない。"}], "correct_form": "覗く", "base_form": "覗く", "form_label": "終止形", "sentence_index": 1, "explanations": {"覗く": "終止形（辞書形）。「人の手紙を覗くのは、失礼だ」と行為を一般論として述べる形。", "覗い": "連用形の語幹。「覗いのは」と名詞句を作れず、文が成り立たない。", "覗いて": "て形。「覗いてのは」と続かず、文の主語を作れない。", "覗こう": "意志形。「覗こうのは」と続かず、一般論の文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39697, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫が箱の陰から顔を出して、じっとこちらに覗いていた。", "corrected_sentence": "猫が箱の陰から顔を出して、じっとこちらを覗いていた。", "error_description": "誤りは「こちらに」。覗くの対象には「を」を使い、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "覗いた", "is_correct": true, "explanation": "過去形。「彼は部屋の中を覗いた」と、過去の行為として文を結ぶ正しい形。"}, {"text": "覗かない", "is_correct": false, "explanation": "否定形。「覗かない」と過去の行為を否定する文になり、文の内容と合わない。"}, {"text": "覗ける", "is_correct": false, "explanation": "可能形。能力を表すため、実際に覗いた行為の文と合わない。"}, {"text": "覗き", "is_correct": false, "explanation": "連用形の語幹。動詞として文を結べない。"}], "correct_form": "覗いた", "base_form": "覗く", "form_label": "過去形", "sentence_index": 7, "explanations": {"覗いた": "過去形。「彼は部屋の中を覗いた」と、過去の行為として文を結ぶ正しい形。", "覗かない": "否定形。「覗かない」と過去の行為を否定する文になり、文の内容と合わない。", "覗ける": "可能形。能力を表すため、実際に覗いた行為の文と合わない。", "覗き": "連用形の語幹。動詞として文を結べない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd61b4965-1018-41e2-baba-8be12215805a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「電子が動く」の主語を示す。動作の主体は電子なので「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「動く」は目的語をとらないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「電子で動くと」では主語が立たない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すが、「電子に動くと」では意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「電子が動く」の主語を示す。動作の主体は電子なので「が」が正しい。", "を": "「を」は目的語を示すが、「動く」は目的語をとらないので合わない。", "で": "「で」は場所や手段を示すが、「電子で動くと」では主語が立たない。", "に": "「に」は相手や方向を示すが、「電子に動くと」では意味が通らない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "に": "相手・方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電子を〜にたとえる」の目的語を示す。たとえられる対象は電子なので「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「たとえて説明した」の対象は主語ではないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、たとえる対象には使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や相手を示すが、「電子とたとえて」では対象が立たない。"}], "correct_answer": "を", "explanations": {"を": "「電子を〜にたとえる」の目的語を示す。たとえられる対象は電子なので「を」が正しい。", "が": "「が」は主語を示すが、「たとえて説明した」の対象は主語ではないので合わない。", "で": "「で」は手段や場所を示すが、たとえる対象には使えない。", "と": "「と」は共同や相手を示すが、「電子とたとえて」では対象が立たない。"}, "error_tags": {"が": "主格", "で": "場所・手段", "と": "共同・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "でんきのはたらきをする、とてもちいさいつぶです。", "primary_collocate": null, "pronunciation": "でんし", "ipa": "deɴɕi", "syllable_count": 3, "sentences": [{"text": "電子は、電気を運ぶとても小さな粒です。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)は、電気(でんき)を運(はこ)ぶとても小(ちい)さな粒(つぶ)です。", "sentence_source": "generated"}, {"text": "電子が動くと、電気が流れます。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)が動(うご)くと、電気(でんき)が流(なが)れます。", "sentence_source": "generated"}, {"text": "原子のまわりには、電子があります。", "target_word": "電子", "complexity_tier": "T3", "furigana": "原子(げんし)のまわりには、電子(でんし)があります。", "sentence_source": "generated"}, {"text": "電子は小さすぎて、目では見えません。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)は小(ちい)さすぎて、目(め)では見(み)えません。", "sentence_source": "generated"}, {"text": "電子の数がふえると、マイナスの電気が強くなる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)の数(かず)がふえると、マイナスの電気(でんき)が強(つよ)くなる。", "sentence_source": "generated"}, {"text": "理科の授業で、電子のはたらきを習った。", "target_word": "電子", "complexity_tier": "T3", "furigana": "理科(りか)の授業(じゅぎょう)で、電子(でんし)のはたらきを習(なら)った。", "sentence_source": "generated"}, {"text": "電池につなぐと、電線の中を電子が流れていく。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電池(でんち)につなぐと、電線(でんせん)の中(なか)を電子(でんし)が流(なが)れていく。", "sentence_source": "generated"}, {"text": "先生は、電子を小さな玉にたとえて説明した。", "target_word": "電子", "complexity_tier": "T3", "furigana": "先生(せんせい)は、電子(でんし)を小(ちい)さな玉(たま)にたとえて説明(せつめい)した。", "sentence_source": "generated"}, {"text": "下じきをこすると、電子が移って静電気が起きる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "下(した)じきをこすると、電子(でんし)が移(うつ)って静電気(せいでんき)が起(お)きる。", "sentence_source": "generated"}, {"text": "電子の動きがわかると、電気のしくみが理解できる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)の動(うご)きがわかると、電気(でんき)のしくみが理解(りかい)できる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電子", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "理科で習う、電気を運ぶ小さな粒としての「電子」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電子", "is_correct": true, "explanation": "「電子は、電気を運ぶとても小さな粒です」と、主語が粒であることに合う。"}, {"text": "電池", "is_correct": false, "explanation": "電池は電気をためる装置で、小さな粒ではない。文の主語として合わない。"}, {"text": "電線", "is_correct": false, "explanation": "電線は電気を通す線で、小さな粒ではない。文の主語として合わない。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気の押す力を表す量で、粒ではない。「粒です」と合わない。"}], "explanations": {"電子": "「電子は、電気を運ぶとても小さな粒です」と、主語が粒であることに合う。", "電池": "電池は電気をためる装置で、小さな粒ではない。文の主語として合わない。", "電線": "電線は電気を通す線で、小さな粒ではない。文の主語として合わない。", "電圧": "電圧は電気の押す力を表す量で、粒ではない。「粒です」と合わない。"}, "sentence_index": 0, "correct_answer": "電子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎日、この電子で部屋のほこりを吸い取った。", "explanation": "ここは〈掃除機〉の意味。電子は粒で、ほこりを吸い取る家電を指さないので合わない。"}, {"text": "この電子は、三時間たつと切れてしまう。", "explanation": "ここは〈電池〉の意味。電子は粒で、時間がたつと切れる装置ではないので合わない。"}, {"text": "電子が切れると、家の電気が止まってしまう。", "explanation": "ここは〈電線〉の意味。電子は粒で、切れて電気を止める線ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電子", "is_correct": true, "explanation": "電子が電線の中を流れていくという文に合う。"}, {"text": "電圧", "is_correct": false, "explanation": "電圧は電気の押す力を表す量で、電線の中を流れていくものではない。"}, {"text": "電球", "is_correct": false, "explanation": "電球は光を出す器具で、電線の中を流れていくものではない。"}, {"text": "電柱", "is_correct": false, "explanation": "電柱は電線を支える柱で、電線の中を流れていくものではない。"}], "explanations": {"電子": "電子が電線の中を流れていくという文に合う。", "電圧": "電圧は電気の押す力を表す量で、電線の中を流れていくものではない。", "電球": "電球は光を出す器具で、電線の中を流れていくものではない。", "電柱": "電柱は電線を支える柱で、電線の中を流れていくものではない。"}, "sentence_index": 6, "correct_answer": "電子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この電子は、夜のあいだ食べ物を冷やしておく。", "explanation": "ここは〈冷蔵庫〉の意味。電子は粒で、食べ物を冷やす家電ではないので合わない。"}, {"text": "この電子は、電気で光を出す道具だ。", "explanation": "ここは〈電球〉の意味。電子は粒で、光を出す道具ではないので合わない。"}, {"text": "電子で、友だちと話した。", "explanation": "ここは〈電話〉の意味。電子は粒で、人と話すための道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金属の中では、電子を電線を通って動く。", "corrected_sentence": "金属の中では、電子が電線を通って動く。", "error_description": "「動く」の主体は電子なので、「電子が」と主格の「が」を使う。「電子を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39698, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電子を、目で見えないほど小さい。", "corrected_sentence": "電子は、目で見えないほど小さい。", "error_description": "形容詞の主題は「は」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39699, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「電子が回る」の主語を示す。「回っている」の動作主は電子なので「が」が正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「回る」は目的語をとらない自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すが、「電子に回っている」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、動く主体には使えない。"}], "correct_answer": "が", "explanations": {"が": "「電子が回る」の主語を示す。「回っている」の動作主は電子なので「が」が正しい。", "を": "「を」は目的語を示すが、「回る」は目的語をとらない自動詞なので合わない。", "に": "「に」は位置や相手を示すが、「電子に回っている」では意味が通らない。", "で": "「で」は場所や手段を示すが、動く主体には使えない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
