INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39699, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "原子よりもはるかに小さい、負の電荷をもつ粒子。電気や磁気のはたらきに関わります。", "primary_collocate": null, "pronunciation": "でんし", "ipa": "deɴɕi", "syllable_count": 3, "sentences": [{"text": "電子は、負の電荷をもつ素粒子の一つである。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)は、負(ふ)の電荷(でんか)をもつ素粒子(そりゅうし)の一つである。", "sentence_source": "generated"}, {"text": "原子の中では、電子が原子核のまわりを回っている。", "target_word": "電子", "complexity_tier": "T3", "furigana": "原子(げんし)の中(なか)では、電子(でんし)が原子核(げんしかく)のまわりを回(まわ)っている。", "sentence_source": "generated"}, {"text": "電子はマイナスの電気をもつ、とても小さな粒子だ。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)はマイナスの電気(でんき)をもつ、とても小(ちい)さな粒子(りゅうし)だ。", "sentence_source": "generated"}, {"text": "金属の中を電子が動くことで、電流が流れる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "金属(きんぞく)の中(なか)を電子(でんし)が動(うご)くことで、電流(でんりゅう)が流(なが)れる。", "sentence_source": "generated"}, {"text": "電子の数が変わると、物質は電気を帯びる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)の数(かず)が変(か)わると、物質(ぶっしつ)は電気(でんき)を帯(お)びる。", "sentence_source": "generated"}, {"text": "実験では、電子の動きを特殊な装置で調べた。", "target_word": "電子", "complexity_tier": "T3", "furigana": "実験(じっけん)では、電子(でんし)の動(うご)きを特殊(とくしゅ)な装置(そうち)で調(しら)べた。", "sentence_source": "generated"}, {"text": "電子は原子核よりはるかに軽く、電場の力で動きやすい。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)は原子核(げんしかく)よりはるかに軽(かる)く、電場(でんば)の力(ちから)で動(うご)きやすい。", "sentence_source": "generated"}, {"text": "静電気は、物体の間で電子が移ることで起こる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "静電気(せいでんき)は、物体(ぶったい)の間(あいだ)で電子(でんし)が移(うつ)ることで起(お)こる。", "sentence_source": "generated"}, {"text": "電子が高いエネルギーの状態から低い状態に移ると、光が出る。", "target_word": "電子", "complexity_tier": "T3", "furigana": "電子(でんし)が高(たか)いエネルギーの状態(じょうたい)から低(ひく)い状態(じょうたい)に移(うつ)ると、光(ひかり)が出(で)る。", "sentence_source": "generated"}, {"text": "原子が電子を失うと、プラスの電気を帯びる。", "target_word": "電子", "complexity_tier": "T3", "furigana": "原子(げんし)が電子(でんし)を失(うしな)うと、プラスの電気(でんき)を帯(お)びる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "電子", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物理で、原子の中にあり負の電荷をもつ素粒子としての「電子」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: 電場 (Zipf 2.12)']::text[], '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39699, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "電子", "is_correct": true, "explanation": "「電子は、負の電荷をもつ素粒子の一つである」と、この定義文に合う。"}, {"text": "陽子", "is_correct": false, "explanation": "陽子は正の電荷をもつので、「負の電荷」の文には合わない。"}, {"text": "中性子", "is_correct": false, "explanation": "中性子は電荷をもたないので、「負の電荷」の文には合わない。"}, {"text": "光子", "is_correct": false, "explanation": "光子も電荷をもたず、「負の電荷をもつ」素粒子ではないので合わない。"}], "explanations": {"電子": "「電子は、負の電荷をもつ素粒子の一つである」と、この定義文に合う。", "陽子": "陽子は正の電荷をもつので、「負の電荷」の文には合わない。", "中性子": "中性子は電荷をもたないので、「負の電荷」の文には合わない。", "光子": "光子も電荷をもたず、「負の電荷をもつ」素粒子ではないので合わない。"}, "sentence_index": 0, "correct_answer": "電子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、この電子が鳴って私を起こしてくれる。", "explanation": "ここは〈目覚まし時計〉の意味。電子は粒子で、鳴って人を起こす機械を指さないので合わない。"}, {"text": "毎日、この電子で床のごみを吸い取っている。", "explanation": "ここは〈掃除機〉の意味。電子は粒子で、ごみを吸い取る家電を指さないので合わない。"}, {"text": "この電子は、一度の充電で一週間使える。", "explanation": "ここは〈電池〉の意味。電子は粒子で、充電して使う装置を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39699, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電子", "is_correct": true, "explanation": "電子は原子核より軽く、電場の力で動きやすい粒子。文の内容に合う。"}, {"text": "光子", "is_correct": false, "explanation": "光子は電気をもたず電場の力を受けないので、「電場の力で動きやすい」と合わない。"}, {"text": "分子", "is_correct": false, "explanation": "分子は電気的にまとまった重い粒で、電場の力で動きやすいとは言えない。"}, {"text": "ニュートリノ", "is_correct": false, "explanation": "ニュートリノは電気をもたないので、電場の力では動かず、文の内容と合わない。"}], "explanations": {"電子": "電子は原子核より軽く、電場の力で動きやすい粒子。文の内容に合う。", "光子": "光子は電気をもたず電場の力を受けないので、「電場の力で動きやすい」と合わない。", "分子": "分子は電気的にまとまった重い粒で、電場の力で動きやすいとは言えない。", "ニュートリノ": "ニュートリノは電気をもたないので、電場の力では動かず、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "電子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "台風の夜、電子が止まって部屋が真っ暗になった。", "explanation": "ここは〈電気〉の意味。電子は粒子で、停電で止まる電力そのものを指さないので合わない。"}, {"text": "この電池の電子は、一・五ボルトだ。", "explanation": "ここは〈電圧〉の意味。電子は粒子で、ボルトで表す電位差を指さないので合わない。"}, {"text": "この回路の電子は、一アンペアだ。", "explanation": "ここは〈電流〉の意味。電子は粒子で、アンペアで測る電流の大きさを指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39699, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金属の中では、電子を自由に動きまわる。", "corrected_sentence": "金属の中では、電子が自由に動きまわる。", "error_description": "「動きまわる」は自動詞で、動く主体の「電子」には「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39699, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電子を電場の力で引かれる。", "corrected_sentence": "電子は電場の力で引かれる。", "error_description": "受身文の主語は「は」か「が」で示す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39700, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「工作の時間」の連体修飾を示す。「工作」と「時間」を結ぶので「の」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「工作が時間に」では文の構造が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「工作を時間」では名詞どうしがつながらない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「工作で時間」では修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「工作の時間」の連体修飾を示す。「工作」と「時間」を結ぶので「の」が正しい。", "が": "「が」は主語を示すが、「工作が時間に」では文の構造が成り立たない。", "を": "「を」は目的語を示すが、「工作を時間」では名詞どうしがつながらない。", "で": "「で」は場所や手段を示すが、「工作で時間」では修飾にならない。"}, "error_tags": {"が": "主格", "を": "目的語", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39700, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「工作に使う」の目的を示す。「使う」は「〜に使う」の形をとるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「工作を使う」では意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「工作が使う色紙」では色紙を使う主体にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や相手を示すが、「工作と使う」では意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「工作に使う」の目的を示す。「使う」は「〜に使う」の形をとるので正しい。", "を": "「を」は目的語を示すが、「工作を使う」では意味が通らない。", "が": "「が」は主語を示すが、「工作が使う色紙」では色紙を使う主体にならない。", "と": "「と」は共同や相手を示すが、「工作と使う」では意味が通らない。"}, "error_tags": {"を": "目的語", "が": "主格", "と": "共同・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39700, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "手や道具を使って、何かを作ること。", "primary_collocate": null, "pronunciation": "こうさく", "ipa": "koːsakɯ", "syllable_count": 4, "sentences": [{"text": "今日の工作では、紙でお面を作りました。", "target_word": "工作", "complexity_tier": "T3", "furigana": "今日(きょう)の工作(こうさく)では、紙(かみ)でお面(めん)を作(つく)りました。", "sentence_source": "generated"}, {"text": "工作の時間に、ペットボトルでロケットを作った。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)の時間(じかん)に、ペットボトルでロケットを作(つく)った。", "sentence_source": "generated"}, {"text": "妹は工作が好きで、毎日何か作っている。", "target_word": "工作", "complexity_tier": "T3", "furigana": "妹(いもうと)は工作(こうさく)が好(す)きで、毎日(まいにち)何(なに)か作(つく)っている。", "sentence_source": "generated"}, {"text": "はさみとのりを使って、工作をしました。", "target_word": "工作", "complexity_tier": "T3", "furigana": "はさみとのりを使(つか)って、工作(こうさく)をしました。", "sentence_source": "generated"}, {"text": "夏休みの宿題で、工作を出さなければならない。", "target_word": "工作", "complexity_tier": "T3", "furigana": "夏休(なつやす)みの宿題(しゅくだい)で、工作(こうさく)を出(だ)さなければならない。", "sentence_source": "generated"}, {"text": "工作で作った箱に、おもちゃを入れている。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)で作(つく)った箱(はこ)に、おもちゃを入(い)れている。", "sentence_source": "generated"}, {"text": "工作がうまくできて、先生にほめられた。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)がうまくできて、先生(せんせい)にほめられた。", "sentence_source": "generated"}, {"text": "工作に使う色紙を、教室に持っていった。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)に使(つか)う色紙(いろがみ)を、教室(きょうしつ)に持(も)っていった。", "sentence_source": "generated"}, {"text": "父と工作をして、木の小さな椅子を作った。", "target_word": "工作", "complexity_tier": "T3", "furigana": "父(ちち)と工作(こうさく)をして、木(き)の小(ちい)さな椅子(いす)を作(つく)った。", "sentence_source": "generated"}, {"text": "工作をすると、手を動かしながら考える力が育つ。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)をすると、手(て)を動(うご)かしながら考(かんが)える力(ちから)が育(そだ)つ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工作", "label": "基本形"}, {"form": "工作する", "label": "サ変動詞形"}], "register": "neutral", "sense_fingerprint": "紙や木などを使い、手や道具で何かを作ること。図画工作の「工作」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39700, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作", "is_correct": true, "explanation": "「今日の工作では、紙でお面を作りました」の活動名として自然。"}, {"text": "天気", "is_correct": false, "explanation": "「今日の天気では、紙でお面を作りました」は意味が通らない。"}, {"text": "試合", "is_correct": false, "explanation": "「今日の試合では、紙でお面を作りました」は意味が通らない。"}, {"text": "旅行", "is_correct": false, "explanation": "「今日の旅行では、紙でお面を作りました」は意味が通らない。"}], "explanations": {"工作": "「今日の工作では、紙でお面を作りました」の活動名として自然。", "天気": "「今日の天気では、紙でお面を作りました」は意味が通らない。", "試合": "「今日の試合では、紙でお面を作りました」は意味が通らない。", "旅行": "「今日の旅行では、紙でお面を作りました」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "工作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みの工作で、海の思い出を書いた。", "explanation": "ここは〈作文〉の意味。工作は手で物を作ることで、文章を書く意味では合わない。"}, {"text": "夕飯の工作で、野菜を切った。", "explanation": "ここは〈料理〉の意味。工作は物を作ることで、食材を切る調理の意味では合わない。"}, {"text": "毎朝、玄関の工作で床をふいた。", "explanation": "ここは〈掃除〉の意味。工作は物づくりで、床をふく意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39700, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作", "is_correct": true, "explanation": "「工作がうまくできて」の主語として、ものを作る活動の名詞が自然。"}, {"text": "天気", "is_correct": false, "explanation": "「天気がうまくできて」は意味が通らない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震がうまくできて」は意味が通らない。"}, {"text": "台風", "is_correct": false, "explanation": "「台風がうまくできて」は意味が通らない。"}], "explanations": {"工作": "「工作がうまくできて」の主語として、ものを作る活動の名詞が自然。", "天気": "「天気がうまくできて」は意味が通らない。", "地震": "「地震がうまくできて」は意味が通らない。", "台風": "「台風がうまくできて」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "工作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝の工作で、近所の公園を散歩した。", "explanation": "ここは〈散歩〉の意味。工作は手や道具で物を作ることで、歩いて出かける意味では合わない。"}, {"text": "体育の工作で、グラウンドを走った。", "explanation": "ここは〈運動〉の意味。工作はものを作る活動で、走る運動の意味では合わない。"}, {"text": "国語の工作で、漢字を覚えた。", "explanation": "ここは〈勉強〉の意味。工作はものを作る活動で、漢字を覚える学習の意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39700, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は工作を好きで、毎晩紙の人形を作っている。", "corrected_sentence": "弟は工作が好きで、毎晩紙の人形を作っている。", "error_description": "「好き」は対象に「が」をとる。「工作」には「が」を使うので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
