INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39701, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「工作が得意」の対象を示す。「得意」は「が」をとるので正しい。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「得意」は「が」をとるので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は相手や方向を示すが、「工作に得意」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「得意」の対象には使えない。"}], "correct_answer": "が", "explanations": {"が": "「工作が得意」の対象を示す。「得意」は「が」をとるので正しい。", "を": "「を」は目的語を示すが、「得意」は「が」をとるので合わない。", "に": "「に」は相手や方向を示すが、「工作に得意」では意味が通らない。", "で": "「で」は場所や手段を示すが、「得意」の対象には使えない。"}, "error_tags": {"を": "目的語", "に": "相手・方向", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39701, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「工作が好き」の対象を示す。「好き」は「が」をとるので正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「工作へ好き」では「好き」の対象にならず合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「工作から好き」では「好き」の対象を示せず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並べる相手を示すが、「工作と好き」では「好き」の対象が一つにならず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「工作が好き」の対象を示す。「好き」は「が」をとるので正しい。", "へ": "「へ」は方向を示すが、「工作へ好き」では「好き」の対象にならず合わない。", "から": "「から」は起点を示すが、「工作から好き」では「好き」の対象を示せず合わない。", "と": "「と」は並べる相手を示すが、「工作と好き」では「好き」の対象が一つにならず文が成り立たない。"}, "error_tags": {"へ": "方向", "から": "起点", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39701, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "材料を加工したり組み立てたりして、目的のものを作り出すこと。特に、機械や電気製品などを自分で作ることを指す。", "primary_collocate": null, "pronunciation": "こうさく", "ipa": "koːsakɯ", "syllable_count": 4, "sentences": [{"text": "部品を組み立てる工作では、配線を先に確かめる。", "target_word": "工作", "complexity_tier": "T3", "furigana": "部品(ぶひん)を組(く)み立(た)てる工作(こうさく)では、配線(はいせん)を先(さき)に確(たし)かめる。", "sentence_source": "generated"}, {"text": "兄は工作が得意で、古いラジオを自分で直した。", "target_word": "工作", "complexity_tier": "T3", "furigana": "兄(あに)は工作(こうさく)が得意(とくい)で、古(ふる)いラジオを自分(じぶん)で直(なお)した。", "sentence_source": "generated"}, {"text": "部品を買い集めて、小さなロボットの工作に取りかかった。", "target_word": "工作", "complexity_tier": "T3", "furigana": "部品(ぶひん)を買(か)い集(あつ)めて、小(ちい)さなロボットの工作(こうさく)に取(と)りかかった。", "sentence_source": "generated"}, {"text": "この工作には、はんだごてとテスターが必要だ。", "target_word": "工作", "complexity_tier": "T3", "furigana": "この工作(こうさく)には、はんだごてとテスターが必要(ひつよう)だ。", "sentence_source": "generated"}, {"text": "工作の途中で配線を間違え、最初からやり直した。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)の途中(とちゅう)で配線(はいせん)を間違(まちが)え、最初(さいしょ)からやり直(なお)した。", "sentence_source": "generated"}, {"text": "彼は工作で作ったアンプを、友人に自慢した。", "target_word": "工作", "complexity_tier": "T3", "furigana": "彼(かれ)は工作(こうさく)で作(つく)ったアンプを、友人(ゆうじん)に自慢(じまん)した。", "sentence_source": "generated"}, {"text": "材料費が安いので、初心者でも工作を始めやすい。", "target_word": "工作", "complexity_tier": "T3", "furigana": "材料費(ざいりょうひ)が安(やす)いので、初心者(しょしんしゃ)でも工作(こうさく)を始(はじ)めやすい。", "sentence_source": "generated"}, {"text": "工作が好きな私は、棚も自分で組み立てた。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)が好(す)きな私(わたし)は、棚(たな)も自分(じぶん)で組(く)み立(た)てた。", "sentence_source": "generated"}, {"text": "工作に使う電池を、ホームセンターで買った。", "target_word": "工作", "complexity_tier": "T3", "furigana": "工作(こうさく)に使(つか)う電池(でんち)を、ホームセンターで買(か)った。", "sentence_source": "generated"}, {"text": "夏休みの工作で、風で動く小さな車を作った。", "target_word": "工作", "complexity_tier": "T3", "furigana": "夏休(なつやす)みの工作(こうさく)で、風(かぜ)で動(うご)く小(ちい)さな車(くるま)を作(つく)った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工作", "label": "基本形"}, {"form": "工作する", "label": "サ変動詞形"}], "register": "neutral", "sense_fingerprint": "機械や電気製品などを自分で組み立てて作ること。裏工作の「工作」ではない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作", "is_correct": true, "explanation": "「部品を組み立てる工作では」の活動名として自然。配線を確かめる作業と合う。"}, {"text": "料理", "is_correct": false, "explanation": "「部品を組み立てる料理では、配線を先に確かめる」は意味が通らない。"}, {"text": "旅行", "is_correct": false, "explanation": "「部品を組み立てる旅行では、配線を先に確かめる」は意味が通らない。"}, {"text": "掃除", "is_correct": false, "explanation": "「部品を組み立てる掃除では、配線を先に確かめる」は意味が通らない。"}], "explanations": {"工作": "「部品を組み立てる工作では」の活動名として自然。配線を確かめる作業と合う。", "料理": "「部品を組み立てる料理では、配線を先に確かめる」は意味が通らない。", "旅行": "「部品を組み立てる旅行では、配線を先に確かめる」は意味が通らない。", "掃除": "「部品を組み立てる掃除では、配線を先に確かめる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "工作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みの工作で、海まで出かけた。", "explanation": "ここは〈旅行〉の意味。工作は物を作ることで、出かける意味では合わない。"}, {"text": "理科の工作で、水の温度を測った。", "explanation": "ここは〈実験〉の意味。工作は物を組み立てることで、温度を測る意味では合わない。"}, {"text": "道路の工作で、この先は通行止めだ。", "explanation": "ここは〈工事〉の意味。工作は機械や製品を組み立てる行為で、道路の施工には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作", "is_correct": true, "explanation": "「材料費が安いので、初心者でも工作を始めやすい」の「工作」は、ものを作る活動として自然。"}, {"text": "停電", "is_correct": false, "explanation": "「停電を始めやすい」は意味が通らない。電気が止まる出来事で、始める活動ではない。"}, {"text": "渋滞", "is_correct": false, "explanation": "「渋滞を始めやすい」は意味が通らない。車が止まる状態で、始める活動ではない。"}, {"text": "台風", "is_correct": false, "explanation": "「台風を始めやすい」は意味が通らない。自然現象で、始める活動ではない。"}], "explanations": {"工作": "「材料費が安いので、初心者でも工作を始めやすい」の「工作」は、ものを作る活動として自然。", "停電": "「停電を始めやすい」は意味が通らない。電気が止まる出来事で、始める活動ではない。", "渋滞": "「渋滞を始めやすい」は意味が通らない。車が止まる状態で、始める活動ではない。", "台風": "「台風を始めやすい」は意味が通らない。自然現象で、始める活動ではない。"}, "sentence_index": 6, "correct_answer": "工作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕食の工作で、魚を焼いた。", "explanation": "ここは〈料理〉の意味。工作は物を組み立てることで、食べ物を調理する意味では合わない。"}, {"text": "テスト前の工作で、ノートをまとめた。", "explanation": "ここは〈勉強〉の意味。工作は物づくりで、ノートをまとめる学習の意味では合わない。"}, {"text": "休みの日に、部屋の工作で窓を拭いた。", "explanation": "ここは〈掃除〉の意味。工作は物づくりで、窓を拭く意味では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
