INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みの工作を終わって、ほっとした。", "corrected_sentence": "夏休みの工作を終えて、ほっとした。", "error_description": "「工作を」と目的語をとるのは他動詞の「終える」。「終わる」は自動詞なので、「を」と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
