INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39702, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "何かと何かが、ちょうどよく合うこと。", "primary_collocate": null, "pronunciation": "ぴったり", "ipa": "pitːaɾi", "syllable_count": 4, "sentences": [{"text": "この靴は足にぴったりです。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "この靴[くつ]は足[あし]にぴったりです。", "sentence_source": "generated"}, {"text": "ふたがびんにぴったり合いました。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "ふたがびんにぴったり合[あ]いました。", "sentence_source": "generated"}, {"text": "二つの数字がぴったり同じだった。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "二[ふた]つの数字[すうじ]がぴったり同[おな]じだった。", "sentence_source": "generated"}, {"text": "新しいかばんは、ぴったり棚に入る。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "新[あたら]しいかばんは、ぴったり棚[たな]に入[はい]る。", "sentence_source": "generated"}, {"text": "このワンピースは私にぴったりのサイズです。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "このワンピースは私[わたし]にぴったりのサイズです。", "sentence_source": "generated"}, {"text": "時計の針がぴったり十二時を指した。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "時計[とけい]の針[はり]がぴったり十二時[じゅうにじ]を指[さ]した。", "sentence_source": "generated"}, {"text": "ドアがぴったり閉まって、風が入らない。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "ドアがぴったり閉[し]まって、風[かぜ]が入[はい]らない。", "sentence_source": "generated"}, {"text": "絵の大きさに合わせて、ぴったりの額を買った。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "絵[え]の大[おお]きさに合[あ]わせて、ぴったりの額[がく]を買[か]った。", "sentence_source": "generated"}, {"text": "計算の答えがぴったり合って、うれしかった。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "計算[けいさん]の答[こた]えがぴったり合[あ]って、うれしかった。", "sentence_source": "generated"}, {"text": "この箱は、本を入れるとぴったりだった。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "この箱[はこ]は、本[ほん]を入[い]れるとぴったりだった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ぴったりだ", "label": "断定形"}, {"form": "ぴったりな", "label": "連体形"}, {"form": "ぴったりの", "label": "連体形（の）"}, {"form": "ぴったりと", "label": "副詞形"}], "register": "口語", "sense_fingerprint": "二つの物がすきまなくちょうど合う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "足と靴が隙間なく合うという意味で、この文の空所に入る。"}, {"text": "派手", "is_correct": false, "explanation": "色や装いが目立つさま。「足に派手です」は意味が通らない。"}, {"text": "静か", "is_correct": false, "explanation": "音や動きが少ないさま。靴の合い方の話には当てはまらない。"}, {"text": "新鮮", "is_correct": false, "explanation": "できたてで生き生きしたさま。靴と足の関係には使えない。"}], "explanations": {"ぴったり": "足と靴が隙間なく合うという意味で、この文の空所に入る。", "派手": "色や装いが目立つさま。「足に派手です」は意味が通らない。", "静か": "音や動きが少ないさま。靴の合い方の話には当てはまらない。", "新鮮": "できたてで生き生きしたさま。靴と足の関係には使えない。"}, "sentence_index": 0, "correct_answer": "ぴったり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宿題のことを、ぴったり忘れていた。", "explanation": "ここは〈すっかり〉の意味。ぴったりは物や条件が合うことを表し、忘れてしまった程度は表さない。"}, {"text": "彼は提案を、ぴったり断った。", "explanation": "ここは〈きっぱり〉の意味。ぴったりは条件に合うことを表し、断り方の強さは表さない。"}, {"text": "駅で昔の友だちにぴったり会った。", "explanation": "ここは〈偶然出会う〉のばったりの意味。ぴったりは物や条件が合うことを表し、人と偶然出くわす場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "戸が枠に隙間なく閉まる様子を表し、この空所に入る。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "深く眠る様子を表す。ドアが閉まる様子には使えない。"}, {"text": "うっとり", "is_correct": false, "explanation": "心を奪われて夢見心地になる様子。ドアの動きとは合わない。"}, {"text": "のんびり", "is_correct": false, "explanation": "ゆったりと落ち着いた様子。ドアが閉まる動作の様子としては不自然。"}], "explanations": {"ぴったり": "戸が枠に隙間なく閉まる様子を表し、この空所に入る。", "ぐっすり": "深く眠る様子を表す。ドアが閉まる様子には使えない。", "うっとり": "心を奪われて夢見心地になる様子。ドアの動きとは合わない。", "のんびり": "ゆったりと落ち着いた様子。ドアが閉まる動作の様子としては不自然。"}, "sentence_index": 6, "correct_answer": "ぴったり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜は部屋でぴったり眠った。", "explanation": "ここは〈ぐっすり〉の意味。ぴったりは物や条件が合うことを表し、眠りの深さには使わない。"}, {"text": "難しい本を、ぴったり読んだ。", "explanation": "ここは〈すらすら〉の意味。ぴったりは物や条件が合うことを表し、読むスピードや流暢さは表さない。"}, {"text": "彼女は、ぴったり笑った。", "explanation": "ここは〈にっこり〉の意味。ぴったりは笑い方を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドアが枠にぴったと閉まった。", "corrected_sentence": "ドアが枠にぴったりと閉まった。", "error_description": "誤った形は「ぴったと」。副詞形は「ぴったりと」で、「ぴったと」という語形はない。隙間なく閉まる様子を表すには副詞形「ぴったりと」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "動詞「合う」を直接修飾する語幹の形。この位置で正しい形。"}, {"text": "ぴったりな", "is_correct": false, "explanation": "連体形で名詞の前に置く。「合いました」を修飾する位置には入らない。"}, {"text": "ぴったりの", "is_correct": false, "explanation": "連体形（の）で名詞の前に置く。動詞の前では使えない。"}, {"text": "ぴったりだ", "is_correct": false, "explanation": "断定形で文末に来る。「合いました」の前には置けない。"}], "correct_form": "ぴったり", "base_form": "ぴったり", "form_label": "語幹", "sentence_index": 1, "explanations": {"ぴったり": "動詞「合う」を直接修飾する語幹の形。この位置で正しい形。", "ぴったりな": "連体形で名詞の前に置く。「合いました」を修飾する位置には入らない。", "ぴったりの": "連体形（の）で名詞の前に置く。動詞の前では使えない。", "ぴったりだ": "断定形で文末に来る。「合いました」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓がぴったりを閉まって、音が聞こえない。", "corrected_sentence": "窓がぴったり閉まって、音が聞こえない。", "error_description": "「ぴったり」は副詞なので、直後に助詞「を」は付かない。「閉まって」に直接かかる形が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "「ぴったりの額」の語幹で、「の」の前に来る形。"}, {"text": "ぴったりだ", "is_correct": false, "explanation": "断定形で、名詞の前には置けない。「ぴったりだの額」は成り立たない。"}, {"text": "ぴったりです", "is_correct": false, "explanation": "丁寧な述語の形で、「の額」の前には置けない。"}, {"text": "ぴったりと", "is_correct": false, "explanation": "副詞形で、名詞を直接修飾しない。「ぴったりとの額」は成り立たない。"}], "correct_form": "ぴったり", "base_form": "ぴったり", "form_label": "語幹", "sentence_index": 7, "explanations": {"ぴったり": "「ぴったりの額」の語幹で、「の」の前に来る形。", "ぴったりだ": "断定形で、名詞の前には置けない。「ぴったりだの額」は成り立たない。", "ぴったりです": "丁寧な述語の形で、「の額」の前には置けない。", "ぴったりと": "副詞形で、名詞を直接修飾しない。「ぴったりとの額」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
