INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39703, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある条件や状況に、ちょうどよく合っているさま。", "primary_collocate": null, "pronunciation": "ぴったり", "ipa": "pitːaɾi", "syllable_count": 4, "sentences": [{"text": "雨の日にぴったりの映画を見つけた。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]にぴったりの映画[えいが]を見[み]つけた。", "sentence_source": "generated"}, {"text": "このカレーは、寒い夜にぴったりの料理です。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "このカレーは、寒[さむ]い夜[よる]にぴったりの料理[りょうり]です。", "sentence_source": "generated"}, {"text": "彼は営業の仕事にぴったりな人だ。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "彼[かれ]は営業[えいぎょう]の仕事[しごと]にぴったりな人[ひと]だ。", "sentence_source": "generated"}, {"text": "友だちへの贈り物に、このハンカチはぴったりだと思う。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "友[とも]だちへの贈[おく]り物[もの]に、このハンカチはぴったりだと思[おも]う。", "sentence_source": "generated"}, {"text": "静かなこの町は、休みを過ごすのにぴったりです。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "静[しず]かなこの町[まち]は、休[やす]みを過[す]ごすのにぴったりです。", "sentence_source": "generated"}, {"text": "運動のあとは、冷たい水がぴったりだ。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "運動[うんどう]のあとは、冷[つめ]たい水[みず]がぴったりだ。", "sentence_source": "generated"}, {"text": "「頼りになる」という言葉は、彼にぴったりだ。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "「頼[たよ]りになる」という言葉[ことば]は、彼[かれ]にぴったりだ。", "sentence_source": "generated"}, {"text": "子どもの誕生日にぴったりのケーキを予約した。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "子[こ]どもの誕生日[たんじょうび]にぴったりのケーキを予約[よやく]した。", "sentence_source": "generated"}, {"text": "この部屋は、一人で勉強するのにぴったりです。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "この部屋[へや]は、一人[ひとり]で勉強[べんきょう]するのにぴったりです。", "sentence_source": "generated"}, {"text": "夏の海にぴったりの音楽を流した。", "target_word": "ぴったり", "complexity_tier": "T3", "furigana": "夏[なつ]の海[うみ]にぴったりの音楽[おんがく]を流[なが]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ぴったりだ", "label": "断定形"}, {"form": "ぴったりな", "label": "連体形"}, {"form": "ぴったりの", "label": "連体形（の）"}, {"form": "ぴったりです", "label": "丁寧形"}], "register": "口語", "sense_fingerprint": "条件や場面にちょうどふさわしい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39703, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "雨の日という場面にちょうど合う、の意味で入る。"}, {"text": "静か", "is_correct": false, "explanation": "音や動きが少ないさま。「雨の日に静かの映画」は不自然で、映画の選び方に合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "できたてで生き生きしたさま。映画を場面に合わせる文には合わない。"}, {"text": "派手", "is_correct": false, "explanation": "目立つさま。「雨の日に派手の映画」は場面との適合を表せない。"}], "explanations": {"ぴったり": "雨の日という場面にちょうど合う、の意味で入る。", "静か": "音や動きが少ないさま。「雨の日に静かの映画」は不自然で、映画の選び方に合わない。", "新鮮": "できたてで生き生きしたさま。映画を場面に合わせる文には合わない。", "派手": "目立つさま。「雨の日に派手の映画」は場面との適合を表せない。"}, "sentence_index": 0, "correct_answer": "ぴったり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は質問に、ぴったり答えた。", "explanation": "ここは〈はっきり〉の意味。ぴったりは条件に合うことを表し、答え方の明確さは表さない。"}, {"text": "彼は仕事を、ぴったり片付けた。", "explanation": "ここは〈てきぱき〉の意味。ぴったりは場面や条件に合うことを表し、手際のよさは表さない。"}, {"text": "昨夜はぴったり眠った。", "explanation": "ここは〈ぐっすり〉の意味。ぴったりは場面に合うことを表し、眠りの深さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39703, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "彼という人にふさわしい、の意味で空所に入る。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく快活な性格を表す。「彼に陽気だ」は、ふさわしさを言う文に合わない。"}, {"text": "無口", "is_correct": false, "explanation": "口数が少ないさま。「頼りになる言葉」の話とは関係がない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深いさま。言葉と人の適合の話には当てはまらない。"}], "explanations": {"ぴったり": "彼という人にふさわしい、の意味で空所に入る。", "陽気": "明るく快活な性格を表す。「彼に陽気だ」は、ふさわしさを言う文に合わない。", "無口": "口数が少ないさま。「頼りになる言葉」の話とは関係がない。", "慎重": "注意深いさま。言葉と人の適合の話には当てはまらない。"}, "sentence_index": 6, "correct_answer": "ぴったり"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その話を聞いて、彼はぴったり感動した。", "explanation": "ここは〈しみじみ〉の意味。ぴったりは条件に合うことを表し、感慨の深さは表さない。"}, {"text": "彼女は、ぴったり笑った。", "explanation": "ここは〈にっこり〉の意味。ぴったりは笑い方を表す語ではない。"}, {"text": "富士山が、ぴったり見えた。", "explanation": "ここは〈くっきり〉の意味。ぴったりは隙間なく合うことで、見え方の明瞭さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39703, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この料理は、寒い夜ぴったりだ。", "corrected_sentence": "この料理は、寒い夜にぴったりだ。", "error_description": "「ぴったり」は場面を示すときに「～に」を伴う。「夜ぴったり」は助詞「に」が抜けているので、正しくは「夜にぴったり」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "「の料理」の前に来る語幹の形。この文の形として正しい。"}, {"text": "ぴったりだ", "is_correct": false, "explanation": "断定形で、名詞の前には置けない。「ぴったりだの料理」は成り立たない。"}, {"text": "ぴったりです", "is_correct": false, "explanation": "丁寧な述語の形で、「の料理」の前には置けない。"}, {"text": "ぴったりと", "is_correct": false, "explanation": "副詞形で、名詞を直接修飾しない。「ぴったりとの料理」は成り立たない。"}], "correct_form": "ぴったり", "base_form": "ぴったり", "form_label": "語幹", "sentence_index": 1, "explanations": {"ぴったり": "「の料理」の前に来る語幹の形。この文の形として正しい。", "ぴったりだ": "断定形で、名詞の前には置けない。「ぴったりだの料理」は成り立たない。", "ぴったりです": "丁寧な述語の形で、「の料理」の前には置けない。", "ぴったりと": "副詞形で、名詞を直接修飾しない。「ぴったりとの料理」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39703, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏の海に、ぴったりだ音楽を流した。", "corrected_sentence": "夏の海に、ぴったりな音楽を流した。", "error_description": "「ぴったり」が名詞を修飾するときは「な」か「の」が必要。「ぴったりだ音楽」は「だ」が名詞の前で誤り。正しくは「ぴったりな音楽」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ぴったり", "is_correct": true, "explanation": "「の ケーキ」の前に来る語幹の形。この文の形として正しい。"}, {"text": "ぴったりな", "is_correct": false, "explanation": "連体形。「なのケーキ」と続けると文として成り立たず、「の」の前には置けない。"}, {"text": "ぴったりに", "is_correct": false, "explanation": "連用形で、動詞や形容詞を修飾する。名詞「ケーキ」の前には直接置けない。"}, {"text": "ぴったりだった", "is_correct": false, "explanation": "過去の断定形。「だったのケーキ」は成り立たず、名詞の前に入らない。"}], "correct_form": "ぴったり", "base_form": "ぴったり", "form_label": "語幹", "sentence_index": 7, "explanations": {"ぴったり": "「の ケーキ」の前に来る語幹の形。この文の形として正しい。", "ぴったりな": "連体形。「なのケーキ」と続けると文として成り立たず、「の」の前には置けない。", "ぴったりに": "連用形で、動詞や形容詞を修飾する。名詞「ケーキ」の前には直接置けない。", "ぴったりだった": "過去の断定形。「だったのケーキ」は成り立たず、名詞の前に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「絵の完成」の「の」で、絵と完成をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す「を」では、名詞どうしをつなげない。"}, {"text": "に", "is_correct": false, "explanation": "時点や相手を示す「に」では、「絵に完成まで」が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、「絵へ完成」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「絵の完成」の「の」で、絵と完成をつなぐ。", "を": "目的語を示す「を」では、名詞どうしをつなげない。", "に": "時点や相手を示す「に」では、「絵に完成まで」が成り立たない。", "へ": "方向を示す「へ」では、「絵へ完成」は意味が通らない。"}, "error_tags": {"の": "連体修飾（名詞をつなぐ）", "を": "目的語", "に": "時点・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「春に完成する」の「に」で、完成する時期を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」では、「春を完成する」となり、春を仕上げる意味になって誤り。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す「で」では、時期の意味にならない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」では、「春が完成する」となり意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「春に完成する」の「に」で、完成する時期を表す。", "を": "目的語の「を」では、「春を完成する」となり、春を仕上げる意味になって誤り。", "で": "手段や場所を示す「で」では、時期の意味にならない。", "が": "主語の「が」では、「春が完成する」となり意味が通らない。"}, "error_tags": {"に": "時期", "を": "目的語", "で": "手段・場所", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "作っていたものが、全部できあがること。", "primary_collocate": null, "pronunciation": "かんせい", "ipa": "kanseː", "syllable_count": 4, "sentences": [{"text": "三か月かかった家が、ついに完成した。", "target_word": "完成", "complexity_tier": "T3", "furigana": "三[さん]か月[げつ]かかった家[いえ]が、ついに完成[かんせい]した。", "sentence_source": "generated"}, {"text": "絵の完成まで、あと二日ほどかかりそうです。", "target_word": "完成", "complexity_tier": "T3", "furigana": "絵[え]の完成[かんせい]まで、あと二日[ふつか]ほどかかりそうです。", "sentence_source": "generated"}, {"text": "完成した模型を、みんなでクラスの前に並べました。", "target_word": "完成", "complexity_tier": "T3", "furigana": "完成[かんせい]した模型[もけい]を、みんなでクラスの前[まえ]に並[なら]べました。", "sentence_source": "generated"}, {"text": "橋の完成を祝って、町では小さなお祭りが開かれた。", "target_word": "完成", "complexity_tier": "T3", "furigana": "橋[はし]の完成[かんせい]を祝[いわ]って、町[まち]では小[ちい]さなお祭[まつ]りが開[ひら]かれた。", "sentence_source": "generated"}, {"text": "材料が足りなくて、料理はまだ完成していません。", "target_word": "完成", "complexity_tier": "T3", "furigana": "材料[ざいりょう]が足[た]りなくて、料理[りょうり]はまだ完成[かんせい]していません。", "sentence_source": "generated"}, {"text": "兄は夏休みの間に、大きなパズルを完成させた。", "target_word": "完成", "complexity_tier": "T3", "furigana": "兄[あに]は夏休[なつやす]みの間[あいだ]に、大[おお]きなパズルを完成[かんせい]させた。", "sentence_source": "generated"}, {"text": "完成までの道は長かったが、最後まであきらめなかった。", "target_word": "完成", "complexity_tier": "T3", "furigana": "完成[かんせい]までの道[みち]は長[なが]かったが、最後[さいご]まであきらめなかった。", "sentence_source": "generated"}, {"text": "新しい駅ビルは来年の春に完成する予定です。", "target_word": "完成", "complexity_tier": "T3", "furigana": "新[あたら]しい駅[えき]ビルは来年[らいねん]の春[はる]に完成[かんせい]する予定[よてい]です。", "sentence_source": "generated"}, {"text": "作品が完成したら、まず先生に見せるつもりです。", "target_word": "完成", "complexity_tier": "T3", "furigana": "作品[さくひん]が完成[かんせい]したら、まず先生[せんせい]に見[み]せるつもりです。", "sentence_source": "generated"}, {"text": "毎日少しずつ編んで、マフラーがやっと完成した。", "target_word": "完成", "complexity_tier": "T3", "furigana": "毎日[まいにち]少[すこ]しずつ編[あ]んで、マフラーがやっと完成[かんせい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "完成", "label": "基本形"}, {"form": "完成する", "label": "サ変動詞・終止形"}, {"form": "完成した", "label": "過去形"}, {"form": "完成して", "label": "て形"}, {"form": "完成させる", "label": "使役形"}, {"form": "完成しない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "作っていたものが最後まで仕上がり、全部できあがること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1150120c-165e-4f2c-8c6f-3d4fb6877a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完成", "is_correct": true, "explanation": "「完成した」で、家ができあがったことを表す。"}, {"text": "完走", "is_correct": false, "explanation": "レースを走り切る意味なので、家には使えない。"}, {"text": "完治", "is_correct": false, "explanation": "病気やけがが治る意味で、家には合わない。"}, {"text": "完敗", "is_correct": false, "explanation": "試合で負けることを指すので、家の文には合わない。"}], "explanations": {"完成": "「完成した」で、家ができあがったことを表す。", "完走": "レースを走り切る意味なので、家には使えない。", "完治": "病気やけがが治る意味で、家には合わない。", "完敗": "試合で負けることを指すので、家の文には合わない。"}, "sentence_index": 0, "correct_answer": "完成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事務手続きは、今日の午後に完成した。", "explanation": "ここは〈完了〉の意味。手続きや作業が終わることは「完了」で言う。手続きはできあがる物ではないので「完成」とは合わない。"}, {"text": "風邪は一週間で完成した。", "explanation": "ここは〈完治〉の意味。病気やけがが治ることは「完治」で言い、「完成」は作品などに使う。"}, {"text": "三十キロのレースを完成した。", "explanation": "ここは〈完走〉の意味。レースを最後まで走り切ることは「完走」で言い、「完成」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完成", "is_correct": true, "explanation": "「完成までの道」で、仕上がるまでの過程を表す。"}, {"text": "完備", "is_correct": false, "explanation": "設備がそろっている意味で、道の長さの文には合わない。"}, {"text": "完封", "is_correct": false, "explanation": "野球で相手に点を取らせないことで、道には使えない。"}, {"text": "完投", "is_correct": false, "explanation": "投手が試合を投げ切る意味で、道の文には合わない。"}], "explanations": {"完成": "「完成までの道」で、仕上がるまでの過程を表す。", "完備": "設備がそろっている意味で、道の長さの文には合わない。", "完封": "野球で相手に点を取らせないことで、道には使えない。", "完投": "投手が試合を投げ切る意味で、道の文には合わない。"}, "sentence_index": 6, "correct_answer": "完成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "チケットは発売一日で完成した。", "explanation": "ここは〈完売〉の意味。商品が売り切れることは「完売」で言い、「完成」は作り上げる意味なので合わない。"}, {"text": "試合は三対零で完成した。", "explanation": "ここは〈完敗〉の意味。試合で完全に負けることは「完敗」で言い、「完成」とは言わない。"}, {"text": "トマトが完成した。", "explanation": "ここは〈完熟〉の意味。果物が十分に熟すことは「完熟」で言い、「完成」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダムの工事は来年の三月に完成を予定です。", "corrected_sentence": "ダムの工事は来年の三月に完成する予定です。", "error_description": "「完成」はサ変名詞で、「完成する予定」の形にする必要がある。「する」を「を」に変えたため、動詞の形が崩れて誤り。正しくは「完成する予定です」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39704, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その模型は、来月の初めに完成した予定です。", "corrected_sentence": "その模型は、来月の初めに完成する予定です。", "error_description": "まだ起きていない未来の予定には、動詞の辞書形「完成する予定」を使う。「完成した予定」と過去形にしたため、時制が合わず誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac1b130-5bc9-47de-9744-1638a9b421cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
