INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39706, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とても特別で、とてもよい気持ちになること。", "primary_collocate": null, "pronunciation": "かくべつ", "ipa": "kakɯbetsɯ", "syllable_count": 4, "sentences": [{"text": "仕事のあとのビールは格別だ。", "target_word": "格別", "complexity_tier": "T3", "furigana": "仕事[しごと]のあとのビールは格別[かくべつ]だ。", "sentence_source": "generated"}, {"text": "山の上で食べるおにぎりは格別な味です。", "target_word": "格別", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]で食[た]べるおにぎりは格別[かくべつ]な味[あじ]です。", "sentence_source": "generated"}, {"text": "風呂上がりの冷たい牛乳は、格別においしい。", "target_word": "格別", "complexity_tier": "T3", "furigana": "風呂上[ふろあ]がりの冷[つめ]たい牛乳[ぎゅうにゅう]は、格別[かくべつ]においしい。", "sentence_source": "generated"}, {"text": "朝の静かな時間は、私には格別です。", "target_word": "格別", "complexity_tier": "T3", "furigana": "朝[あさ]の静[しず]かな時間[じかん]は、私[わたし]には格別[かくべつ]です。", "sentence_source": "generated"}, {"text": "久しぶりに家族で食べるごはんは格別だった。", "target_word": "格別", "complexity_tier": "T3", "furigana": "久[ひさ]しぶりに家族[かぞく]で食[た]べるごはんは格別[かくべつ]だった。", "sentence_source": "generated"}, {"text": "温泉に入りながら見る雪景色は格別でした。", "target_word": "格別", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]りながら見[み]る雪景色[ゆきげしき]は格別[かくべつ]でした。", "sentence_source": "generated"}, {"text": "疲れた日の甘いお菓子は格別だ。", "target_word": "格別", "complexity_tier": "T3", "furigana": "疲[つか]れた日[ひ]の甘[あま]いお菓子[かし]は格別[かくべつ]だ。", "sentence_source": "generated"}, {"text": "自分で育てた野菜の味は格別です。", "target_word": "格別", "complexity_tier": "T3", "furigana": "自分[じぶん]で育[そだ]てた野菜[やさい]の味[あじ]は格別[かくべつ]です。", "sentence_source": "generated"}, {"text": "海を見ながら飲むコーヒーは格別だ。", "target_word": "格別", "complexity_tier": "T3", "furigana": "海[うみ]を見[み]ながら飲[の]むコーヒーは格別[かくべつ]だ。", "sentence_source": "generated"}, {"text": "一日歩いたあとの布団は、格別に気持ちがいい。", "target_word": "格別", "complexity_tier": "T3", "furigana": "一日[いちにち]歩[ある]いたあとの布団[ふとん]は、格別[かくべつ]に気持[きも]ちがいい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "格別だ", "label": "断定形"}, {"form": "格別な", "label": "連体形"}, {"form": "格別に", "label": "連用形"}, {"form": "格別で", "label": "て形相当"}], "register": "中立", "sense_fingerprint": "特別によい気持ちや味わいがする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格別", "is_correct": true, "explanation": "とても特別でよい気持ちになる、の意味でこの空所に入る。"}, {"text": "派手", "is_correct": false, "explanation": "目立つさま。「ビールは派手だ」は味や気持ちを表せない。"}, {"text": "静か", "is_correct": false, "explanation": "音や動きが少ないさま。ビールの満足感を表す文には合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "変化がなく面白くないさま。よい気持ちを表す文とは逆の意味になる。"}], "explanations": {"格別": "とても特別でよい気持ちになる、の意味でこの空所に入る。", "派手": "目立つさま。「ビールは派手だ」は味や気持ちを表せない。", "静か": "音や動きが少ないさま。ビールの満足感を表す文には合わない。", "退屈": "変化がなく面白くないさま。よい気持ちを表す文とは逆の意味になる。"}, "sentence_index": 0, "correct_answer": "格別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "荷物を格別に分けて運んだ。", "explanation": "ここは〈別々に〉の意味。格別は〈とても特別〉を表し、ものを分けるという意味は持たないので合わない。"}, {"text": "ほんの少し、格別に塩を足した。", "explanation": "ここは〈ほんの〉の意味。格別は〈とても特別〉を表し、少しの量は表さない。"}, {"text": "財布を、格別忘れてしまった。", "explanation": "ここは〈うっかり〉の意味。格別は〈とても特別〉を表し、不注意は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格別", "is_correct": true, "explanation": "疲れた日に食べるお菓子のよさを表す語として、この空所に入る。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深いさま。「お菓子は慎重だ」は意味が通らない。"}, {"text": "無口", "is_correct": false, "explanation": "口数が少ないさま。お菓子の味を表す文には合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく快活なさま。お菓子の味や気持ちを表す文には合わない。"}], "explanations": {"格別": "疲れた日に食べるお菓子のよさを表す語として、この空所に入る。", "慎重": "注意深いさま。「お菓子は慎重だ」は意味が通らない。", "無口": "口数が少ないさま。お菓子の味を表す文には合わない。", "陽気": "明るく快活なさま。お菓子の味や気持ちを表す文には合わない。"}, "sentence_index": 6, "correct_answer": "格別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "バスには人が格別に乗っていた。", "explanation": "ここは〈ぎっしり〉の詰まり具合を表す語。格別はよい気持ちや味わいのすぐれた感じを表し、混み具合には使わない。"}, {"text": "この部屋は、一人で勉強するのに格別です。", "explanation": "ここは〈場面にちょうどふさわしい〉の意味。格別は満足の大きさを表すので、用途の適合を言う文には合わない。"}, {"text": "彼はさっさと格別に帰った。", "explanation": "ここは〈さっさと〉の意味。格別は満足感やすぐれた感じを表し、帰る速さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の静かな時間は、私には格別なだ。", "corrected_sentence": "朝の静かな時間は、私には格別だ。", "error_description": "「格別」は形容動詞で、述語では「だ」を直接付ける。「格別なだ」は「な」が余計で、正しくは「格別だ」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "格別", "is_correct": true, "explanation": "「な味」の前にある語幹の形。この文の形として正しい。"}, {"text": "格別だ", "is_correct": false, "explanation": "断定形で、名詞「味」の前には置けない。「格別だ味」は成り立たない。"}, {"text": "格別に", "is_correct": false, "explanation": "連用形で、名詞を直接修飾しない。「格別に味」は成り立たない。"}, {"text": "格別で", "is_correct": false, "explanation": "て形相当で、名詞の前には置けない。「格別で味」は成り立たない。"}], "correct_form": "格別", "base_form": "格別", "form_label": "語幹", "sentence_index": 1, "explanations": {"格別": "「な味」の前にある語幹の形。この文の形として正しい。", "格別だ": "断定形で、名詞「味」の前には置けない。「格別だ味」は成り立たない。", "格別に": "連用形で、名詞を直接修飾しない。「格別に味」は成り立たない。", "格別で": "て形相当で、名詞の前には置けない。「格別で味」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の日の露天風呂は格別景色だ。", "corrected_sentence": "雪の日の露天風呂は格別な景色だ。", "error_description": "「格別」は形容動詞なので、名詞の前では「な」が必要。「格別景色」は誤りで、正しくは「格別な景色」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "格別", "is_correct": true, "explanation": "「です」の前に置く語幹の形。この文の形として正しい。"}, {"text": "格別な", "is_correct": false, "explanation": "連体形で名詞の前に来る。「味は格別なです」とは続かず、「です」の前には置けない。"}, {"text": "格別の", "is_correct": false, "explanation": "連体形（の）で名詞の前に来る。「味は格別のです」とは続かず、「です」の前には置けない。"}, {"text": "格別だった", "is_correct": false, "explanation": "過去の断定形。現在の丁寧な述語「です」と重なるので、この文の形には合わない。"}], "correct_form": "格別", "base_form": "格別", "form_label": "語幹", "sentence_index": 7, "explanations": {"格別": "「です」の前に置く語幹の形。この文の形として正しい。", "格別な": "連体形で名詞の前に来る。「味は格別なです」とは続かず、「です」の前には置けない。", "格別の": "連体形（の）で名詞の前に来る。「味は格別のです」とは続かず、「です」の前には置けない。", "格別だった": "過去の断定形。現在の丁寧な述語「です」と重なるので、この文の形には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
