INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39707, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "普通とは違って、とてもすぐれていて、満足感が大きいさま。", "primary_collocate": null, "pronunciation": "かくべつ", "ipa": "kakɯbetsɯ", "syllable_count": 4, "sentences": [{"text": "このお店のすしは、他と比べて格別においしい。", "target_word": "格別", "complexity_tier": "T3", "furigana": "このお店[みせ]のすしは、他[ほか]と比[くら]べて格別[かくべつ]においしい。", "sentence_source": "generated"}, {"text": "今年の桜は格別の美しさだった。", "target_word": "格別", "complexity_tier": "T3", "furigana": "今年[ことし]の桜[さくら]は格別[かくべつ]の美[うつく]しさだった。", "sentence_source": "generated"}, {"text": "祖母が作る梅干しは、味が格別です。", "target_word": "格別", "complexity_tier": "T3", "furigana": "祖母[そぼ]が作[つく]る梅干[うめぼ]しは、味[あじ]が格別[かくべつ]です。", "sentence_source": "generated"}, {"text": "優勝した日の夜空は、格別に美しく見えた。", "target_word": "格別", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]した日[ひ]の夜空[よぞら]は、格別[かくべつ]に美[うつく]しく見[み]えた。", "sentence_source": "generated"}, {"text": "彼の歌声は格別で、会場が静まり返った。", "target_word": "格別", "complexity_tier": "T3", "furigana": "彼[かれ]の歌声[うたごえ]は格別[かくべつ]で、会場[かいじょう]が静[しず]まり返[かえ]った。", "sentence_source": "generated"}, {"text": "長い練習のあとの勝利は、格別のよろこびだった。", "target_word": "格別", "complexity_tier": "T3", "furigana": "長[なが]い練習[れんしゅう]のあとの勝利[しょうり]は、格別[かくべつ]のよろこびだった。", "sentence_source": "generated"}, {"text": "この旅館の料理は、値段のわりに格別な味でした。", "target_word": "格別", "complexity_tier": "T3", "furigana": "この旅館[りょかん]の料理[りょうり]は、値段[ねだん]のわりに格別[かくべつ]な味[あじ]でした。", "sentence_source": "generated"}, {"text": "格別のごちそうでなくても、家族といれば幸せだ。", "target_word": "格別", "complexity_tier": "T3", "furigana": "格別[かくべつ]のごちそうでなくても、家族[かぞく]といれば幸[しあわ]せだ。", "sentence_source": "generated"}, {"text": "今日のホテルのサービスは格別によかった。", "target_word": "格別", "complexity_tier": "T3", "furigana": "今日[きょう]のホテルのサービスは格別[かくべつ]によかった。", "sentence_source": "generated"}, {"text": "この景色は、写真で見るより実際のほうが格別だ。", "target_word": "格別", "complexity_tier": "T3", "furigana": "この景色[けしき]は、写真[しゃしん]で見[み]るより実際[じっさい]のほうが格別[かくべつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "格別だ", "label": "断定形"}, {"form": "格別な", "label": "連体形"}, {"form": "格別に", "label": "連用形"}, {"form": "格別の", "label": "連体形（の）"}], "register": "中立", "sense_fingerprint": "普通よりずっとすぐれて満足が大きい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308dcfa0-b85b-4ce7-a3c8-a936325820cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39707, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "格別", "is_correct": true, "explanation": "他と比べて特にすぐれている、の意味でこの空所に入る。"}, {"text": "ぐったり", "is_correct": false, "explanation": "疲れて力が抜けた様子。すしのおいしさを表す文には合わない。"}, {"text": "うっかり", "is_correct": false, "explanation": "注意が足りない様子。「おいしい」を修飾しても意味が通らない。"}, {"text": "のんびり", "is_correct": false, "explanation": "ゆったりした様子。味の比較の文には合わない。"}], "explanations": {"格別": "他と比べて特にすぐれている、の意味でこの空所に入る。", "ぐったり": "疲れて力が抜けた様子。すしのおいしさを表す文には合わない。", "うっかり": "注意が足りない様子。「おいしい」を修飾しても意味が通らない。", "のんびり": "ゆったりした様子。味の比較の文には合わない。"}, "sentence_index": 0, "correct_answer": "格別"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "電車は、格別到着した。", "explanation": "ここは〈まもなく〉の意味。格別は〈すぐれて満足が大きい〉の意味で、時間の近さは表さない。"}, {"text": "彼は、きっぱり断ったのに格別に断った。", "explanation": "ここは〈きっぱり〉の断り方を表す語。格別は普通より優れて満足が大きいことを表し、断り方の強さには使わない。"}, {"text": "彼は、格別扉を閉めた。", "explanation": "ここは〈そっと〉の意味。格別は〈すぐれて満足が大きい〉の意味で、動作の静かさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39707, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格別", "is_correct": true, "explanation": "値段のわりに特にすぐれた味、の意味で空所に入る。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく快活なさま。味を表す語としては不自然。"}, {"text": "無口", "is_correct": false, "explanation": "口数が少ないさま。料理の味には使えない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深いさま。料理の味を表す文には合わない。"}], "explanations": {"格別": "値段のわりに特にすぐれた味、の意味で空所に入る。", "陽気": "明るく快活なさま。味を表す語としては不自然。", "無口": "口数が少ないさま。料理の味には使えない。", "慎重": "注意深いさま。料理の味を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "格別"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事は、格別完成した。", "explanation": "ここは〈ついに〉の意味。格別は〈すぐれて満足が大きい〉の意味で、やっと実現した時期は表さない。"}, {"text": "その件は、格別保留にした。", "explanation": "ここは〈ひとまず〉の意味。格別は〈すぐれて満足が大きい〉の意味で、一時的な措置は表さない。"}, {"text": "彼は格別に帰った。", "explanation": "ここは〈さっさと〉の意味。格別は満足感やすぐれた感じを表し、帰る速さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39707, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "優勝の瞬間は、観客にとって格別だ思い出だ。", "corrected_sentence": "優勝の瞬間は、観客にとって格別な思い出だ。", "error_description": "「格別」は名詞を修飾するときに「な」が必要。「格別だ思い出」は「だ」が誤りで、正しくは「格別な思い出」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "格別", "is_correct": true, "explanation": "「今年の桜は格別の美しさ」の〈格別〉。〈の〉の前に来る語幹の形で、ここでは活用語尾を付けない。"}, {"text": "格別だ", "is_correct": false, "explanation": "断定形。〈の〉に続く名詞の前では〈だ〉を置けないので、この文には合わない。"}, {"text": "格別な", "is_correct": false, "explanation": "連体形。この文では〈の〉が続いており、〈な〉を付けた形は使われていない。"}, {"text": "格別に", "is_correct": false, "explanation": "連用形。名詞〈美しさ〉を修飾する形ではないので、〈の美しさ〉の部分に入らない。"}], "correct_form": "格別", "base_form": "格別", "form_label": "語幹（の前）", "sentence_index": 1, "explanations": {"格別": "「今年の桜は格別の美しさ」の〈格別〉。〈の〉の前に来る語幹の形で、ここでは活用語尾を付けない。", "格別だ": "断定形。〈の〉に続く名詞の前では〈だ〉を置けないので、この文には合わない。", "格別な": "連体形。この文では〈の〉が続いており、〈な〉を付けた形は使われていない。", "格別に": "連用形。名詞〈美しさ〉を修飾する形ではないので、〈の美しさ〉の部分に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39707, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この川辺の夕暮れは格別景色だ。", "corrected_sentence": "この川辺の夕暮れは格別な景色だ。", "error_description": "「格別」は名詞を修飾するときに「な」が必要。「格別景色」は連体形が抜けており、正しくは「格別な景色」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "格別", "is_correct": true, "explanation": "「格別のごちそう」の〈格別〉。〈の〉の前に来る語幹の形で、ここでは活用語尾を付けない。"}, {"text": "格別で", "is_correct": false, "explanation": "て形相当。〈で〉の後に名詞〈ごちそう〉は続かず、〈格別でのごちそう〉は成り立たない。"}, {"text": "格別だった", "is_correct": false, "explanation": "過去の断定形。名詞〈ごちそう〉の前には置けず、〈格別だったのごちそう〉は成り立たない。"}, {"text": "格別でした", "is_correct": false, "explanation": "丁寧な過去形。〈格別でしたのごちそう〉とは続かず、名詞の前には入らない。"}], "correct_form": "格別", "base_form": "格別", "form_label": "語幹（の前）", "sentence_index": 7, "explanations": {"格別": "「格別のごちそう」の〈格別〉。〈の〉の前に来る語幹の形で、ここでは活用語尾を付けない。", "格別で": "て形相当。〈で〉の後に名詞〈ごちそう〉は続かず、〈格別でのごちそう〉は成り立たない。", "格別だった": "過去の断定形。名詞〈ごちそう〉の前には置けず、〈格別だったのごちそう〉は成り立たない。", "格別でした": "丁寧な過去形。〈格別でしたのごちそう〉とは続かず、名詞の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '768bd0c7-daa7-4275-89d3-dea48b90b403') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「部品が多い」の主語を示す。多い状態の主体が部品なので合う。"}, {"text": "を", "is_correct": false, "explanation": "「多い」は目的語を取らないので、「部品を多くて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「部品に多くて」では、多いという述語の主体を示せず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「部品で多くて」は場所や手段の形で、部品の数が多いことを表せない。"}], "correct_answer": "が", "explanations": {"が": "「部品が多い」の主語を示す。多い状態の主体が部品なので合う。", "を": "「多い」は目的語を取らないので、「部品を多くて」は成り立たない。", "に": "「部品に多くて」では、多いという述語の主体を示せず不自然。", "で": "「部品で多くて」は場所や手段の形で、部品の数が多いことを表せない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「部品は軽い」の主題を示す。木でできた部品について述べる文なので合う。"}, {"text": "へ", "is_correct": false, "explanation": "「部品へ軽い」は方向の形で、軽さの説明にならないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「部品の軽いので」は名詞を修飾する形で、述語が続かないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「部品と軽いので」は並列の形で、軽いという述語と続かないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「部品は軽い」の主題を示す。木でできた部品について述べる文なので合う。", "へ": "「部品へ軽い」は方向の形で、軽さの説明にならないので合わない。", "の": "「部品の軽いので」は名詞を修飾する形で、述語が続かないので合わない。", "と": "「部品と軽いので」は並列の形で、軽いという述語と続かないので合わない。"}, "error_tags": {"は": "主題", "へ": "方向", "の": "修飾", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "何かを作るときに使う、一つ一つの小さな物。", "primary_collocate": null, "pronunciation": "ぶひん", "ipa": "bɯçiɴ", "syllable_count": 3, "sentences": [{"text": "模型を作るために、小さな部品を箱から出して並べた。", "target_word": "部品", "complexity_tier": "T3", "furigana": "模型[もけい]を作[つく]るために、小[ちい]さな部品[ぶひん]を箱[はこ]から出[だ]して並[なら]べた。", "sentence_source": "generated"}, {"text": "この棚は部品が多くて、組み立てるのに二時間もかかった。", "target_word": "部品", "complexity_tier": "T3", "furigana": "この棚[たな]は部品[ぶひん]が多[おお]くて、組[く]み立[た]てるのに二時間[にじかん]もかかった。", "sentence_source": "generated"}, {"text": "部品が一つ足りなくて、おもちゃを完成させられなかった。", "target_word": "部品", "complexity_tier": "T3", "furigana": "部品[ぶひん]が一[ひと]つ足[た]りなくて、おもちゃを完成[かんせい]させられなかった。", "sentence_source": "generated"}, {"text": "説明書を見ながら、部品を順番に取り付けた。", "target_word": "部品", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を見[み]ながら、部品[ぶひん]を順番[じゅんばん]に取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "弟は小さい部品をなくさないように、袋に入れておいた。", "target_word": "部品", "complexity_tier": "T3", "furigana": "弟[おとうと]は小[ちい]さい部品[ぶひん]をなくさないように、袋[ふくろ]に入[い]れておいた。", "sentence_source": "generated"}, {"text": "机を作る部品は、店から箱に入れて送られてきた。", "target_word": "部品", "complexity_tier": "T3", "furigana": "机[つくえ]を作[つく]る部品[ぶひん]は、店[みせ]から箱[はこ]に入[い]れて送[おく]られてきた。", "sentence_source": "generated"}, {"text": "部品の数をかぞえてから、組み立てを始めましょう。", "target_word": "部品", "complexity_tier": "T3", "furigana": "部品[ぶひん]の数[かず]をかぞえてから、組[く]み立[た]てを始[はじ]めましょう。", "sentence_source": "generated"}, {"text": "木でできた部品は軽いので、子どもでも持てる。", "target_word": "部品", "complexity_tier": "T3", "furigana": "木[き]でできた部品[ぶひん]は軽[かる]いので、子[こ]どもでも持[も]てる。", "sentence_source": "generated"}, {"text": "古い時計から部品を取り出して、新しい作品に使った。", "target_word": "部品", "complexity_tier": "T3", "furigana": "古[ふる]い時計[とけい]から部品[ぶひん]を取[と]り出[だ]して、新[あたら]しい作品[さくひん]に使[つか]った。", "sentence_source": "generated"}, {"text": "ネジは小さいが、大切な部品の一つだ。", "target_word": "部品", "complexity_tier": "T3", "furigana": "ネジは小[ちい]さいが、大切[たいせつ]な部品[ぶひん]の一[ひと]つだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "部品", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "模型・家具・おもちゃなどを作るときに使う、小さな一つ一つの物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T2: contains vocabulary far above tier T2: かぞえ (Zipf 2.42)']::text[], '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部品", "is_correct": true, "explanation": "組み立てに使う小さな一つ一つの物で、箱から出して並べられるので合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様は箱から出して並べられるものではないので合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "空に見える現象で、箱に入れて並べることはできないので合わない。"}, {"text": "感情", "is_correct": false, "explanation": "目に見えない心の動きで、箱から出して並べることはできないので合わない。"}], "explanations": {"部品": "組み立てに使う小さな一つ一つの物で、箱から出して並べられるので合う。", "天気": "空模様は箱から出して並べられるものではないので合わない。", "夕焼け": "空に見える現象で、箱に入れて並べることはできないので合わない。", "感情": "目に見えない心の動きで、箱から出して並べることはできないので合わない。"}, "sentence_index": 0, "correct_answer": "部品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は部品が多くて、作るのに二時間もかかった。", "explanation": "ここは〈材料〉の意味。料理の食材は部品とは言わないので合わない。"}, {"text": "この作品は特に難しい部品を練習した。", "explanation": "ここは〈部分〉の意味。練習するのは作品の一節で、組み立てる物ではないので合わない。"}, {"text": "彼は来月から経理の部品に異動する。", "explanation": "ここは〈部署〉の意味。部品は組み立てに使う物で、職場の単位には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部品", "is_correct": true, "explanation": "組み立てる部品の数をかぞえる文脈なので合う。"}, {"text": "愛情", "is_correct": false, "explanation": "数をかぞえられない感情で、かぞえる対象にはならないので合わない。"}, {"text": "空気", "is_correct": false, "explanation": "数えられない物質で、数をかぞえるのは不自然なので合わない。"}, {"text": "湿気", "is_correct": false, "explanation": "数えられない空気の状態で、数をかぞえる対象ではないので合わない。"}], "explanations": {"部品": "組み立てる部品の数をかぞえる文脈なので合う。", "愛情": "数をかぞえられない感情で、かぞえる対象にはならないので合わない。", "空気": "数えられない物質で、数をかぞえるのは不自然なので合わない。", "湿気": "数えられない空気の状態で、数をかぞえる対象ではないので合わない。"}, "sentence_index": 6, "correct_answer": "部品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は部品の宿題を終わらせた。", "explanation": "ここは〈教科〉の意味。算数や国語などの科目は部品とは言わないので合わない。"}, {"text": "このシャツは部品がやわらかくて、着心地がいい。", "explanation": "ここは〈素材〉の意味。布や衣類の材質は部品とは言わないので合わない。"}, {"text": "転んでけがをした部品を、冷やして手当てした。", "explanation": "ここは〈部位〉の意味。体の一部は部品とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ネジを外したあと、部品に箱に戻した。", "corrected_sentence": "ネジを外したあと、部品を箱に戻した。", "error_description": "正しくは「部品を箱に戻す」で、戻す対象の部品には「を」が付く。誤りは部品に「に」を付けた格助詞の誤りで、戻す対象を示せていない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ネジと部品が一つずつ袋に分けた。", "corrected_sentence": "ネジと部品を一つずつ袋に分けた。", "error_description": "正しくは「部品を分ける」で、分ける対象の部品には「を」が付く。誤りは「が」にして部品を主語にしてしまい、分けるという動詞の目的語になれていない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39709, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「部品を新しいものに換えた」の目的語で、換える対象を示すので合う。"}, {"text": "が", "is_correct": false, "explanation": "部品を主語にすると、換えるという動詞の目的語が欠けるので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、換える対象を示せないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "並列の形になり、換える対象を示せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「部品を新しいものに換えた」の目的語で、換える対象を示すので合う。", "が": "部品を主語にすると、換えるという動詞の目的語が欠けるので合わない。", "へ": "方向を表すが、換える対象を示せないので合わない。", "と": "並列の形になり、換える対象を示せないので合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39709, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「予備の部品がたくさん入っている」の主語で、入っているものを示すので合う。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は目的語を取らないので、「部品をたくさん入っている」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所を示すが、「たくさん入っている」の主体を表せないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所の形で、入っているものを示せないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「予備の部品がたくさん入っている」の主語で、入っているものを示すので合う。", "を": "「入る」は目的語を取らないので、「部品をたくさん入っている」は成り立たない。", "に": "場所を示すが、「たくさん入っている」の主体を表せないので合わない。", "で": "手段や場所の形で、入っているものを示せないので合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "機械や道具などを組み立てるための、一つ一つの材料や部分。", "primary_collocate": null, "pronunciation": "ぶひん", "ipa": "bɯçiɴ", "syllable_count": 3, "sentences": [{"text": "工場では、車の部品を一つずつ機械で作っている。", "target_word": "部品", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、車[くるま]の部品[ぶひん]を一[ひと]つずつ機械[きかい]で作[つく]っている。", "sentence_source": "generated"}, {"text": "自転車が壊れたので、古くなった部品を新しいものに換えた。", "target_word": "部品", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]が壊[こわ]れたので、古[ふる]くなった部品[ぶひん]を新[あたら]しいものに換[か]えた。", "sentence_source": "generated"}, {"text": "この会社は、スマートフォンに使う部品を世界中に売っている。", "target_word": "部品", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、スマートフォンに使[つか]う部品[ぶひん]を世界中[せかいじゅう]に売[う]っている。", "sentence_source": "generated"}, {"text": "部品が合わなかったため、機械を組み立てられなかった。", "target_word": "部品", "complexity_tier": "T3", "furigana": "部品[ぶひん]が合[あ]わなかったため、機械[きかい]を組[く]み立[た]てられなかった。", "sentence_source": "generated"}, {"text": "エンジンの部品は、とても細かく正確に作られている。", "target_word": "部品", "complexity_tier": "T3", "furigana": "エンジンの部品[ぶひん]は、とても細[こま]かく正確[せいかく]に作[つく]られている。", "sentence_source": "generated"}, {"text": "修理屋さんは、壊れた掃除機の部品を取り寄せてくれた。", "target_word": "部品", "complexity_tier": "T3", "furigana": "修理屋[しゅうりや]さんは、壊[こわ]れた掃除機[そうじき]の部品[ぶひん]を取[と]り寄[よ]せてくれた。", "sentence_source": "generated"}, {"text": "同じ部品を使えば、修理の費用が安くなる。", "target_word": "部品", "complexity_tier": "T3", "furigana": "同[おな]じ部品[ぶひん]を使[つか]えば、修理[しゅうり]の費用[ひよう]が安[やす]くなる。", "sentence_source": "generated"}, {"text": "工具箱には、予備の部品がたくさん入っている。", "target_word": "部品", "complexity_tier": "T3", "furigana": "工具箱[こうぐばこ]には、予備[よび]の部品[ぶひん]がたくさん入[はい]っている。", "sentence_source": "generated"}, {"text": "古い洗濯機は、部品が見つからなくて直せなかった。", "target_word": "部品", "complexity_tier": "T3", "furigana": "古[ふる]い洗濯機[せんたくき]は、部品[ぶひん]が見[み]つからなくて直[なお]せなかった。", "sentence_source": "generated"}, {"text": "時計の部品は小さいので、ピンセットでつまんで取り付ける。", "target_word": "部品", "complexity_tier": "T3", "furigana": "時計[とけい]の部品[ぶひん]は小[ちい]さいので、ピンセットでつまんで取[と]り付[つ]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "部品", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "車・時計・家電などの機械や道具を構成する、交換や修理もできる部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "部品", "is_correct": true, "explanation": "機械で一つずつ作られる、車を構成する部分を指すので合う。"}, {"text": "料理", "is_correct": false, "explanation": "車の料理を機械で作るという意味にならず、文脈に合わないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "車の天気を機械で作ることはできないので合わない。"}, {"text": "雑草", "is_correct": false, "explanation": "車の雑草を機械で作るという意味にはならないので合わない。"}], "explanations": {"部品": "機械で一つずつ作られる、車を構成する部分を指すので合う。", "料理": "車の料理を機械で作るという意味にならず、文脈に合わないので合わない。", "天気": "車の天気を機械で作ることはできないので合わない。", "雑草": "車の雑草を機械で作るという意味にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "部品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この本は部品によって難しさが違う。", "explanation": "ここは〈章〉の意味。書物の区切りは機械や道具の部品ではないので合わない。"}, {"text": "彼は部品に入って、毎日遅くまで練習している。", "explanation": "ここは〈部活〉の意味。部や団体に所属する意味で、部品とは言わないので合わない。"}, {"text": "新しい部品が、来週の会議を開く。", "explanation": "ここは〈部長〉の意味。人の役職を表す語で、部品は人を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "部品", "is_correct": true, "explanation": "交換用の部品を同じものを使えば修理費が安くなるという文脈に合うので合う。"}, {"text": "夜景", "is_correct": false, "explanation": "夜景を使うという意味にならず、修理費の文脈に合わないので合わない。"}, {"text": "歌詞", "is_correct": false, "explanation": "歌詞を使っても修理費は変わらず、文脈に合わないので合わない。"}, {"text": "笑顔", "is_correct": false, "explanation": "笑顔を使うことで修理費が安くなるという意味にはならないので合わない。"}], "explanations": {"部品": "交換用の部品を同じものを使えば修理費が安くなるという文脈に合うので合う。", "夜景": "夜景を使うという意味にならず、修理費の文脈に合わないので合わない。", "歌詞": "歌詞を使っても修理費は変わらず、文脈に合わないので合わない。", "笑顔": "笑顔を使うことで修理費が安くなるという意味にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "部品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、部品で野菜を育てた。", "explanation": "ここは〈畑〉の意味。野菜を育てる場所は部品ではないので合わない。"}, {"text": "このアプリは部品が多くて、使いやすい。", "explanation": "ここは〈機能〉の意味。アプリの働きや特長は部品とは言わないので合わない。"}, {"text": "ひざをぶつけた部品を、冷やして手当てした。", "explanation": "ここは〈部位〉の意味。体の一部を指す語で、部品とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
