INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39709, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修理の前に、部品で箱ごとに分けた。", "corrected_sentence": "修理の前に、部品を箱ごとに分けた。", "error_description": "正しくは「部品を分ける」で、分ける対象には「を」が付く。誤りは「で」にして手段や場所の意味になり、分けられる対象が示されていない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
