INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39710, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ものをうごかす。", "primary_collocate": null, "pronunciation": "うごかす", "ipa": "uɡokasɯ", "syllable_count": 4, "sentences": [{"text": "重い机を二人で動かしました。", "target_word": "動かし", "complexity_tier": "T3", "furigana": "重[おも]い机[つくえ]を二人[ふたり]で動[うご]かしました。", "sentence_source": "generated"}, {"text": "手を動かさないと、仕事は終わりません。", "target_word": "動かさ", "complexity_tier": "T3", "furigana": "手[て]を動[うご]かさないと、仕事[しごと]は終[お]わりません。", "sentence_source": "generated"}, {"text": "力が足りなくて、石を動かすことができなかった。", "target_word": "動かす", "complexity_tier": "T3", "furigana": "力[ちから]が足[た]りなくて、石[いし]を動[うご]かすことができなかった。", "sentence_source": "generated"}, {"text": "部屋を広く使うために、ソファーを動かした。", "target_word": "動かした", "complexity_tier": "T3", "furigana": "部屋[へや]を広[ひろ]く使[つか]うために、ソファーを動[うご]かした。", "sentence_source": "generated"}, {"text": "車を動かしてください。ここは駐車禁止です。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "車[くるま]を動[うご]かしてください。ここは駐車禁止[ちゅうしゃきんし]です。", "sentence_source": "generated"}, {"text": "彼は機械を動かす仕事をしています。", "target_word": "動かす", "complexity_tier": "T3", "furigana": "彼[かれ]は機械[きかい]を動[うご]かす仕事[しごと]をしています。", "sentence_source": "generated"}, {"text": "地震のあとで、倒れた棚を動かして道を作った。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "地震[じしん]のあとで、倒[たお]れた棚[たな]を動[うご]かして道[みち]を作[つく]った。", "sentence_source": "generated"}, {"text": "指を動かして、ピアノの練習をする。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "指[ゆび]を動[うご]かして、ピアノの練習[れんしゅう]をする。", "sentence_source": "generated"}, {"text": "荷物が邪魔なので、少し動かしてもらえますか。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "荷物[にもつ]が邪魔[じゃま]なので、少[すこ]し動[うご]かしてもらえますか。", "sentence_source": "generated"}, {"text": "子どもは積み木を動かして遊んでいる。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "子[こ]どもは積[つ]み木[き]を動[うご]かして遊[あそ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動かす", "label": "終止形"}, {"form": "動かさ", "label": "未然形"}, {"form": "動かし", "label": "連用形"}, {"form": "動かせ", "label": "仮定形・可能"}, {"form": "動かして", "label": "て形"}, {"form": "動かした", "label": "た形"}], "register": "neutral", "sense_fingerprint": "物を押したり操作したりして、位置や動きを変える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39710, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動かし", "is_correct": true, "explanation": "連用形。「〜しました」に続く正しい形で、文の空欄に入る。"}, {"text": "動かさ", "is_correct": false, "explanation": "未然形。「ない」「せる」に続く形で、「しました」には続かない。"}, {"text": "動かす", "is_correct": false, "explanation": "終止形。「ました」の前には置けず、「動かすました」となって文が成り立たない。"}, {"text": "動かした", "is_correct": false, "explanation": "た形。「ました」と重ねると「動かしたました」となり、文が成り立たない。"}], "explanations": {"動かし": "連用形。「〜しました」に続く正しい形で、文の空欄に入る。", "動かさ": "未然形。「ない」「せる」に続く形で、「しました」には続かない。", "動かす": "終止形。「ました」の前には置けず、「動かすました」となって文が成り立たない。", "動かした": "た形。「ました」と重ねると「動かしたました」となり、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "動かし"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は言い訳を動かして、その場を逃れた。", "explanation": "ここは〈並べる〉の意味。言い訳は〈並べる・する〉もので、〈動かす〉は物の位置を変える意味では合わない。"}, {"text": "彼は夕食の味付けを動かして、少し薄くした。", "explanation": "ここは〈加減する〉の意味。味付けは〈加減する〉もので、〈動かす〉は使わない。"}, {"text": "彼は薬を動かして、すぐに飲んだ。", "explanation": "ここは〈飲む〉の意味。薬は〈飲む〉もので、〈動かす〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39710, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動かして", "is_correct": true, "explanation": "て形。「作った」につながり、棚を動かして道を作るという意味になる。"}, {"text": "笑わせて", "is_correct": false, "explanation": "「笑わせる」のて形。棚を笑わせるという内容になり、文が成り立たない。"}, {"text": "眠らせて", "is_correct": false, "explanation": "「眠らせる」のて形。棚を眠らせるという内容で、道を作る文脈に合わない。"}, {"text": "聞いて", "is_correct": false, "explanation": "「聞く」のて形。棚を聞くという内容になり、文が成り立たない。"}], "explanations": {"動かして": "て形。「作った」につながり、棚を動かして道を作るという意味になる。", "笑わせて": "「笑わせる」のて形。棚を笑わせるという内容になり、文が成り立たない。", "眠らせて": "「眠らせる」のて形。棚を眠らせるという内容で、道を作る文脈に合わない。", "聞いて": "「聞く」のて形。棚を聞くという内容になり、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "動かして"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社はやり方を動かした。", "explanation": "ここは〈変える〉の意味。やり方や方針は物ではないので、〈動かす〉ではなく〈変える〉を使う。"}, {"text": "彼女は怒りを動かして、そのまま部屋を出た。", "explanation": "ここは〈かき立てる〉の意味。怒りは〈かき立てる・鎮める〉もので、〈動かす〉は物を移す意味なので使わない。"}, {"text": "彼は部屋の電気を動かして、そのまま寝た。", "explanation": "ここは〈消す〉の意味。電気は〈つける・消す〉で扱い、〈動かす〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39710, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机を動かしないと、掃除ができません。", "corrected_sentence": "机を動かさないと、掃除ができません。", "error_description": "「動かし」は連用形。「ないと」の前には未然形「動かさ」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "動かさ", "is_correct": true, "explanation": "未然形。「ないと」に続く、文中の正しい形。"}, {"text": "動かし", "is_correct": false, "explanation": "連用形。「ないと」の前には置けない。"}, {"text": "動かす", "is_correct": false, "explanation": "終止形。「ないと」の前には置けず、「動かすないと」となって文が成り立たない。"}, {"text": "動かした", "is_correct": false, "explanation": "た形。「ないと」とは続かず、「動かしたないと」となって文が成り立たない。"}], "correct_form": "動かさ", "base_form": "動かす", "form_label": "未然形", "sentence_index": 1, "explanations": {"動かさ": "未然形。「ないと」に続く、文中の正しい形。", "動かし": "連用形。「ないと」の前には置けない。", "動かす": "終止形。「ないと」の前には置けず、「動かすないと」となって文が成り立たない。", "動かした": "た形。「ないと」とは続かず、「動かしたないと」となって文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39710, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人形の腕を動かた、子どもが笑っている。", "corrected_sentence": "人形の腕を動かして、子どもが笑っている。", "error_description": "「動かた」は誤った形。「〜して」と続ける、て形の「動かして」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "動かして", "is_correct": true, "explanation": "て形。「動かして遊ぶ」の形で、文中の形として正しい。"}, {"text": "動かせ", "is_correct": false, "explanation": "仮定形・可能の形。「、」で続けても文として成り立たない。"}, {"text": "動かさ", "is_correct": false, "explanation": "未然形。「ない」「せる」に続く形で、「て」とは続かない。"}, {"text": "動かそう", "is_correct": false, "explanation": "意志形。「、ピアノの練習をする」と続けると文として成り立たず、意味も通らない。"}], "correct_form": "動かして", "base_form": "動かす", "form_label": "て形", "sentence_index": 7, "explanations": {"動かして": "て形。「動かして遊ぶ」の形で、文中の形として正しい。", "動かせ": "仮定形・可能の形。「、」で続けても文として成り立たない。", "動かさ": "未然形。「ない」「せる」に続く形で、「て」とは続かない。", "動かそう": "意志形。「、ピアノの練習をする」と続けると文として成り立たず、意味も通らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "動詞を名詞化する「の」。「動かすのがつらい」の形で、文中のこれにあたる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。名詞化の位置に入ると、「動かすをがつらい」となり不自然。"}, {"text": "に", "is_correct": false, "explanation": "方向や対象の「に」。動詞の後の名詞化には使わず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "移動の方向を表す「へ」。ここでは方向の意味がなく、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "動詞を名詞化する「の」。「動かすのがつらい」の形で、文中のこれにあたる。", "を": "目的語の「を」。名詞化の位置に入ると、「動かすをがつらい」となり不自然。", "に": "方向や対象の「に」。動詞の後の名詞化には使わず、文が成り立たない。", "へ": "移動の方向を表す「へ」。ここでは方向の意味がなく、文が成り立たない。"}, "error_tags": {"を": "目的語の格（名詞化の「の」が必要）", "に": "方向・対象の格", "へ": "移動の方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や体の一部に力を加えて、位置や状態を変える。", "primary_collocate": null, "pronunciation": "うごかす", "ipa": "uɡokasɯ", "syllable_count": 4, "sentences": [{"text": "朝起きたら、まず足の指を動かすようにしています。", "target_word": "動かす", "complexity_tier": "T3", "furigana": "朝[あさ]起[お]きたら、まず足[あし]の指[ゆび]を動[うご]かすようにしています。", "sentence_source": "generated"}, {"text": "足が痛くて、ひざを動かすのがつらい。", "target_word": "動かす", "complexity_tier": "T3", "furigana": "足[あし]が痛[いた]くて、ひざを動[うご]かすのがつらい。", "sentence_source": "generated"}, {"text": "重い箱に力を加えて、少しだけ動かした。", "target_word": "動かした", "complexity_tier": "T3", "furigana": "重[おも]い箱[はこ]に力[ちから]を加[くわ]えて、少[すこ]しだけ動[うご]かした。", "sentence_source": "generated"}, {"text": "首を動かすと痛いので、病院へ行きました。", "target_word": "動かす", "complexity_tier": "T3", "furigana": "首[くび]を動[うご]かすと痛[いた]いので、病院[びょういん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "犬は耳を動かして、小さな音を聞いている。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "犬[いぬ]は耳[みみ]を動[うご]かして、小[ちい]さな音[おと]を聞[き]いている。", "sentence_source": "generated"}, {"text": "彼は口を大きく動かして、ゆっくり話した。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "彼[かれ]は口[くち]を大[おお]きく動[うご]かして、ゆっくり話[はな]した。", "sentence_source": "generated"}, {"text": "レバーを右に動かすと、ドアが開きます。", "target_word": "動かす", "complexity_tier": "T3", "furigana": "レバーを右[みぎ]に動[うご]かすと、ドアが開[ひら]きます。", "sentence_source": "generated"}, {"text": "地図の上の駒を動かして、位置を変えた。", "target_word": "動かして", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]の駒[こま]を動[うご]かして、位置[いち]を変[か]えた。", "sentence_source": "generated"}, {"text": "腕を動かしにくいので、リハビリを始めた。", "target_word": "動かし", "complexity_tier": "T3", "furigana": "腕[うで]を動[うご]かしにくいので、リハビリを始[はじ]めた。", "sentence_source": "generated"}, {"text": "冷蔵庫は重くて、一人では動かせない。", "target_word": "動かせ", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]は重[おも]くて、一人[ひとり]では動[うご]かせない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "動かす", "label": "終止形"}, {"form": "動かさ", "label": "未然形"}, {"form": "動かし", "label": "連用形"}, {"form": "動かせ", "label": "仮定形・可能"}, {"form": "動かして", "label": "て形"}, {"form": "動かした", "label": "た形"}], "register": "neutral", "sense_fingerprint": "体の一部や物に力を加えて、位置や状態を変える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3049333-685e-4b1b-9295-162778d51a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動かす", "is_correct": true, "explanation": "終止形。「動かすようにしています」として、習慣を表す文に合う。"}, {"text": "動かし", "is_correct": false, "explanation": "連用形。「ようにしています」には続かない。"}, {"text": "動かさ", "is_correct": false, "explanation": "未然形。「ようにしています」とは続かず、文が成り立たない。"}, {"text": "動かせ", "is_correct": false, "explanation": "仮定形・可能の形。「ようにしています」とは続かない。"}], "explanations": {"動かす": "終止形。「動かすようにしています」として、習慣を表す文に合う。", "動かし": "連用形。「ようにしています」には続かない。", "動かさ": "未然形。「ようにしています」とは続かず、文が成り立たない。", "動かせ": "仮定形・可能の形。「ようにしています」とは続かない。"}, "sentence_index": 0, "correct_answer": "動かす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝、近所の人と挨拶を動かした。", "explanation": "ここは〈交わす〉の意味。挨拶は〈交わす〉もので、〈動かす〉は体や物に力を加える意味と合わない。"}, {"text": "彼は深く息を動かした。", "explanation": "ここは〈吸う〉の意味。呼吸は息を吸う・吐くで言い、〈動かす〉は使わない。"}, {"text": "彼は予定の時間を動かした。", "explanation": "ここは〈進める・ずらす〉の意味。時間は〈進める〉〈戻す〉で言い、〈動かす〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "動かす", "is_correct": true, "explanation": "終止形。「動かすと、ドアが開きます」の条件の形で、文に合う。"}, {"text": "聞く", "is_correct": false, "explanation": "「聞く」の終止形。レバーを聞くという内容になり、文が成り立たない。"}, {"text": "眠らせる", "is_correct": false, "explanation": "「眠らせる」の終止形。レバーを眠らせるという内容で、文に合わない。"}, {"text": "笑わせる", "is_correct": false, "explanation": "「笑わせる」の終止形。レバーを笑わせるという内容で、文が成り立たない。"}], "explanations": {"動かす": "終止形。「動かすと、ドアが開きます」の条件の形で、文に合う。", "聞く": "「聞く」の終止形。レバーを聞くという内容になり、文が成り立たない。", "眠らせる": "「眠らせる」の終止形。レバーを眠らせるという内容で、文に合わない。", "笑わせる": "「笑わせる」の終止形。レバーを笑わせるという内容で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "動かす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は夕食の献立を動かして、子どもを喜ばせた。", "explanation": "ここは〈考える〉の意味。献立は〈考える・決める〉もので、〈動かす〉は物を物理的に移す意味なので使わない。"}, {"text": "彼は汗を動かした。", "explanation": "ここは〈拭く〉の意味。汗は拭くもので、〈動かす〉は使わない。"}, {"text": "彼は代金を動かした。", "explanation": "ここは〈払う〉の意味。代金は払うもので、〈動かす〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "腕を動かしと痛いので、湿布を貼った。", "corrected_sentence": "腕を動かすと痛いので、湿布を貼った。", "error_description": "「と」の前は辞書形が必要。「動かしと」は連用形で誤り、「動かすと」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "動かす", "is_correct": true, "explanation": "終止形（連体形と同形）。「動かすのが」の形で、文中の正しい形。"}, {"text": "動かさ", "is_correct": false, "explanation": "未然形。「の」には続かず、文が成り立たない。"}, {"text": "動かし", "is_correct": false, "explanation": "連用形。「の」の前には置けない。"}, {"text": "動かせ", "is_correct": false, "explanation": "仮定形・可能の形。「のがつらい」とは続かない。"}], "correct_form": "動かす", "base_form": "動かす", "form_label": "終止形", "sentence_index": 1, "explanations": {"動かす": "終止形（連体形と同形）。「動かすのが」の形で、文中の正しい形。", "動かさ": "未然形。「の」には続かず、文が成り立たない。", "動かし": "連用形。「の」の前には置けない。", "動かせ": "仮定形・可能の形。「のがつらい」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39711, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この机は重くて、子どもでは動かすない。", "corrected_sentence": "この机は重くて、子どもでは動かせない。", "error_description": "「動かすない」は誤り。「ない」の前は未然形「動かさ」（動かさない）か、可能形「動かせ」（動かせない）が必要。ここは「重くて動かせない」の意味なので可能形の「動かせない」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "動かして", "is_correct": true, "explanation": "て形。「動かして、位置を変えた」の形で、文中の正しい形。"}, {"text": "動かさない", "is_correct": false, "explanation": "否定形。「て」の形ではなく、「、位置を変えた」と続けると文が成り立たない。"}, {"text": "動かせる", "is_correct": false, "explanation": "可能形の終止形。「て」の形ではなく、「、位置を変えた」の前には置けず文が成り立たない。"}, {"text": "動かします", "is_correct": false, "explanation": "丁寧形。文体が「位置を変えた」と合わず、「て」の形が必要。"}], "correct_form": "動かして", "base_form": "動かす", "form_label": "て形", "sentence_index": 7, "explanations": {"動かして": "て形。「動かして、位置を変えた」の形で、文中の正しい形。", "動かさない": "否定形。「て」の形ではなく、「、位置を変えた」と続けると文が成り立たない。", "動かせる": "可能形の終止形。「て」の形ではなく、「、位置を変えた」の前には置けず文が成り立たない。", "動かします": "丁寧形。文体が「位置を変えた」と合わず、「て」の形が必要。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f85d9819-83f9-481b-865a-2430605a6e4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「モーターがこわれて」のモーターは主語。"}, {"text": "を", "is_correct": false, "explanation": "「モーターをこわれて」は目的語にできず、不自然。"}, {"text": "の", "is_correct": false, "explanation": "「モーターのこわれて」は文として続かず、不自然。"}, {"text": "と", "is_correct": false, "explanation": "「モーターとこわれて」は並列になり、意味が合わない。"}], "correct_answer": "が", "explanations": {"が": "正解。「モーターがこわれて」のモーターは主語。", "を": "「モーターをこわれて」は目的語にできず、不自然。", "の": "「モーターのこわれて」は文として続かず、不自然。", "と": "「モーターとこわれて」は並列になり、意味が合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「モーターを三つ使う」の目的語。"}, {"text": "が", "is_correct": false, "explanation": "「モーターが三つ使って」では、モーターが使う主体になり不自然。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を表し、「モーターから三つ使って」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「モーターへ使って」は方向を表す〈へ〉になり、不自然。"}], "correct_answer": "を", "explanations": {"を": "正解。「モーターを三つ使う」の目的語。", "が": "「モーターが三つ使って」では、モーターが使う主体になり不自然。", "から": "〈から〉は起点を表し、「モーターから三つ使って」は不自然。", "へ": "「モーターへ使って」は方向を表す〈へ〉になり、不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くるくる回る力で、物を動かす機械の部品です。", "primary_collocate": null, "pronunciation": "もーたー", "ipa": "moːtaː", "syllable_count": 4, "sentences": [{"text": "この車のおもちゃは、中のモーターが回って走る。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "この車[くるま]のおもちゃは、中[なか]のモーターが回[まわ]って走[はし]る。", "sentence_source": "generated"}, {"text": "モーターがこわれて、せんぷう機の羽が回らない。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "モーターがこわれて、せんぷう機[き]の羽[はね]が回[まわ]らない。", "sentence_source": "generated"}, {"text": "兄は電池とモーターで、小さな船を作った。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "兄[あに]は電池[でんち]とモーターで、小[ちい]さな船[ふね]を作[つく]った。", "sentence_source": "generated"}, {"text": "モーターが回ると、ぶーんと音がする。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "モーターが回[まわ]ると、ぶーんと音[おと]がする。", "sentence_source": "generated"}, {"text": "理科の時間に、モーターのしくみを調べた。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "理科[りか]の時間[じかん]に、モーターのしくみを調[しら]べた。", "sentence_source": "generated"}, {"text": "このロボットは、モーターで足を動かす。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "このロボットは、モーターで足[あし]を動[うご]かす。", "sentence_source": "generated"}, {"text": "モーターが熱くなったので、いったん止めた。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "モーターが熱[あつ]くなったので、いったん止[と]めた。", "sentence_source": "generated"}, {"text": "弟はモーターを三つ使って、車を速くした。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "弟[おとうと]はモーターを三[みっ]つ使[つか]って、車[くるま]を速[はや]くした。", "sentence_source": "generated"}, {"text": "洗濯機の中には、大きなモーターが入っている。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "洗濯機[せんたくき]の中[なか]には、大[おお]きなモーターが入[はい]っている。", "sentence_source": "generated"}, {"text": "模型の飛行機のモーターが回らないのは、電池が切れたからだ。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "模型[もけい]の飛行機[ひこうき]のモーターが回[まわ]らないのは、電池[でんち]が切[き]れたからだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モーター", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "回る力で物を動かす、おもちゃや家電に入っている機械の部品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: contains vocabulary far above tier T3: せんぷ (Zipf 1.74)']::text[], '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モーター", "is_correct": true, "explanation": "正解。中で回って車を走らせる部品。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は回って車を走らせる部品ではない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は回転して動く部品ではない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は回って車を走らせる部品ではない。"}], "explanations": {"モーター": "正解。中で回って車を走らせる部品。", "砂糖": "砂糖は回って車を走らせる部品ではない。", "紙": "紙は回転して動く部品ではない。", "窓": "窓は回って車を走らせる部品ではない。"}, "sentence_index": 0, "correct_answer": "モーター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "モーターをぎりぎりまで巻いて、おもちゃを動かした。", "explanation": "ここは〈ゼンマイ〉の意味。モーターは巻いて力をためる部品ではなく、ゼンマイと取り違えた使い方は合わない。"}, {"text": "モーターから音楽が流れた。", "explanation": "ここは〈スピーカー〉の意味。モーターは音楽を出す装置ではないので合わない。"}, {"text": "モーターで部屋を暖めた。", "explanation": "ここは〈ヒーター〉の意味。モーターは部屋を暖める暖房の装置ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モーター", "is_correct": true, "explanation": "正解。熱くなって止めた対象は、動いて熱を持つモーター。"}, {"text": "氷", "is_correct": false, "explanation": "氷は熱くなって止める対象にならず、文に合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は熱くならず、この文に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書が熱くなって止めたとは言わず、文に合わない。"}], "explanations": {"モーター": "正解。熱くなって止めた対象は、動いて熱を持つモーター。", "氷": "氷は熱くなって止める対象にならず、文に合わない。", "手紙": "手紙は熱くならず、この文に合わない。", "教科書": "教科書が熱くなって止めたとは言わず、文に合わない。"}, "sentence_index": 6, "correct_answer": "モーター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "モーターに火をつけて、部屋を明るくした。", "explanation": "ここは〈ろうそく〉の意味。モーターは火をつけて明かりを取る物ではないので合わない。"}, {"text": "モーターを入れて、明かりをつけた。", "explanation": "ここは〈スイッチ〉の意味。モーターは電気を入れる操作部ではないので、明かりをつける道具とは合わない。"}, {"text": "モーターに手紙を入れた。", "explanation": "ここは〈ポスト〉の意味。モーターは手紙を入れる箱ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "扇風機のモーターに外して、掃除した。", "corrected_sentence": "扇風機のモーターを外して、掃除した。", "error_description": "「外す」は目的語を取るので「を」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39712, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このモーターで、熱に弱い。", "corrected_sentence": "このモーターは、熱に弱い。", "error_description": "主語を示す「は」が正しい。「で」は手段を表すため、ここでは不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。手段を表す〈で〉で、モーターで車輪を回す。"}, {"text": "を", "is_correct": false, "explanation": "「車輪を回す」と目的語が重なり、〈を〉は続けられず不自然。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は「モーターに車輪を回す」となり、回す対象との関係が不自然。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を表すが、「モーターへ車輪を回す」は不自然。"}], "correct_answer": "で", "explanations": {"で": "正解。手段を表す〈で〉で、モーターで車輪を回す。", "を": "「車輪を回す」と目的語が重なり、〈を〉は続けられず不自然。", "に": "〈に〉は「モーターに車輪を回す」となり、回す対象との関係が不自然。", "へ": "〈へ〉は方向を表すが、「モーターへ車輪を回す」は不自然。"}, "error_tags": {"を": "目的語の重複", "に": "不自然な結合", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電気を動力に変えて回転や直線運動を生み出す装置。モーターは家電製品や機械に広く使われている。", "primary_collocate": null, "pronunciation": "もーたー", "ipa": "moːtaː", "syllable_count": 4, "sentences": [{"text": "モーターは、電気を動力に変えて回転を生み出す装置だ。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "モーターは、電気[でんき]を動力[どうりょく]に変[か]えて回転[かいてん]を生[う]み出[だ]す装置[そうち]だ。", "sentence_source": "generated"}, {"text": "電気自動車は、大きなモーターで車輪を回す。", "target_word": "モーター", "complexity_tier": "T3", "furigana": "電気自動車[でんきじどうしゃ]は、大[おお]きなモーターで車輪[しゃりん]を回[まわ]す。", "sentence_source": "generated"}, {"text": "掃除機のモーターが故障し、吸い込む力が弱まった。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "掃除機[そうじき]のモーターが故障[こしょう]し、吸[す]い込[こ]む力[ちから]が弱[よわ]まった。", "sentence_source": "generated"}, {"text": "このモーターは、少ない電力で高い出力を得られる。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "このモーターは、少[すく]ない電力[でんりょく]で高[たか]い出力[しゅつりょく]を得[え]られる。", "sentence_source": "generated"}, {"text": "工場のラインでは、数百台のモーターが休まず動いている。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "工場[こうじょう]のラインでは、数百台[すうひゃくだい]のモーターが休[やす]まず動[うご]いている。", "sentence_source": "generated"}, {"text": "エンジンに比べて、モーターは音が静かで効率もよい。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "エンジンに比[くら]べて、モーターは音[おと]が静[しず]かで効率[こうりつ]もよい。", "sentence_source": "generated"}, {"text": "技術者は、モーターの回転数を細かく制御した。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "技術者[ぎじゅつしゃ]は、モーターの回転数[かいてんすう]を細[こま]かく制御[せいぎょ]した。", "sentence_source": "generated"}, {"text": "エレベーターのモーターは、定期的に点検が必要だ。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "エレベーターのモーターは、定期的[ていきてき]に点検[てんけん]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "家電の省エネ化には、高効率なモーターの開発が欠かせない。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "家電[かでん]の省[しょう]エネ化[か]には、高効率[こうこうりつ]なモーターの開発[かいはつ]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "直線運動を生むモーターは、搬送装置に使われている。", "target_word": "モーター", "complexity_tier": "T4", "furigana": "直線運動[ちょくせんうんどう]を生[う]むモーターは、搬送装置[はんそうそうち]に使[つか]われている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モーター", "label": "基本形"}], "register": "technical", "sense_fingerprint": "電気を動力に変えて回転や直線運動を生み出す装置（家電・産業機械・電気自動車など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b526506-9c46-4ef2-864a-493950eda46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モーター", "is_correct": true, "explanation": "正解。電気を動力に変えて回転を生み出す装置。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は電気を動力に変える装置ではない。"}, {"text": "石", "is_correct": false, "explanation": "石は回転を生み出す装置ではない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は電気を動力に変える装置ではない。"}], "explanations": {"モーター": "正解。電気を動力に変えて回転を生み出す装置。", "砂糖": "砂糖は電気を動力に変える装置ではない。", "石": "石は回転を生み出す装置ではない。", "紙": "紙は電気を動力に変える装置ではない。"}, "sentence_index": 0, "correct_answer": "モーター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "モーターに電気をためて、車を動かす。", "explanation": "ここは〈バッテリー〉の意味。モーターは電気をためる装置ではなく、電気を動力に変える装置なので合わない。"}, {"text": "モーターが光って、部屋を明るくする。", "explanation": "ここは〈ランプ〉の意味。モーターは光る部品ではないので合わない。"}, {"text": "モーターが温度を測って、制御する。", "explanation": "ここは〈センサー〉の意味。モーターは温度を測る部品ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モーター", "is_correct": true, "explanation": "正解。回転数を制御する対象は、回転するモーター。"}, {"text": "電圧", "is_correct": false, "explanation": "「電圧の回転数」は意味をなさず、制御の対象にならない。"}, {"text": "水温", "is_correct": false, "explanation": "「水温の回転数」は不自然で、制御の対象にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は回転数の制御対象ではない。"}], "explanations": {"モーター": "正解。回転数を制御する対象は、回転するモーター。", "電圧": "「電圧の回転数」は意味をなさず、制御の対象にならない。", "水温": "「水温の回転数」は不自然で、制御の対象にならない。", "湿度": "湿度は回転数の制御対象ではない。"}, "sentence_index": 6, "correct_answer": "モーター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "モーターは、ガソリンの力で電気を生む装置だ。", "explanation": "ここは〈発電機〉の意味。モーターは電気を動力に変える装置で、ガソリンの力で電気を生むのは発電機なので合わない。"}, {"text": "モーターは、電流が強すぎると切れて回路を守る。", "explanation": "ここは〈ヒューズ〉の意味。モーターは回路を守るために切れる部品ではないので合わない。"}, {"text": "モーターで光を集めて、写真を撮る。", "explanation": "ここは〈レンズ〉の意味。モーターは光を集める部品ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電気自動車には、モーターを使われる。", "corrected_sentence": "電気自動車には、モーターが使われる。", "error_description": "「使われる」の主語は「が」。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39713, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "搬送装置には、モーターに使われる。", "corrected_sentence": "搬送装置には、モーターが使われる。", "error_description": "「使われる」の主語は「が」。「に」は誤りで、主語を示す形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6246d581-4712-49cb-8136-42a49a1494df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
