INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39714, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「指先に細かい注意が必要だ」の、注意を向ける対象を示すので合う。"}, {"text": "を", "is_correct": false, "explanation": "「必要だ」は目的語を取らないので、「指先を細かい注意が必要だ」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表すが、「必要だ」の対象にはならないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表すが、「必要だ」の対象にならず文として不自然なので合わない。"}], "correct_answer": "に", "explanations": {"に": "「指先に細かい注意が必要だ」の、注意を向ける対象を示すので合う。", "を": "「必要だ」は目的語を取らないので、「指先を細かい注意が必要だ」は成り立たない。", "へ": "方向を表すが、「必要だ」の対象にはならないので合わない。", "から": "起点を表すが、「必要だ」の対象にならず文として不自然なので合わない。"}, "error_tags": {"に": "対象", "を": "目的語", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39714, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ゆびの先の部分。", "primary_collocate": null, "pronunciation": "ゆびさき", "ipa": "jɯbisaki", "syllable_count": 4, "sentences": [{"text": "寒い朝は、指先が冷たくなって字がうまく書けない。", "target_word": "指先", "complexity_tier": "T3", "furigana": "寒[さむ]い朝[あさ]は、指先[ゆびさき]が冷[つめ]たくなって字[じ]がうまく書[か]けない。", "sentence_source": "generated"}, {"text": "彼女は指先で、赤ちゃんのほおにそっとふれた。", "target_word": "指先", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は指先[ゆびさき]で、赤[あか]ちゃんのほおにそっとふれた。", "sentence_source": "generated"}, {"text": "ピアノの練習で、指先が少し痛くなった。", "target_word": "指先", "complexity_tier": "T3", "furigana": "ピアノの練習[れんしゅう]で、指先[ゆびさき]が少[すこ]し痛[いた]くなった。", "sentence_source": "generated"}, {"text": "指先を水でぬらしてから、紙を一枚ずつめくった。", "target_word": "指先", "complexity_tier": "T3", "furigana": "指先[ゆびさき]を水[みず]でぬらしてから、紙[かみ]を一枚[いちまい]ずつめくった。", "sentence_source": "generated"}, {"text": "手袋をしていたのに、指先だけが凍るように冷えた。", "target_word": "指先", "complexity_tier": "T3", "furigana": "手袋[てぶくろ]をしていたのに、指先[ゆびさき]だけが凍[こお]るように冷[ひ]えた。", "sentence_source": "generated"}, {"text": "画面を指先でなぞると、写真が大きくなる。", "target_word": "指先", "complexity_tier": "T3", "furigana": "画面[がめん]を指先[ゆびさき]でなぞると、写真[しゃしん]が大[おお]きくなる。", "sentence_source": "generated"}, {"text": "料理中に、指先を包丁で少し切ってしまった。", "target_word": "指先", "complexity_tier": "T3", "furigana": "料理中[りょうりちゅう]に、指先[ゆびさき]を包丁[ほうちょう]で少[すこ]し切[き]ってしまった。", "sentence_source": "generated"}, {"text": "針を持つときは、指先に細かい注意が必要だ。", "target_word": "指先", "complexity_tier": "T3", "furigana": "針[はり]を持[も]つときは、指先[ゆびさき]に細[こま]かい注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "指先についた絵の具を、せっけんで洗い落とした。", "target_word": "指先", "complexity_tier": "T3", "furigana": "指先[ゆびさき]についた絵[え]の具[ぐ]を、せっけんで洗[あら]い落[お]とした。", "sentence_source": "generated"}, {"text": "彼の指先は器用で、小さなビーズも簡単に動かす。", "target_word": "指先", "complexity_tier": "T3", "furigana": "彼[かれ]の指先[ゆびさき]は器用[きよう]で、小[ちい]さなビーズも簡単[かんたん]に動[うご]かす。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指先", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "手の指の先端の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T3: contains vocabulary far above tier T3: 洗い落とし (Zipf 1.46)']::text[], '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39714, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指先", "is_correct": true, "explanation": "冷えると字が書きにくくなる指の先の部分で、主語として合う。"}, {"text": "期待", "is_correct": false, "explanation": "冷たくなるのは気持ちではないので合わない。"}, {"text": "名前", "is_correct": false, "explanation": "名前が冷たくなって字が書けないという意味にはならないので合わない。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙が冷たくなって字が書けないという意味にはならないので合わない。"}], "explanations": {"指先": "冷えると字が書きにくくなる指の先の部分で、主語として合う。", "期待": "冷たくなるのは気持ちではないので合わない。", "名前": "名前が冷たくなって字が書けないという意味にはならないので合わない。", "手紙": "手紙が冷たくなって字が書けないという意味にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "指先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上司が新しい指先を出した。", "explanation": "ここは〈指示〉の意味。命令や方針を表す語で、体の部分の指先とは言わないので合わない。"}, {"text": "山の指先に雪が積もった。", "explanation": "ここは〈頂上〉の意味。山の頂は指先とは言わないので合わない。"}, {"text": "ペンの指先が折れてしまった。", "explanation": "ここは〈先端〉の意味。物の先は指先とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39714, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指先", "is_correct": true, "explanation": "包丁で切ってしまう体の部分として合う。"}, {"text": "天気", "is_correct": false, "explanation": "包丁で切る対象にならないので合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "包丁で切ることはできないので合わない。"}, {"text": "感情", "is_correct": false, "explanation": "包丁で切れるものではないので合わない。"}], "explanations": {"指先": "包丁で切ってしまう体の部分として合う。", "天気": "包丁で切る対象にならないので合わない。", "夕焼け": "包丁で切ることはできないので合わない。", "感情": "包丁で切れるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "指先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で指先が滑りやすいので、ゆっくり歩いた。", "explanation": "ここは〈足元〉の意味。滑るのは地面を踏む足元で、指先の部分ではないので合わない。"}, {"text": "指先の明かりで、本をゆっくり読んだ。", "explanation": "ここは〈手元〉の意味。ものを扱う位置を指す語で、体の一部の指先では明かりの位置を表せないので合わない。"}, {"text": "指先をまくって、作業を始めた。", "explanation": "ここは〈腕〉の意味。袖をまくるのは腕で、指先ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39714, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "糸を指先につまんで結んだ。", "corrected_sentence": "糸を指先でつまんで結んだ。", "error_description": "正しくは「指先でつまむ」で、つまむ手段を示す「で」を使う。誤りは「に」にして、つまむ手段を示せていない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39714, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "針で指先が軽く刺した。", "corrected_sentence": "針で指先を軽く刺した。", "error_description": "正しくは「指先を刺す」で、刺される対象の指先には「を」が付く。誤りは「が」にして指先を主語にしてしまい、刺すという動詞の目的語がなくなっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す『が』で、「グリッパーが小さすぎて」の主語になるのでここに入る。"}, {"text": "を", "is_correct": false, "explanation": "『を』は動作の対象につくので、「小さすぎて」の主語にはならず合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は方向や場所を表すので、ここでは主語の位置に合わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を表すので、「小さすぎて」の主語にはならず合わない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す『が』で、「グリッパーが小さすぎて」の主語になるのでここに入る。", "を": "『を』は動作の対象につくので、「小さすぎて」の主語にはならず合わない。", "に": "『に』は方向や場所を表すので、ここでは主語の位置に合わない。", "で": "『で』は手段や場所を表すので、「小さすぎて」の主語にはならず合わない。"}, "error_tags": {"を": "対象", "に": "方向・着点", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「替える」の相手や着点を示す『に』で、「新しいグリッパーに替えた」となるのでここに入る。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すので、「替えた」の相手を示せず、主語の位置に置くと意味が通らないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表すので、「新しいグリッパーから替えた」では替える相手の関係を示せず合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表すので、ここでは比較の意味がなく合わない。"}], "correct_answer": "に", "explanations": {"に": "「替える」の相手や着点を示す『に』で、「新しいグリッパーに替えた」となるのでここに入る。", "が": "『が』は主語を示すので、「替えた」の相手を示せず、主語の位置に置くと意味が通らないので合わない。", "から": "『から』は起点を表すので、「新しいグリッパーから替えた」では替える相手の関係を示せず合わない。", "より": "『より』は比較を表すので、ここでは比較の意味がなく合わない。"}, "error_tags": {"が": "主語", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものをしっかりとつかむための、手の部分のようなものです。", "primary_collocate": null, "pronunciation": "ぐりっぱー", "ipa": "ɡɯɾippaː", "syllable_count": 5, "sentences": [{"text": "この機械の先には、物をつかむグリッパーが付いています。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "この機械[きかい]の先[さき]には、物[もの]をつかむグリッパーが付[つ]いています。", "sentence_source": "generated"}, {"text": "グリッパーが小さすぎて、重い箱は持ち上げられません。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーが小[ちい]さすぎて、重[おも]い箱[はこ]は持[も]ち上[あ]げられません。", "sentence_source": "generated"}, {"text": "工場のロボットは、グリッパーで部品を一つずつ運びます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "工場[こうじょう]のロボットは、グリッパーで部品[ぶひん]を一[ひと]つずつ運[はこ]びます。", "sentence_source": "generated"}, {"text": "グリッパーの指がゴムでできているので、卵もつぶさずにつかめます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーの指[ゆび]がゴムでできているので、卵[たまご]もつぶさずにつかめます。", "sentence_source": "generated"}, {"text": "私たちは学校の授業で、グリッパーを自分で作りました。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "私[わたし]たちは学校[がっこう]の授業[じゅぎょう]で、グリッパーを自分[じぶん]で作[つく]りました。", "sentence_source": "generated"}, {"text": "グリッパーを開いてから、ゆっくり缶に近づけました。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーを開[ひら]いてから、ゆっくり缶[かん]に近[ちか]づけました。", "sentence_source": "generated"}, {"text": "グリッパーの力が弱いと、つかんだ物が落ちてしまいます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーの力[ちから]が弱[よわ]いと、つかんだ物[もの]が落[お]ちてしまいます。", "sentence_source": "generated"}, {"text": "新しいグリッパーに替えたら、丸い物も安定してつかめるようになりました。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "新[あたら]しいグリッパーに替[か]えたら、丸[まる]い物[もの]も安定[あんてい]してつかめるようになりました。", "sentence_source": "generated"}, {"text": "ごみを拾うために、棒の先にグリッパーが付いた道具を買いました。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "ごみを拾[ひろ]うために、棒[ぼう]の先[さき]にグリッパーが付[つ]いた道具[どうぐ]を買[か]いました。", "sentence_source": "generated"}, {"text": "このアームの先のグリッパーは、人の手に似た形をしています。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "このアームの先[さき]のグリッパーは、人[ひと]の手[て]に似[に]た形[かたち]をしています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グリッパー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "物をつかむ機械の手の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グリッパー", "is_correct": true, "explanation": "物をつかむ部分なので、ここに入る。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪は回って移動する部品で、物をつかむ部分ではないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は光や風を通す部分で、物をつかむ部分ではないので合わない。"}, {"text": "歯車", "is_correct": false, "explanation": "歯車は回転を伝える部品で、物をつかむ部分ではないので合わない。"}], "explanations": {"グリッパー": "物をつかむ部分なので、ここに入る。", "車輪": "車輪は回って移動する部品で、物をつかむ部分ではないので合わない。", "窓": "窓は光や風を通す部分で、物をつかむ部分ではないので合わない。", "歯車": "歯車は回転を伝える部品で、物をつかむ部分ではないので合わない。"}, "sentence_index": 0, "correct_answer": "グリッパー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ケーキを、グリッパーで焼きました。", "explanation": "ここは〈オーブン〉でケーキを焼く場面。グリッパーは物をつかむ部分で、焼く道具ではないので合わない。"}, {"text": "ネジを、グリッパーで締めました。", "explanation": "ここは〈ドライバー〉でネジを締める場面。グリッパーは物をつかむ部分で、ネジを締める工具ではないので合わない。"}, {"text": "グリッパーで、紙を切りました。", "explanation": "ここは〈ハサミ〉で紙を切る場面。グリッパーは物をつかむ部分で、切る道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グリッパー", "is_correct": true, "explanation": "物をつかむ力の主体になる部分なので、ここに入る。"}, {"text": "扉", "is_correct": false, "explanation": "扉は出入り口の板で、物をつかむ力の主体にはならないので合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、物をつかむ力の主体にはならないので合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は料理器具で、物をつかむ力の主体にはならないので合わない。"}], "explanations": {"グリッパー": "物をつかむ力の主体になる部分なので、ここに入る。", "扉": "扉は出入り口の板で、物をつかむ力の主体にはならないので合わない。", "天井": "天井は部屋の上の面で、物をつかむ力の主体にはならないので合わない。", "鍋": "鍋は料理器具で、物をつかむ力の主体にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "グリッパー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "グリッパーで、壁に穴をあけました。", "explanation": "ここは〈ドリル〉で穴をあける場面。グリッパーは物をつかむ部分で、穴をあける道具ではないので合わない。"}, {"text": "ロボットのグリッパーは、部屋の天井を照らします。", "explanation": "ここは〈ライト〉（照らす装置）の意味。グリッパーは物をつかむ部分で、照らす装置ではないので合わない。"}, {"text": "グリッパーで、書類をとじました。", "explanation": "ここは〈ホッチキス〉で書類をとじる場面。グリッパーは物をつかむ部分で、書類をとじる道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "グリッパーを、柔らかい卵を運びます。", "corrected_sentence": "グリッパーで、柔らかい卵を運びます。", "error_description": "手段を表す『で』が正しいのに『を』になっている。『を』は『卵を』と重なって目的語が二つになり、文として不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39716, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "グリッパーを食べて、部品をしっかりつかみます。", "corrected_sentence": "グリッパーを閉じて、部品をしっかりつかみます。", "error_description": "グリッパーに結びつく動詞が誤っている。正しくは『閉じて』で、グリッパーを『食べる』ことはできないので不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「グリッパーの」と「センサー」をつなぐ『の』で、所属を示すのでここに入る。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すので、「グリッパーがセンサーが」では主語が二つになり合わない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すので、「グリッパーをセンサー」では名詞同士をつなげず合わない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は着点や所在を示すので、「グリッパーにセンサー」では名詞をつなげられず合わない。"}], "correct_answer": "の", "explanations": {"の": "「グリッパーの」と「センサー」をつなぐ『の』で、所属を示すのでここに入る。", "が": "『が』は主語を示すので、「グリッパーがセンサーが」では主語が二つになり合わない。", "を": "『を』は目的語を示すので、「グリッパーをセンサー」では名詞同士をつなげず合わない。", "に": "『に』は着点や所在を示すので、「グリッパーにセンサー」では名詞をつなげられず合わない。"}, "error_tags": {"が": "主語", "を": "対象", "に": "方向・着点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「グリッパーが」の主語を示す『が』で、物をつかむ動作の主語になるのでここに入る。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を表すので、「グリッパーへ物をつかむ」では主語にならず合わない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示すので、「グリッパーを」と「物を」が重なって目的語が二つになり、不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "『から』は起点を表すので、「グリッパーから物をつかむ」では主語にならず合わない。"}], "correct_answer": "が", "explanations": {"が": "「グリッパーが」の主語を示す『が』で、物をつかむ動作の主語になるのでここに入る。", "へ": "『へ』は方向を表すので、「グリッパーへ物をつかむ」では主語にならず合わない。", "を": "『を』は目的語を示すので、「グリッパーを」と「物を」が重なって目的語が二つになり、不自然になる。", "から": "『から』は起点を表すので、「グリッパーから物をつかむ」では主語にならず合わない。"}, "error_tags": {"が": "主語", "へ": "方向", "を": "対象", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ロボットなどが物を掴むための装置。指の代わりになる部分。", "primary_collocate": null, "pronunciation": "ぐりっぱー", "ipa": "ɡɯɾippaː", "syllable_count": 5, "sentences": [{"text": "ロボットのグリッパーは、指の代わりに物をはさみます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "ロボットのグリッパーは、指[ゆび]の代[か]わりに物[もの]をはさみます。", "sentence_source": "generated"}, {"text": "グリッパーのセンサーが、物の硬さを調べています。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーのセンサーが、物[もの]の硬[かた]さを調[しら]べています。", "sentence_source": "generated"}, {"text": "空気で動くグリッパーは、軽い部品を運ぶのに向いています。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "空気[くうき]で動[うご]くグリッパーは、軽[かる]い部品[ぶひん]を運[はこ]ぶのに向[む]いています。", "sentence_source": "generated"}, {"text": "薄いガラスの板は、力の強いグリッパーだと割れてしまいます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "薄[うす]いガラスの板[いた]は、力[ちから]の強[つよ]いグリッパーだと割[わ]れてしまいます。", "sentence_source": "generated"}, {"text": "倉庫のロボットは、グリッパーで荷物を棚から取り出します。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "倉庫[そうこ]のロボットは、グリッパーで荷物[にもつ]を棚[たな]から取[と]り出[だ]します。", "sentence_source": "generated"}, {"text": "グリッパーを交換すれば、同じロボットで別の形の物も運べます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーを交換[こうかん]すれば、同[おな]じロボットで別[べつ]の形[かたち]の物[もの]も運[はこ]べます。", "sentence_source": "generated"}, {"text": "吸盤式のグリッパーは、表面が平らな箱を持ち上げるのに便利です。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "吸盤式[きゅうばんしき]のグリッパーは、表面[ひょうめん]が平[たい]らな箱[はこ]を持[も]ち上[あ]げるのに便利[べんり]です。", "sentence_source": "generated"}, {"text": "エンジニアは、グリッパーが物をつかむ力を調整しました。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "エンジニアは、グリッパーが物[もの]をつかむ力[ちから]を調整[ちょうせい]しました。", "sentence_source": "generated"}, {"text": "このロボットは、二本指のグリッパーでペンを持って字を書きます。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "このロボットは、二本指[にほんゆび]のグリッパーでペンを持[も]って字[じ]を書[か]きます。", "sentence_source": "generated"}, {"text": "グリッパーが故障したため、ロボットは作業を止めました。", "target_word": "グリッパー", "complexity_tier": "T3", "furigana": "グリッパーが故障[こしょう]したため、ロボットは作業[さぎょう]を止[と]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グリッパー", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "ロボットの指の代わりになる把持装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965ae35d-beef-46d8-a8ec-408e2f838578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グリッパー", "is_correct": true, "explanation": "指の代わりに物をはさむ部分なので、ここに入る。"}, {"text": "車輪", "is_correct": false, "explanation": "車輪は移動に使う部品で、指の代わりに物をはさむものではないので合わない。"}, {"text": "アンテナ", "is_correct": false, "explanation": "アンテナは電波を受ける部品で、物をはさむ役ではないので合わない。"}, {"text": "モニター", "is_correct": false, "explanation": "モニターは画面を表示する部品で、物をはさむ部分ではないので合わない。"}], "explanations": {"グリッパー": "指の代わりに物をはさむ部分なので、ここに入る。", "車輪": "車輪は移動に使う部品で、指の代わりに物をはさむものではないので合わない。", "アンテナ": "アンテナは電波を受ける部品で、物をはさむ役ではないので合わない。", "モニター": "モニターは画面を表示する部品で、物をはさむ部分ではないので合わない。"}, "sentence_index": 0, "correct_answer": "グリッパー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "釘を、グリッパーで打ちつけました。", "explanation": "ここは〈ハンマー〉で釘を打つ場面。グリッパーは物をつかむ装置で、打ちつける道具ではないので合わない。"}, {"text": "水を、グリッパーで沸かしました。", "explanation": "ここは〈ヤカン〉で水を沸かす場面。グリッパーは物をつかむ部分で、熱を加える道具ではないので合わない。"}, {"text": "床のごみを、グリッパーで掃きました。", "explanation": "ここは〈ほうき〉で床を掃く場面。グリッパーは物をつかむ装置で、掃く道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グリッパー", "is_correct": true, "explanation": "吸盤式の把持部分で箱を持ち上げるものなので、ここに入る。"}, {"text": "歯車", "is_correct": false, "explanation": "歯車は回転を伝える部品で、吸盤式の把持部分ではないので合わない。"}, {"text": "窓", "is_correct": false, "explanation": "窓は光を通す部分で、箱を持ち上げる部分ではないので合わない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は料理器具で、箱を持ち上げる装置ではないので合わない。"}], "explanations": {"グリッパー": "吸盤式の把持部分で箱を持ち上げるものなので、ここに入る。", "歯車": "歯車は回転を伝える部品で、吸盤式の把持部分ではないので合わない。", "窓": "窓は光を通す部分で、箱を持ち上げる部分ではないので合わない。", "鍋": "鍋は料理器具で、箱を持ち上げる装置ではないので合わない。"}, "sentence_index": 6, "correct_answer": "グリッパー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "布を、グリッパーで縫いました。", "explanation": "ここは〈ミシン〉で布を縫う場面。グリッパーは物をつかむ装置で、縫う道具ではないので合わない。"}, {"text": "大きな鉄骨を、グリッパーで溶接しました。", "explanation": "ここは〈溶接機〉で鉄骨をつなぐ場面。グリッパーは物をつかむ装置で、溶接する機械ではないので合わない。"}, {"text": "スープを、グリッパーですくいました。", "explanation": "ここは〈スプーン〉でスープをすくう場面。グリッパーは物をつかむ装置で、すくう道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロボットのグリッパーで、部品をやさしく切ります。", "corrected_sentence": "ロボットのグリッパーで、部品をやさしくつかみます。", "error_description": "『グリッパーで』と結びつく動詞が誤っている。正しくは『つかむ』で、『切る』は刃物の動作なので合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39717, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "エンジニアは、グリッパーを部品を持ち上げました。", "corrected_sentence": "エンジニアは、グリッパーで部品を持ち上げました。", "error_description": "手段を表す『で』が正しいのに『を』になっている。『を』は『部品を』と重なって目的語が二つになり、文として不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3d56cda-426d-4c9e-8856-418e76b89830') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
