INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39718, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものを、一つにつなげる。", "primary_collocate": null, "pronunciation": "つなぎあわせる", "ipa": "tsɯnaɡiawaseɾɯ", "syllable_count": 7, "sentences": [{"text": "破れた布を繋ぎ合わせて、一枚の大きなかばんにした。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "破[やぶ]れた布[ぬの]を繋[つな]ぎ合[あ]わせて、一枚[いちまい]の大[おお]きなかばんにした。", "sentence_source": "generated"}, {"text": "切れたひもを繋ぎ合わせれば、まだ使える。", "target_word": "繋ぎ合わせれば", "complexity_tier": "T3", "furigana": "切[き]れたひもを繋[つな]ぎ合[あ]わせれば、まだ使[つか]える。", "sentence_source": "generated"}, {"text": "子どもたちは、ばらばらの紙を繋ぎ合わせて、一枚の地図を作った。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ばらばらの紙[かみ]を繋[つな]ぎ合[あ]わせて、一枚[いちまい]の地図[ちず]を作[つく]った。", "sentence_source": "generated"}, {"text": "古い服の布を繋ぎ合わせたので、色がいろいろ混ざっている。", "target_word": "繋ぎ合わせた", "complexity_tier": "T3", "furigana": "古[ふる]い服[ふく]の布[ぬの]を繋[つな]ぎ合[あ]わせたので、色[いろ]がいろいろ混[ま]ざっている。", "sentence_source": "generated"}, {"text": "二本の短い棒を繋ぎ合わせて、長い棒にした。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "二本[にほん]の短[みじか]い棒[ぼう]を繋[つな]ぎ合[あ]わせて、長[なが]い棒[ぼう]にした。", "sentence_source": "generated"}, {"text": "割れた皿を繋ぎ合わせようとしたが、小さな破片が足りなかった。", "target_word": "繋ぎ合わせよう", "complexity_tier": "T3", "furigana": "割[わ]れた皿[さら]を繋[つな]ぎ合[あ]わせようとしたが、小[ちい]さな破片[はへん]が足[た]りなかった。", "sentence_source": "generated"}, {"text": "別々に撮った写真を繋ぎ合わせると、山全体の景色になる。", "target_word": "繋ぎ合わせる", "complexity_tier": "T3", "furigana": "別々[べつべつ]に撮[と]った写真[しゃしん]を繋[つな]ぎ合[あ]わせると、山全体[やまぜんたい]の景色[けしき]になる。", "sentence_source": "generated"}, {"text": "彼女は残った毛糸を繋ぎ合わせて、マフラーを編んだ。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は残[のこ]った毛糸[けいと]を繋[つな]ぎ合[あ]わせて、マフラーを編[あ]んだ。", "sentence_source": "generated"}, {"text": "切り取った絵の部分を繋ぎ合わせないと、全体が見えない。", "target_word": "繋ぎ合わせない", "complexity_tier": "T3", "furigana": "切[き]り取[と]った絵[え]の部分[ぶぶん]を繋[つな]ぎ合[あ]わせないと、全体[ぜんたい]が見[み]えない。", "sentence_source": "generated"}, {"text": "テープで繋ぎ合わせた紙は、すぐにはがれてしまった。", "target_word": "繋ぎ合わせた", "complexity_tier": "T3", "furigana": "テープで繋[つな]ぎ合[あ]わせた紙[かみ]は、すぐにはがれてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繋ぎ合わせる", "label": "基本形"}, {"form": "繋ぎ合わせます", "label": "丁寧形"}, {"form": "繋ぎ合わせて", "label": "て形"}, {"form": "繋ぎ合わせた", "label": "過去形"}, {"form": "繋ぎ合わせない", "label": "否定形"}, {"form": "繋ぎ合わせれば", "label": "仮定形"}, {"form": "繋ぎ合わせよう", "label": "意向形"}, {"form": "繋ぎ合わせられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "布・紙・ひもなど、別々の二つ以上のものを接続して一つにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39718, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繋ぎ合わせて", "is_correct": true, "explanation": "布を連結して一枚にする動作のて形で、後ろの文へ続くので合う。"}, {"text": "歌って", "is_correct": false, "explanation": "布を歌うという意味にはならないので合わない。"}, {"text": "眠って", "is_correct": false, "explanation": "布は眠らないので合わない。"}, {"text": "笑って", "is_correct": false, "explanation": "布を笑うという意味にはならないので合わない。"}], "explanations": {"繋ぎ合わせて": "布を連結して一枚にする動作のて形で、後ろの文へ続くので合う。", "歌って": "布を歌うという意味にはならないので合わない。", "眠って": "布は眠らないので合わない。", "笑って": "布を笑うという意味にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "繋ぎ合わせて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、髪を繋ぎ合わせて学校へ行った。", "explanation": "ここは〈結ぶ〉の意味。髪を束ねる動作は結ぶで、繋ぎ合わせるとは言わないので合わない。"}, {"text": "二人の答えを繋ぎ合わせて、どちらが正しいか確かめた。", "explanation": "ここは〈照合〉の意味。答えを照らし合わせるのは繋ぎ合わせるとは言わないので合わない。"}, {"text": "さいころを繋ぎ合わせて、一の目を出した。", "explanation": "ここは〈振る〉の意味。さいころを転がす動作には繋ぎ合わせるは合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39718, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繋ぎ合わせる", "is_correct": true, "explanation": "写真を組み合わせて一つにすると景色になるという文脈に合うので合う。"}, {"text": "踊る", "is_correct": false, "explanation": "写真は踊らないので合わない。"}, {"text": "怒る", "is_correct": false, "explanation": "写真は怒らないので合わない。"}, {"text": "泣く", "is_correct": false, "explanation": "写真は泣かないので合わない。"}], "explanations": {"繋ぎ合わせる": "写真を組み合わせて一つにすると景色になるという文脈に合うので合う。", "踊る": "写真は踊らないので合わない。", "怒る": "写真は怒らないので合わない。", "泣く": "写真は泣かないので合わない。"}, "sentence_index": 6, "correct_answer": "繋ぎ合わせる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "絵の具で赤と青を繋ぎ合わせて、紫を作った。", "explanation": "ここは〈混ぜる〉の意味。色を混ぜ合わせる意味で、物理的につなぐ繋ぎ合わせるは合わない。"}, {"text": "寒いので、コートを繋ぎ合わせた。", "explanation": "ここは〈着る〉の意味。服を身につける動作で、繋ぎ合わせるとは言わないので合わない。"}, {"text": "友達に手紙を繋ぎ合わせた。", "explanation": "ここは〈届ける〉の意味。相手に渡す動作で、繋ぎ合わせるは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39718, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二本の糸を繋ぎ合わせる、長い糸にした。", "corrected_sentence": "二本の糸を繋ぎ合わせて、長い糸にした。", "error_description": "正しくは「繋ぎ合わせて」で、後ろの文へ続けるためのて形。誤りは終止形の「繋ぎ合わせる」にしたことで、文が途中で切れてしまっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繋ぎ合わせれば", "is_correct": true, "explanation": "仮定の「ば」の形で、切れたひもを繋ぎ合わせるという条件を表すので合う。"}, {"text": "繋ぎ合わせる", "is_correct": false, "explanation": "基本形で、「ば」を続けた条件の形にならないので合わない。"}, {"text": "繋ぎ合わせない", "is_correct": false, "explanation": "否定形で、繋がないという意味になるので合わない。"}, {"text": "繋ぎ合わせよう", "is_correct": false, "explanation": "意向形で、「〜しよう」という意志を表すので合わない。"}], "correct_form": "繋ぎ合わせれば", "base_form": "繋ぎ合わせる", "form_label": "仮定形（〜ば）", "sentence_index": 1, "explanations": {"繋ぎ合わせれば": "仮定の「ば」の形で、切れたひもを繋ぎ合わせるという条件を表すので合う。", "繋ぎ合わせる": "基本形で、「ば」を続けた条件の形にならないので合わない。", "繋ぎ合わせない": "否定形で、繋がないという意味になるので合わない。", "繋ぎ合わせよう": "意向形で、「〜しよう」という意志を表すので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39718, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "紙が繋ぎ合わせて、一枚の絵にした。", "corrected_sentence": "紙を繋ぎ合わせて、一枚の絵にした。", "error_description": "正しくは「紙を繋ぎ合わせる」で、つなぐ対象の紙には「を」が付く。誤りは「が」にして紙を主語にしてしまい、繋ぎ合わせる動作の目的語がなくなっている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繋ぎ合わせて", "is_correct": true, "explanation": "て形で、後ろの「マフラーを編んだ」へ続くので合う。"}, {"text": "繋ぎ合わせます", "is_correct": false, "explanation": "丁寧形で文を終える形なので、後ろの文へ続かないので合わない。"}, {"text": "繋ぎ合わせられる", "is_correct": false, "explanation": "可能形で、できるという意味になり文の流れに合わないので合わない。"}, {"text": "繋ぎ合わせない", "is_correct": false, "explanation": "否定形で、続けるなら「ないで」が必要になり、文の流れに合わないので合わない。"}], "correct_form": "繋ぎ合わせて", "base_form": "繋ぎ合わせる", "form_label": "て形", "sentence_index": 7, "explanations": {"繋ぎ合わせて": "て形で、後ろの「マフラーを編んだ」へ続くので合う。", "繋ぎ合わせます": "丁寧形で文を終える形なので、後ろの文へ続かないので合わない。", "繋ぎ合わせられる": "可能形で、できるという意味になり文の流れに合わないので合わない。", "繋ぎ合わせない": "否定形で、続けるなら「ないで」が必要になり、文の流れに合わないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電池を繋ぎ合わせる」で、繋ぎ合わせる対象の電池を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「電池が繋ぎ合わせる」では電池が動作の主体になり、繋ぎ合わせる対象を示せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「電池の繋ぎ合わせると」では名詞の修飾になり、条件を表す動詞の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「電池へ繋ぎ合わせる」は方向を示すため、繋ぎ合わせる対象を表す文の形と合わない。"}], "correct_answer": "を", "explanations": {"を": "「電池を繋ぎ合わせる」で、繋ぎ合わせる対象の電池を示す「を」が入る。", "が": "「電池が繋ぎ合わせる」では電池が動作の主体になり、繋ぎ合わせる対象を示せず不自然。", "の": "「電池の繋ぎ合わせると」では名詞の修飾になり、条件を表す動詞の文として成り立たない。", "へ": "「電池へ繋ぎ合わせる」は方向を示すため、繋ぎ合わせる対象を表す文の形と合わない。"}, "error_tags": {"が": "主語の格", "の": "連体修飾", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「繋ぎ合わせないと」で、つながない場合の結果を示す条件の「と」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「繋ぎ合わせないに」は動詞の後に続かず、文の構造と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、条件を示す文脈では意味が合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」を続けると名詞化の形になり、「機械は動かない」と結果がつながらない。"}], "correct_answer": "と", "explanations": {"と": "「繋ぎ合わせないと」で、つながない場合の結果を示す条件の「と」が入る。", "に": "「繋ぎ合わせないに」は動詞の後に続かず、文の構造と合わない。", "より": "「より」は比較を表すため、条件を示す文脈では意味が合わない。", "の": "「の」を続けると名詞化の形になり、「機械は動かない」と結果がつながらない。"}, "error_tags": {"に": "相手・場所の格", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数の部品や要素を、一つに連結すること。", "primary_collocate": null, "pronunciation": "つなぎあわせる", "ipa": "tsɯnaɡiawaseɾɯ", "syllable_count": 7, "sentences": [{"text": "技術者は、細いパイプを繋ぎ合わせて、長い水道管を作った。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "技術者[ぎじゅつしゃ]は、細[ほそ]いパイプを繋[つな]ぎ合[あ]わせて、長[なが]い水道管[すいどうかん]を作[つく]った。", "sentence_source": "generated"}, {"text": "基板と電池を繋ぎ合わせると、ライトがつく。", "target_word": "繋ぎ合わせる", "complexity_tier": "T3", "furigana": "基板[きばん]と電池[でんち]を繋[つな]ぎ合[あ]わせると、ライトがつく。", "sentence_source": "generated"}, {"text": "小さな部品を繋ぎ合わせて、ロボットの腕を組み立てた。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "小[ちい]さな部品[ぶひん]を繋[つな]ぎ合[あ]わせて、ロボットの腕[うで]を組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "工場では、機械が金属の板を繋ぎ合わせている。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]が金属[きんぞく]の板[いた]を繋[つな]ぎ合[あ]わせている。", "sentence_source": "generated"}, {"text": "古い部品を繋ぎ合わせたので、見た目は悪いが、ちゃんと動く。", "target_word": "繋ぎ合わせた", "complexity_tier": "T3", "furigana": "古[ふる]い部品[ぶひん]を繋[つな]ぎ合[あ]わせたので、見[み]た目[め]は悪[わる]いが、ちゃんと動[うご]く。", "sentence_source": "generated"}, {"text": "二つの装置を繋ぎ合わせるには、専用のケーブルが必要だ。", "target_word": "繋ぎ合わせる", "complexity_tier": "T3", "furigana": "二[ふた]つの装置[そうち]を繋[つな]ぎ合[あ]わせるには、専用[せんよう]のケーブルが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "短いレールを繋ぎ合わせて、長い線路を作った。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "短[みじか]いレールを繋[つな]ぎ合[あ]わせて、長[なが]い線路[せんろ]を作[つく]った。", "sentence_source": "generated"}, {"text": "部品を正しく繋ぎ合わせないと、機械は動かない。", "target_word": "繋ぎ合わせない", "complexity_tier": "T3", "furigana": "部品[ぶひん]を正[ただ]しく繋[つな]ぎ合[あ]わせないと、機械[きかい]は動[うご]かない。", "sentence_source": "generated"}, {"text": "切れた配線を繋ぎ合わせたあと、テープで巻いた。", "target_word": "繋ぎ合わせた", "complexity_tier": "T3", "furigana": "切[き]れた配線[はいせん]を繋[つな]ぎ合[あ]わせたあと、テープで巻[ま]いた。", "sentence_source": "generated"}, {"text": "複数のプログラムを繋ぎ合わせて、一つのアプリにした。", "target_word": "繋ぎ合わせて", "complexity_tier": "T3", "furigana": "複数[ふくすう]のプログラムを繋[つな]ぎ合[あ]わせて、一[ひと]つのアプリにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "繋ぎ合わせる", "label": "基本形"}, {"form": "繋ぎ合わせます", "label": "丁寧形"}, {"form": "繋ぎ合わせて", "label": "て形"}, {"form": "繋ぎ合わせた", "label": "過去形"}, {"form": "繋ぎ合わせない", "label": "否定形"}, {"form": "繋ぎ合わせれば", "label": "仮定形"}, {"form": "繋ぎ合わせよう", "label": "意向形"}, {"form": "繋ぎ合わせられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "部品・配線・装置・プログラムなどの要素を連結して一つのまとまりにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繋ぎ合わせて", "is_correct": true, "explanation": "「細いパイプを〜て、長い水道管を作った」で、複数のパイプを連結する動作の連用形として自然に入る。"}, {"text": "切り離して", "is_correct": false, "explanation": "切り離すとパイプが分かれてしまい、長い水道管を作る流れに合わない。"}, {"text": "分解して", "is_correct": false, "explanation": "分解するとばらばらになるので、長い水道管を作る文脈とは逆の意味になる。"}, {"text": "削り取って", "is_correct": false, "explanation": "表面を削っても長くはならないので、パイプをつないで長くする内容と合わない。"}], "explanations": {"繋ぎ合わせて": "「細いパイプを〜て、長い水道管を作った」で、複数のパイプを連結する動作の連用形として自然に入る。", "切り離して": "切り離すとパイプが分かれてしまい、長い水道管を作る流れに合わない。", "分解して": "分解するとばらばらになるので、長い水道管を作る文脈とは逆の意味になる。", "削り取って": "表面を削っても長くはならないので、パイプをつないで長くする内容と合わない。"}, "sentence_index": 0, "correct_answer": "繋ぎ合わせて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "おしゃれな服の色を繋ぎ合わせて、今日のコーデを決めた。", "explanation": "ここは〈組み合わせる〉の意味。繋ぎ合わせるは部品の端を連結する語で、色や服の取り合わせには使わないので不自然。"}, {"text": "水素と酸素を繋ぎ合わせて、水という物質を作った。", "explanation": "ここは〈結合する〉の意味。繋ぎ合わせるは人や機械が部品を継ぐ行為を指し、原子同士の結びつきには使わない。"}, {"text": "古いドアを繋ぎ合わせて、寒い部屋をしっかり閉めた。", "explanation": "ここは〈塞ぐ〉の意味。繋ぎ合わせるは部品を一つにつなぐ語で、戸口を塞ぐ動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繋ぎ合わせて", "is_correct": true, "explanation": "「短いレールを〜て、長い線路を作った」で、短い部品を連結して長くする動作の連用形が自然に入る。"}, {"text": "引きはがして", "is_correct": false, "explanation": "引きはがすと部品が離れるので、短いレールを集めて長くする文脈と逆になる。"}, {"text": "解体して", "is_correct": false, "explanation": "解体すると線路がばらばらになるので、長い線路を作る流れに合わない。"}, {"text": "取り外して", "is_correct": false, "explanation": "取り外すとレールが外れてしまい、長い線路を作ることにつながらない。"}], "explanations": {"繋ぎ合わせて": "「短いレールを〜て、長い線路を作った」で、短い部品を連結して長くする動作の連用形が自然に入る。", "引きはがして": "引きはがすと部品が離れるので、短いレールを集めて長くする文脈と逆になる。", "解体して": "解体すると線路がばらばらになるので、長い線路を作る流れに合わない。", "取り外して": "取り外すとレールが外れてしまい、長い線路を作ることにつながらない。"}, "sentence_index": 6, "correct_answer": "繋ぎ合わせて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い機械を繋ぎ合わせて、中の部品を一つずつ取り出した。", "explanation": "ここは〈分解する〉の意味。繋ぎ合わせるは部品を集めて一つにすることで、機械を開いて部品を取り出す場面には使わない。"}, {"text": "古い瓶を繋ぎ合わせて、ごみに出した。", "explanation": "ここは〈まとめる〉の意味。繋ぎ合わせるは複数の部品を一つにする語で、一本の瓶には使えないので不自然。"}, {"text": "壁から古いシールを繋ぎ合わせて、丁寧に剥がした。", "explanation": "ここは〈取り外す〉の意味。繋ぎ合わせるは部品を連結する語で、貼ってあるものを外す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "細い針金を繋ぎ合わせたて、ハンガーを作った。", "corrected_sentence": "細い針金を繋ぎ合わせて、ハンガーを作った。", "error_description": "誤りは「繋ぎ合わせたて」の「た」。「繋ぎ合わせて」のて形が正しく、過去の「た」を重ねると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "繋ぎ合わせる", "is_correct": true, "explanation": "「〜と、ライトがつく」の前に来る基本形で、文の形と合う。"}, {"text": "繋ぎ合わせて", "is_correct": false, "explanation": "て形は「〜と」の前に直接続かず、この文の条件の形と合わない。"}, {"text": "繋ぎ合わせられる", "is_correct": false, "explanation": "可能形になると「つなぐことができる」という意味に変わり、ここでは意味が合わない。"}, {"text": "繋ぎ合わせよう", "is_correct": false, "explanation": "意向形は「つなごう」という意志の意味になり、ライトがつく結果の文とつながらない。"}], "correct_form": "繋ぎ合わせる", "base_form": "繋ぎ合わせる", "form_label": "基本形", "sentence_index": 1, "explanations": {"繋ぎ合わせる": "「〜と、ライトがつく」の前に来る基本形で、文の形と合う。", "繋ぎ合わせて": "て形は「〜と」の前に直接続かず、この文の条件の形と合わない。", "繋ぎ合わせられる": "可能形になると「つなぐことができる」という意味に変わり、ここでは意味が合わない。", "繋ぎ合わせよう": "意向形は「つなごう」という意志の意味になり、ライトがつく結果の文とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つのケーブルの繋ぎ合わせて、通信を始めた。", "corrected_sentence": "二つのケーブルを繋ぎ合わせて、通信を始めた。", "error_description": "誤りは「ケーブルの」の「の」。繋ぎ合わせての目的語には「を」が必要で、「の」では動詞とつながらない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "繋ぎ合わせない", "is_correct": true, "explanation": "「〜ないと、機械は動かない」の否定形で、文の意味と合う。"}, {"text": "繋ぎ合わせる", "is_correct": false, "explanation": "肯定の基本形では「つなぐと」の意味になり、否定の条件にならない。"}, {"text": "繋ぎ合わせた", "is_correct": false, "explanation": "過去形は「つないだ」の意味になり、これから起きる条件の文と合わない。"}, {"text": "繋ぎ合わせて", "is_correct": false, "explanation": "て形は「ないと」の前に続かず、この文の形と合わない。"}], "correct_form": "繋ぎ合わせない", "base_form": "繋ぎ合わせる", "form_label": "否定形", "sentence_index": 7, "explanations": {"繋ぎ合わせない": "「〜ないと、機械は動かない」の否定形で、文の意味と合う。", "繋ぎ合わせる": "肯定の基本形では「つなぐと」の意味になり、否定の条件にならない。", "繋ぎ合わせた": "過去形は「つないだ」の意味になり、これから起きる条件の文と合わない。", "繋ぎ合わせて": "て形は「ないと」の前に続かず、この文の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39720, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基板に部品をつける」で、部品を取りつける先を示す「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「基板を小さな部品を」と目的語が重なり、文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「基板で」では部品を取りつける相手が示せず、文の意味が合わない。"}, {"text": "から", "is_correct": false, "explanation": "「基板から」は起点を表し、部品をつける相手を示す文脈と合わない。"}], "correct_answer": "に", "explanations": {"に": "「基板に部品をつける」で、部品を取りつける先を示す「に」が入る。", "を": "「基板を小さな部品を」と目的語が重なり、文として成り立たない。", "で": "「基板で」では部品を取りつける相手が示せず、文の意味が合わない。", "から": "「基板から」は起点を表し、部品をつける相手を示す文脈と合わない。"}, "error_tags": {"を": "目的語の格", "で": "手段の格", "から": "起点の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39720, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「基板に部品をつなぐ」で、部品をつなぐ先を示す「に」が入る。"}, {"text": "を", "is_correct": false, "explanation": "「基板を部品を」と目的語が二つ重なり、文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、部品をつなぐ先を示す文脈では意味が合わない。"}, {"text": "が", "is_correct": false, "explanation": "「基板が部品をつなぐ」では基板が作業の主体になり、はんだごてで作業する人の文と合わない。"}], "correct_answer": "に", "explanations": {"に": "「基板に部品をつなぐ」で、部品をつなぐ先を示す「に」が入る。", "を": "「基板を部品を」と目的語が二つ重なり、文として成り立たない。", "より": "「より」は比較を表すため、部品をつなぐ先を示す文脈では意味が合わない。", "が": "「基板が部品をつなぐ」では基板が作業の主体になり、はんだごてで作業する人の文と合わない。"}, "error_tags": {"へ": "方向の格", "より": "比較", "が": "主語の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39720, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電子の部品をのせるための、うすい板のことです。", "primary_collocate": null, "pronunciation": "きばん", "ipa": "kibaɴ", "syllable_count": 3, "sentences": [{"text": "電子機器の中には、緑色の基板が入っている。", "target_word": "基板", "complexity_tier": "T3", "furigana": "電子機器[でんしきき]の中[なか]には、緑色[みどりいろ]の基板[きばん]が入[はい]っている。", "sentence_source": "generated"}, {"text": "基板に小さな部品をはんだでつけた。", "target_word": "基板", "complexity_tier": "T3", "furigana": "基板[きばん]に小[ちい]さな部品[ぶひん]をはんだでつけた。", "sentence_source": "generated"}, {"text": "水がかかって、基板が壊れてしまった。", "target_word": "基板", "complexity_tier": "T3", "furigana": "水[みず]がかかって、基板[きばん]が壊[こわ]れてしまった。", "sentence_source": "generated"}, {"text": "古いラジオを開けると、基板がほこりだらけだった。", "target_word": "基板", "complexity_tier": "T3", "furigana": "古[ふる]いラジオを開[あ]けると、基板[きばん]がほこりだらけだった。", "sentence_source": "generated"}, {"text": "技術者は、基板の上の線を虫めがねで確かめた。", "target_word": "基板", "complexity_tier": "T3", "furigana": "技術者[ぎじゅつしゃ]は、基板[きばん]の上[うえ]の線[せん]を虫[むし]めがねで確[たし]かめた。", "sentence_source": "generated"}, {"text": "この基板はうすくて軽いので、スマートフォンに使われる。", "target_word": "基板", "complexity_tier": "T3", "furigana": "この基板[きばん]はうすくて軽[かる]いので、スマートフォンに使[つか]われる。", "sentence_source": "generated"}, {"text": "基板を新しいものに換えたら、テレビが映った。", "target_word": "基板", "complexity_tier": "T3", "furigana": "基板[きばん]を新[あたら]しいものに換[か]えたら、テレビが映[うつ]った。", "sentence_source": "generated"}, {"text": "電子工作では、はんだごてで基板に部品をつなぐ。", "target_word": "基板", "complexity_tier": "T3", "furigana": "電子工作[でんしこうさく]では、はんだごてで基板[きばん]に部品[ぶひん]をつなぐ。", "sentence_source": "generated"}, {"text": "工場では、機械が基板に部品を自動でのせている。", "target_word": "基板", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、機械[きかい]が基板[きばん]に部品[ぶひん]を自動[じどう]でのせている。", "sentence_source": "generated"}, {"text": "熱で基板が曲がらないように、ファンで冷やしている。", "target_word": "基板", "complexity_tier": "T3", "furigana": "熱[ねつ]で基板[きばん]が曲[ま]がらないように、ファンで冷[ひ]やしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基板", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "電子部品をのせて配線をつなぐ、機器の中のうすい板（回路基板）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T4: contains vocabulary far above tier T4: 虫めがね (Zipf 1.44)']::text[], '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基板", "is_correct": true, "explanation": "電子機器の中に入り、電子部品をのせる板なので、「緑色の基板が入っている」に合う。"}, {"text": "基準", "is_correct": false, "explanation": "基準は目安や判断の基になるものを指し、機器の中に入る物としては合わない。"}, {"text": "基点", "is_correct": false, "explanation": "基点は出発点や測定の起点を指し、機器の中に入る物としては合わない。"}, {"text": "基地", "is_correct": false, "explanation": "基地は活動の拠点を指し、機器の中に入る部品としては意味が合わない。"}], "explanations": {"基板": "電子機器の中に入り、電子部品をのせる板なので、「緑色の基板が入っている」に合う。", "基準": "基準は目安や判断の基になるものを指し、機器の中に入る物としては合わない。", "基点": "基点は出発点や測定の起点を指し、機器の中に入る物としては合わない。", "基地": "基地は活動の拠点を指し、機器の中に入る部品としては意味が合わない。"}, "sentence_index": 0, "correct_answer": "基板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家は基板がしっかりしているので、地震に強い。", "explanation": "ここは〈基礎〉の意味。基板は電子部品を載せる板で、建物の土台の話には使わない。"}, {"text": "料理のあと、基板をきれいに洗って乾かした。", "explanation": "ここは〈まな板〉の意味。基板は電子回路の板で、食材を切る台所用品には使わない。"}, {"text": "教室の基板に、先生が大事な文字を書いた。", "explanation": "ここは〈黒板〉の意味。基板は電子部品を載せる板で、チョークで文字を書く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基板", "is_correct": true, "explanation": "テレビの部品として換える板なので、「基板を新しいものに換えたら、テレビが映った」に合う。"}, {"text": "基盤", "is_correct": false, "explanation": "基盤は組織や物の土台を指し、部品として換える板の意味とは合わない。"}, {"text": "基点", "is_correct": false, "explanation": "基点は出発点や測定の起点を指し、換える対象としての意味が成り立たない。"}, {"text": "基調", "is_correct": false, "explanation": "基調は全体の調子や傾向を指し、物として換える文脈には合わない。"}], "explanations": {"基板": "テレビの部品として換える板なので、「基板を新しいものに換えたら、テレビが映った」に合う。", "基盤": "基盤は組織や物の土台を指し、部品として換える板の意味とは合わない。", "基点": "基点は出発点や測定の起点を指し、換える対象としての意味が成り立たない。", "基調": "基調は全体の調子や傾向を指し、物として換える文脈には合わない。"}, "sentence_index": 6, "correct_answer": "基板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅の基板に、新しいお知らせを貼った。", "explanation": "ここは〈掲示板〉の意味。基板は電子部品を載せる板で、お知らせを貼る場所には使わない。"}, {"text": "壁のカレンダーに予定を書き込むように、壁の基板に予定を書き込んだ。", "explanation": "ここは〈ホワイトボード〉の意味。基板は電子回路の板で、予定を書き込む面としては使わない。"}, {"text": "窓の基板に雨粒がついていた。", "explanation": "ここは〈ガラス〉の意味。基板は電子回路の板で、雨粒がつく透明な面としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ラジオの基板を壊れて、音が出なくなった。", "corrected_sentence": "ラジオの基板が壊れて、音が出なくなった。", "error_description": "誤りは「基板を」の「を」。壊れるは自動詞なので、主語には「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
