INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「基板が壊れた」で、壊れた物が主語になるので「が」が入る。"}, {"text": "を", "is_correct": false, "explanation": "壊れるは自動詞なので「基板を壊れた」は成り立たず、目的語の格とも合わない。"}, {"text": "に", "is_correct": false, "explanation": "「基板に壊れた」は相手や場所を示す形で、壊れた主体を示す文と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は壊れる動作の主体を示せず、文の構造と合わない。"}], "correct_answer": "が", "explanations": {"が": "「基板が壊れた」で、壊れた物が主語になるので「が」が入る。", "を": "壊れるは自動詞なので「基板を壊れた」は成り立たず、目的語の格とも合わない。", "に": "「基板に壊れた」は相手や場所を示す形で、壊れた主体を示す文と合わない。", "へ": "方向を表す「へ」は壊れる動作の主体を示せず、文の構造と合わない。"}, "error_tags": {"を": "目的語の格", "に": "相手・場所の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「古い基板を新しいものに交換する」で、交換される対象を示す「を」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「基板が交換すれば」では基板が交換する主体になり、文の意味が合わない。"}, {"text": "で", "is_correct": false, "explanation": "「基板で交換する」では道具や手段の意味になり、交換される物を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、交換される対象を示す文脈では意味が合わない。"}], "correct_answer": "を", "explanations": {"を": "「古い基板を新しいものに交換する」で、交換される対象を示す「を」が入る。", "が": "「基板が交換すれば」では基板が交換する主体になり、文の意味が合わない。", "で": "「基板で交換する」では道具や手段の意味になり、交換される物を示せない。", "より": "「より」は比較を表すため、交換される対象を示す文脈では意味が合わない。"}, "error_tags": {"が": "主語の格", "で": "手段の格", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "電子回路を構成するための部品を実装する、絶縁性の板。", "primary_collocate": null, "pronunciation": "きばん", "ipa": "kibaɴ", "syllable_count": 3, "sentences": [{"text": "基板に小さな部品をはんだで取りつけた。", "target_word": "基板", "complexity_tier": "T3", "furigana": "基板[きばん]に小[ちい]さな部品[ぶひん]をはんだで取[と]りつけた。", "sentence_source": "generated"}, {"text": "この基板が壊れたので、テレビがつかなくなった。", "target_word": "基板", "complexity_tier": "T3", "furigana": "この基板[きばん]が壊[こわ]れたので、テレビがつかなくなった。", "sentence_source": "generated"}, {"text": "工場では、基板を一枚ずつ検査している。", "target_word": "基板", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、基板[きばん]を一枚[いちまい]ずつ検査[けんさ]している。", "sentence_source": "generated"}, {"text": "スマホを分解すると、中に緑色の基板が見える。", "target_word": "基板", "complexity_tier": "T3", "furigana": "スマホを分解[ぶんかい]すると、中[なか]に緑色[みどりいろ]の基板[きばん]が見[み]える。", "sentence_source": "generated"}, {"text": "基板の上に、抵抗やコンデンサーが並んでいる。", "target_word": "基板", "complexity_tier": "T3", "furigana": "基板[きばん]の上[うえ]に、抵抗[ていこう]やコンデンサーが並[なら]んでいる。", "sentence_source": "generated"}, {"text": "水がかかって基板がショートし、機械が止まった。", "target_word": "基板", "complexity_tier": "T3", "furigana": "水[みず]がかかって基板[きばん]がショートし、機械[きかい]が止[と]まった。", "sentence_source": "generated"}, {"text": "彼は自分で基板を設計して、ラジオを作った。", "target_word": "基板", "complexity_tier": "T3", "furigana": "彼[かれ]は自分[じぶん]で基板[きばん]を設計[せっけい]して、ラジオを作[つく]った。", "sentence_source": "generated"}, {"text": "古い基板を新しいものに交換すれば、修理は終わる。", "target_word": "基板", "complexity_tier": "T3", "furigana": "古[ふる]い基板[きばん]を新[あたら]しいものに交換[こうかん]すれば、修理[しゅうり]は終[お]わる。", "sentence_source": "generated"}, {"text": "基板は熱に弱いので、風を当てて冷やす必要がある。", "target_word": "基板", "complexity_tier": "T3", "furigana": "基板[きばん]は熱[ねつ]に弱[よわ]いので、風[かぜ]を当[あ]てて冷[ひ]やす必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "電子工作の授業で、私は初めて基板を使った。", "target_word": "基板", "complexity_tier": "T3", "furigana": "電子[でんし]工作[こうさく]の授業[じゅぎょう]で、私[わたし]は初[はじ]めて基板[きばん]を使[つか]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "基板", "label": "dictionary form"}], "register": "neutral", "sense_fingerprint": "電子部品を取りつけて回路を作る板(プリント基板)。土台の意味の「基盤」ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基板", "is_correct": true, "explanation": "電子部品を取りつける板なので、「〜に小さな部品をはんだで取りつけた」に合う。"}, {"text": "基幹", "is_correct": false, "explanation": "基幹は中心となる骨組みの意味で、部品を取りつける板としては意味が合わない。"}, {"text": "基点", "is_correct": false, "explanation": "基点は出発点や測定の起点を指し、部品を取りつける対象としては意味が合わない。"}, {"text": "基地", "is_correct": false, "explanation": "基地は拠点の意味で、部品をはんだで取りつける対象とは合わない。"}], "explanations": {"基板": "電子部品を取りつける板なので、「〜に小さな部品をはんだで取りつけた」に合う。", "基幹": "基幹は中心となる骨組みの意味で、部品を取りつける板としては意味が合わない。", "基点": "基点は出発点や測定の起点を指し、部品を取りつける対象としては意味が合わない。", "基地": "基地は拠点の意味で、部品をはんだで取りつける対象とは合わない。"}, "sentence_index": 0, "correct_answer": "基板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社の基板を固めるため、社員研修を行った。", "explanation": "ここは〈基盤〉の意味。基板は電子回路の板で、組織の土台を固める話には使わない。"}, {"text": "授業の内容を、基板に書きとめた。", "explanation": "ここは〈ノート〉の意味。基板は電子部品を載せる板で、文字を書きとめる用途には使わない。"}, {"text": "キッチンで、基板を絞って机を拭いた。", "explanation": "ここは〈ふきん〉の意味。基板は電子回路の板で、水を絞って机を拭く布には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基板", "is_correct": true, "explanation": "回路の板を自分で設計してラジオを作る文なので、「基板を設計して」に合う。"}, {"text": "基準", "is_correct": false, "explanation": "基準は評価や判断の目安を指し、ラジオの回路板を設計する文脈とは意味が合わない。"}, {"text": "基軸", "is_correct": false, "explanation": "基軸は中心となる考え方を指し、設計の対象としての意味が成り立たない。"}, {"text": "基調", "is_correct": false, "explanation": "基調は全体の基本的な傾向や色合いを指し、設計して作る物としては意味が合わない。"}], "explanations": {"基板": "回路の板を自分で設計してラジオを作る文なので、「基板を設計して」に合う。", "基準": "基準は評価や判断の目安を指し、ラジオの回路板を設計する文脈とは意味が合わない。", "基軸": "基軸は中心となる考え方を指し、設計の対象としての意味が成り立たない。", "基調": "基調は全体の基本的な傾向や色合いを指し、設計して作る物としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "基板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校舎の入り口の基板に、試験の日程を貼った。", "explanation": "ここは〈掲示板〉の意味。基板は電子部品を載せる板で、日程を貼る場所には使わない。"}, {"text": "旅行のとき、基板を広げて道を確かめた。", "explanation": "ここは〈地図〉の意味。基板は電子回路の板で、道を確かめるために広げる紙には使わない。"}, {"text": "カーテンを開けるように、基板を開けて部屋に光を入れた。", "explanation": "ここは〈ブラインド〉の意味。基板は電子回路の板で、光を入れるために開ける仕切りには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この基板を壊れたので、ラジオの音が消えた。", "corrected_sentence": "この基板が壊れたので、ラジオの音が消えた。", "error_description": "誤りは「基板を」の「を」。壊れるは自動詞なので、主語には「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39721, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電子工作で、私は初めて基板が組み立てた。", "corrected_sentence": "電子工作で、私は初めて基板を組み立てた。", "error_description": "誤りは「基板が」の「が」。組み立てるは他動詞なので、目的語には「を」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「する」の対象を示す格助詞で、プログラミングを行う意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「すると」の主語として文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここでは行為の対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する格で、ここでは文の成分として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「する」の対象を示す格助詞で、プログラミングを行う意味になる。", "が": "「が」は主語を示すが、「すると」の主語として文が成り立たない。", "へ": "「へ」は方向を示すが、ここでは行為の対象を示せない。", "の": "「の」は名詞を修飾する格で、ここでは文の成分として成り立たない。"}, "error_tags": {"が": "主語の格", "へ": "方向の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「する」の対象を示す格助詞で、プログラミングを行う意味になる。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは行為の対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格で、行為の対象にはならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、ここでは対象を示す位置に合わない。"}], "correct_answer": "を", "explanations": {"を": "「する」の対象を示す格助詞で、プログラミングを行う意味になる。", "より": "「より」は比較を示すが、ここでは行為の対象を示せない。", "から": "起点を示す格で、行為の対象にはならない。", "で": "「で」は手段や場所を示すが、ここでは対象を示す位置に合わない。"}, "error_tags": {"より": "比較の格", "から": "起点の格", "で": "手段・場所の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コンピューターにやってほしいことを、言葉で教えること。", "primary_collocate": null, "pronunciation": "ぷろぐらみんぐ", "ipa": "pɯɾoɡɯɾamiŋɡɯ", "syllable_count": 7, "sentences": [{"text": "私はプログラミングを習って、自分でゲームを作りたい。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "私[わたし]はプログラミングを習[なら]って、自分[じぶん]でゲームを作[つく]りたい。", "sentence_source": "generated"}, {"text": "プログラミングをすると、コンピューターが言った通りに動く。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングをすると、コンピューターが言[い]った通[とお]りに動[うご]く。", "sentence_source": "generated"}, {"text": "弟は学校のプログラミングの時間が大好きだ。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "弟[おとうと]は学校[がっこう]のプログラミングの時間[じかん]が大好[だいす]きだ。", "sentence_source": "generated"}, {"text": "プログラミングでは、間違いが一つあるだけで、コンピューターは動かなくなる。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングでは、間違[まちが]いが一[ひと]つあるだけで、コンピューターは動[うご]かなくなる。", "sentence_source": "generated"}, {"text": "姉はプログラミングが上手で、アプリを作って友達に見せた。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "姉[あね]はプログラミングが上手[じょうず]で、アプリを作[つく]って友達[ともだち]に見[み]せた。", "sentence_source": "generated"}, {"text": "毎週土曜日に、図書館でプログラミングを教えてもらっている。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]土曜日[どようび]に、図書館[としょかん]でプログラミングを教[おし]えてもらっている。", "sentence_source": "generated"}, {"text": "プログラミングを始めたばかりなので、まだ簡単な画面しか作れない。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングを始[はじ]めたばかりなので、まだ簡単[かんたん]な画面[がめん]しか作[つく]れない。", "sentence_source": "generated"}, {"text": "父は仕事でプログラミングをして、会社のシステムを直している。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]でプログラミングをして、会社[かいしゃ]のシステムを直[なお]している。", "sentence_source": "generated"}, {"text": "子どもでもプログラミングを楽しめるように、絵のようなブロックを使う教材がある。", "target_word": "プログラミング", "complexity_tier": "T4", "furigana": "子[こ]どもでもプログラミングを楽[たの]しめるように、絵[え]のようなブロックを使[つか]う教材[きょうざい]がある。", "sentence_source": "generated"}, {"text": "プログラミングは、コンピューターに言葉でやってほしいことを教えることだ。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングは、コンピューターに言葉[ことば]でやってほしいことを教[おし]えることだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プログラミング", "label": "名詞の基本形"}], "register": "標準（やさしい話し言葉）", "sense_fingerprint": "コンピューターに言葉でやってほしいことを教えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プログラミング", "is_correct": true, "explanation": "習う対象となる技術の名称で、ゲームを作りたいという文脈に合う。"}, {"text": "ルーター", "is_correct": false, "explanation": "通信機器の名称で、習って身につける技術ではない。"}, {"text": "ドアノブ", "is_correct": false, "explanation": "扉の部品で、習う対象にはならない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓にかける布製品で、習う対象にはならない。"}], "explanations": {"プログラミング": "習う対象となる技術の名称で、ゲームを作りたいという文脈に合う。", "ルーター": "通信機器の名称で、習って身につける技術ではない。", "ドアノブ": "扉の部品で、習う対象にはならない。", "カーテン": "窓にかける布製品で、習う対象にはならない。"}, "sentence_index": 0, "correct_answer": "プログラミング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は、難しい計算の方法を生徒にプログラミングした。", "explanation": "ここは〈教える〉（人に伝える）の意味。プログラミングは人ではなくコンピューターへの命令に使うので、生徒には使えない。"}, {"text": "母は夕食に、新しいカレーをプログラミングした。", "explanation": "ここは〈料理〉の意味。プログラミングは調理の作業ではないので、料理の意味では使わない。"}, {"text": "父は壊れた椅子をプログラミングして直した。", "explanation": "ここは〈修理〉の意味。プログラミングは物を直す作業ではないので、修理の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プログラミング", "is_correct": true, "explanation": "始めたばかりの技術の名称で、簡単な画面しか作れないという文脈に合う。"}, {"text": "スピーカー", "is_correct": false, "explanation": "音を出す機器の名称で、始める対象の技術にはならない。"}, {"text": "バッテリー", "is_correct": false, "explanation": "電源装置の名称で、始める対象の技術にはならない。"}, {"text": "ディスプレイ", "is_correct": false, "explanation": "表示装置の名称で、始める対象の技術にはならない。"}], "explanations": {"プログラミング": "始めたばかりの技術の名称で、簡単な画面しか作れないという文脈に合う。", "スピーカー": "音を出す機器の名称で、始める対象の技術にはならない。", "バッテリー": "電源装置の名称で、始める対象の技術にはならない。", "ディスプレイ": "表示装置の名称で、始める対象の技術にはならない。"}, "sentence_index": 6, "correct_answer": "プログラミング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日の体重を、ノートにプログラミングしている。", "explanation": "ここは〈記録〉の意味。プログラミングは命令の記述であり、数値を書き留める意味では使えない。"}, {"text": "祖父は庭で野菜をプログラミングしている。", "explanation": "ここは〈栽培〉の意味。プログラミングは植物を育てる行為ではないので合わない。"}, {"text": "友達の結婚式を動画でプログラミングした。", "explanation": "ここは〈撮影〉の意味。プログラミングは映像を記録する行為ではないので、撮影の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は、プログラミングに毎日練習している。", "corrected_sentence": "妹は、プログラミングを毎日練習している。", "error_description": "「練習する」は練習の対象を「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39722, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は、クラスの子どもたちにプログラミングに教えてくれた。", "corrected_sentence": "先生は、クラスの子どもたちにプログラミングを教えてくれた。", "error_description": "「教える」は教える内容を「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「学ぶ」の対象（学ぶ内容）を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「学ぶ」の対象は方向ではないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「学ぶ」の主語は人で、プログラミングが学ぶ主体になると文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する格で、ここでは文の成分として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「学ぶ」の対象（学ぶ内容）を示す格助詞。", "へ": "「へ」は方向を示すが、「学ぶ」の対象は方向ではないので合わない。", "が": "「が」は主語を示すが、「学ぶ」の主語は人で、プログラミングが学ぶ主体になると文が成り立たない。", "の": "「の」は名詞を修飾する格で、ここでは文の成分として成り立たない。"}, "error_tags": {"へ": "方向の格", "が": "主語の格", "の": "連体修飾の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「必修になる」の主語を示す格助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「必修になる」は主語を必要とするので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、ここでは主語の位置に入らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す格で、主語の役割を果たせない。"}], "correct_answer": "が", "explanations": {"が": "「必修になる」の主語を示す格助詞。", "を": "「を」は目的語を示すが、「必修になる」は主語を必要とするので合わない。", "で": "「で」は手段や場所を示すが、ここでは主語の位置に入らない。", "から": "起点を示す格で、主語の役割を果たせない。"}, "error_tags": {"を": "目的語の格", "で": "手段の格", "から": "起点の格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コンピュータに特定の動作や処理を実行させるための命令や手順を記述すること。", "primary_collocate": null, "pronunciation": "ぷろぐらみんぐ", "ipa": "pɯɾoɡɯɾamiŋɡɯ", "syllable_count": 7, "sentences": [{"text": "しかる後に、プログラミングという「神経系」を構築し、抽象的論理と物理的挙動を厳密に同期させるのだ。", "target_word": "プログラミング", "complexity_tier": "T4", "furigana": "しかる後[のち]に、プログラミングという「神経系[しんけいけい]」を構築[こうちく]し、抽象的[ちゅうしょうてき]論理[ろんり]と物理的[ぶつりてき]挙動[きょどう]を厳密[げんみつ]に同期[どうき]させるのだ。", "sentence_source": "mined"}, {"text": "プログラミングを学ぶと、コンピュータに手順を正確に伝える力が身につく。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングを学[まな]ぶと、コンピュータに手順[てじゅん]を正確[せいかく]に伝[つた]える力[ちから]が身[み]につく。", "sentence_source": "generated"}, {"text": "彼女は大学で、ロボットを動かすためのプログラミングを研究している。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は大学[だいがく]で、ロボットを動[うご]かすためのプログラミングを研究[けんきゅう]している。", "sentence_source": "generated"}, {"text": "プログラミングでは、命令の順番を間違えると、思った通りに動かない。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングでは、命令[めいれい]の順番[じゅんばん]を間違[まちが]えると、思[おも]った通[とお]りに動[うご]かない。", "sentence_source": "generated"}, {"text": "兄は毎晩、ゲームを作るためにプログラミングをしている。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "兄[あに]は毎晩[まいばん]、ゲームを作[つく]るためにプログラミングをしている。", "sentence_source": "generated"}, {"text": "このアプリは、複雑なプログラミングのおかげで、とても速く動く。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "このアプリは、複雑[ふくざつ]なプログラミングのおかげで、とても速[はや]く動[うご]く。", "sentence_source": "generated"}, {"text": "プログラミングが得意な田中さんに、エラーの原因を調べてもらった。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "プログラミングが得意[とくい]な田中[たなか]さんに、エラーの原因[げんいん]を調[しら]べてもらった。", "sentence_source": "generated"}, {"text": "小学校でもプログラミングが必修になり、先生たちは新しい授業の準備に追われている。", "target_word": "プログラミング", "complexity_tier": "T4", "furigana": "小学校[しょうがっこう]でもプログラミングが必修[ひっしゅう]になり、先生[せんせい]たちは新[あたら]しい授業[じゅぎょう]の準備[じゅんび]に追[お]われている。", "sentence_source": "generated"}, {"text": "初心者は、まず簡単なプログラミングから始めるのがよい。", "target_word": "プログラミング", "complexity_tier": "T3", "furigana": "初心者[しょしんしゃ]は、まず簡単[かんたん]なプログラミングから始[はじ]めるのがよい。", "sentence_source": "generated"}, {"text": "工場の機械は、精密なプログラミングによって、一日中同じ作業をくり返す。", "target_word": "プログラミング", "complexity_tier": "T4", "furigana": "工場[こうじょう]の機械[きかい]は、精密[せいみつ]なプログラミングによって、一日中[いちにちじゅう]同[おな]じ作業[さぎょう]をくり返[かえ]す。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プログラミング", "label": "名詞の基本形"}], "register": "標準（書き言葉）", "sense_fingerprint": "コンピュータへの命令や手順を記述する作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edb8103a-cdfa-4994-b1e8-bcd75eb2303e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "プログラミング", "is_correct": true, "explanation": "命令や手順を記述する作業を指し、論理と挙動を同期させる構築の文脈に合う。"}, {"text": "ウイルス", "is_correct": false, "explanation": "悪意あるプログラムの名称で、神経系を構築する主体として意味が通らない。"}, {"text": "ディスプレイ", "is_correct": false, "explanation": "表示装置の名称で、「という神経系」を構築する対象にはならない。"}, {"text": "バッテリー", "is_correct": false, "explanation": "電源装置の名称で、抽象的論理を物理的挙動と同期させる文脈に合わない。"}], "explanations": {"プログラミング": "命令や手順を記述する作業を指し、論理と挙動を同期させる構築の文脈に合う。", "ウイルス": "悪意あるプログラムの名称で、神経系を構築する主体として意味が通らない。", "ディスプレイ": "表示装置の名称で、「という神経系」を構築する対象にはならない。", "バッテリー": "電源装置の名称で、抽象的論理を物理的挙動と同期させる文脈に合わない。"}, "sentence_index": 0, "correct_answer": "プログラミング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "式のプログラミングは、午後三時から始まる。", "explanation": "ここは〈プログラム〉（催しの進行表）の意味。プログラミングは命令を書く作業なので、式の進行表の意味では使えない。"}, {"text": "弟は画用紙の絵を、色鉛筆でプログラミングした。", "explanation": "ここは〈描画〉の意味。プログラミングは命令を書く作業で、絵を描く意味にはならない。"}, {"text": "来年の旅行のプログラミングを立てるのに、一週間かかった。", "explanation": "ここは〈計画〉の意味。プログラミングは命令を記述する作業で、旅行の予定を立てる意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "プログラミング", "is_correct": true, "explanation": "得意な技能の名称で、エラーの原因を調べてもらう文脈に合う。"}, {"text": "スピーカー", "is_correct": false, "explanation": "音を出す機器の名称で、得意な技能としては意味が通らない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓にかける布製品で、得意な技能にはならない。"}, {"text": "ドアノブ", "is_correct": false, "explanation": "扉の部品で、得意な技能としては意味が通らない。"}], "explanations": {"プログラミング": "得意な技能の名称で、エラーの原因を調べてもらう文脈に合う。", "スピーカー": "音を出す機器の名称で、得意な技能としては意味が通らない。", "カーテン": "窓にかける布製品で、得意な技能にはならない。", "ドアノブ": "扉の部品で、得意な技能としては意味が通らない。"}, "sentence_index": 6, "correct_answer": "プログラミング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この小説のプログラミングは、原文の雰囲気をよく伝えている。", "explanation": "ここは〈翻訳〉の意味。プログラミングは命令の記述で、文章を別の言語に移す意味にはならない。"}, {"text": "会議のプログラミングは、英語を日本語に正確に訳した。", "explanation": "ここは〈通訳〉の意味。プログラミングは機械への命令を書く作業で、言葉を訳す行為ではない。"}, {"text": "先生は答案を丁寧にプログラミングして、点数をつけた。", "explanation": "ここは〈採点〉の意味。プログラミングは答案を評価する行為ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟はプログラミングに習っている。", "corrected_sentence": "弟はプログラミングを習っている。", "error_description": "「習う」は学ぶ内容を「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39723, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は私にプログラミングに教えてくれた。", "corrected_sentence": "兄は私にプログラミングを教えてくれた。", "error_description": "「教える」は教える内容を「を」で示す。「に」が誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c30641-0cbb-4a67-b0b3-935e995156fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ペンで描いた」で、描く道具を示す「で」が描いたの直前に入る。"}, {"text": "を", "is_correct": false, "explanation": "「ペンを描いた」は道具を目的語にする形になり、文の意味が合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ペンに描いた」では道具を示せず、描くための手段を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は道具を示さず、「ペンへ描いた」は文として成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「ペンで描いた」で、描く道具を示す「で」が描いたの直前に入る。", "を": "「ペンを描いた」は道具を目的語にする形になり、文の意味が合わない。", "に": "「ペンに描いた」では道具を示せず、描くための手段を表せない。", "へ": "方向を表す「へ」は道具を示さず、「ペンへ描いた」は文として成り立たない。"}, "error_tags": {"を": "目的語の格", "に": "相手・場所の格", "へ": "方向の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「描いてから、角度を測った」で、描いた後に次の動作をする順序を示す「から」が入る。"}, {"text": "が", "is_correct": false, "explanation": "「描いてが」は主語を示す形にならず、動作の順序を表せない。"}, {"text": "と", "is_correct": false, "explanation": "並列や相手を示す「と」は、描いての後に続けると順序の意味が合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞につながるため、描いての後に続けると文が成り立たない。"}], "correct_answer": "から", "explanations": {"から": "「描いてから、角度を測った」で、描いた後に次の動作をする順序を示す「から」が入る。", "が": "「描いてが」は主語を示す形にならず、動作の順序を表せない。", "と": "並列や相手を示す「と」は、描いての後に続けると順序の意味が合わない。", "の": "連体修飾の「の」は名詞につながるため、描いての後に続けると文が成り立たない。"}, "error_tags": {"が": "主語の格", "と": "並列・相手の格", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "えんぴつやペンで、紙に絵や形をかくこと。", "primary_collocate": null, "pronunciation": "えがく", "ipa": "eɡaku", "syllable_count": 3, "sentences": [{"text": "妹は紙にねこの絵を描くのが好きだ。", "target_word": "描く", "complexity_tier": "T3", "furigana": "妹[いもうと]は紙[かみ]にねこの絵[え]を描[えが]くのが好[す]きだ。", "sentence_source": "generated"}, {"text": "先生は紙に大きな丸をペンで描いた。", "target_word": "描いた", "complexity_tier": "T3", "furigana": "先[せん]生[せい]は紙[かみ]に大[おお]きな丸[まる]をペンで描[えが]いた。", "sentence_source": "generated"}, {"text": "雨の日は、家でえんぴつで花を描いて過ごす。", "target_word": "描いて", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、家[いえ]でえんぴつで花[はな]を描[えが]いて過[す]ごす。", "sentence_source": "generated"}, {"text": "ペンで地図を描いて、道を教えてくれた。", "target_word": "描いて", "complexity_tier": "T3", "furigana": "ペンで地図[ちず]を描[えが]いて、道[みち]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "弟は机でノートに車を描いている。", "target_word": "描いて", "complexity_tier": "T3", "furigana": "弟[おとうと]は机[つくえ]でノートに車[くるま]を描[えが]いている。", "sentence_source": "generated"}, {"text": "定規を使わずに、きれいな直線を描くのは難しい。", "target_word": "描く", "complexity_tier": "T3", "furigana": "定規[じょうぎ]を使[つか]わずに、きれいな直線[ちょくせん]を描[えが]くのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "私は毎朝、ノートに小さな絵を描いている。", "target_word": "描いて", "complexity_tier": "T3", "furigana": "私[わたし]は毎朝[まいあさ]、ノートに小[ちい]さな絵[え]を描[えが]いている。", "sentence_source": "generated"}, {"text": "彼は三角形を描いてから、角度を測った。", "target_word": "描いて", "complexity_tier": "T3", "furigana": "彼[かれ]は三角形[さんかっけい]を描[えが]いてから、角度[かくど]を測[はか]った。", "sentence_source": "generated"}, {"text": "絵の具がないので、ペンだけで山を描くことにした。", "target_word": "描く", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]がないので、ペンだけで山[やま]を描[えが]くことにした。", "sentence_source": "generated"}, {"text": "紙に円を描くとき、コンパスがあると便利だ。", "target_word": "描く", "complexity_tier": "T3", "furigana": "紙[かみ]に円[えん]を描[えが]くとき、コンパスがあると便利[べんり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "描く", "label": "dictionary form"}, {"form": "描いて", "label": "te-form"}, {"form": "描いた", "label": "past"}, {"form": "描かない", "label": "negative"}, {"form": "描きます", "label": "polite"}, {"form": "描ける", "label": "potential"}], "register": "neutral", "sense_fingerprint": "えんぴつやペンで紙に絵や図形を実際にかく(えがく)。夢や未来を思い浮かべる意味ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描く", "is_correct": true, "explanation": "「妹は紙にねこの絵を描くのが好きだ」で、絵をかく行為を表す「描く」が入る。"}, {"text": "刻む", "is_correct": false, "explanation": "刻むは固い物に彫って形を作る意味で、紙に絵をかく文脈とは合わない。"}, {"text": "割る", "is_correct": false, "explanation": "割るは物を分けて壊す意味で、絵をかくことの好みという文とは意味が合わない。"}, {"text": "溶かす", "is_correct": false, "explanation": "溶かすは固体を液体にする意味で、紙の絵を対象にする文脈には合わない。"}], "explanations": {"描く": "「妹は紙にねこの絵を描くのが好きだ」で、絵をかく行為を表す「描く」が入る。", "刻む": "刻むは固い物に彫って形を作る意味で、紙に絵をかく文脈とは合わない。", "割る": "割るは物を分けて壊す意味で、絵をかくことの好みという文とは意味が合わない。", "溶かす": "溶かすは固体を液体にする意味で、紙の絵を対象にする文脈には合わない。"}, "sentence_index": 0, "correct_answer": "描く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ノートに手紙を描いて、友達に送った。", "explanation": "ここは〈書く〉の意味。描くは絵や図形をかくことで、手紙の文字を書く場面には使わない。"}, {"text": "旅行先で景色の写真を描いて、家族に見せた。", "explanation": "ここは〈撮る〉の意味。描くは手でかく行為なので、カメラで写真を撮る場面には使わない。"}, {"text": "授業のすべてを描いて、後で聞けるようにした。", "explanation": "ここは〈録音する〉の意味。描くは絵や図形をかく動作で、音声を残す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描いて", "is_correct": true, "explanation": "「絵を描いている」で、描く動作を続けている形として「描いて」が入る。"}, {"text": "破って", "is_correct": false, "explanation": "破るは紙を裂く動作で、絵を描いているという文と意味が合わない。"}, {"text": "煮て", "is_correct": false, "explanation": "煮るは食べ物を加熱する意味で、ノートの絵の文脈には合わない。"}, {"text": "砕いて", "is_correct": false, "explanation": "砕くは固い物を細かくする意味で、ノートに小さな絵を描く文と合わない。"}], "explanations": {"描いて": "「絵を描いている」で、描く動作を続けている形として「描いて」が入る。", "破って": "破るは紙を裂く動作で、絵を描いているという文と意味が合わない。", "煮て": "煮るは食べ物を加熱する意味で、ノートの絵の文脈には合わない。", "砕いて": "砕くは固い物を細かくする意味で、ノートに小さな絵を描く文と合わない。"}, "sentence_index": 6, "correct_answer": "描いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事の前に、道路の長さを描いて確かめた。", "explanation": "ここは〈測る〉の意味。描くはかく動作で、長さを数値として確かめる場面には使わない。"}, {"text": "バスの中で、乗客の人数を描いた。", "explanation": "ここは〈数える〉の意味。描くは絵や図形をかく動作で、人数を数える場面には使わない。"}, {"text": "朝ごはんに、食パンを描いて出した。", "explanation": "ここは〈焼く〉の意味。描くは絵や図形をかく動作で、食パンを焼く場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟はノートに車に描いている。", "corrected_sentence": "弟はノートに車を描いている。", "error_description": "誤りは「車に」の「に」。描くの目的語は「を」で、「車を描く」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "描いた", "is_correct": true, "explanation": "「先生は紙に大きな丸をペンで描いた」で、過去の出来事を述べる形として合う。"}, {"text": "描いて", "is_correct": false, "explanation": "て形は文の最後の述語として終わらず、「〜た」で言い切る文の形と合わない。"}, {"text": "描かない", "is_correct": false, "explanation": "否定形は「描かない」となり、丸を描いたという事実と反対の意味になる。"}, {"text": "描ける", "is_correct": false, "explanation": "可能形は「描くことができる」の意味になり、実際に描いたという文と合わない。"}], "correct_form": "描いた", "base_form": "描く", "form_label": "過去形", "sentence_index": 1, "explanations": {"描いた": "「先生は紙に大きな丸をペンで描いた」で、過去の出来事を述べる形として合う。", "描いて": "て形は文の最後の述語として終わらず、「〜た」で言い切る文の形と合わない。", "描かない": "否定形は「描かない」となり、丸を描いたという事実と反対の意味になる。", "描ける": "可能形は「描くことができる」の意味になり、実際に描いたという文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は円を描いたて、コンパスを使った。", "corrected_sentence": "先生は円を描いて、コンパスを使った。", "error_description": "誤りは「描いたて」の「た」。て形は「描いて」で、過去の「た」を重ねると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "描いて", "is_correct": true, "explanation": "「三角形を描いてから、角度を測った」で、動作を続けて次の動作につなぐ て形が入る。"}, {"text": "描きます", "is_correct": false, "explanation": "丁寧形は文の途中の「描いてから」には続かず、この文の形と合わない。"}, {"text": "描いた", "is_correct": false, "explanation": "過去形は「描いたから」となり、続く動作の関係が合わない。"}, {"text": "描く", "is_correct": false, "explanation": "基本形は「描くから」となり、描き終えた後に測るという順序と合わない。"}], "correct_form": "描いて", "base_form": "描く", "form_label": "て形", "sentence_index": 7, "explanations": {"描いて": "「三角形を描いてから、角度を測った」で、動作を続けて次の動作につなぐ て形が入る。", "描きます": "丁寧形は文の途中の「描いてから」には続かず、この文の形と合わない。", "描いた": "過去形は「描いたから」となり、続く動作の関係が合わない。", "描く": "基本形は「描くから」となり、描き終えた後に測るという順序と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「色を揃える」の目的語を示す「を」で、「揃えた」に直接かかる。"}, {"text": "が", "is_correct": false, "explanation": "揃えるは他動詞で、目的語は「を」で示す。「色が揃えた」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「色の揃えた」では名詞の修飾にならず、文の構造が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では「色へ揃えた」となり、目的語の関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "「色を揃える」の目的語を示す「を」で、「揃えた」に直接かかる。", "が": "揃えるは他動詞で、目的語は「を」で示す。「色が揃えた」は成り立たない。", "の": "「色の揃えた」では名詞の修飾にならず、文の構造が成り立たない。", "へ": "方向を示す「へ」では「色へ揃えた」となり、目的語の関係が合わない。"}, "error_tags": {"が": "主語と目的語の取り違え", "の": "連体修飾の誤用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「大きさ順に」の「に」で、並べる基準を示し、「揃えて」にかかる。"}, {"text": "から", "is_correct": false, "explanation": "「大きさ順から」は起点を示すため、並べる基準を表す文脈と合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すため、基準を示す「に」の代わりにはならず、意味が合わない。"}, {"text": "が", "is_correct": false, "explanation": "揃えるは他動詞なので「大きさ順が」は主語にできず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「大きさ順に」の「に」で、並べる基準を示し、「揃えて」にかかる。", "から": "「大きさ順から」は起点を示すため、並べる基準を表す文脈と合わない。", "より": "「より」は比較を表すため、基準を示す「に」の代わりにはならず、意味が合わない。", "が": "揃えるは他動詞なので「大きさ順が」は主語にできず、文が成り立たない。"}, "error_tags": {"から": "起点の格", "より": "比較", "が": "主語と目的語の取り違え"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "長さ・色・向きなどを同じにして、ばらばらでない状態にする。", "primary_collocate": null, "pronunciation": "そろえる", "ipa": "soɾoeɾɯ", "syllable_count": 4, "sentences": [{"text": "玄関では、靴の向きを揃えて脱ぐのがマナーだ。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "玄関[げんかん]では、靴[くつ]の向[む]きを揃[そろ]えて脱[ぬ]ぐのがマナーだ。", "sentence_source": "generated"}, {"text": "全員の服の色を揃えたので、写真がきれいに見える。", "target_word": "揃えた", "complexity_tier": "T3", "furigana": "全員[ぜんいん]の服[ふく]の色[いろ]を揃[そろ]えたので、写真[しゃしん]がきれいに見[み]える。", "sentence_source": "generated"}, {"text": "紙の端を揃えてから、ホッチキスで留めた。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "紙[かみ]の端[はし]を揃[そろ]えてから、ホッチキスで留[と]めた。", "sentence_source": "generated"}, {"text": "美容師は毛先の長さを揃えて、髪を整えた。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "美容師[びようし]は毛先[けさき]の長[なが]さを揃[そろ]えて、髪[かみ]を整[ととの]えた。", "sentence_source": "generated"}, {"text": "合唱では、みんなで声を揃えて歌うことが大切だ。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "合唱[がっしょう]では、みんなで声[こえ]を揃[そろ]えて歌[うた]うことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "机の高さを揃えると、教室が整って見える。", "target_word": "揃える", "complexity_tier": "T3", "furigana": "机[つくえ]の高[たか]さを揃[そろ]えると、教室[きょうしつ]が整[ととの]って見[み]える。", "sentence_source": "generated"}, {"text": "資料の書き方を揃えないと、読みにくい。", "target_word": "揃えない", "complexity_tier": "T3", "furigana": "資料[しりょう]の書[か]き方[かた]を揃[そろ]えないと、読[よ]みにくい。", "sentence_source": "generated"}, {"text": "本棚の本を大きさ順に揃えて並べた。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "本棚[ほんだな]の本[ほん]を大[おお]きさ順[じゅん]に揃[そろ]えて並[なら]べた。", "sentence_source": "generated"}, {"text": "試合で目立つように、チームでユニフォームの色を揃える。", "target_word": "揃える", "complexity_tier": "T3", "furigana": "試合[しあい]で目立[めだ]つように、チームでユニフォームの色[いろ]を揃[そろ]える。", "sentence_source": "generated"}, {"text": "文字の大きさを揃えれば、ポスターが見やすくなる。", "target_word": "揃えれば", "complexity_tier": "T3", "furigana": "文字[もじ]の大[おお]きさを揃[そろ]えれば、ポスターが見[み]やすくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "揃える", "label": "dictionary form"}, {"form": "揃えて", "label": "te-form"}, {"form": "揃えた", "label": "past"}, {"form": "揃えない", "label": "negative"}, {"form": "揃えれば", "label": "conditional"}, {"form": "揃えられる", "label": "potential"}], "register": "neutral", "sense_fingerprint": "長さ・色・向き・声などを同じにして、ばらばらでない状態にする(そろえる)。必要な物を用意する意味ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揃えて", "is_correct": true, "explanation": "て形で、後ろの「脱ぐ」に続いて「揃えて脱ぐ」となり、文として成立する。"}, {"text": "揃える", "is_correct": false, "explanation": "辞書形のままでは「脱ぐ」に続かず、「靴の向きを揃える脱ぐ」は文にならない。"}, {"text": "揃えない", "is_correct": false, "explanation": "否定形では「脱ぐ」と続かず、「向きを揃えない脱ぐ」は文法的に成立しない。"}, {"text": "揃えた", "is_correct": false, "explanation": "過去形では「脱ぐ」に接続できず、「揃えた脱ぐ」は文にならない。"}], "explanations": {"揃えて": "て形で、後ろの「脱ぐ」に続いて「揃えて脱ぐ」となり、文として成立する。", "揃える": "辞書形のままでは「脱ぐ」に続かず、「靴の向きを揃える脱ぐ」は文にならない。", "揃えない": "否定形では「脱ぐ」と続かず、「向きを揃えない脱ぐ」は文法的に成立しない。", "揃えた": "過去形では「脱ぐ」に接続できず、「揃えた脱ぐ」は文にならない。"}, "sentence_index": 0, "correct_answer": "揃えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急いで出かける前に、寝ぐせを揃えた。", "explanation": "ここは〈整える〉の意味。〈揃える〉は長さや向きを同じにする意味で、乱れを直す意味では使わない。"}, {"text": "散らかった部屋を揃えた。", "explanation": "ここは〈片付ける〉の意味。〈揃える〉は形や色を同じにすることで、散らかったものを元に戻す意味はない。"}, {"text": "お風呂のお湯を揃えた。", "explanation": "ここは〈張る〉の意味。〈揃える〉は同じ状態にそろえる意味で、水を入れる意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揃えない", "is_correct": true, "explanation": "否定形の「ないと」で条件を表し、「読みにくい」に続いて文が成立する。"}, {"text": "揃え", "is_correct": false, "explanation": "連用形で止まり、「ないと」の条件の文として続かない。"}, {"text": "揃えて", "is_correct": false, "explanation": "て形では「ないと」に続かず、文が成立しない。"}, {"text": "揃えろ", "is_correct": false, "explanation": "命令形では「ないと」の条件の文にならず、意味も合わない。"}], "explanations": {"揃えない": "否定形の「ないと」で条件を表し、「読みにくい」に続いて文が成立する。", "揃え": "連用形で止まり、「ないと」の条件の文として続かない。", "揃えて": "て形では「ないと」に続かず、文が成立しない。", "揃えろ": "命令形では「ないと」の条件の文にならず、意味も合わない。"}, "sentence_index": 6, "correct_answer": "揃えない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床にこぼした牛乳を揃えた。", "explanation": "ここは〈拭き取る〉の意味。〈揃える〉は形や向きをそろえる意味で、汚れを取る意味はない。"}, {"text": "なくした鍵を揃えた。", "explanation": "ここは〈探す〉の意味。〈揃える〉は形や色をそろえる意味で、見つけ出す意味はない。"}, {"text": "ついに夢を揃えた。", "explanation": "ここは〈あきらめる〉の意味。〈揃える〉は同じにすることで、望みを手放す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "紙の端が揃えてから、袋に入れる。", "corrected_sentence": "紙の端を揃えてから、袋に入れる。", "error_description": "「揃える」は他動詞なので目的語に「を」を付ける。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "揃えた", "is_correct": true, "explanation": "「ので」の前にある、完了した出来事を表す過去形で、この文の形として正しい。"}, {"text": "揃えて", "is_correct": false, "explanation": "て形は「ので」に直接続かず、完了した出来事を示せない。"}, {"text": "揃えろ", "is_correct": false, "explanation": "命令形は「ので」に続かず、文として成り立たない。"}, {"text": "揃えれば", "is_correct": false, "explanation": "仮定形は「ので」（原因・理由）の文と合わず、条件の意味になってしまう。"}], "correct_form": "揃えた", "base_form": "揃える", "form_label": "過去形", "sentence_index": 1, "explanations": {"揃えた": "「ので」の前にある、完了した出来事を表す過去形で、この文の形として正しい。", "揃えて": "て形は「ので」に直接続かず、完了した出来事を示せない。", "揃えろ": "命令形は「ので」に続かず、文として成り立たない。", "揃えれば": "仮定形は「ので」（原因・理由）の文と合わず、条件の意味になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39726, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "資料の書き方が揃えると、読みやすくなる。", "corrected_sentence": "資料の書き方を揃えると、読みやすくなる。", "error_description": "「揃える」は他動詞なので目的語に「を」を付ける。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "揃えて", "is_correct": true, "explanation": "て形で、後ろの「並べた」に続いて「揃えて並べた」となり、文の形として正しい。"}, {"text": "揃える", "is_correct": false, "explanation": "辞書形では「並べた」に直接続かず、「揃える並べた」となって文の形が合わない。"}, {"text": "揃えられる", "is_correct": false, "explanation": "可能形は「揃えることができる」の意味になり、実際に並べた完了の動作を表す文と合わない。"}, {"text": "揃えろ", "is_correct": false, "explanation": "命令形では「揃えろ並べた」となり、過去の出来事を述べる文の形と合わない。"}], "correct_form": "揃えて", "base_form": "揃える", "form_label": "て形", "sentence_index": 7, "explanations": {"揃えて": "て形で、後ろの「並べた」に続いて「揃えて並べた」となり、文の形として正しい。", "揃える": "辞書形では「並べた」に直接続かず、「揃える並べた」となって文の形が合わない。", "揃えられる": "可能形は「揃えることができる」の意味になり、実際に並べた完了の動作を表す文と合わない。", "揃えろ": "命令形では「揃えろ並べた」となり、過去の出来事を述べる文の形と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
