INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39727, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「書類を揃える」の目的語を示す「を」で、「揃えなければ」の対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「書類に揃えなければ」では目的語の関係が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "揃えるは他動詞で主語に「が」は使えず、「書類が揃えなければ」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「書類と揃えなければ」では共同の相手を示すことになり、目的語の関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "「書類を揃える」の目的語を示す「を」で、「揃えなければ」の対象を表す。", "に": "「書類に揃えなければ」では目的語の関係が成り立たない。", "が": "揃えるは他動詞で主語に「が」は使えず、「書類が揃えなければ」は不自然。", "と": "「書類と揃えなければ」では共同の相手を示すことになり、目的語の関係が合わない。"}, "error_tags": {"に": "相手・位置", "が": "主語と目的語の取り違え", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39727, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "必要なものをすべて準備すること。", "primary_collocate": null, "pronunciation": "そろえる", "ipa": "soɾoeɾɯ", "syllable_count": 4, "sentences": [{"text": "引っ越しの前に、新しい生活に必要な家具を揃えた。", "target_word": "揃えた", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの前[まえ]に、新[あたら]しい生活[せいかつ]に必要[ひつよう]な家具[かぐ]を揃[そろ]えた。", "sentence_source": "generated"}, {"text": "料理を始める前に、材料をすべて揃えておく。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "料理[りょうり]を始[はじ]める前[まえ]に、材料[ざいりょう]をすべて揃[そろ]えておく。", "sentence_source": "generated"}, {"text": "登山には、まず安全な道具を揃えることが大切だ。", "target_word": "揃える", "complexity_tier": "T3", "furigana": "登山[とざん]には、まず安全[あんぜん]な道具[どうぐ]を揃[そろ]えることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "入学の手続きのために、必要な書類を揃えて提出した。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "入学[にゅうがく]の手続[てつづ]きのために、必要[ひつよう]な書類[しょるい]を揃[そろ]えて提出[ていしゅつ]した。", "sentence_source": "generated"}, {"text": "新しい店を開くために、品物を揃えている。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]を開[ひら]くために、品物[しなもの]を揃[そろ]えている。", "sentence_source": "generated"}, {"text": "運動会の前日に、お弁当の食材を揃えた。", "target_word": "揃えた", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の前日[ぜんじつ]に、お弁当[べんとう]の食材[しょくざい]を揃[そろ]えた。", "sentence_source": "generated"}, {"text": "勉強を始める前に、ノートやペンなどを揃える。", "target_word": "揃える", "complexity_tier": "T3", "furigana": "勉強[べんきょう]を始[はじ]める前[まえ]に、ノートやペンなどを揃[そろ]える。", "sentence_source": "generated"}, {"text": "留学するには、お金と書類を揃えなければならない。", "target_word": "揃えなければ", "complexity_tier": "T3", "furigana": "留学[りゅうがく]するには、お金[かね]と書類[しょるい]を揃[そろ]えなければならない。", "sentence_source": "generated"}, {"text": "文化祭で使う道具を、クラスのみんなで揃えた。", "target_word": "揃えた", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]で使[つか]う道具[どうぐ]を、クラスのみんなで揃[そろ]えた。", "sentence_source": "generated"}, {"text": "工事を始める前に、必要な機械を揃えておいた。", "target_word": "揃えて", "complexity_tier": "T3", "furigana": "工事[こうじ]を始[はじ]める前[まえ]に、必要[ひつよう]な機械[きかい]を揃[そろ]えておいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "揃える", "label": "dictionary form"}, {"form": "揃えて", "label": "te-form"}, {"form": "揃えた", "label": "past"}, {"form": "揃えない", "label": "negative"}, {"form": "揃えなければ", "label": "obligation stem"}, {"form": "揃えられる", "label": "potential"}], "register": "neutral", "sense_fingerprint": "何かをするために必要な道具・材料・書類などを、足りないものがないようにすべて用意する(そろえる)。形や色を同じにする意味ではない。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39727, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "揃えた", "is_correct": true, "explanation": "過去形で、文末に置くと一つの文として完結する。「準備した」という完了の意味に合う。"}, {"text": "揃えて", "is_correct": false, "explanation": "て形で、文末に置くと文が終わらず、完結しない。"}, {"text": "揃え", "is_correct": false, "explanation": "連用形で止まり、文として完結しない。"}, {"text": "揃えたら", "is_correct": false, "explanation": "条件形で、続きの述語がないと文が終わらない。"}], "explanations": {"揃えた": "過去形で、文末に置くと一つの文として完結する。「準備した」という完了の意味に合う。", "揃えて": "て形で、文末に置くと文が終わらず、完結しない。", "揃え": "連用形で止まり、文として完結しない。", "揃えたら": "条件形で、続きの述語がないと文が終わらない。"}, "sentence_index": 0, "correct_answer": "揃えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ベッドのシーツの角を揃えた。", "explanation": "ここは〈整える〉の意味。〈揃える〉のこの義項は必要なものを用意する意味で、角の位置をそろえる意味ではない。"}, {"text": "古い服の袖を揃えた。", "explanation": "ここは〈長さを同じにする〉の意味。この義項は必要なものを用意することで、袖の長さを直す意味ではない。"}, {"text": "前髪を揃えた。", "explanation": "ここは〈切りそろえる〉の意味。この義項は必要なものを用意することで、髪の長さをそろえる意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39727, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揃える", "is_correct": true, "explanation": "辞書形で文末に置け、「勉強を始める前に」の後に続く文として完結する。"}, {"text": "揃えながら", "is_correct": false, "explanation": "「ながら」形で同時の動作を表し、文末に置くと文が完結しない。"}, {"text": "揃えるので", "is_correct": false, "explanation": "理由を表す接続形で、後ろの文がないと文が完結しない。"}, {"text": "揃えても", "is_correct": false, "explanation": "逆接の接続形で、続きの文がないと文が完結しない。"}], "explanations": {"揃える": "辞書形で文末に置け、「勉強を始める前に」の後に続く文として完結する。", "揃えながら": "「ながら」形で同時の動作を表し、文末に置くと文が完結しない。", "揃えるので": "理由を表す接続形で、後ろの文がないと文が完結しない。", "揃えても": "逆接の接続形で、続きの文がないと文が完結しない。"}, "sentence_index": 6, "correct_answer": "揃える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ワイシャツの襟を揃えた。", "explanation": "ここは〈整える〉の意味。この義項は必要なものを用意する意味ではなく、形をそろえる意味で使う。"}, {"text": "卵の大きさを揃えた。", "explanation": "ここは〈大きさを同じにする〉の意味。この義項は用意する意味で、大きさをそろえる意味ではない。"}, {"text": "テーブルの脚の長さを揃えた。", "explanation": "ここは〈長さを同じにする〉の意味。この義項は必要なものを用意する意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39727, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行の前に、着替えが揃えておく。", "corrected_sentence": "旅行の前に、着替えを揃えておく。", "error_description": "「揃える」は他動詞なので目的語に「を」を付ける。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "揃えて", "is_correct": true, "explanation": "て形で、後ろの「おく」に続いて「揃えておく」となり、事前の準備を表す。"}, {"text": "揃えた", "is_correct": false, "explanation": "過去形では「おく」に続けにくく、事前に準備しておく意味と合わない。"}, {"text": "揃えない", "is_correct": false, "explanation": "否定形では「おく」に続いても、材料をすべて準備するという意味にならない。"}, {"text": "揃える", "is_correct": false, "explanation": "辞書形では「おく」に直接続かず、「揃えるおく」は不自然。"}], "correct_form": "揃えて", "base_form": "揃える", "form_label": "て形", "sentence_index": 1, "explanations": {"揃えて": "て形で、後ろの「おく」に続いて「揃えておく」となり、事前の準備を表す。", "揃えた": "過去形では「おく」に続けにくく、事前に準備しておく意味と合わない。", "揃えない": "否定形では「おく」に続いても、材料をすべて準備するという意味にならない。", "揃える": "辞書形では「おく」に直接続かず、「揃えるおく」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39727, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出発の前に、荷物が揃えておく。", "corrected_sentence": "出発の前に、荷物を揃えておく。", "error_description": "「揃える」は他動詞なので目的語に「を」を付ける。「が」は誤りで、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "揃えなければ", "is_correct": true, "explanation": "「なければならない」の条件形で、必要性を表す形として正しい。"}, {"text": "揃えられる", "is_correct": false, "explanation": "可能形では必要性ではなく可能の意味になり、文の意味が合わない。"}, {"text": "揃えよう", "is_correct": false, "explanation": "意志形では「ならない」に続けられず、必要性を表す形として合わない。"}, {"text": "揃えろ", "is_correct": false, "explanation": "命令形では「ならない」に続けられず、文の意味が成り立たない。"}], "correct_form": "揃えなければ", "base_form": "揃える", "form_label": "なければ形", "sentence_index": 7, "explanations": {"揃えなければ": "「なければならない」の条件形で、必要性を表す形として正しい。", "揃えられる": "可能形では必要性ではなく可能の意味になり、文の意味が合わない。", "揃えよう": "意志形では「ならない」に続けられず、必要性を表す形として合わない。", "揃えろ": "命令形では「ならない」に続けられず、文の意味が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39728, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「キットの箱」は「キットに入っていた箱」の意味で、連体修飾の「の」が自然。"}, {"text": "が", "is_correct": false, "explanation": "「キットが箱を開けると」は、キットが箱を開ける主語になり意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「キットを箱を開けると」は目的語が二つ並んで文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「キットに箱を開けると」は、「に」が箱を開ける動作と結びつかず不自然。"}], "correct_answer": "の", "explanations": {"の": "「キットの箱」は「キットに入っていた箱」の意味で、連体修飾の「の」が自然。", "が": "「キットが箱を開けると」は、キットが箱を開ける主語になり意味が通らない。", "を": "「キットを箱を開けると」は目的語が二つ並んで文が成り立たない。", "に": "「キットに箱を開けると」は、「に」が箱を開ける動作と結びつかず不自然。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
