INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39728, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "くみたてる ための ぶひんの セット。", "primary_collocate": null, "pronunciation": "きっと", "ipa": "kitːo", "syllable_count": 3, "sentences": [{"text": "兄は電車の模型のキットを組み立てています。", "target_word": "キット", "complexity_tier": "T3", "furigana": "兄[あに]は電車[でんしゃ]の模型[もけい]のキットを組[く]み立[た]てています。", "sentence_source": "generated"}, {"text": "キットの箱を開けると、小さな部品がたくさん入っていました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "キットの箱[はこ]を開[あ]けると、小[ちい]さな部品[ぶひん]がたくさん入[はい]っていました。", "sentence_source": "generated"}, {"text": "このキットは、はさみがなくても作れます。", "target_word": "キット", "complexity_tier": "T3", "furigana": "このキットは、はさみがなくても作[つく]れます。", "sentence_source": "generated"}, {"text": "キットがあれば、家でも簡単にスピーカーが作れます。", "target_word": "キット", "complexity_tier": "T3", "furigana": "キットがあれば、家[いえ]でも簡単[かんたん]にスピーカーが作[つく]れます。", "sentence_source": "generated"}, {"text": "部品を一つずつ出して、キットの説明書どおりに並べました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "部品[ぶひん]を一[ひと]つずつ出[だ]して、キットの説明書[せつめいしょ]どおりに並[なら]べました。", "sentence_source": "generated"}, {"text": "友だちに、車のキットを贈りました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "友[とも]だちに、車[くるま]のキットを贈[おく]りました。", "sentence_source": "generated"}, {"text": "キットは高かったので、貯金してから買いました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "キットは高[たか]かったので、貯金[ちょきん]してから買[か]いました。", "sentence_source": "generated"}, {"text": "小学生向けのキットだから、作り方が分かりやすいです。", "target_word": "キット", "complexity_tier": "T3", "furigana": "小学生[しょうがくせい]向[む]けのキットだから、作[つく]り方[かた]が分[わ]かりやすいです。", "sentence_source": "generated"}, {"text": "組み立て用のキットは、棚の上の段にあります。", "target_word": "キット", "complexity_tier": "T3", "furigana": "組[く]み立[た]て用[よう]のキットは、棚[たな]の上[うえ]の段[だん]にあります。", "sentence_source": "generated"}, {"text": "弟はキットの部品をなくして、泣いてしまいました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "弟[おとうと]はキットの部品[ぶひん]をなくして、泣[な]いてしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キット", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "組み立てるための部品をまとめたセット", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39728, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キット", "is_correct": true, "explanation": "組み立てるための部品をまとめたセットの意味で、電車の模型を組み立てる文に合う。"}, {"text": "説明書", "is_correct": false, "explanation": "説明書は組み立てる物ではないので、「組み立てています」の目的語にならない。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶は組み立てる物ではなく、電車の模型の文脈には合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "野菜は組み立てる物ではないので、電車の模型を組み立てる文と合わない。"}], "explanations": {"キット": "組み立てるための部品をまとめたセットの意味で、電車の模型を組み立てる文に合う。", "説明書": "説明書は組み立てる物ではないので、「組み立てています」の目的語にならない。", "花瓶": "花瓶は組み立てる物ではなく、電車の模型の文脈には合わない。", "野菜": "野菜は組み立てる物ではないので、電車の模型を組み立てる文と合わない。"}, "sentence_index": 0, "correct_answer": "キット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このキットは塗装まで終わっていて、箱から出すとすぐ飾れます。", "explanation": "ここは〈完成品〉の意味。キットは組み立て前の部品のセットなので、もう完成している物には使わない。"}, {"text": "姉は、キットを読みながら、組み立ての順番を確かめました。", "explanation": "ここは〈説明書〉の意味。キットは部品のセットで、読むための説明書そのものは指さない。"}, {"text": "引っ越しのとき、新しいふとんのキットをそろえました。", "explanation": "ここは〈寝具一式〉の意味。キットは組み立て用の部品のセットなので、寝具をまとめて買うときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39728, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キット", "is_correct": true, "explanation": "組み立てるための部品のセットを指し、高い買い物として文が成り立つ。"}, {"text": "行列", "is_correct": false, "explanation": "行列は並んだ人の列を指し、値段が高いものには当てはまらない。"}, {"text": "空気", "is_correct": false, "explanation": "空気は値段がつかないので、高いものを買うという文には合わない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空にあるもので、買えるものではないので文に合わない。"}], "explanations": {"キット": "組み立てるための部品のセットを指し、高い買い物として文が成り立つ。", "行列": "行列は並んだ人の列を指し、値段が高いものには当てはまらない。", "空気": "空気は値段がつかないので、高いものを買うという文には合わない。", "雲": "雲は空にあるもので、買えるものではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "キット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は、この車のキットを箱から出して、そのまま走らせて遊びました。", "explanation": "ここは〈玩具〉の意味。キットは組み立ててから使う物なので、そのまま遊べる玩具には使わない。"}, {"text": "兄は、のこぎり一本だけのキットを買いに行きました。", "explanation": "ここは〈道具〉の意味。キットは組み立てるための部品をまとめた物なので、道具一本だけは言わない。"}, {"text": "夏休みに作った木の船のキットを、先生に見せました。", "explanation": "ここは〈作品〉の意味。キットは組み立て前の部品のセットなので、作り終えた船には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39728, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は、ラジオのキットに組み立てて、机に置きました。", "corrected_sentence": "父は、ラジオのキットを組み立てて、机に置きました。", "error_description": "「組み立てる」は「を」をとるので、「に」は誤り。正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39728, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は、模型のキットが組み立てて、窓辺に飾りました。", "corrected_sentence": "姉は、模型のキットを組み立てて、窓辺に飾りました。", "error_description": "「組み立てる」は他動詞なので目的語に「を」を付ける。「が」は誤りで、「を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "もらう物はキットなので、目的語を示す「を」が自然。"}, {"text": "に", "is_correct": false, "explanation": "「キットにもらいました」では、もらう物の目的語にならず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、もらう物を示す文には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を表すので、「キットともらいました」は目的語として合わない。"}], "correct_answer": "を", "explanations": {"を": "もらう物はキットなので、目的語を示す「を」が自然。", "に": "「キットにもらいました」では、もらう物の目的語にならず文が成り立たない。", "へ": "「へ」は方向を表すので、もらう物を示す文には合わない。", "と": "「と」は相手や並列を表すので、「キットともらいました」は目的語として合わない。"}, "error_tags": {"に": "受け手・位置", "へ": "方向", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「このキットは」でキットを話題として示し、「値段が安い」と続けられる。"}, {"text": "を", "is_correct": false, "explanation": "「キットを値段が安いので」は文がつながらない。「を」は動作の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「キットに値段が安い」は文が成り立たず、「に」は位置や相手を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、キットの値段の説明には合わない。"}], "correct_answer": "は", "explanations": {"は": "「このキットは」でキットを話題として示し、「値段が安い」と続けられる。", "を": "「キットを値段が安いので」は文がつながらない。「を」は動作の目的語を示す。", "に": "「キットに値段が安い」は文が成り立たず、「に」は位置や相手を示す。", "へ": "「へ」は方向を示すので、キットの値段の説明には合わない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "組み立てに必要な部品や道具を一式そろえたもの。", "primary_collocate": null, "pronunciation": "きっと", "ipa": "kitːo", "syllable_count": 3, "sentences": [{"text": "組み立てる前に、キットを箱から出して机に並べます。", "target_word": "キット", "complexity_tier": "T3", "furigana": "組[く]み立[た]てる前[まえ]に、キットを箱[はこ]から出[だ]して机[つくえ]に並[なら]べます。", "sentence_source": "generated"}, {"text": "弟は誕生日に、ロボットのキットをもらいました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "弟[おとうと]は誕生日[たんじょうび]に、ロボットのキットをもらいました。", "sentence_source": "generated"}, {"text": "このキットには、部品と道具が全部入っています。", "target_word": "キット", "complexity_tier": "T3", "furigana": "このキットには、部品[ぶひん]と道具[どうぐ]が全部[ぜんぶ]入[はい]っています。", "sentence_source": "generated"}, {"text": "キットを使えば、初心者でも本棚が作れます。", "target_word": "キット", "complexity_tier": "T3", "furigana": "キットを使[つか]えば、初心者[しょしんしゃ]でも本棚[ほんだな]が作[つく]れます。", "sentence_source": "generated"}, {"text": "説明書を読みながら、模型のキットを組み立てました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]を読[よ]みながら、模型[もけい]のキットを組[く]み立[た]てました。", "sentence_source": "generated"}, {"text": "キットの部品が一つ足りなかったので、店に電話しました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "キットの部品[ぶひん]が一[ひと]つ足[た]りなかったので、店[みせ]に電話[でんわ]しました。", "sentence_source": "generated"}, {"text": "理科の授業で、ラジオのキットを作りました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、ラジオのキットを作[つく]りました。", "sentence_source": "generated"}, {"text": "このキットは値段が安いので、子どもにも人気があります。", "target_word": "キット", "complexity_tier": "T3", "furigana": "このキットは値段[ねだん]が安[やす]いので、子[こ]どもにも人気[にんき]があります。", "sentence_source": "generated"}, {"text": "父は工具が少ないので、道具つきのキットを選びました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "父[ちち]は工具[こうぐ]が少[すく]ないので、道具[どうぐ]つきのキットを選[えら]びました。", "sentence_source": "generated"}, {"text": "夏休みの工作に、木の船のキットを買いました。", "target_word": "キット", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの工作[こうさく]に、木[き]の船[ふね]のキットを買[か]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "キット", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "組み立てや作業に必要な部品・道具を一式にまとめた商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'daf805db-419a-467a-8461-dae6362a403c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "キット", "is_correct": true, "explanation": "組み立てる前に箱から出して並べる、部品と道具の一式を指すので合う。"}, {"text": "雲", "is_correct": false, "explanation": "雲は空に浮かぶもので、箱から出して机に並べる物ではない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は箱から出して机に並べる物ではないので、文に合わない。"}, {"text": "渋滞", "is_correct": false, "explanation": "渋滞は車が進まない状態を指し、箱から出して並べる物ではない。"}], "explanations": {"キット": "組み立てる前に箱から出して並べる、部品と道具の一式を指すので合う。", "雲": "雲は空に浮かぶもので、箱から出して机に並べる物ではない。", "歌": "歌は箱から出して机に並べる物ではないので、文に合わない。", "渋滞": "渋滞は車が進まない状態を指し、箱から出して並べる物ではない。"}, "sentence_index": 0, "correct_answer": "キット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このキットは組み立て済みで届くので、箱を開けてすぐ使えます。", "explanation": "ここは〈完成品〉の意味。キットは自分で組み立てる部品の一式なので、組み立て済みの物には使わない。"}, {"text": "父は、新しい機械のキットを読みながら、操作の手順を覚えました。", "explanation": "ここは〈説明書〉の意味。キットは部品と道具の一式で、読むための説明書そのものは指さない。"}, {"text": "美容院で、ヘアキットを頼みました。", "explanation": "ここは〈ヘアセット〉の意味。キットは組み立てる部品の一式なので、美容院での髪の仕上げには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "キット", "is_correct": true, "explanation": "理科の授業で作る、部品と道具の一式を指すので、ラジオのキットが合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空の様子を指すので、理科の授業で作るものとして合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "野菜は育てるものや食べ物で、ラジオを組み立てる授業の文には合わない。"}, {"text": "交通", "is_correct": false, "explanation": "交通は人やものの行き来を指し、ラジオのように組み立てて作る物ではないので文に合わない。"}], "explanations": {"キット": "理科の授業で作る、部品と道具の一式を指すので、ラジオのキットが合う。", "天気": "天気は空の様子を指すので、理科の授業で作るものとして合わない。", "野菜": "野菜は育てるものや食べ物で、ラジオを組み立てる授業の文には合わない。", "交通": "交通は人やものの行き来を指し、ラジオのように組み立てて作る物ではないので文に合わない。"}, "sentence_index": 6, "correct_answer": "キット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、友だちからもらった木の船のキットで、すぐ水に浮かべて遊びました。", "explanation": "ここは〈玩具〉の意味。キットは組み立ててから使う物なので、そのまますぐ遊べる玩具には使わない。"}, {"text": "夏休みの工作に、のこぎり一本だけのキットを買いました。", "explanation": "ここは〈道具〉の意味。キットは部品と道具の一式なので、道具一本だけの物には使わない。"}, {"text": "夏休みの工作で作った木の船のキットを、先生に見せました。", "explanation": "ここは〈作品〉の意味。キットは組み立て前の部品の一式なので、作り終えた船には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "説明書を見ながら、本棚のキットが組み立てました。", "corrected_sentence": "説明書を見ながら、本棚のキットを組み立てました。", "error_description": "「組み立てる」は他動詞なので、目的語のキットには「を」を付ける。「が」は誤りで、「を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39729, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は、模型のキットへていねいに組み立てました。", "corrected_sentence": "祖父は、模型のキットをていねいに組み立てました。", "error_description": "「組み立てる」は「を」をとるので、「へ」は誤り。正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aeb0e059-20bb-42f7-b240-e1df93734878') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本を検索する」の対象を示す「を」で、「検索した」の対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「本が検索した」は主語の関係になり、検索の対象を示す形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「本に検索した」では対象の関係が合わない。"}, {"text": "と", "is_correct": false, "explanation": "「本と検索した」では共同の相手を示すことになり、対象を示す文にならない。"}], "correct_answer": "を", "explanations": {"を": "「本を検索する」の対象を示す「を」で、「検索した」の対象を表す。", "が": "「本が検索した」は主語の関係になり、検索の対象を示す形にならない。", "に": "「本に検索した」では対象の関係が合わない。", "と": "「本と検索した」では共同の相手を示すことになり、対象を示す文にならない。"}, "error_tags": {"が": "主語と目的語の取り違え", "に": "相手・位置", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「作り方を検索する」の対象を示す「を」で、「検索して」に直接かかる。"}, {"text": "の", "is_correct": false, "explanation": "「作り方の検索して」は名詞修飾にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」では「作り方へ検索して」となり、対象の関係が合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「作り方より検索して」となり、対象の関係が合わない。"}], "correct_answer": "を", "explanations": {"を": "「作り方を検索する」の対象を示す「を」で、「検索して」に直接かかる。", "の": "「作り方の検索して」は名詞修飾にならず、文が成り立たない。", "へ": "方向の「へ」では「作り方へ検索して」となり、対象の関係が合わない。", "より": "比較の「より」では「作り方より検索して」となり、対象の関係が合わない。"}, "error_tags": {"の": "連体修飾の誤用", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを見つけるために、コンピューターや本で調べること。", "primary_collocate": null, "pronunciation": "けんさく", "ipa": "keɴsaku", "syllable_count": 4, "sentences": [{"text": "知らない言葉は、スマホで検索すればすぐ分かる。", "target_word": "検索", "complexity_tier": "T3", "furigana": "知[し]らない言葉[ことば]は、スマホで検索[けんさく]すればすぐ分[わ]かる。", "sentence_source": "generated"}, {"text": "図書館のパソコンで、読みたい本を検索した。", "target_word": "検索", "complexity_tier": "T3", "furigana": "図書館[としょかん]のパソコンで、読[よ]みたい本[ほん]を検索[けんさく]した。", "sentence_source": "generated"}, {"text": "駅までの行き方を検索してから、家を出た。", "target_word": "検索", "complexity_tier": "T3", "furigana": "駅[えき]までの行[い]き方[かた]を検索[けんさく]してから、家[いえ]を出[で]た。", "sentence_source": "generated"}, {"text": "名前を入れて検索すると、写真が何枚も出てきた。", "target_word": "検索", "complexity_tier": "T3", "furigana": "名前[なまえ]を入[い]れて検索[けんさく]すると、写真[しゃしん]が何枚[なんまい]も出[で]てきた。", "sentence_source": "generated"}, {"text": "店の場所が分からなかったので、地図アプリで検索した。", "target_word": "検索", "complexity_tier": "T3", "furigana": "店[みせ]の場所[ばしょ]が分[わ]からなかったので、地図[ちず]アプリで検索[けんさく]した。", "sentence_source": "generated"}, {"text": "辞書で調べる代わりに、ネットで意味を検索する人が多い。", "target_word": "検索", "complexity_tier": "T3", "furigana": "辞書[じしょ]で調[しら]べる代[か]わりに、ネットで意味[いみ]を検索[けんさく]する人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "検索の結果が多すぎて、必要な情報が見つからない。", "target_word": "検索", "complexity_tier": "T3", "furigana": "検索[けんさく]の結果[けっか]が多[おお]すぎて、必要[ひつよう]な情報[じょうほう]が見[み]つからない。", "sentence_source": "generated"}, {"text": "私は料理の作り方を検索して、夕食を作った。", "target_word": "検索", "complexity_tier": "T3", "furigana": "私[わたし]は料理[りょうり]の作[つく]り方[かた]を検索[けんさく]して、夕食[ゆうしょく]を作[つく]った。", "sentence_source": "generated"}, {"text": "授業のレポートのために、資料を検索している。", "target_word": "検索", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]のレポートのために、資料[しりょう]を検索[けんさく]している。", "sentence_source": "generated"}, {"text": "検索でいちばん上に出たページを開いた。", "target_word": "検索", "complexity_tier": "T3", "furigana": "検索[けんさく]でいちばん上[うえ]に出[で]たページを開[ひら]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "検索", "label": "dictionary form"}, {"form": "検索する", "label": "suru-verb dictionary form"}, {"form": "検索して", "label": "te-form"}, {"form": "検索した", "label": "past"}, {"form": "検索しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "知りたい言葉・場所・情報を見つけるために、コンピューターやスマホなどで調べること(スル名詞)。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7acc094e-1a61-48e4-86fe-d66c6a4975ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "検索", "is_correct": true, "explanation": "「スマホで検索する」の名詞で、「すればすぐ分かる」に続いて意味が通る。"}, {"text": "印刷", "is_correct": false, "explanation": "印刷では言葉の意味は分からず、「すればすぐ分かる」の内容に合わない。"}, {"text": "撮影", "is_correct": false, "explanation": "写真を撮る意味で、知らない言葉の意味を調べる文脈に合わない。"}, {"text": "削除", "is_correct": false, "explanation": "データを消す意味で、言葉を調べて分かるという内容に合わない。"}], "explanations": {"検索": "「スマホで検索する」の名詞で、「すればすぐ分かる」に続いて意味が通る。", "印刷": "印刷では言葉の意味は分からず、「すればすぐ分かる」の内容に合わない。", "撮影": "写真を撮る意味で、知らない言葉の意味を調べる文脈に合わない。", "削除": "データを消す意味で、言葉を調べて分かるという内容に合わない。"}, "sentence_index": 0, "correct_answer": "検索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行方不明の子どもを検索した。", "explanation": "ここは〈捜索〉の意味。〈検索〉は情報や言葉を調べる意味で、人を探し回る意味では使わない。"}, {"text": "ペンの色を検索した。", "explanation": "ここは〈選ぶ〉の意味。〈検索〉は情報や言葉を探す意味で、物を選び出す意味はない。"}, {"text": "庭の雑草を検索した。", "explanation": "ここは〈抜く〉の意味。〈検索〉は情報や言葉を探す意味で、草を取り除く意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "検索", "is_correct": true, "explanation": "「検索の結果」の名詞で、情報を探した結果が多すぎるという文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩の結果では情報が多すぎるという文脈に合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯の結果は、情報が見つからないという文の内容に合わない。"}, {"text": "録音", "is_correct": false, "explanation": "録音の結果が多すぎるという文脈は、情報を探す話と合わない。"}], "explanations": {"検索": "「検索の結果」の名詞で、情報を探した結果が多すぎるという文脈に合う。", "散歩": "散歩の結果では情報が多すぎるという文脈に合わない。", "洗濯": "洗濯の結果は、情報が見つからないという文の内容に合わない。", "録音": "録音の結果が多すぎるという文脈は、情報を探す話と合わない。"}, "sentence_index": 6, "correct_answer": "検索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "なくした財布を検索した。", "explanation": "ここは〈探す〉の意味。〈検索〉は情報を調べる意味で、物を探し回る意味では使わない。"}, {"text": "空港で、荷物の重さを検索した。", "explanation": "ここは〈計る〉の意味。〈検索〉は情報を探す意味で、重さを量る意味はない。"}, {"text": "お金を検索した。", "explanation": "ここは〈数える〉の意味。〈検索〉は情報を探す意味で、数量を数える意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "気になるお店を地図アプリに検索する。", "corrected_sentence": "気になるお店を地図アプリで検索する。", "error_description": "「検索する」の手段を示すのは「で」。「に」は誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の場所を地図アプリで検索にする。", "corrected_sentence": "店の場所を地図アプリで検索する。", "error_description": "「検索」は名詞で、「する」を直接付けて動詞になる。「検索にする」は不自然で、正しくは「検索する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329cb57b-822f-4e3e-aa9d-34faf041405d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
