INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39732, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「セットが置いてある」の主語を示し、置かれている状態を説明する文に合う。"}, {"text": "を", "is_correct": false, "explanation": "「セットを置いてある」は「置いてある」の形と合わず、文が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「セットと置いてある」となり、並列の意味になって文脈に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「セットより置いてある」では文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「セットが置いてある」の主語を示し、置かれている状態を説明する文に合う。", "を": "「セットを置いてある」は「置いてある」の形と合わず、文が通らない。", "と": "「セットと置いてある」となり、並列の意味になって文脈に合わない。", "より": "「より」は比較の助詞で、「セットより置いてある」では文が成り立たない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39732, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものの集まり。", "primary_collocate": null, "pronunciation": "せっと", "ipa": "setto", "syllable_count": 3, "sentences": [{"text": "このセットにはカップとお皿が六つずつ入っている。", "target_word": "セット", "complexity_tier": "T3", "furigana": "このセットにはカップとお皿[さら]が六[むっ]つずつ入[はい]っている。", "sentence_source": "generated"}, {"text": "同じ値段なら、バラで買うよりセットで買うほうが得だ。", "target_word": "セット", "complexity_tier": "T3", "furigana": "同[おな]じ値段[ねだん]なら、バラで買[か]うよりセットで買[か]うほうが得[とく]だ。", "sentence_source": "generated"}, {"text": "祖母から、おそろいのカップのセットをもらった。", "target_word": "セット", "complexity_tier": "T3", "furigana": "祖母[そぼ]から、おそろいのカップのセットをもらった。", "sentence_source": "generated"}, {"text": "ハンバーガーとポテトとドリンクのセットを注文した。", "target_word": "セット", "complexity_tier": "T3", "furigana": "ハンバーガーとポテトとドリンクのセットを注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "工具のセットを買ったが、ねじ回しが入っていなかった。", "target_word": "セット", "complexity_tier": "T3", "furigana": "工具[こうぐ]のセットを買[か]ったが、ねじ回[まわ]しが入[はい]っていなかった。", "sentence_source": "generated"}, {"text": "母は結婚祝いにタオルのセットを選んだ。", "target_word": "セット", "complexity_tier": "T3", "furigana": "母[はは]は結婚祝[けっこんいわ]いにタオルのセットを選[えら]んだ。", "sentence_source": "generated"}, {"text": "このセットは、ペンと消しゴムとノートがひとまとめになっている。", "target_word": "セット", "complexity_tier": "T3", "furigana": "このセットは、ペンと消[け]しゴムとノートがひとまとめになっている。", "sentence_source": "generated"}, {"text": "机の上に、絵の具のセットが置いてある。", "target_word": "セット", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]に、絵[え]の具[ぐ]のセットが置[お]いてある。", "sentence_source": "generated"}, {"text": "旅行には、小さいシャンプーのセットが便利だ。", "target_word": "セット", "complexity_tier": "T3", "furigana": "旅行[りょこう]には、小[ちい]さいシャンプーのセットが便利[べんり]だ。", "sentence_source": "generated"}, {"text": "一つでも足りないと、セットとして売れない。", "target_word": "セット", "complexity_tier": "T3", "furigana": "一[ひと]つでも足[た]りないと、セットとして売[う]れない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "セット", "label": "基本形"}, {"form": "セットで", "label": "助詞つき（で）"}], "register": "neutral", "sense_fingerprint": "いくつかのものをひとまとめにした一組", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39732, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "セット", "is_correct": true, "explanation": "一組になった品物を指し、カップとお皿が六つずつ入った一組の中身を説明する文に合う。"}, {"text": "包丁", "is_correct": false, "explanation": "刃物の一本を指し、カップとお皿が入るという文脈に合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "文具の一本を指し、カップとお皿が入るという文脈に合わない。"}, {"text": "石鹸", "is_correct": false, "explanation": "洗浄用品の一つで、カップとお皿が六つずつ入るという文脈には合わない。"}], "explanations": {"セット": "一組になった品物を指し、カップとお皿が六つずつ入った一組の中身を説明する文に合う。", "包丁": "刃物の一本を指し、カップとお皿が入るという文脈に合わない。", "鉛筆": "文具の一本を指し、カップとお皿が入るという文脈に合わない。", "石鹸": "洗浄用品の一つで、カップとお皿が六つずつ入るという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "セット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お昼どき、レジのセットに並んだ。", "explanation": "ここは〈列〉の意味。人が順番に並ぶ列を指すので、物の集まりを表すセットは合わない。"}, {"text": "子どもたちのセットが、公園で遊んでいる。", "explanation": "ここは〈集団〉の意味。人の集まりを指すので、物を一組にまとめたセットは合わない。"}, {"text": "野球のセットが、試合に勝った。", "explanation": "ここは〈チーム〉の意味。選手の集団を指すので、物の一組を表すセットは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39732, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "セット", "is_correct": true, "explanation": "ひとまとめになった物の一組を指し、ペンと消しゴムとノートがまとまっている文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を表す語で、文房具がひとまとめになる文脈に合わない。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の味覚を表す語で、文房具の組み合わせには合わない。"}, {"text": "季節", "is_correct": false, "explanation": "一年の時期を表す語で、物の組を指さないので合わない。"}], "explanations": {"セット": "ひとまとめになった物の一組を指し、ペンと消しゴムとノートがまとまっている文に合う。", "天気": "空模様を表す語で、文房具がひとまとめになる文脈に合わない。", "味": "食べ物の味覚を表す語で、文房具の組み合わせには合わない。", "季節": "一年の時期を表す語で、物の組を指さないので合わない。"}, "sentence_index": 6, "correct_answer": "セット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "テニスの試合で、彼は第一セットを取った。", "explanation": "ここは〈試合の区切り〉の意味。テニスの一区切りを指すので、物の一組を表すセットは合わない。"}, {"text": "財布のセットを空にして、お金を数えた。", "explanation": "ここは〈中身〉の意味。財布の中身は中身と言い、物の組み合わせを表すセットは合わない。"}, {"text": "夏休みに向けて、家族旅行のセットを立てた。", "explanation": "ここは〈計画〉の意味。立てるのは計画で、物の組み合わせを表すセットは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39732, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "引っ越し祝いに、食器のセットに贈った。", "corrected_sentence": "引っ越し祝いに、食器のセットを贈った。", "error_description": "「贈る」は目的語に「を」を取る。「セットに」の「に」が誤りで、正しくは「セットを贈った」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39732, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台所の棚に、食器のセットをしまた。", "corrected_sentence": "台所の棚に、食器のセットをしまった。", "error_description": "「しまう」の過去形は促音を入れた「しまった」。「しまた」は活用の誤りで、正しくは「しまった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「もらう」の対象を示す「を」で、「セットをもらいました」として文が成り立つ。"}, {"text": "の", "is_correct": false, "explanation": "「セットのもらいました」では名詞修飾の形が合わず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「セットへもらいました」では方向を表す「へ」が合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「セットよりもらいました」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「もらう」の対象を示す「を」で、「セットをもらいました」として文が成り立つ。", "の": "「セットのもらいました」では名詞修飾の形が合わず、文が成り立たない。", "へ": "「セットへもらいました」では方向を表す「へ」が合わない。", "より": "「より」は比較の助詞で、「セットよりもらいました」では文が成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「入れました」の対象を示す「を」で、「セットを入れました」として文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「セットが入れました」では主語が「彼女」と合わず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「セットに」と「かばんに」の二つの「に」が並び、入れる先が二つになって文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の助詞で、「セットより入れました」では文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「入れました」の対象を示す「を」で、「セットを入れました」として文が成り立つ。", "が": "「セットが入れました」では主語が「彼女」と合わず、文が成り立たない。", "に": "「セットに」と「かばんに」の二つの「に」が並び、入れる先が二つになって文が成り立たない。", "より": "「より」は比較の助詞で、「セットより入れました」では文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "着点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "複数の要素や部品を組み合わせたひとまとまりのこと。", "primary_collocate": null, "pronunciation": "せっと", "ipa": "setto", "syllable_count": 3, "sentences": [{"text": "このレストランでは、サンドイッチとスープのセットを注文できます。", "target_word": "セット", "complexity_tier": "T3", "furigana": "このレストランでは、サンドイッチとスープのセットを注文[ちゅうもん]できます。", "sentence_source": "generated"}, {"text": "誕生日に、ペンとノートのセットをもらいました。", "target_word": "セット", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、ペンとノートのセットをもらいました。", "sentence_source": "generated"}, {"text": "工具のセットが安かったので、買って帰りました。", "target_word": "セット", "complexity_tier": "T3", "furigana": "工具[こうぐ]のセットが安[やす]かったので、買[か]って帰[かえ]りました。", "sentence_source": "generated"}, {"text": "この店の朝食のセットにはコーヒーも付いています。", "target_word": "セット", "complexity_tier": "T3", "furigana": "この店[みせ]の朝食[ちょうしょく]のセットにはコーヒーも付[つ]いています。", "sentence_source": "generated"}, {"text": "食器をセットで買うと、一つずつ買うより安くなります。", "target_word": "セット", "complexity_tier": "T3", "furigana": "食器[しょっき]をセットで買[か]うと、一[ひと]つずつ買[か]うより安[やす]くなります。", "sentence_source": "generated"}, {"text": "引っ越しのとき、客用の布団のセットを用意しました。", "target_word": "セット", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しのとき、客用[きゃくよう]の布団[ふとん]のセットを用意[ようい]しました。", "sentence_source": "generated"}, {"text": "このゲームは、本体とソフトがセットになって売られています。", "target_word": "セット", "complexity_tier": "T3", "furigana": "このゲームは、本体[ほんたい]とソフトがセットになって売[う]られています。", "sentence_source": "generated"}, {"text": "彼女は化粧品のセットを旅行用のかばんに入れました。", "target_word": "セット", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は化粧品[けしょうひん]のセットを旅行用[りょこうよう]のかばんに入[い]れました。", "sentence_source": "generated"}, {"text": "茶碗が一つ割れて、セットがそろわなくなりました。", "target_word": "セット", "complexity_tier": "T3", "furigana": "茶碗[ちゃわん]が一[ひと]つ割[わ]れて、セットがそろわなくなりました。", "sentence_source": "generated"}, {"text": "お祝いに、紅茶とお菓子のセットを贈るつもりです。", "target_word": "セット", "complexity_tier": "T3", "furigana": "お祝[いわ]いに、紅茶[こうちゃ]とお菓子[かし]のセットを贈[おく]るつもりです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "セット", "label": "基本形"}, {"form": "セットで", "label": "で格"}, {"form": "セットの", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "いくつかの物をまとめた一組。ペンとノートのセット、食器のセットなど。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: そろわ (Zipf 2.29)']::text[], 'b9f35ae2-3626-49c3-8754-26766e35d357') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "セット", "is_correct": true, "explanation": "一組の料理を指し、サンドイッチとスープの組み合わせを注文する文に合う。"}, {"text": "割引", "is_correct": false, "explanation": "値引きを指し、料理を注文する文の目的語としては合わない。"}, {"text": "予約", "is_correct": false, "explanation": "席や料理を前もって押さえることで、サンドイッチとスープを注文する文には合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "人の年数を表し、料理の注文とは結びつかないので合わない。"}], "explanations": {"セット": "一組の料理を指し、サンドイッチとスープの組み合わせを注文する文に合う。", "割引": "値引きを指し、料理を注文する文の目的語としては合わない。", "予約": "席や料理を前もって押さえることで、サンドイッチとスープを注文する文には合わない。", "年齢": "人の年数を表し、料理の注文とは結びつかないので合わない。"}, "sentence_index": 0, "correct_answer": "セット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週のセットを確認しました。", "explanation": "ここは〈予定〉の意味。日程を確認する語で、物の組み合わせを表すセットは合わない。"}, {"text": "彼女は友達とのセットを守りました。", "explanation": "ここは〈約束〉の意味。守るのは約束で、物の組み合わせを表すセットは合わない。"}, {"text": "鳥のセットが空を飛んでいます。", "explanation": "ここは〈群れ〉の意味。生き物の集まりを指すので、物を一組にまとめたセットは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "セット", "is_correct": true, "explanation": "本体とソフトを組にして売る状態を表し、「セットになって売られる」で文が成り立つ。"}, {"text": "故障", "is_correct": false, "explanation": "機械が壊れることで、売り方を表す文脈には合わない。"}, {"text": "準備", "is_correct": false, "explanation": "用意を表す語で、「準備になって売られる」では不自然で合わない。"}, {"text": "試練", "is_correct": false, "explanation": "苦しい経験を表す語で、売り方の文脈には合わない。"}], "explanations": {"セット": "本体とソフトを組にして売る状態を表し、「セットになって売られる」で文が成り立つ。", "故障": "機械が壊れることで、売り方を表す文脈には合わない。", "準備": "用意を表す語で、「準備になって売られる」では不自然で合わない。", "試練": "苦しい経験を表す語で、売り方の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "セット"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新人は、セットを踏んで仕事を覚えました。", "explanation": "ここは〈段階〉の意味。踏むのは段階で、物の組み合わせを表すセットは合わない。"}, {"text": "作業の後、彼はセットをつきました。", "explanation": "ここは〈息〉の意味。ひと息つくのは息で、物の組み合わせを表すセットは合わない。"}, {"text": "走った後、彼はセットをかきました。", "explanation": "ここは〈汗〉の意味。かくのは汗で、物の組み合わせを表すセットは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもの誕生日に、おもちゃのセットに買ってあげた。", "corrected_sentence": "子どもの誕生日に、おもちゃのセットを買ってあげた。", "error_description": "「買う」は目的語に「を」を取る。「セットに」の「に」が誤りで、正しくは「セットを買ってあげた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は、新しい工具のセットを車に積むいる。", "corrected_sentence": "父は、新しい工具のセットを車に積んでいる。", "error_description": "「積む」のて形は「積んで」なので「積んでいる」が正しい。「積むいる」は活用の誤りで、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '759ccecf-2033-42ce-bfec-2bb1b2e263ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
