INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39734, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "隠れていたものや分からなかったことが、人に気づかれて明らかになること。", "primary_collocate": null, "pronunciation": "みつかる", "ipa": "mitsɯkaɾɯ", "syllable_count": 4, "sentences": [{"text": "隠れていた猫が、押し入れの中で見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "隠[かく]れていた猫[ねこ]が、押[お]し入[い]れの中[なか]で見[み]つかった。", "sentence_source": "generated"}, {"text": "かくれんぼで、すぐに見つかってしまった。", "target_word": "見つかって", "complexity_tier": "T3", "furigana": "かくれんぼで、すぐに見[み]つかってしまった。", "sentence_source": "generated"}, {"text": "試験で不正をして、先生に見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "試験[しけん]で不正[ふせい]をして、先生[せんせい]に見[み]つかった。", "sentence_source": "generated"}, {"text": "病気の原因がやっと見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "病気[びょうき]の原因[げんいん]がやっと見[み]つかった。", "sentence_source": "generated"}, {"text": "駅の近くで、安くて広い部屋が見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くで、安[やす]くて広[ひろ]い部屋[へや]が見[み]つかった。", "sentence_source": "generated"}, {"text": "答えが見つからないときは、先生に聞く。", "target_word": "見つからない", "complexity_tier": "T3", "furigana": "答[こた]えが見[み]つからないときは、先生[せんせい]に聞[き]く。", "sentence_source": "generated"}, {"text": "地震のあと、行方不明の人が見つかったというニュースを見た。", "target_word": "見つかった", "complexity_tier": "T4", "furigana": "地震[じしん]のあと、行方不明[ゆくえふめい]の人[ひと]が見[み]つかったというニュースを見[み]た。", "sentence_source": "generated"}, {"text": "間違いが見つかれば、すぐに直す。", "target_word": "見つかれば", "complexity_tier": "T3", "furigana": "間違[まちが]いが見[み]つかれば、すぐに直[なお]す。", "sentence_source": "generated"}, {"text": "この森では、珍しい花がときどき見つかる。", "target_word": "見つかる", "complexity_tier": "T3", "furigana": "この森[もり]では、珍[めずら]しい花[はな]がときどき見[み]つかる。", "sentence_source": "generated"}, {"text": "悪いことをしても、いつかは見つかるものだ。", "target_word": "見つかる", "complexity_tier": "T3", "furigana": "悪[わる]いことをしても、いつかは見[み]つかるものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見つかる", "label": "終止形"}, {"form": "見つかった", "label": "過去形"}, {"form": "見つかって", "label": "て形"}, {"form": "見つからない", "label": "否定形"}, {"form": "見つかれば", "label": "仮定形"}], "register": "plain", "sense_fingerprint": "隠れていたものや分からなかったことが、人に気づかれて明らかになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39734, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見つかった", "is_correct": true, "explanation": "自動詞「見つかる」の過去形で、猫が押し入れで発見された事実を述べる。"}, {"text": "見つけた", "is_correct": false, "explanation": "他動詞なので目的語が必要。主語の猫が見つける側にはなれず、文が成り立たない。"}, {"text": "見つける", "is_correct": false, "explanation": "辞書形は過去の出来事を述べる文末に合わない。他動詞で目的語もない。"}, {"text": "見つかって", "is_correct": false, "explanation": "て形で文が途中で切れ、『。』で終わる文の述語にならない。"}], "explanations": {"見つかった": "自動詞「見つかる」の過去形で、猫が押し入れで発見された事実を述べる。", "見つけた": "他動詞なので目的語が必要。主語の猫が見つける側にはなれず、文が成り立たない。", "見つける": "辞書形は過去の出来事を述べる文末に合わない。他動詞で目的語もない。", "見つかって": "て形で文が途中で切れ、『。』で終わる文の述語にならない。"}, "sentence_index": 0, "correct_answer": "見つかった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "風が強くて、ろうそくの火が見つかった。", "explanation": "ここは〈消える〉の意味。〈見つかる〉は物や事実が発見される意味で、火が消える現象には使えないので文が通らない。"}, {"text": "ドライヤーで髪がすぐ見つかった。", "explanation": "ここは〈乾く〉の意味。〈見つかる〉は物や事実の発見に使い、髪が乾く変化は表せないので文が通らない。"}, {"text": "夏の暑さで、汗がだらだら見つかった。", "explanation": "ここは〈出る〉の意味。〈見つかる〉は発見の意味で、汗が出る現象は表せないので文が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39734, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見つかった", "is_correct": true, "explanation": "過去形で、行方不明の人が発見されたという報道の内容を表す。"}, {"text": "見つけた", "is_correct": false, "explanation": "他動詞なので『人が見つけた』では目的語が欠け、報道文として成り立たない。"}, {"text": "見つけよう", "is_correct": false, "explanation": "意志形は『というニュース』の内容として不自然。他動詞で目的語も欠ける。"}, {"text": "見つけて", "is_correct": false, "explanation": "て形のままでは『ニュースを見た』へ続く内容文にならない。"}], "explanations": {"見つかった": "過去形で、行方不明の人が発見されたという報道の内容を表す。", "見つけた": "他動詞なので『人が見つけた』では目的語が欠け、報道文として成り立たない。", "見つけよう": "意志形は『というニュース』の内容として不自然。他動詞で目的語も欠ける。", "見つけて": "て形のままでは『ニュースを見た』へ続く内容文にならない。"}, "sentence_index": 6, "correct_answer": "見つかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜になって、部屋がすっかり見つかった。", "explanation": "ここは〈冷える〉の意味。〈見つかる〉は物や事実の発見に使い、部屋の温度が下がる変化は表せないので文が通らない。"}, {"text": "強い風が、窓を叩きながら見つかった。", "explanation": "ここは〈吹く〉の意味。〈見つかる〉は発見の意味で、風が吹く動きは表せないので文が通らない。"}, {"text": "会議で、部長の案に皆が見つかった。", "explanation": "ここは〈反対する〉の意味。〈見つかる〉は発見の意味で、意見に異を唱える動作は表せないので文が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39734, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の木の下で、子猫を見つかった。", "corrected_sentence": "庭の木の下で、子猫が見つかった。", "error_description": "助詞の誤り。自動詞『見つかる』は『が』で主語を示す。『を』は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見つかって", "is_correct": true, "explanation": "て形の『見つかって』は『しまった』に続き、『すぐに…てしまった』の構文に合う。"}, {"text": "見つかった", "is_correct": false, "explanation": "『見つかったてしまった』は成り立たない。て形が必要。"}, {"text": "見つからない", "is_correct": false, "explanation": "否定形だと『見つけられなかった』の意味になり、文の内容と矛盾する。"}, {"text": "見つかれば", "is_correct": false, "explanation": "仮定形は『しまった』と続かず、文の意味が変わる。"}], "correct_form": "見つかって", "base_form": "見つかる", "form_label": "て形", "sentence_index": 1, "explanations": {"見つかって": "て形の『見つかって』は『しまった』に続き、『すぐに…てしまった』の構文に合う。", "見つかった": "『見つかったてしまった』は成り立たない。て形が必要。", "見つからない": "否定形だと『見つけられなかった』の意味になり、文の内容と矛盾する。", "見つかれば": "仮定形は『しまった』と続かず、文の意味が変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39734, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机の引き出しから、昔の手紙が見つかるた。", "corrected_sentence": "机の引き出しから、昔の手紙が見つかった。", "error_description": "活用の誤り。『見つかる』の過去形は『見つかった』で、『見つかるた』は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見つかれば", "is_correct": true, "explanation": "仮定形『見つかれば』は『〜すれば』の条件を表し、文の『ば』節に合う。"}, {"text": "見つからなかった", "is_correct": false, "explanation": "過去の否定形は『ば』と続かず、条件節として文が成り立たない。"}, {"text": "見つからなければ", "is_correct": false, "explanation": "否定の仮定形だと『見つからなければ直す』となり、見つからない場合に直すという意味で文の前提と矛盾する。"}, {"text": "見つかろう", "is_correct": false, "explanation": "意志形は『ば』と続かず、条件節として成り立たない。"}], "correct_form": "見つかれば", "base_form": "見つかる", "form_label": "仮定形", "sentence_index": 7, "explanations": {"見つかれば": "仮定形『見つかれば』は『〜すれば』の条件を表し、文の『ば』節に合う。", "見つからなかった": "過去の否定形は『ば』と続かず、条件節として文が成り立たない。", "見つからなければ": "否定の仮定形だと『見つからなければ直す』となり、見つからない場合に直すという意味で文の前提と矛盾する。", "見つかろう": "意志形は『ば』と続かず、条件節として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
