INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39735, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "探していたものが、自分のところに現れること。", "primary_collocate": null, "pronunciation": "みつかる", "ipa": "mitsɯkaɾɯ", "syllable_count": 4, "sentences": [{"text": "なくした財布が、交番で見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "なくした財布[さいふ]が、交番[こうばん]で見[み]つかった。", "sentence_source": "generated"}, {"text": "家じゅうを探したが、鍵は見つからなかった。", "target_word": "見つからなかった", "complexity_tier": "T3", "furigana": "家[いえ]じゅうを探[さが]したが、鍵[かぎ]は見[み]つからなかった。", "sentence_source": "generated"}, {"text": "探していた本が、図書館でやっと見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "探[さが]していた本[ほん]が、図書館[としょかん]でやっと見[み]つかった。", "sentence_source": "generated"}, {"text": "眼鏡が見つかって、ほっとした。", "target_word": "見つかって", "complexity_tier": "T3", "furigana": "眼鏡[めがね]が見[み]つかって、ほっとした。", "sentence_source": "generated"}, {"text": "かばんの中から、なくしたペンが見つかった。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "かばんの中[なか]から、なくしたペンが見[み]つかった。", "sentence_source": "generated"}, {"text": "犬がまだ見つからないので、毎日探している。", "target_word": "見つからない", "complexity_tier": "T3", "furigana": "犬[いぬ]がまだ見[み]つからないので、毎日[まいにち]探[さが]している。", "sentence_source": "generated"}, {"text": "見つかったら、すぐに電話してほしい。", "target_word": "見つかったら", "complexity_tier": "T3", "furigana": "見[み]つかったら、すぐに電話[でんわ]してほしい。", "sentence_source": "generated"}, {"text": "昨日なくした傘は、駅で見つかったそうだ。", "target_word": "見つかった", "complexity_tier": "T3", "furigana": "昨日[きのう]なくした傘[かさ]は、駅[えき]で見[み]つかったそうだ。", "sentence_source": "generated"}, {"text": "どこを探しても、携帯電話が見つからない。", "target_word": "見つからない", "complexity_tier": "T3", "furigana": "どこを探[さが]しても、携帯電話[けいたいでんわ]が見[み]つからない。", "sentence_source": "generated"}, {"text": "探していた写真が、引き出しの奥から見つかった。", "target_word": "見つかった", "complexity_tier": "T4", "furigana": "探[さが]していた写真[しゃしん]が、引[ひ]き出[だ]しの奥[おく]から見[み]つかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "見つかる", "label": "終止形"}, {"form": "見つかった", "label": "過去形"}, {"form": "見つかって", "label": "て形"}, {"form": "見つからない", "label": "否定形"}, {"form": "見つかったら", "label": "たら形"}], "register": "plain", "sense_fingerprint": "なくしたものや探していたものが、見つかって手元に戻る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39735, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "見つかった", "is_correct": true, "explanation": "過去形で、財布が交番で発見されて手元に戻ったことを表す。"}, {"text": "見つけた", "is_correct": false, "explanation": "他動詞なので目的語が必要。主語の財布が見つける側になれず、文が成り立たない。"}, {"text": "見つけて", "is_correct": false, "explanation": "て形のままでは文が途中で切れ、述語にならない。"}, {"text": "見つけよう", "is_correct": false, "explanation": "意志形は財布を主語にできず、他動詞で目的語もないため不自然。"}], "explanations": {"見つかった": "過去形で、財布が交番で発見されて手元に戻ったことを表す。", "見つけた": "他動詞なので目的語が必要。主語の財布が見つける側になれず、文が成り立たない。", "見つけて": "て形のままでは文が途中で切れ、述語にならない。", "見つけよう": "意志形は財布を主語にできず、他動詞で目的語もないため不自然。"}, "sentence_index": 0, "correct_answer": "見つかった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "息を入れると、風船がみるみる大きく見つかった。", "explanation": "ここは〈膨らむ〉の意味。〈見つかる〉は発見の意味で、風船が大きくなる変化は表せないので文が通らない。"}, {"text": "お湯がぐらぐら見つかった。", "explanation": "ここは〈沸く〉の意味。〈見つかる〉は発見の意味で、湯が沸く現象は表せないので文が通らない。"}, {"text": "昨日の名前がふと見つかって、思い出せなかった。", "explanation": "ここは〈思い出す〉の意味。名前を思い出す場面は〈思い出す〉で表し、〈見つかる〉は物の発見に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39735, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "見つかったら", "is_correct": true, "explanation": "たら形で『見つかった時点で』という条件を表し、『すぐに電話してほしい』に続く。"}, {"text": "見つかろう", "is_correct": false, "explanation": "意志形は条件節に続かず、『すぐに電話してほしい』と文がつながらない。"}, {"text": "見つかったのに", "is_correct": false, "explanation": "逆接の『のに』では、見つかった後に電話を頼む文意がつながらず不自然。"}, {"text": "見つかって", "is_correct": false, "explanation": "て形は文の条件節にならず、『すぐに電話してほしい』へ続かない。"}], "explanations": {"見つかったら": "たら形で『見つかった時点で』という条件を表し、『すぐに電話してほしい』に続く。", "見つかろう": "意志形は条件節に続かず、『すぐに電話してほしい』と文がつながらない。", "見つかったのに": "逆接の『のに』では、見つかった後に電話を頼む文意がつながらず不自然。", "見つかって": "て形は文の条件節にならず、『すぐに電話してほしい』へ続かない。"}, "sentence_index": 6, "correct_answer": "見つかったら"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープがすっかり見つかった。", "explanation": "ここは〈冷める〉の意味。〈見つかる〉は発見の意味で、温度の変化は表せないので文が通らない。"}, {"text": "夏の暑さで、汗がだらだら見つかった。", "explanation": "ここは〈出る〉の意味。〈見つかる〉は発見の意味で、汗が出る現象は表せないので文が通らない。"}, {"text": "合格の知らせを聞いて、私は見つかった。", "explanation": "ここは〈喜ぶ〉の意味。〈見つかる〉は発見される意味で、感情を表す動作には使えないので文が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39735, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "なくした財布が、交番で見つかるなかった。", "corrected_sentence": "なくした財布が、交番で見つからなかった。", "error_description": "活用の誤り。否定形は『見つからなかった』で、『見つかるなかった』は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "見つからなかった", "is_correct": true, "explanation": "否定過去形で、家じゅうを探したが鍵が見つからなかったという文脈に合う。"}, {"text": "見つかろう", "is_correct": false, "explanation": "意志形は『鍵は』に続かず、文として成り立たない。"}, {"text": "見つからない", "is_correct": false, "explanation": "現在の否定形では過去の探索の結果を述べられず、時制が合わない。"}, {"text": "見つかったら", "is_correct": false, "explanation": "たら形は仮定の条件を表し、探索の結果を述べる文には合わない。"}], "correct_form": "見つからなかった", "base_form": "見つかる", "form_label": "否定過去形", "sentence_index": 1, "explanations": {"見つからなかった": "否定過去形で、家じゅうを探したが鍵が見つからなかったという文脈に合う。", "見つかろう": "意志形は『鍵は』に続かず、文として成り立たない。", "見つからない": "現在の否定形では過去の探索の結果を述べられず、時制が合わない。", "見つかったら": "たら形は仮定の条件を表し、探索の結果を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39735, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は駅のホームで、なくした傘を見つかった。", "corrected_sentence": "父は駅のホームで、なくした傘が見つかった。", "error_description": "助詞の誤り。自動詞『見つかる』の主語は『が』で示す。『を』は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "見つかった", "is_correct": true, "explanation": "過去形で、傘が駅で見つかったという伝聞の内容を表す。"}, {"text": "見つかって", "is_correct": false, "explanation": "て形は『そうだ』の伝聞の文末に続かず、文が途中で切れる。"}, {"text": "見つかれば", "is_correct": false, "explanation": "仮定形は条件を表すため、『見つかればそうだ』では伝聞の文として成り立たない。"}, {"text": "見つからなければ", "is_correct": false, "explanation": "否定の仮定形は傘が見つからない場合の条件となり、駅で見つかったという伝聞の内容と矛盾する。"}], "correct_form": "見つかった", "base_form": "見つかる", "form_label": "過去形", "sentence_index": 7, "explanations": {"見つかった": "過去形で、傘が駅で見つかったという伝聞の内容を表す。", "見つかって": "て形は『そうだ』の伝聞の文末に続かず、文が途中で切れる。", "見つかれば": "仮定形は条件を表すため、『見つかればそうだ』では伝聞の文として成り立たない。", "見つからなければ": "否定の仮定形は傘が見つからない場合の条件となり、駅で見つかったという伝聞の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解する", "is_correct": true, "explanation": "組み立てるの対義語。組み立てられたものを部品に戻す意味で、このいすの文脈にも対応する。"}, {"text": "作る", "is_correct": false, "explanation": "類似する動詞だが対義語ではない。組み立てるとは反対の意味関係にない。"}, {"text": "取り付ける", "is_correct": false, "explanation": "部品を装着する意味で、組み立てると対義語にはならない。"}, {"text": "組み合わせる", "is_correct": false, "explanation": "要素を合わせる意味で、組み立てと近い意味だが対義語ではない。"}], "correct_answer": "分解する", "explanations": {"分解する": "組み立てるの対義語。組み立てられたものを部品に戻す意味で、このいすの文脈にも対応する。", "作る": "類似する動詞だが対義語ではない。組み立てるとは反対の意味関係にない。", "取り付ける": "部品を装着する意味で、組み立てると対義語にはならない。", "組み合わせる": "要素を合わせる意味で、組み立てと近い意味だが対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『板を』で板が組み立てる対象（目的語）を示し、直後の『組み立てれば』に直接つながる。"}, {"text": "が", "is_correct": false, "explanation": "『板が組み立てれば』は板が主語になり、他動詞の目的語を失うため不自然。"}, {"text": "に", "is_correct": false, "explanation": "『板に組み立てれば』は場所や相手を示すが、ここでは目的語が必要なので意味が合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『板へ組み立てれば』は方向を示し、他動詞の目的語を表す文脈に合わない。"}], "correct_answer": "を", "explanations": {"を": "『板を』で板が組み立てる対象（目的語）を示し、直後の『組み立てれば』に直接つながる。", "が": "『板が組み立てれば』は板が主語になり、他動詞の目的語を失うため不自然。", "に": "『板に組み立てれば』は場所や相手を示すが、ここでは目的語が必要なので意味が合わない。", "へ": "『板へ組み立てれば』は方向を示し、他動詞の目的語を表す文脈に合わない。"}, "error_tags": {"が": "subject", "に": "location", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解する", "is_correct": true, "explanation": "組み立てるの対義語。組み立てられたテントを部品に戻す意味で、この文脈に対応する。"}, {"text": "解く", "is_correct": false, "explanation": "問題を解くなどの意味で、組み立てるとは対義語の関係にない。"}, {"text": "積み上げる", "is_correct": false, "explanation": "物を重ねる意味で、組み立てるの対義語ではない。"}, {"text": "包む", "is_correct": false, "explanation": "物を布などで覆う意味で、組み立てるとは対義語の関係にない。"}], "correct_answer": "分解する", "explanations": {"分解する": "組み立てるの対義語。組み立てられたテントを部品に戻す意味で、この文脈に対応する。", "解く": "問題を解くなどの意味で、組み立てるとは対義語の関係にない。", "積み上げる": "物を重ねる意味で、組み立てるの対義語ではない。", "包む": "物を布などで覆う意味で、組み立てるとは対義語の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ばらばらのものを、一つにくっつけて、一つのものにする。", "primary_collocate": null, "pronunciation": "くみたてる", "ipa": "kɯmitateɾɯ", "syllable_count": 5, "sentences": [{"text": "兄は説明書を見ながら、新しい棚を組み立てた。", "target_word": "組み立てた", "complexity_tier": "T3", "furigana": "兄[あに]は説明書[せつめいしょ]を見[み]ながら、新[あたら]しい棚[たな]を組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "箱の中の部品を、一つずつ組み立てる。", "target_word": "組み立てる", "complexity_tier": "T3", "furigana": "箱[はこ]の中[なか]の部品[ぶひん]を、一[ひと]つずつ組[く]み立[た]てる。", "sentence_source": "generated"}, {"text": "子どもたちは、ブロックでロボットを組み立てている。", "target_word": "組み立てている", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、ブロックでロボットを組[く]み立[た]てている。", "sentence_source": "generated"}, {"text": "このいすは、一人でも簡単に組み立てられる。", "target_word": "組み立てられる", "complexity_tier": "T3", "furigana": "このいすは、一人[ひとり]でも簡単[かんたん]に組[く]み立[た]てられる。", "sentence_source": "generated"}, {"text": "部品が足りなくて、机を組み立てることができなかった。", "target_word": "組み立てる", "complexity_tier": "T4", "furigana": "部品[ぶひん]が足[た]りなくて、机[つくえ]を組[く]み立[た]てることができなかった。", "sentence_source": "generated"}, {"text": "工場では、ロボットが車を組み立てている。", "target_word": "組み立てている", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、ロボットが車[くるま]を組[く]み立[た]てている。", "sentence_source": "generated"}, {"text": "父は休みの日に、模型の飛行機を組み立てる。", "target_word": "組み立てる", "complexity_tier": "T3", "furigana": "父[ちち]は休[やす]みの日[ひ]に、模型[もけい]の飛行機[ひこうき]を組[く]み立[た]てる。", "sentence_source": "generated"}, {"text": "ねじで板を組み立てれば、本棚になる。", "target_word": "組み立てれば", "complexity_tier": "T3", "furigana": "ねじで板[いた]を組[く]み立[た]てれば、本棚[ほんだな]になる。", "sentence_source": "generated"}, {"text": "引っ越しのあとで、ベッドを組み立てなければならない。", "target_word": "組み立てなければ", "complexity_tier": "T4", "furigana": "引[ひ]っ越[こ]しのあとで、ベッドを組[く]み立[た]てなければならない。", "sentence_source": "generated"}, {"text": "組み立てたばかりのテントが、風で倒れてしまった。", "target_word": "組み立てた", "complexity_tier": "T4", "furigana": "組[く]み立[た]てたばかりのテントが、風[かぜ]で倒[たお]れてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み立てる", "label": "終止形"}, {"form": "組み立てた", "label": "過去形"}, {"form": "組み立てて", "label": "て形"}, {"form": "組み立てない", "label": "否定形"}, {"form": "組み立てられる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "ばらばらの部品を合わせて、家具や模型などの一つの物に仕上げる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み立てた", "is_correct": true, "explanation": "過去形で、兄が説明書を見ながら棚を組み上げたことを表す。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形のままでは文が途中で切れ、述語にならない。"}, {"text": "組み立てられた", "is_correct": false, "explanation": "受身形にすると『棚が組み立てられた』となり、『兄は』が主語の文として不自然。"}, {"text": "組み立て", "is_correct": false, "explanation": "連用形の名詞形では文が終わらず、述語として成り立たない。"}], "explanations": {"組み立てた": "過去形で、兄が説明書を見ながら棚を組み上げたことを表す。", "組み立てて": "て形のままでは文が途中で切れ、述語にならない。", "組み立てられた": "受身形にすると『棚が組み立てられた』となり、『兄は』が主語の文として不自然。", "組み立て": "連用形の名詞形では文が終わらず、述語として成り立たない。"}, "sentence_index": 0, "correct_answer": "組み立てた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このパンは、朝に組み立てて焼いた。", "explanation": "ここは〈焼く〉の意味。〈組み立てる〉は部品を一つにまとめる意味で、パンを焼く動作には使わない。"}, {"text": "彼女は冬の間、セーターを組み立てた。", "explanation": "ここは〈編む〉の意味。〈組み立てる〉は部品を一つにまとめる意味で、糸を編む動作には使わないので不自然。"}, {"text": "彼女はカップにお茶を組み立てた。", "explanation": "ここは〈注ぐ〉の意味。〈組み立てる〉は部品をまとめる意味で、液体を容器に入れる動作には使わないので不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み立てる", "is_correct": true, "explanation": "辞書形で、父が休みの日にする習慣的な動作を述べる文末に合う。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形のままでは文が途中で切れ、述語にならない。"}, {"text": "組み立てられ", "is_correct": false, "explanation": "連用形の受身では文が終わらず、『父は』が主語の文として成り立たない。"}, {"text": "組み立てたら", "is_correct": false, "explanation": "たら形は条件節で、『父は〜する』の文末にならない。"}], "explanations": {"組み立てる": "辞書形で、父が休みの日にする習慣的な動作を述べる文末に合う。", "組み立てて": "て形のままでは文が途中で切れ、述語にならない。", "組み立てられ": "連用形の受身では文が終わらず、『父は』が主語の文として成り立たない。", "組み立てたら": "たら形は条件節で、『父は〜する』の文末にならない。"}, "sentence_index": 6, "correct_answer": "組み立てる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女はパーティーに友人を組み立てた。", "explanation": "ここは〈招く〉の意味。〈組み立てる〉は部品をまとめる意味で、人を呼ぶ動作には使わないので不自然。"}, {"text": "食器を組み立てて洗った。", "explanation": "ここは〈洗う〉の意味。〈組み立てる〉は食器を洗う動作を表せず、意味が合わない。"}, {"text": "プレゼントを組み立てて包んだ。", "explanation": "ここは〈包む〉の意味。〈組み立てる〉は物を包む動作には使わず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は説明書を読みながら、古い机が組み立てた。", "corrected_sentence": "母は説明書を読みながら、古い机を組み立てた。", "error_description": "助詞の誤り。他動詞『組み立てる』の目的語は『を』で示す。『が』では目的語がなく、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組み立てる", "is_correct": true, "explanation": "辞書形で、『一つずつ組み立てる』と習慣や一般的な動作を述べる文末に合う。"}, {"text": "組み立てたら", "is_correct": false, "explanation": "たら形は条件節で、文末にはならない。『一つずつ組み立てたら』では文が途中で切れる。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形は文末にならず、『一つずつ組み立てて』だけでは文が途中で切れる。"}, {"text": "組み立てない", "is_correct": false, "explanation": "否定形だと『組み立てない』となり、文の意図と矛盾する。"}], "correct_form": "組み立てる", "base_form": "組み立てる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"組み立てる": "辞書形で、『一つずつ組み立てる』と習慣や一般的な動作を述べる文末に合う。", "組み立てたら": "たら形は条件節で、文末にはならない。『一つずつ組み立てたら』では文が途中で切れる。", "組み立てて": "て形は文末にならず、『一つずつ組み立てて』だけでは文が途中で切れる。", "組み立てない": "否定形だと『組み立てない』となり、文の意図と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39736, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は工具を使って、本棚に組み立てた。", "corrected_sentence": "兄は工具を使って、本棚を組み立てた。", "error_description": "助詞の誤り。他動詞『組み立てる』の目的語は『を』で示す。『に』では目的語がなく、文の意味が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組み立てれば", "is_correct": true, "explanation": "仮定形で、『ねじで板を組み立てれば』という条件を表し、『本棚になる』へ続く。"}, {"text": "組み立てよう", "is_correct": false, "explanation": "意志形は『ば』と続かず、『本棚になる』へつながる条件節として成り立たない。"}, {"text": "組み立てなかった", "is_correct": false, "explanation": "過去の否定形は『ば』と続かず、条件節として文が成り立たない。"}, {"text": "組み立てなければ", "is_correct": false, "explanation": "否定の仮定形だと組み立てない場合に本棚になるという意味になり、文の内容と矛盾する。"}], "correct_form": "組み立てれば", "base_form": "組み立てる", "form_label": "仮定形", "sentence_index": 7, "explanations": {"組み立てれば": "仮定形で、『ねじで板を組み立てれば』という条件を表し、『本棚になる』へ続く。", "組み立てよう": "意志形は『ば』と続かず、『本棚になる』へつながる条件節として成り立たない。", "組み立てなかった": "過去の否定形は『ば』と続かず、条件節として文が成り立たない。", "組み立てなければ": "否定の仮定形だと組み立てない場合に本棚になるという意味になり、文の内容と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
