INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39737, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『部分に』で結果の形を示し、直後の『組み立てた』に直接つながる。"}, {"text": "を", "is_correct": false, "explanation": "『授業を三つの部分を組み立てた』は目的語が二つになり、不自然。"}, {"text": "が", "is_correct": false, "explanation": "『部分が組み立てた』は部分が主語になり、目的語を欠くため不自然。"}, {"text": "へ", "is_correct": false, "explanation": "『部分へ組み立てた』は方向を示すが、結果の形を表す文脈に合わない。"}], "correct_answer": "に", "explanations": {"に": "『部分に』で結果の形を示し、直後の『組み立てた』に直接つながる。", "を": "『授業を三つの部分を組み立てた』は目的語が二つになり、不自然。", "が": "『部分が組み立てた』は部分が主語になり、目的語を欠くため不自然。", "へ": "『部分へ組み立てた』は方向を示すが、結果の形を表す文脈に合わない。"}, "error_tags": {"を": "double_object", "が": "subject", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39737, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数の部品や要素を、順序や決まりに従って、一つのまとまった形にすること。", "primary_collocate": null, "pronunciation": "くみたてる", "ipa": "kɯmitateɾɯ", "syllable_count": 5, "sentences": [{"text": "彼は事実を順に並べて、わかりやすい説明を組み立てた。", "target_word": "組み立てた", "complexity_tier": "T4", "furigana": "彼[かれ]は事実[じじつ]を順[じゅん]に並[なら]べて、わかりやすい説明[せつめい]を組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "論文を書く前に、話の流れを組み立てる。", "target_word": "組み立てる", "complexity_tier": "T3", "furigana": "論文[ろんぶん]を書[か]く前[まえ]に、話[はなし]の流[なが]れを組[く]み立[た]てる。", "sentence_source": "generated"}, {"text": "作家は、事件の順序を考えながら物語を組み立てている。", "target_word": "組み立てている", "complexity_tier": "T4", "furigana": "作家[さっか]は、事件[じけん]の順序[じゅんじょ]を考[かんが]えながら物語[ものがたり]を組[く]み立[た]てている。", "sentence_source": "generated"}, {"text": "理由を組み立てて話せば、相手にも伝わりやすい。", "target_word": "組み立てて", "complexity_tier": "T3", "furigana": "理由[りゆう]を組[く]み立[た]てて話[はな]せば、相手[あいて]にも伝[つた]わりやすい。", "sentence_source": "generated"}, {"text": "弁護士は証拠をもとに、主張を組み立てた。", "target_word": "組み立てた", "complexity_tier": "T4", "furigana": "弁護士[べんごし]は証拠[しょうこ]をもとに、主張[しゅちょう]を組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "計画を組み立てるときは、時間の順番が大切だ。", "target_word": "組み立てる", "complexity_tier": "T3", "furigana": "計画[けいかく]を組[く]み立[た]てるときは、時間[じかん]の順番[じゅんばん]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "英語で文を組み立てるのは、まだ難しい。", "target_word": "組み立てる", "complexity_tier": "T3", "furigana": "英語[えいご]で文[ぶん]を組[く]み立[た]てるのは、まだ難[むずか]しい。", "sentence_source": "generated"}, {"text": "先生は、授業を三つの部分に組み立てた。", "target_word": "組み立てた", "complexity_tier": "T3", "furigana": "先生[せんせい]は、授業[じゅぎょう]を三[みっ]つの部分[ぶぶん]に組[く]み立[た]てた。", "sentence_source": "generated"}, {"text": "筋の通った理論を組み立てるには、たくさんの資料が必要だ。", "target_word": "組み立てる", "complexity_tier": "T4", "furigana": "筋[すじ]の通[とお]った理論[りろん]を組[く]み立[た]てるには、たくさんの資料[しりょう]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "弁論大会のために、原稿の構成を組み立てた。", "target_word": "組み立てた", "complexity_tier": "T3", "furigana": "べんろんたいかい[弁論大会]のために、げんこう[原稿]のこうせい[構成]を組[く]み立[た]てた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組み立てる", "label": "終止形"}, {"form": "組み立てた", "label": "過去形"}, {"form": "組み立てて", "label": "て形"}, {"form": "組み立てない", "label": "否定形"}, {"form": "組み立てるとき", "label": "連体形"}], "register": "中立", "sense_fingerprint": "考えや事実などの要素を順序立てて並べ、筋の通った計画・説明・文章にまとめる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組み立てた", "is_correct": true, "explanation": "過去形で、彼が事実を順に並べて説明をまとめ上げたことを表す。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形のままでは文が途中で切れ、述語にならない。"}, {"text": "組み立てられ", "is_correct": false, "explanation": "連用形の受身では文が終わらず、『彼は』が主語の文として成り立たない。"}, {"text": "組み立て", "is_correct": false, "explanation": "連用形の名詞形では文が終わらず、述語として成り立たない。"}], "explanations": {"組み立てた": "過去形で、彼が事実を順に並べて説明をまとめ上げたことを表す。", "組み立てて": "て形のままでは文が途中で切れ、述語にならない。", "組み立てられ": "連用形の受身では文が終わらず、『彼は』が主語の文として成り立たない。", "組み立て": "連用形の名詞形では文が終わらず、述語として成り立たない。"}, "sentence_index": 0, "correct_answer": "組み立てた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は布を赤く組み立てた。", "explanation": "ここは〈染める〉の意味。〈組み立てる〉は要素を筋道立てて一つにまとめる意味で、布の色を変える動作には使わないので不自然。"}, {"text": "彼女は窓から海を組み立てた。", "explanation": "ここは〈眺める〉の意味。〈組み立てる〉は要素をまとめる意味で、景色を見る動作には使わないので不自然。"}, {"text": "今日の天気を組み立てた。", "explanation": "ここは〈予報する〉の意味。天気は組み立てるものではなく、〈組み立てる〉は予想の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組み立てる", "is_correct": true, "explanation": "辞書形で、『英語で文を組み立てるのは難しい』と主語の『こと』を述べる文に合う。"}, {"text": "組み立てよう", "is_correct": false, "explanation": "意志形は『〜のは』の名詞節に続かず、『英語で文を組み立てようのは』は成り立たない。"}, {"text": "組み立てれば", "is_correct": false, "explanation": "仮定形は条件を表し、『〜のは難しい』の主語となる名詞節にならない。"}, {"text": "組み立てたら", "is_correct": false, "explanation": "たら形は条件を表し、『〜のは難しい』の主語節にならない。"}], "explanations": {"組み立てる": "辞書形で、『英語で文を組み立てるのは難しい』と主語の『こと』を述べる文に合う。", "組み立てよう": "意志形は『〜のは』の名詞節に続かず、『英語で文を組み立てようのは』は成り立たない。", "組み立てれば": "仮定形は条件を表し、『〜のは難しい』の主語となる名詞節にならない。", "組み立てたら": "たら形は条件を表し、『〜のは難しい』の主語節にならない。"}, "sentence_index": 6, "correct_answer": "組み立てる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は突然の知らせを組み立てた。", "explanation": "ここは〈驚く〉の意味。〈組み立てる〉は要素をまとめる意味で、知らせに心が動く反応は表せないので不自然。"}, {"text": "妹は毎朝、ジョギングで体を組み立てた。", "explanation": "ここは〈鍛える〉の意味。〈組み立てる〉は要素をまとめる意味で、体を強くする動作には使わないので不自然。"}, {"text": "原稿の表紙を組み立てた。", "explanation": "ここは〈製本する〉の意味。表紙を作る場面は〈組み立てる〉では表せず、構成の意味とも違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39737, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は資料を順に並べて、わかりやすい説明が組み立てた。", "corrected_sentence": "彼は資料を順に並べて、わかりやすい説明を組み立てた。", "error_description": "助詞の誤り。他動詞『組み立てる』の目的語は『を』で示す。『が』では目的語がなく、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "組み立てる", "is_correct": true, "explanation": "辞書形で、論文を書く前にする動作を述べる文末に合う。"}, {"text": "組み立てたら", "is_correct": false, "explanation": "たら形は条件節で、文末にはならない。『論文を書く前に、話の流れを組み立てたら』では文が途中で切れる。"}, {"text": "組み立てて", "is_correct": false, "explanation": "て形は文末にならず、文が途中で切れる。"}, {"text": "組み立てない", "is_correct": false, "explanation": "否定形だと『組み立てない』の意味になり、前置きの文の意図と矛盾する。"}], "correct_form": "組み立てる", "base_form": "組み立てる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"組み立てる": "辞書形で、論文を書く前にする動作を述べる文末に合う。", "組み立てたら": "たら形は条件節で、文末にはならない。『論文を書く前に、話の流れを組み立てたら』では文が途中で切れる。", "組み立てて": "て形は文末にならず、文が途中で切れる。", "組み立てない": "否定形だと『組み立てない』の意味になり、前置きの文の意図と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39737, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "論文の構成が、三つの章に組み立てた。", "corrected_sentence": "論文の構成を、三つの章に組み立てた。", "error_description": "助詞の誤り。他動詞『組み立てる』の目的語は『を』で示す。『が』では目的語がなく、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "組み立てた", "is_correct": true, "explanation": "過去形で、先生が授業を三つの部分にまとめた完了の動作を表す。"}, {"text": "組み立てず", "is_correct": false, "explanation": "連用形の否定で、文末にはならず、『授業を三つの部分に組み立てず』では文が途中で切れる。"}, {"text": "組み立てれば", "is_correct": false, "explanation": "仮定形は条件節で、文末にはならず、『授業を三つの部分に組み立てれば』では文が途中で切れる。"}, {"text": "組み立てられた", "is_correct": false, "explanation": "受身にすると『先生』が組み立てられる側になり、『先生は授業を組み立てた』という意味と矛盾する。"}], "correct_form": "組み立てた", "base_form": "組み立てる", "form_label": "過去形", "sentence_index": 7, "explanations": {"組み立てた": "過去形で、先生が授業を三つの部分にまとめた完了の動作を表す。", "組み立てず": "連用形の否定で、文末にはならず、『授業を三つの部分に組み立てず』では文が途中で切れる。", "組み立てれば": "仮定形は条件節で、文末にはならず、『授業を三つの部分に組み立てれば』では文が途中で切れる。", "組み立てられた": "受身にすると『先生』が組み立てられる側になり、『先生は授業を組み立てた』という意味と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「名前の札」は取り付ける対象（目的語）なので、「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「札が取り付ける」では目的語がなく、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点や出どころを示す。取り付ける対象を示せず、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示す。「札と取り付ける」では対象を示せず、不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「名前の札」は取り付ける対象（目的語）なので、「を」で示す。", "が": "「が」は主語を示す。「札が取り付ける」では目的語がなく、文が成り立たない。", "から": "「から」は起点や出どころを示す。取り付ける対象を示せず、意味が通らない。", "と": "「と」は共同の相手を示す。「札と取り付ける」では対象を示せず、不自然になる。"}, "error_tags": {"が": "主格", "から": "起点", "と": "共同"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取り外す", "is_correct": true, "explanation": "くっつけたものを外す意味で、「取り付ける」の対義語。"}, {"text": "差し込む", "is_correct": false, "explanation": "穴や隙間に入れる動作で、くっつけるの対義語ではない。"}, {"text": "結びつける", "is_correct": false, "explanation": "つなぎ合わせる意味で、「取り付ける」に近い語であり、対義語ではない。"}, {"text": "引き継ぐ", "is_correct": false, "explanation": "仕事や立場を受け渡す意味で、物をくっつける動作とは関係がなく、対義語ではない。"}], "correct_answer": "取り外す", "explanations": {"取り外す": "くっつけたものを外す意味で、「取り付ける」の対義語。", "差し込む": "穴や隙間に入れる動作で、くっつけるの対義語ではない。", "結びつける": "つなぎ合わせる意味で、「取り付ける」に近い語であり、対義語ではない。", "引き継ぐ": "仕事や立場を受け渡す意味で、物をくっつける動作とは関係がなく、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「荷物用の箱」は取り付ける対象（目的語）なので、「を」で示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞をつなぐだけで、「箱の取り付けている」では動詞の目的語にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「箱へ取り付けている」では対象を示せず、意味が不明確になる。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は対象を示せず、「箱より取り付けている」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「荷物用の箱」は取り付ける対象（目的語）なので、「を」で示す。", "の": "連体修飾の「の」は名詞をつなぐだけで、「箱の取り付けている」では動詞の目的語にならず、文が成り立たない。", "へ": "方向を示す「へ」は、「箱へ取り付けている」では対象を示せず、意味が不明確になる。", "より": "比較の「より」は対象を示せず、「箱より取り付けている」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "より": "比較"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取り外す", "is_correct": true, "explanation": "くっつけたものを外す意味で、「取り付ける」の対義語。"}, {"text": "持ち上げる", "is_correct": false, "explanation": "物を高く上げる動作で、くっつけるの対義語ではない。"}, {"text": "埋め込む", "is_correct": false, "explanation": "物を中に入れて固定する意味で、「取り付ける」に近い語だが、対義語ではない。"}, {"text": "押し付ける", "is_correct": false, "explanation": "強く押し当てる意味で、くっつけるの仲間の動作だが、対義語ではない。"}], "correct_answer": "取り外す", "explanations": {"取り外す": "くっつけたものを外す意味で、「取り付ける」の対義語。", "持ち上げる": "物を高く上げる動作で、くっつけるの対義語ではない。", "埋め込む": "物を中に入れて固定する意味で、「取り付ける」に近い語だが、対義語ではない。", "押し付ける": "強く押し当てる意味で、くっつけるの仲間の動作だが、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを、別のものにくっつけること。", "primary_collocate": null, "pronunciation": "とりつける", "ipa": "toɾit͡sɯkeɾɯ", "syllable_count": 5, "sentences": [{"text": "母はカーテンに、小さなリボンを取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "母[はは]はカーテンに、小[ちい]さなリボンを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "かばんに名前の札を取り付ける。", "target_word": "取り付ける", "complexity_tier": "T3", "furigana": "かばんに名前[なまえ]の札[ふだ]を取[と]り付[つ]ける。", "sentence_source": "generated"}, {"text": "子どもの自転車に、かごを取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "子[こ]どもの自転車[じてんしゃ]に、かごを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "古い扉に新しい取っ手を取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "古[ふる]い扉[とびら]に新[あたら]しい取[と]っ手[て]を取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "ランドセルに、防犯ブザーを取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "ランドセルに、防犯[ぼうはん]ブザーを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "棒の先にブラシを取り付けて、天井を掃除する。", "target_word": "取り付けて", "complexity_tier": "T4", "furigana": "棒[ぼう]の先[さき]にブラシを取[と]り付[つ]けて、天井[てんじょう]を掃除[そうじ]する。", "sentence_source": "generated"}, {"text": "壁に、鏡を取り付けたいと思っている。", "target_word": "取り付けたい", "complexity_tier": "T3", "furigana": "壁[かべ]に、鏡[かがみ]を取[と]り付[つ]けたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "車のうしろに、荷物用の箱を取り付けている。", "target_word": "取り付けている", "complexity_tier": "T3", "furigana": "車[くるま]のうしろに、荷物用[にもつよう]の箱[はこ]を取[と]り付[つ]けている。", "sentence_source": "generated"}, {"text": "取り付けた飾りが、風で落ちてしまった。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "取[と]り付[つ]けた飾[かざ]りが、風[かぜ]で落[お]ちてしまった。", "sentence_source": "generated"}, {"text": "窓の外に、小さな鳥の巣箱を取り付ける。", "target_word": "取り付ける", "complexity_tier": "T3", "furigana": "窓[まど]の外[そと]に、小[ちい]さな鳥[とり]の巣箱[すばこ]を取[と]り付[つ]ける。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り付ける", "label": "終止形"}, {"form": "取り付けた", "label": "過去形"}, {"form": "取り付けて", "label": "て形"}, {"form": "取り付けない", "label": "否定形"}, {"form": "取り付けたい", "label": "願望形"}], "register": "中立", "sense_fingerprint": "小さな物や飾りなどを、別の物にくっつけて付ける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り付けた", "is_correct": true, "explanation": "過去の出来事を述べる普通形で、「リボンを」を目的語にとる他動詞として文の述語になる。"}, {"text": "取り付いた", "is_correct": false, "explanation": "「取り付く」は自動詞で「〜に取り付く（まとわりつく）」の形をとる。「小さなリボンを」の目的語とは合わない。"}, {"text": "取り付けられた", "is_correct": false, "explanation": "受身形にすると「リボン」が主語の位置に移り、「母は」を動作主とする文の構造が崩れる。"}, {"text": "取り付けて", "is_correct": false, "explanation": "て形は文を続けるための形で、ここでは述語として文を終えられない。"}], "explanations": {"取り付けた": "過去の出来事を述べる普通形で、「リボンを」を目的語にとる他動詞として文の述語になる。", "取り付いた": "「取り付く」は自動詞で「〜に取り付く（まとわりつく）」の形をとる。「小さなリボンを」の目的語とは合わない。", "取り付けられた": "受身形にすると「リボン」が主語の位置に移り、「母は」を動作主とする文の構造が崩れる。", "取り付けて": "て形は文を続けるための形で、ここでは述語として文を終えられない。"}, "sentence_index": 0, "correct_answer": "取り付けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい課題に、毎日取り付けている。", "explanation": "ここは〈取り組む（力を注いで努力する）〉の意味。取り付けるは〈くっつける〉なので、課題に力を注ぐ文には合わない。"}, {"text": "遠くの店から本を取り付けた。", "explanation": "ここは〈取り寄せる（注文して届けてもらう）〉の意味。取り付けるは〈くっつける〉なので、注文して手に入れる文には使えない。"}, {"text": "盗まれた財布を取り付けた。", "explanation": "ここは〈取り戻す〉の意味。取り付けるは〈くっつける〉なので、盗まれたものを取り戻す文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り付けたい", "is_correct": true, "explanation": "願望形で、「〜たいと思っている」と続いて、鏡を付けたいという希望を表す。"}, {"text": "取り付け", "is_correct": false, "explanation": "連用形（名詞形）で、「〜たい」に続かず、文の述語として完結しない。"}, {"text": "取り付きたい", "is_correct": false, "explanation": "「取り付く」の願望形で、目的語に「を」をとれず、「鏡を」と合わない。"}, {"text": "取り付けられたい", "is_correct": false, "explanation": "受身の願望形になると「鏡を」が主語の位置に移り、文の構造が崩れる。"}], "explanations": {"取り付けたい": "願望形で、「〜たいと思っている」と続いて、鏡を付けたいという希望を表す。", "取り付け": "連用形（名詞形）で、「〜たい」に続かず、文の述語として完結しない。", "取り付きたい": "「取り付く」の願望形で、目的語に「を」をとれず、「鏡を」と合わない。", "取り付けられたい": "受身の願望形になると「鏡を」が主語の位置に移り、文の構造が崩れる。"}, "sentence_index": 6, "correct_answer": "取り付けたい"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい意見を計画に取り付けた。", "explanation": "ここは〈取り入れる（新しい考えを取り込んで使う）〉の意味。「取り付ける」は物を固定する意味なので、意見を計画に組み込む文には使えない。"}, {"text": "古い電球を新しいものに取り付けた。", "explanation": "ここは〈取り替える〉の意味。「取り付ける」は新たに付ける意味で、古いものを別のものに替える文では使えない。"}, {"text": "この店では、輸入品の雑貨を取り付けている。", "explanation": "ここは〈取り扱う（商品を仕入れて売る）〉の意味。「取り付ける」は固定する意味なので、商品を店で扱う文には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は玄関に鍵が取り付けた。", "corrected_sentence": "兄は玄関に鍵を取り付けた。", "error_description": "誤りは「鍵が」の「が」。「取り付けた」は他動詞なので、取り付ける対象の「鍵」に「を」を付ける。「が」にすると鍵が主語になり、目的語がなくなる。正しくは「鍵を取り付けた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り付ける", "is_correct": true, "explanation": "終止形で、文末で言い切る形。かばんに札を付けるという動作を述べる文の述語として正しい。"}, {"text": "取り付けたら", "is_correct": false, "explanation": "たら形は条件節で、文末にはならない。『かばんに名前の札を取り付けたら』では文が途中で切れる。"}, {"text": "取り付けて", "is_correct": false, "explanation": "て形で、文を続けるための形。単独では文末にならない。"}, {"text": "取り付けない", "is_correct": false, "explanation": "否定形で、札を付けないという逆の内容になり、この文の意味と合わない。"}], "correct_form": "取り付ける", "base_form": "取り付ける", "form_label": "終止形", "sentence_index": 1, "explanations": {"取り付ける": "終止形で、文末で言い切る形。かばんに札を付けるという動作を述べる文の述語として正しい。", "取り付けたら": "たら形は条件節で、文末にはならない。『かばんに名前の札を取り付けたら』では文が途中で切れる。", "取り付けて": "て形で、文を続けるための形。単独では文末にならない。", "取り付けない": "否定形で、札を付けないという逆の内容になり、この文の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39738, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いテレビに、新しいアンテナを取り付けるた。", "corrected_sentence": "古いテレビに、新しいアンテナを取り付けた。", "error_description": "誤りは「取り付けるた」の「る」。過去形は「取り付けた」で、動詞の語尾「る」は付かない。正しくは「取り付けた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り付けている", "is_correct": true, "explanation": "「〜ている」の形で、箱を付けた状態や動作の継続を表し、車に箱がある場面に合う。"}, {"text": "取り付けて", "is_correct": false, "explanation": "て形は文を続けるための形で、文末にはならない。"}, {"text": "取り付けなかった", "is_correct": false, "explanation": "過去の否定形で、付けなかったという逆の内容になり、この文の意味と合わない。"}, {"text": "取り付け", "is_correct": false, "explanation": "連用形で文が終わらず、述語として成り立たない。"}], "correct_form": "取り付けている", "base_form": "取り付ける", "form_label": "〜ている形", "sentence_index": 7, "explanations": {"取り付けている": "「〜ている」の形で、箱を付けた状態や動作の継続を表し、車に箱がある場面に合う。", "取り付けて": "て形は文を続けるための形で、文末にはならない。", "取り付けなかった": "過去の否定形で、付けなかったという逆の内容になり、この文の意味と合わない。", "取り付け": "連用形で文が終わらず、述語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手すり」は取り付ける対象（目的語）なので、「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「手すりが取り付ける」では目的語がなく、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示す。取り付ける対象を示せず、意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は対象を示せず、「手すりより取り付ける」では意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「手すり」は取り付ける対象（目的語）なので、「を」で示す。", "が": "「が」は主語を示す。「手すりが取り付ける」では目的語がなく、文が成り立たない。", "から": "「から」は起点を示す。取り付ける対象を示せず、意味が通らない。", "より": "比較の「より」は対象を示せず、「手すりより取り付ける」では意味が通らない。"}, "error_tags": {"が": "主格", "から": "起点", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取り外す", "is_correct": true, "explanation": "くっつけたものを外す意味で、「取り付ける」の対義語。"}, {"text": "取り替える", "is_correct": false, "explanation": "古いものを新しいものに替える意味で、くっつけるの対義語ではない。"}, {"text": "組み込む", "is_correct": false, "explanation": "全体の中に入れて一体にする意味で、対義語ではない。"}, {"text": "持ち上げる", "is_correct": false, "explanation": "物を高く上げる動作で、くっつけるの対義語ではない。"}], "correct_answer": "取り外す", "explanations": {"取り外す": "くっつけたものを外す意味で、「取り付ける」の対義語。", "取り替える": "古いものを新しいものに替える意味で、くっつけるの対義語ではない。", "組み込む": "全体の中に入れて一体にする意味で、対義語ではない。", "持ち上げる": "物を高く上げる動作で、くっつけるの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「補助の鍵」は取り付ける対象（目的語）なので、「を」で示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞をつなぐだけで、「鍵の取り付ける」では目的語にならず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、「鍵へ取り付ける」では対象を示せず、不自然になる。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示す。「鍵と取り付ける」では対象を示せず、不自然になる。"}], "correct_answer": "を", "explanations": {"を": "「補助の鍵」は取り付ける対象（目的語）なので、「を」で示す。", "の": "連体修飾の「の」は名詞をつなぐだけで、「鍵の取り付ける」では目的語にならず、文が成り立たない。", "へ": "方向を示す「へ」は、「鍵へ取り付ける」では対象を示せず、不自然になる。", "と": "「と」は共同の相手を示す。「鍵と取り付ける」では対象を示せず、不自然になる。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "と": "共同"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取り外す", "is_correct": true, "explanation": "くっつけたものを外す意味で、「取り付ける」の対義語。"}, {"text": "差し込む", "is_correct": false, "explanation": "穴や隙間に入れる動作で、くっつけるの対義語ではない。"}, {"text": "結びつける", "is_correct": false, "explanation": "つなぎ合わせる意味で、「取り付ける」に近い語であり、対義語ではない。"}, {"text": "押し付ける", "is_correct": false, "explanation": "強く押し当てる意味で、対義語ではない。"}], "correct_answer": "取り外す", "explanations": {"取り外す": "くっつけたものを外す意味で、「取り付ける」の対義語。", "差し込む": "穴や隙間に入れる動作で、くっつけるの対義語ではない。", "結びつける": "つなぎ合わせる意味で、「取り付ける」に近い語であり、対義語ではない。", "押し付ける": "強く押し当てる意味で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を他の物に固定したり、接続したりすること。", "primary_collocate": null, "pronunciation": "とりつける", "ipa": "toɾit͡sɯkeɾɯ", "syllable_count": 5, "sentences": [{"text": "業者が来て、リビングにエアコンを取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "業者[ぎょうしゃ]が来[き]て、リビングにエアコンを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "階段に手すりを取り付ける工事が始まった。", "target_word": "取り付ける", "complexity_tier": "T3", "furigana": "階段[かいだん]に手[て]すりを取[と]り付[つ]ける工事[こうじ]が始[はじ]まった。", "sentence_source": "generated"}, {"text": "防犯のために、玄関にカメラを取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "防犯[ぼうはん]のために、玄関[げんかん]にカメラを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "天井に照明を取り付けるには、電気の知識が必要だ。", "target_word": "取り付ける", "complexity_tier": "T4", "furigana": "天井[てんじょう]に照明[しょうめい]を取[と]り付[つ]けるには、電気[でんき]の知識[ちしき]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "壁に新しい棚を取り付けて、本を並べた。", "target_word": "取り付けて", "complexity_tier": "T3", "furigana": "壁[かべ]に新[あたら]しい棚[たな]を取[と]り付[つ]けて、本[ほん]を並[なら]べた。", "sentence_source": "generated"}, {"text": "車にカーナビを取り付けてもらった。", "target_word": "取り付けて", "complexity_tier": "T3", "furigana": "車[くるま]にカーナビを取[と]り付[つ]けてもらった。", "sentence_source": "generated"}, {"text": "古い洗濯機に、新しいホースを取り付けた。", "target_word": "取り付けた", "complexity_tier": "T3", "furigana": "古[ふる]い洗濯機[せんたくき]に、新[あたら]しいホースを取[と]り付[つ]けた。", "sentence_source": "generated"}, {"text": "窓に補助の鍵を取り付ける。", "target_word": "取り付ける", "complexity_tier": "T3", "furigana": "窓[まど]に補助[ほじょ]の鍵[かぎ]を取[と]り付[つ]ける。", "sentence_source": "generated"}, {"text": "ドアにチャイムを取り付ければ、来客がすぐわかる。", "target_word": "取り付ければ", "complexity_tier": "T3", "furigana": "ドアにチャイムを取[と]り付[つ]ければ、来客[らいきゃく]がすぐわかる。", "sentence_source": "generated"}, {"text": "自転車のライトを取り付けるのを、兄が手伝ってくれた。", "target_word": "取り付ける", "complexity_tier": "T4", "furigana": "自転車[じてんしゃ]のライトを取[と]り付[つ]けるのを、兄[あに]が手伝[てつだ]ってくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り付ける", "label": "終止形"}, {"form": "取り付けた", "label": "過去形"}, {"form": "取り付けて", "label": "て形"}, {"form": "取り付けない", "label": "否定形"}, {"form": "取り付ければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "器具や設備などを、壁や機械にしっかり固定したりつないだりして設置する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa599fdd-99a2-4477-850d-2b44375a5a03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り付けた", "is_correct": true, "explanation": "過去形で、エアコンを付けた出来事を述べる普通形。文の述語として正しい。"}, {"text": "取り付く", "is_correct": false, "explanation": "自動詞で、目的語に「を」をとれない。「エアコンを」と合わない。"}, {"text": "取り付け", "is_correct": false, "explanation": "連用形で、文を終えられず、述語にならない。"}, {"text": "取り付けて", "is_correct": false, "explanation": "て形で、文を続けるための形。単独では文末にならない。"}], "explanations": {"取り付けた": "過去形で、エアコンを付けた出来事を述べる普通形。文の述語として正しい。", "取り付く": "自動詞で、目的語に「を」をとれない。「エアコンを」と合わない。", "取り付け": "連用形で、文を終えられず、述語にならない。", "取り付けて": "て形で、文を続けるための形。単独では文末にならない。"}, "sentence_index": 0, "correct_answer": "取り付けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来客のために、お茶を取り付けた。", "explanation": "ここは〈用意する〉の意味。「取り付ける」は物を固定する意味なので、飲み物を準備する文には使えない。"}, {"text": "大皿から、サラダを取り付けた。", "explanation": "ここは〈取り分ける〉の意味。「取り付ける」は固定する意味なので、料理を分けて皿に盛る文には合わない。"}, {"text": "警察が犯人を取り付けた。", "explanation": "ここは〈取り囲む（周りを囲む）〉の意味。「取り付ける」は物を固定する意味なので、人を取り囲む場面には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り付けた", "is_correct": true, "explanation": "過去形で、ホースを付けた出来事を述べる普通形。文の述語として正しい。"}, {"text": "取り付けられた", "is_correct": false, "explanation": "受身形にすると「ホース」が主語の位置に移り、「ホースを取り付けられた」は文が成り立たない。"}, {"text": "取り付いた", "is_correct": false, "explanation": "自動詞で「〜に取り付く」の形をとる。「ホースを」の目的語とは合わない。"}, {"text": "取り付けに", "is_correct": false, "explanation": "「取り付け」に助詞「に」が付いた形で、文の述語にならず、文を完結させられない。"}], "explanations": {"取り付けた": "過去形で、ホースを付けた出来事を述べる普通形。文の述語として正しい。", "取り付けられた": "受身形にすると「ホース」が主語の位置に移り、「ホースを取り付けられた」は文が成り立たない。", "取り付いた": "自動詞で「〜に取り付く」の形をとる。「ホースを」の目的語とは合わない。", "取り付けに": "「取り付け」に助詞「に」が付いた形で、文の述語にならず、文を完結させられない。"}, "sentence_index": 6, "correct_answer": "取り付けた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古いビルを取り付けた。", "explanation": "ここは〈取り壊す〉の意味。「取り付ける」は付ける意味なので、建物を壊す文には使えない。"}, {"text": "先生は、生徒の意見を取り付けた。", "explanation": "ここは〈取り上げる（意見を採り入れる）〉の意味。「取り付ける」は物を固定する意味なので、意見を採用する文には使えない。"}, {"text": "結んだ袋のひもを取り付けて、中を見た。", "explanation": "ここは〈ほどく〉の意味。「取り付ける」は固定する意味なので、結び目をほどく文では使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台所の換気扇を取り付けるたのは、先月でした。", "corrected_sentence": "台所の換気扇を取り付けたのは、先月でした。", "error_description": "誤りは「取り付けるた」の「る」。過去形は「取り付けた」で、語尾「る」は付かない。正しくは「取り付けたのは」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "取り付ける", "is_correct": true, "explanation": "連体形で、後ろの名詞「工事」を修飾する形。辞書形と同じ形で、これから行う工事を説明できる。"}, {"text": "取り付けよう", "is_correct": false, "explanation": "意志形は名詞を修飾できず、『取り付けよう工事』は成り立たない。"}, {"text": "取り付けます", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、『取り付けます工事』は成り立たない。"}, {"text": "取り付けろ", "is_correct": false, "explanation": "命令形は名詞を修飾できず、『取り付けろ工事』は成り立たない。"}], "correct_form": "取り付ける", "base_form": "取り付ける", "form_label": "連体形", "sentence_index": 1, "explanations": {"取り付ける": "連体形で、後ろの名詞「工事」を修飾する形。辞書形と同じ形で、これから行う工事を説明できる。", "取り付けよう": "意志形は名詞を修飾できず、『取り付けよう工事』は成り立たない。", "取り付けます": "丁寧形は名詞を修飾できず、『取り付けます工事』は成り立たない。", "取り付けろ": "命令形は名詞を修飾できず、『取り付けろ工事』は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39739, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の外に、新しい物干し台と取り付けた。", "corrected_sentence": "窓の外に、新しい物干し台を取り付けた。", "error_description": "誤りは「物干し台と」の「と」。「取り付けた」の目的語は「物干し台」なので「を」が必要。「と」にすると対象を示せず、不自然な文になる。正しくは「物干し台を取り付けた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "取り付ける", "is_correct": true, "explanation": "終止形で、文末で言い切る形。鍵を付けるという動作を述べる文の述語として正しい。"}, {"text": "取り付けて", "is_correct": false, "explanation": "て形は文を続けるための形で、文末にはならない。"}, {"text": "取り付けなかった", "is_correct": false, "explanation": "過去の否定形で、付けなかったという逆の内容になり、この文の意味と合わない。"}, {"text": "取り付け", "is_correct": false, "explanation": "連用形で文が終わらず、述語として成り立たない。"}], "correct_form": "取り付ける", "base_form": "取り付ける", "form_label": "終止形", "sentence_index": 7, "explanations": {"取り付ける": "終止形で、文末で言い切る形。鍵を付けるという動作を述べる文の述語として正しい。", "取り付けて": "て形は文を続けるための形で、文末にはならない。", "取り付けなかった": "過去の否定形で、付けなかったという逆の内容になり、この文の意味と合わない。", "取り付け": "連用形で文が終わらず、述語として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5885665b-2e58-435c-8506-65f1f39d5ad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "醍醐を話題（主題）として示す「は」。文頭の名詞を話題にするので、ここに合う。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語に付く。醍醐を主題とするこの文では、後の文の成分とつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所・相手・結果などを示す。醍醐を主題として述べる場面では合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示す。醍醐を文の主題とする位置には合わない。"}], "correct_answer": "は", "explanations": {"は": "醍醐を話題（主題）として示す「は」。文頭の名詞を話題にするので、ここに合う。", "を": "「を」は目的語に付く。醍醐を主題とするこの文では、後の文の成分とつながらない。", "に": "「に」は場所・相手・結果などを示す。醍醐を主題として述べる場面では合わない。", "で": "「で」は手段・場所を示す。醍醐を文の主題とする位置には合わない。"}, "error_tags": {"を": "目的語を示す", "に": "場所・相手を示す", "で": "手段・場所を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "再現する対象は醍醐そのものなので、目的語を示す「を」が入る。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所・相手を示す。醍醐を再現するという対象の関係には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示す。醍醐が再現の対象なので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。醍醐の後に動詞が続くので、対象を示す「を」が必要。"}], "correct_answer": "を", "explanations": {"を": "再現する対象は醍醐そのものなので、目的語を示す「を」が入る。", "に": "「に」は場所・相手を示す。醍醐を再現するという対象の関係には合わない。", "で": "「で」は手段・場所を示す。醍醐が再現の対象なので合わない。", "の": "「の」は名詞をつなぐ。醍醐の後に動詞が続くので、対象を示す「を」が必要。"}, "error_tags": {"に": "場所・相手を示す", "で": "手段・場所を示す", "の": "名詞をつなぐ"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "むかしの、ぎゅうにゅうから つくった とても おいしい もの。", "primary_collocate": null, "pronunciation": "だいご", "ipa": "daiɡo", "syllable_count": 3, "sentences": [{"text": "昔の人は、牛乳を煮詰めて醍醐という食べ物を作った。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "昔[むかし]の人[ひと]は、牛乳[ぎゅうにゅう]を煮詰[につ]めて醍醐[だいご]という食[た]べ物[もの]を作[つく]った。", "sentence_source": "generated"}, {"text": "醍醐は、平安時代の貴族だけが口にできた貴重な食べ物だった。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "醍醐[だいご]は、平安時代[へいあんじだい]の貴族[きぞく]だけが口[くち]にできた貴重[きちょう]な食[た]べ物[もの]だった。", "sentence_source": "generated"}, {"text": "古い書物には、醍醐はとても甘くておいしいと書かれている。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "古[ふる]い書物[しょもつ]には、醍醐[だいご]はとても甘[あま]くておいしいと書[か]かれている。", "sentence_source": "generated"}, {"text": "醍醐を作るにはたくさんの牛乳が必要で、とても高価だった。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "醍醐[だいご]を作[つく]るにはたくさんの牛乳[ぎゅうにゅう]が必要[ひつよう]で、とても高価[こうか]だった。", "sentence_source": "generated"}, {"text": "歴史の授業で、チーズやバターに似た醍醐のことを習った。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "歴史[れきし]の授業[じゅぎょう]で、チーズやバターに似[に]た醍醐[だいご]のことを習[なら]った。", "sentence_source": "generated"}, {"text": "昔は牛乳が貴重だったため、醍醐は薬としても大切にされた。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "昔[むかし]は牛乳[ぎゅうにゅう]が貴重[きちょう]だったため、醍醐[だいご]は薬[くすり]としても大切[たいせつ]にされた。", "sentence_source": "generated"}, {"text": "貴族は、醍醐を少しずつ味わって、その甘さを楽しんだという。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "貴族[きぞく]は、醍醐[だいご]を少[すこ]しずつ味[あじ]わって、その甘[あま]さを楽[たの]しんだという。", "sentence_source": "generated"}, {"text": "醍醐を再現しようと、牛乳を何時間も煮詰めてみた。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "醍醐[だいご]を再現[さいげん]しようと、牛乳[ぎゅうにゅう]を何時間[なんじかん]も煮詰[につ]めてみた。", "sentence_source": "generated"}, {"text": "醍醐は今ではほとんど見られないが、昔は宮中に献上された。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "醍醐[だいご]は今[いま]ではほとんど見[み]られないが、昔[むかし]は宮中[きゅうちゅう]に献上[けんじょう]された。", "sentence_source": "generated"}, {"text": "博物館の説明には、醍醐は牛乳から作った最高の味だと書いてあった。", "target_word": "醍醐", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]の説明[せつめい]には、醍醐[だいご]は牛乳[ぎゅうにゅう]から作[つく]った最高[さいこう]の味[あじ]だと書[か]いてあった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "醍醐", "label": "基本形"}], "register": "標準", "sense_fingerprint": "昔の日本で牛乳を煮詰めて作った、非常においしく貴重な食べ物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "醍醐", "is_correct": true, "explanation": "「〜という食べ物」の名前として、牛乳を煮詰めて作った昔の乳製品の醍醐が入る。"}, {"text": "書物", "is_correct": false, "explanation": "書物は本を指す語で、食べ物の名前にはならないため「書物という食べ物」は成り立たない。"}, {"text": "貴族", "is_correct": false, "explanation": "貴族は身分の高い人を指す語で、「〜という食べ物」の名前にはならない。"}, {"text": "授業", "is_correct": false, "explanation": "授業は学習の時間を指す語で、食べ物の名前として使えないので空欄には入らない。"}], "explanations": {"醍醐": "「〜という食べ物」の名前として、牛乳を煮詰めて作った昔の乳製品の醍醐が入る。", "書物": "書物は本を指す語で、食べ物の名前にはならないため「書物という食べ物」は成り立たない。", "貴族": "貴族は身分の高い人を指す語で、「〜という食べ物」の名前にはならない。", "授業": "授業は学習の時間を指す語で、食べ物の名前として使えないので空欄には入らない。"}, "sentence_index": 0, "correct_answer": "醍醐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今夜は醍醐のステーキを焼いて、家族で食べた。", "explanation": "〈牛肉〉の意味なら自然だが、醍醐は牛乳から作る昔の乳製品で、肉料理を指す語ではないので合わない。"}, {"text": "夜、醍醐を抱いて寝た。", "explanation": "〈猫〉の意味なら自然だが、醍醐は乳製品で、抱いて寝る対象にはならないので合わない。"}, {"text": "昨日の試合で、醍醐を三回も打った。", "explanation": "〈ボール〉の意味なら自然だが、醍醐は乳製品で、打つ対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "醍醐", "is_correct": true, "explanation": "味わう対象となる、昔の貴重な食べ物の醍醐が入る。"}, {"text": "書物", "is_correct": false, "explanation": "書物は味わうものではないので、「書物を少しずつ味わって」は成り立たない。"}, {"text": "宮中", "is_correct": false, "explanation": "宮中は場所を表す語で、味わう対象にはならない。"}, {"text": "平安時代", "is_correct": false, "explanation": "平安時代は時代の名前で、味わう対象にはならない。"}], "explanations": {"醍醐": "味わう対象となる、昔の貴重な食べ物の醍醐が入る。", "書物": "書物は味わうものではないので、「書物を少しずつ味わって」は成り立たない。", "宮中": "宮中は場所を表す語で、味わう対象にはならない。", "平安時代": "平安時代は時代の名前で、味わう対象にはならない。"}, "sentence_index": 6, "correct_answer": "醍醐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関の床に醍醐を塗って、ぴかぴかに磨いた。", "explanation": "〈ワックス〉の意味なら自然だが、醍醐は食べ物の乳製品で、床に塗る語ではないので合わない。"}, {"text": "祝いの席で、醍醐を注いで乾杯した。", "explanation": "〈ワイン〉の意味なら自然だが、醍醐は昔の乳製品で、酒を注いで乾杯する語ではないので合わない。"}, {"text": "朝食中に醍醐を読んだ。", "explanation": "〈新聞〉の意味なら自然だが、醍醐は読むものではない乳製品なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "醍醐に、牛乳を煮詰めて作る貴重な食べ物だった。", "corrected_sentence": "醍醐は、牛乳を煮詰めて作る貴重な食べ物だった。", "error_description": "醍醐を主題として示す「は」が正しい。「に」にすると、醍醐を主題とする文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "貴族たちは、醍醐にそっと味わって、その甘さを楽しんだ。", "corrected_sentence": "貴族たちは、醍醐をそっと味わって、その甘さを楽しんだ。", "error_description": "「味わう」は目的語に「を」を取る。「に」にすると、醍醐に味わうという文になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
