INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39742, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんあるものの中で、いちばん上や前にあること。", "primary_collocate": null, "pronunciation": "いちばん", "ipa": "itɕibaɴ", "syllable_count": 4, "sentences": [{"text": "走るのが速い彼は、運動会の徒競走で一番になった。", "target_word": "一番", "complexity_tier": "T3", "furigana": "走[はし]るのが速[はや]い彼[かれ]は、運動会[うんどうかい]の徒競走[ときょうそう]で一番[いちばん]になった。", "sentence_source": "generated"}, {"text": "一番前の席に座ると、先生の声がよく聞こえる。", "target_word": "一番", "complexity_tier": "T3", "furigana": "一番[いちばん]前[まえ]の席[せき]に座[すわ]ると、先生[せんせい]の声[こえ]がよく聞[き]こえる。", "sentence_source": "generated"}, {"text": "試験の結果が発表され、私の名前が一番上にあった。", "target_word": "一番", "complexity_tier": "T3", "furigana": "試験[しけん]の結果[けっか]が発表[はっぴょう]され、私[わたし]の名前[なまえ]が一番[いちばん]上[うえ]にあった。", "sentence_source": "generated"}, {"text": "彼女は全国大会で一番を取って、みんなを驚かせた。", "target_word": "一番", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は全国大会[ぜんこくたいかい]で一番[いちばん]を取[と]って、みんなを驚[おどろ]かせた。", "sentence_source": "generated"}, {"text": "発表の順番を決めるくじで、私が一番を引いた。", "target_word": "一番", "complexity_tier": "T3", "furigana": "発表[はっぴょう]の順番[じゅんばん]を決[き]めるくじで、私[わたし]が一番[いちばん]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "兄はいつも勉強をがんばるので、クラスで成績が一番だ。", "target_word": "一番", "complexity_tier": "T3", "furigana": "兄[あに]はいつも勉強[べんきょう]をがんばるので、クラスで成績[せいせき]が一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "一番になるために、毎日遅くまで練習を続けている。", "target_word": "一番", "complexity_tier": "T3", "furigana": "一番[いちばん]になるために、毎日[まいにち]遅[おそ]くまで練習[れんしゅう]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "駅に着いたとき、私は改札の一番前に並んでいた。", "target_word": "一番", "complexity_tier": "T3", "furigana": "駅[えき]に着[つ]いたとき、私[わたし]は改札[かいさつ]の一番[いちばん]前[まえ]に並[なら]んでいた。", "sentence_source": "generated"}, {"text": "リストの一番上に書いてある名前から順に呼ばれます。", "target_word": "一番", "complexity_tier": "T3", "furigana": "リストの一番[いちばん]上[うえ]に書[か]いてある名前[なまえ]から順[じゅん]に呼[よ]ばれます。", "sentence_source": "generated"}, {"text": "試合では一番になるより、全力を出すことが大事だと父は言う。", "target_word": "一番", "complexity_tier": "T3", "furigana": "試合[しあい]では一番[いちばん]になるより、全力[ぜんりょく]を出[だ]すことが大事[だいじ]だと父[ちち]は言[い]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一番", "label": "基本形"}], "register": "標準", "sense_fingerprint": "順位や位置が最初・最上位であること（1位、最前列、最上部）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 徒競走 (Zipf 2.14)']::text[], '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39742, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一番", "is_correct": true, "explanation": "徒競走で順位の1位になったことを表す「一番」が入り、文が通る。"}, {"text": "運動会", "is_correct": false, "explanation": "運動会は行事の名前で、「徒競走で運動会になった」とは言えない。"}, {"text": "全力", "is_correct": false, "explanation": "全力は力の程度を表す語で、「徒競走で全力になった」は成り立たない。"}, {"text": "食事", "is_correct": false, "explanation": "食事は行為の名前で、競走の結果を表す「〜になった」には合わない。"}], "explanations": {"一番": "徒競走で順位の1位になったことを表す「一番」が入り、文が通る。", "運動会": "運動会は行事の名前で、「徒競走で運動会になった」とは言えない。", "全力": "全力は力の程度を表す語で、「徒競走で全力になった」は成り立たない。", "食事": "食事は行為の名前で、競走の結果を表す「〜になった」には合わない。"}, "sentence_index": 0, "correct_answer": "一番"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの町には、一番も行ったことがない。", "explanation": "〈一度〉の意味なら自然だが、一番は順位や位置を表すので、回数の「一度も」とは言えないので合わない。"}, {"text": "家に一番でいて、外には出なかった。", "explanation": "〈一人〉の意味なら自然だが、一番は順位や位置を表すので、人数の「一人で」とは言えないので合わない。"}, {"text": "昨夜は一番中眠れなかった。", "explanation": "〈一晩〉の意味なら自然だが、一番は順位や位置を表すので、時間の「一晩中」の意味にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39742, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一番", "is_correct": true, "explanation": "「一番になるために」の「一番」が入り、順位の1位を目指す意味が通る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は気象の状態を表す語で、「天気になるために」は意味が通らない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所の名前で、「教室になるために」は成り立たない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は身体の重さを表す語で、「体重になるために」は意味が通らない。"}], "explanations": {"一番": "「一番になるために」の「一番」が入り、順位の1位を目指す意味が通る。", "天気": "天気は気象の状態を表す語で、「天気になるために」は意味が通らない。", "教室": "教室は場所の名前で、「教室になるために」は成り立たない。", "体重": "体重は身体の重さを表す語で、「体重になるために」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "一番"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は資料を一番ずつ配った。", "explanation": "〈一つずつ〉の意味なら自然だが、一番は順位や位置を表し、「ずつ」で数を配る意味にはならないので合わない。"}, {"text": "彼は会議で一番も話さなかった。", "explanation": "〈一言〉の意味なら自然だが、一番は順位や位置を表すので、「一言も」の意味にはならないので合わない。"}, {"text": "その出来事は、一番のひとときで消えた。", "explanation": "〈一瞬〉の意味なら自然だが、一番は順位を表すので、時間の短さを表す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39742, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は県大会で一番が取って、表彰台に立った。", "corrected_sentence": "彼女は県大会で一番を取って、表彰台に立った。", "error_description": "「取る」の目的語は「を」。「が」にすると一番が主語のように見えて不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39742, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は試合で一番が取り、チームを勝たせた。", "corrected_sentence": "彼は試合で一番を取り、チームを勝たせた。", "error_description": "「取る」の目的語は「を」。「が」にすると主語と誤解され、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
