INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39743, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "他のものと比べて、最も程度が大きいこと。また、最も優れていること。", "primary_collocate": null, "pronunciation": "いちばん", "ipa": "itɕibaɴ", "syllable_count": 4, "sentences": [{"text": "果物の中では、りんごが一番好きです。", "target_word": "一番", "complexity_tier": "T3", "furigana": "果物[くだもの]の中[なか]では、りんごが一番[いちばん]好[す]きです。", "sentence_source": "generated"}, {"text": "このクラスで一番背が高いのは田中さんだ。", "target_word": "一番", "complexity_tier": "T3", "furigana": "このクラスで一番[いちばん]背[せ]が高[たか]いのは田中[たなか]さんだ。", "sentence_source": "generated"}, {"text": "冬の中でも、一月が一番寒い。", "target_word": "一番", "complexity_tier": "T3", "furigana": "冬[ふゆ]の中[なか]でも、一月[いちがつ]が一番[いちばん]寒[さむ]い。", "sentence_source": "generated"}, {"text": "日本で一番高い山は富士山だ。", "target_word": "一番", "complexity_tier": "T3", "furigana": "日本[にほん]で一番[いちばん]高[たか]い山[やま]は富士山[ふじさん]だ。", "sentence_source": "generated"}, {"text": "疲れたときは、ゆっくりお風呂に入るのが一番だ。", "target_word": "一番", "complexity_tier": "T3", "furigana": "疲[つか]れたときは、ゆっくりお風呂[ふろ]に入[はい]るのが一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "道がわからないなら、駅員さんに聞くのが一番早い。", "target_word": "一番", "complexity_tier": "T3", "furigana": "道[みち]がわからないなら、駅員[えきいん]さんに聞[き]くのが一番[いちばん]早[はや]い。", "sentence_source": "generated"}, {"text": "今年の夏は毎日暑かったが、今日が一番暑かった。", "target_word": "一番", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は毎日[まいにち]暑[あつ]かったが、今日[きょう]が一番[いちばん]暑[あつ]かった。", "sentence_source": "generated"}, {"text": "風邪をひいたときは、よく寝るのが一番の薬になる。", "target_word": "一番", "complexity_tier": "T3", "furigana": "風邪[かぜ]をひいたときは、よく寝[ね]るのが一番[いちばん]の薬[くすり]になる。", "sentence_source": "generated"}, {"text": "五人の中で、彼女が一番歌が上手だ。", "target_word": "一番", "complexity_tier": "T3", "furigana": "五人[ごにん]の中[なか]で、彼女[かのじょ]が一番[いちばん]歌[うた]が上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "旅行で一番楽しかったのは、夜に星を見たことです。", "target_word": "一番", "complexity_tier": "T3", "furigana": "旅行[りょこう]で一番[いちばん]楽[たの]しかったのは、夜[よる]に星[ほし]を見[み]たことです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一番", "label": "基本形"}], "register": "標準", "sense_fingerprint": "比較の中で程度が最も大きいこと、最も優れていること（最も、何よりも）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28f064fe-63df-4b1e-8bdc-f091c478d36f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39743, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一番", "is_correct": true, "explanation": "「りんごが一番好き」の「一番」。比べた中で最も程度が大きいことを表す副詞で、ここに入る。"}, {"text": "果物", "is_correct": false, "explanation": "果物は名詞で「りんごが果物好き」とは言えず、程度を表せない。"}, {"text": "中", "is_correct": false, "explanation": "中は位置を表す名詞で、「りんごが中好き」とは言えない。"}, {"text": "夏", "is_correct": false, "explanation": "夏は季節の名詞で、「りんごが夏好き」は成り立たない。"}], "explanations": {"一番": "「りんごが一番好き」の「一番」。比べた中で最も程度が大きいことを表す副詞で、ここに入る。", "果物": "果物は名詞で「りんごが果物好き」とは言えず、程度を表せない。", "中": "中は位置を表す名詞で、「りんごが中好き」とは言えない。", "夏": "夏は季節の名詞で、「りんごが夏好き」は成り立たない。"}, "sentence_index": 0, "correct_answer": "一番"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この島は一番中暑い。", "explanation": "〈一年中〉の意味なら自然だが、一番は程度の比較を表すので、時間の「〜中」の意味にはならないので合わない。"}, {"text": "彼は一番まで諦めなかった。", "explanation": "〈最後まで〉の意味なら自然だが、一番は程度の最上を表し、時間の「最後まで」の意味にはならないので合わない。"}, {"text": "宿題は一番ずつ完成していった。", "explanation": "〈一つずつ〉の意味なら自然だが、一番は程度の最上を表すので、数を分ける「ずつ」とは合わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39743, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一番", "is_correct": true, "explanation": "「今日が一番暑かった」の「一番」。比べた中で最も程度が大きいことを表す副詞で、ここに入る。"}, {"text": "夏", "is_correct": false, "explanation": "夏は季節の名詞で、「今日が夏暑かった」は程度を表せず成り立たない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は天気の名詞で、「今日が雨暑かった」は成り立たない。"}, {"text": "冬", "is_correct": false, "explanation": "冬は季節の名詞で、「今日が冬暑かった」は意味が通らない。"}], "explanations": {"一番": "「今日が一番暑かった」の「一番」。比べた中で最も程度が大きいことを表す副詞で、ここに入る。", "夏": "夏は季節の名詞で、「今日が夏暑かった」は程度を表せず成り立たない。", "雨": "雨は天気の名詞で、「今日が雨暑かった」は成り立たない。", "冬": "冬は季節の名詞で、「今日が冬暑かった」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "一番"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家族と一番暮らしている。", "explanation": "〈一緒〉の意味なら自然だが、一番は程度の最上を表すので、「一緒に」の意味にはならないので合わない。"}, {"text": "大学から一番暮らしを始めた。", "explanation": "〈一人暮らし〉の意味なら自然だが、一番は程度の最上を表すので、単身で住む生活は表せないので合わない。"}, {"text": "彼は一番も読めなかった。", "explanation": "〈一文字〉の意味なら自然だが、一番は程度の最上を表すので、文字の数を表す「一文字も」とは言えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39743, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このチームで一番足が速くのは、山田くんだ。", "corrected_sentence": "このチームで一番足が速いのは、山田くんだ。", "error_description": "「速い」は形容詞で、名詞の「のは」の前では連体形の「速い」を使う。「速く」にすると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39743, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は、昔の写真を見るのが一番楽しくと言う。", "corrected_sentence": "祖父は、昔の写真を見るのが一番楽しいと言う。", "error_description": "「楽しい」は形容詞で、「〜と言う」の前では終止形の「楽しい」を使う。「楽しく」にすると文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f07170da-cdba-42cd-ba18-26fa6eed7cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「左に曲がる」の形で方向を表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「左が曲がります」だと左そのものが主語になり、曲がる人の動作にならない。"}, {"text": "で", "is_correct": false, "explanation": "「左で曲がります」は手段や場所を表すため、方向を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「左の曲がります」は名詞の後ろに動詞を続けられず、不自然。"}], "correct_answer": "に", "explanations": {"に": "「左に曲がる」の形で方向を表す。正解。", "が": "「左が曲がります」だと左そのものが主語になり、曲がる人の動作にならない。", "で": "「左で曲がります」は手段や場所を表すため、方向を示せない。", "の": "「左の曲がります」は名詞の後ろに動詞を続けられず、不自然。"}, "error_tags": {"が": "主語", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「左にある」の形で存在する場所を表す。正解。"}, {"text": "が", "is_correct": false, "explanation": "「左が窓は」となり、「左」が主語になって文の形が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「左で窓がある」は手段や場所の意味になり、存在の場所を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「左と窓」は並列を表すが、「ある」の場所を示す文には合わない。"}], "correct_answer": "に", "explanations": {"に": "「左にある」の形で存在する場所を表す。正解。", "が": "「左が窓は」となり、「左」が主語になって文の形が崩れる。", "で": "「左で窓がある」は手段や場所の意味になり、存在の場所を示せない。", "と": "「左と窓」は並列を表すが、「ある」の場所を示す文には合わない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "右（みぎ）ではない方（ほう）。反対（はんたい）の方。", "primary_collocate": null, "pronunciation": "ひだり", "ipa": "çidaɾi", "syllable_count": 3, "sentences": [{"text": "右ではなく、左の道を行ってください。", "target_word": "左", "complexity_tier": "T3", "furigana": "右(みぎ)ではなく、左(ひだり)の道(みち)を行(い)ってください。", "sentence_source": "generated"}, {"text": "信号を過ぎたら、左に曲がります。", "target_word": "左", "complexity_tier": "T3", "furigana": "信号(しんごう)を過(す)ぎたら、左(ひだり)に曲(ま)がります。", "sentence_source": "generated"}, {"text": "私は左の手でボールを投げます。", "target_word": "左", "complexity_tier": "T3", "furigana": "私(わたし)は左(ひだり)の手(て)でボールを投(な)げます。", "sentence_source": "generated"}, {"text": "駅は右ではなく左にあります。", "target_word": "左", "complexity_tier": "T3", "furigana": "駅(えき)は右(みぎ)ではなく左(ひだり)にあります。", "sentence_source": "generated"}, {"text": "日本では、車は道の左を走ります。", "target_word": "左", "complexity_tier": "T3", "furigana": "日本(にほん)では、車(くるま)は道(みち)の左(ひだり)を走(はし)ります。", "sentence_source": "generated"}, {"text": "本棚の左から二番目の本を取ってください。", "target_word": "左", "complexity_tier": "T3", "furigana": "本棚(ほんだな)の左(ひだり)から二番目(にばんめ)の本(ほん)を取(と)ってください。", "sentence_source": "generated"}, {"text": "右の靴ではなく、左の靴をなくしました。", "target_word": "左", "complexity_tier": "T3", "furigana": "右(みぎ)の靴(くつ)ではなく、左(ひだり)の靴(くつ)をなくしました。", "sentence_source": "generated"}, {"text": "教室の左にある窓は、朝になると明るくなります。", "target_word": "左", "complexity_tier": "T3", "furigana": "教室(きょうしつ)の左(ひだり)にある窓(まど)は、朝(あさ)になると明(あか)るくなります。", "sentence_source": "generated"}, {"text": "左を見ると、大きな木が立っていました。", "target_word": "左", "complexity_tier": "T3", "furigana": "左(ひだり)を見(み)ると、大(おお)きな木(き)が立(た)っていました。", "sentence_source": "generated"}, {"text": "彼は左の端の席にすわっています。", "target_word": "左", "complexity_tier": "T3", "furigana": "彼(かれ)は左(ひだり)の端(はし)の席(せき)にすわっています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "左", "label": "基本形"}], "register": "中立", "sense_fingerprint": "右の反対側の方向・位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "左", "is_correct": true, "explanation": "「右」の反対の方向を表す語。「右ではなく左の道」と対比が成り立つので正解。"}, {"text": "手", "is_correct": false, "explanation": "「手の道」は道の方向を表せず、「右」との対比も成り立たない。"}, {"text": "足", "is_correct": false, "explanation": "「足の道」は意味をなさず、方向の対比にならない。"}, {"text": "頭", "is_correct": false, "explanation": "「頭の道」は不自然で、「右ではなく」と対になる方向を表さない。"}], "explanations": {"左": "「右」の反対の方向を表す語。「右ではなく左の道」と対比が成り立つので正解。", "手": "「手の道」は道の方向を表せず、「右」との対比も成り立たない。", "足": "「足の道」は意味をなさず、方向の対比にならない。", "頭": "「頭の道」は不自然で、「右ではなく」と対になる方向を表さない。"}, "sentence_index": 0, "correct_answer": "左"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅は右ではなく、左右にあります。", "explanation": "「左右」は左と右の両方、またはおおよそを表す語。「右ではなく」と一方の側を示す文では、方向の「左」の意味に合わない。"}, {"text": "信号を過ぎたら、左右に曲がります。", "explanation": "「左右に曲がる」は両方向に曲がる意味になる。信号を過ぎて一方へ曲がる場面では、方向の「左」を使って「左に曲がります」と言う必要がある。"}, {"text": "私は左右の手でボールを投げます。", "explanation": "「左右の手」は両手を指す語。片手でボールを投げる文では、片側を示す「左」の意味で使う必要がある。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "左", "is_correct": true, "explanation": "「右の靴」と対になる「左の靴」を指す。対比が成り立つ正解。"}, {"text": "手袋", "is_correct": false, "explanation": "「手袋の靴」は意味をなさない。「右の靴」と対になるのは靴なので合わない。"}, {"text": "帽子", "is_correct": false, "explanation": "「帽子の靴」は不自然で、靴の左右を表せない。"}, {"text": "傘", "is_correct": false, "explanation": "「傘の靴」は成り立たず、「右の靴」との対比にならない。"}], "explanations": {"左": "「右の靴」と対になる「左の靴」を指す。対比が成り立つ正解。", "手袋": "「手袋の靴」は意味をなさない。「右の靴」と対になるのは靴なので合わない。", "帽子": "「帽子の靴」は不自然で、靴の左右を表せない。", "傘": "「傘の靴」は成り立たず、「右の靴」との対比にならない。"}, "sentence_index": 6, "correct_answer": "左"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は左右の端の席にすわっています。", "explanation": "「左右」は両方を指す語で、片方の端の席を示す文には合わない。一方の端を示す方向の「左」の意味で使う必要がある。"}, {"text": "彼は左寄りの意見に賛成しました。", "explanation": "「左寄り」は政治的立場の〈左翼〉の意味。体や位置の「左」とは違うので、この文脈には合わない。"}, {"text": "彼は左右の端の席で、左の端の席にすわっています。", "explanation": "同じ席を「左右」と「左」で二重に示しており、方向の「左」が指す位置と合わない。「左の端の席」だけで位置を示す必要がある。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "次の角を左を曲がってください。", "corrected_sentence": "次の角を左に曲がってください。", "error_description": "「曲がる」の方向を示す「左」には「に」を付ける。「左を曲がる」は誤りで、正しくは「左に曲がる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨の日に、左に靴をなくしました。", "corrected_sentence": "雨の日に、左の靴をなくしました。", "error_description": "「左」が名詞「靴」を修飾するには「の」が必要。「左に靴」は誤りで、正しくは「左の靴」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39745, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「左の腕」と名詞をつなぐ働きをする。正解。"}, {"text": "が", "is_correct": false, "explanation": "「私の左が腕に」となり、「左」が主語になって文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「左で腕に注射」は手段や場所の意味になり、体の部位を修飾できない。"}, {"text": "と", "is_correct": false, "explanation": "「左と腕」は並列を表し、一つの部位を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「左の腕」と名詞をつなぐ働きをする。正解。", "が": "「私の左が腕に」となり、「左」が主語になって文が崩れる。", "で": "「左で腕に注射」は手段や場所の意味になり、体の部位を修飾できない。", "と": "「左と腕」は並列を表し、一つの部位を修飾する形にならない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39745, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「左のほお」と名詞をつなぎ、体の部位を修飾する。正解。"}, {"text": "が", "is_correct": false, "explanation": "「左がほおが」となり、「左」が主語になって文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「左でほおが」は手段や場所の意味になり、部位を修飾できない。"}, {"text": "を", "is_correct": false, "explanation": "「左をほお」は目的語の形にならず、ほおを修飾する文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「左のほお」と名詞をつなぎ、体の部位を修飾する。正解。", "が": "「左がほおが」となり、「左」が主語になって文が崩れる。", "で": "「左でほおが」は手段や場所の意味になり、部位を修飾できない。", "を": "「左をほお」は目的語の形にならず、ほおを修飾する文として成り立たない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39745, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "「左」は、人の体で心臓（しんぞう）がある方の側を指す言葉です。", "primary_collocate": null, "pronunciation": "ひだり", "ipa": "çidaɾi", "syllable_count": 3, "sentences": [{"text": "転んで、左の足をけがしました。", "target_word": "左", "complexity_tier": "T3", "furigana": "転(ころ)んで、左(ひだり)の足(あし)をけがしました。", "sentence_source": "generated"}, {"text": "医者は、私の左の腕に注射をしました。", "target_word": "左", "complexity_tier": "T3", "furigana": "医者(いしゃ)は、私(わたし)の左(ひだり)の腕(うで)に注射(ちゅうしゃ)をしました。", "sentence_source": "generated"}, {"text": "左の耳が痛くて、病院へ行きました。", "target_word": "左", "complexity_tier": "T3", "furigana": "左(ひだり)の耳(みみ)が痛(いた)くて、病院(びょういん)へ行(い)きました。", "sentence_source": "generated"}, {"text": "彼女は左の手に指輪をしています。", "target_word": "左", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は左(ひだり)の手(て)に指輪(ゆびわ)をしています。", "sentence_source": "generated"}, {"text": "私は左の目が悪いので、めがねをかけています。", "target_word": "左", "complexity_tier": "T3", "furigana": "私(わたし)は左(ひだり)の目(め)が悪(わる)いので、めがねをかけています。", "sentence_source": "generated"}, {"text": "立ち上がるとき、左のひざが少し痛みました。", "target_word": "左", "complexity_tier": "T3", "furigana": "立(た)ち上(あ)がるとき、左(ひだり)のひざが少(すこ)し痛(いた)みました。", "sentence_source": "generated"}, {"text": "左の肩にかばんをかけて歩きます。", "target_word": "左", "complexity_tier": "T3", "furigana": "左(ひだり)の肩(かた)にかばんをかけて歩(ある)きます。", "sentence_source": "generated"}, {"text": "ボールが当たって、左のほおが赤くなりました。", "target_word": "左", "complexity_tier": "T3", "furigana": "ボールが当(あ)たって、左(ひだり)のほおが赤(あか)くなりました。", "sentence_source": "generated"}, {"text": "左の手首に時計をつける人が多いです。", "target_word": "左", "complexity_tier": "T3", "furigana": "左(ひだり)の手首(てくび)に時計(とけい)をつける人(ひと)が多(おお)いです。", "sentence_source": "generated"}, {"text": "彼は左の足から先に階段をのぼりました。", "target_word": "左", "complexity_tier": "T3", "furigana": "彼(かれ)は左(ひだり)の足(あし)から先(さき)に階段(かいだん)をのぼりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "左", "label": "基本形"}], "register": "中立", "sense_fingerprint": "人の体の左側（左の足・腕・目など）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: けがし (Zipf 2.18)']::text[], '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39745, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "左", "is_correct": true, "explanation": "体の左側の足を指す。「左の足」という形で正しい。"}, {"text": "手", "is_correct": false, "explanation": "「手の足」は体の部位として成り立たない。"}, {"text": "目", "is_correct": false, "explanation": "「目の足」は不自然で、足を表せない。"}, {"text": "頭", "is_correct": false, "explanation": "「頭の足」は成り立たず、けがの対象にならない。"}], "explanations": {"左": "体の左側の足を指す。「左の足」という形で正しい。", "手": "「手の足」は体の部位として成り立たない。", "目": "「目の足」は不自然で、足を表せない。", "頭": "「頭の足」は成り立たず、けがの対象にならない。"}, "sentence_index": 0, "correct_answer": "左"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は左の心臓に指輪をしています。", "explanation": "心臓は体の中央にある器官で、左右のどちらにも属さない。「左の心臓」とは言わないので、体の左側の部位を指す「左」の意味で使えない。"}, {"text": "彼女は左寄りの考えを持っています。", "explanation": "「左寄り」は政治的立場の〈左翼〉の意味。体の左側を指す「左」とは違うので、この文脈には合わない。"}, {"text": "彼女は左寄りの席に指輪を置いています。", "explanation": "「左寄り」は位置を表す語で、体の左側の部位を指す「左」の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39745, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "左", "is_correct": true, "explanation": "体の左側にある肩を指す。「左の肩」という形で正しい。"}, {"text": "腰", "is_correct": false, "explanation": "「腰の肩」は成り立たず、かばんをかける部位を表せない。"}, {"text": "足", "is_correct": false, "explanation": "「足の肩」は体の部位として成り立たない。"}, {"text": "頭", "is_correct": false, "explanation": "「頭の肩」は不自然で、かばんをかける位置を示せない。"}], "explanations": {"左": "体の左側にある肩を指す。「左の肩」という形で正しい。", "腰": "「腰の肩」は成り立たず、かばんをかける部位を表せない。", "足": "「足の肩」は体の部位として成り立たない。", "頭": "「頭の肩」は不自然で、かばんをかける位置を示せない。"}, "sentence_index": 6, "correct_answer": "左"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は左の心臓から先に階段をのぼりました。", "explanation": "心臓は左右どちらの側にもないので、「左の心臓」は体の左側を示す「左」の意味で使えない。"}, {"text": "彼は左寄りの意見を先に出して、会議をはじめました。", "explanation": "「左寄り」は政治的立場の〈左翼〉の意味。体の左側を指す「左」とは違うので合わない。"}, {"text": "彼は左寄りの列から先に階段をのぼりました。", "explanation": "「左寄り」は位置を表す語で、体の部位を指す「左」の意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39745, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走っていて、左に足をけがしました。", "corrected_sentence": "走っていて、左の足をけがしました。", "error_description": "「左」が名詞「足」を修飾するには「の」が必要。「左に足」は誤りで、正しくは「左の足」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
