INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「右の」で「手首」を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「右が手首をねんざした」では右が主語になり、意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「右を手首」は目的語を示すことになり、名詞の修飾にならない。"}, {"text": "に", "is_correct": false, "explanation": "「右に手首」は位置を示すことになり、名詞の修飾にならない。"}], "correct_answer": "の", "explanations": {"の": "「右の」で「手首」を修飾する。", "が": "「右が手首をねんざした」では右が主語になり、意味が通らない。", "を": "「右を手首」は目的語を示すことになり、名詞の修飾にならない。", "に": "「右に手首」は位置を示すことになり、名詞の修飾にならない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「右の」で「目」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「右を目」は目的語になり、名詞の修飾にならない。"}, {"text": "に", "is_correct": false, "explanation": "「右に目」は位置を示すことになり、名詞の修飾にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「右で目」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「右の」で「目」を修飾する。", "を": "「右を目」は目的語になり、名詞の修飾にならない。", "に": "「右に目」は位置を示すことになり、名詞の修飾にならない。", "で": "「で」は手段や場所を示すので、「右で目」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "右は、体の向きのうち、左手がある側と反対の側のことです。", "primary_collocate": null, "pronunciation": "みぎ", "ipa": "migi", "syllable_count": 2, "sentences": [{"text": "右の足が痛いので、病院へ行きました。", "target_word": "右", "complexity_tier": "T2", "furigana": "右[みぎ]の足[あし]が痛[いた]いので、病院[びょういん]へ行[い]きました。", "sentence_source": "generated"}, {"text": "右の手首をねんざしたので、字を書くのが大変です。", "target_word": "右", "complexity_tier": "T3", "furigana": "右[みぎ]の手首をねんざしたので、字を書くのが大変です。", "sentence_source": "generated"}, {"text": "右のひじを打ってしまい、しばらく痛かったです。", "target_word": "右", "complexity_tier": "T3", "furigana": "右[みぎ]のひじを打ってしまい、しばらく痛かったです。", "sentence_source": "generated"}, {"text": "彼は左より右のほうが力が強い。", "target_word": "右", "complexity_tier": "T3", "furigana": "彼[かれ]は左[ひだり]より右[みぎ]のほうが力[ちから]が強[つよ]い。", "sentence_source": "generated"}, {"text": "右の耳が聞こえにくいので、大きな声で話してください。", "target_word": "右", "complexity_tier": "T3", "furigana": "右[みぎ]の耳が聞こえにくいので、大きな声で話してください。", "sentence_source": "generated"}, {"text": "左を見たあと、もう一度右を見てから道をわたりましょう。", "target_word": "右", "complexity_tier": "T3", "furigana": "左[ひだり]を見[み]たあと、もう一度[いちど]右[みぎ]を見[み]てから道[みち]をわたりましょう。", "sentence_source": "generated"}, {"text": "右の腕にけがをしたので、字は左手で書いています。", "target_word": "右", "complexity_tier": "T3", "furigana": "右[みぎ]の腕にけがをしたので、字は左手で書いています。", "sentence_source": "generated"}, {"text": "右の目だけ視力が悪いので、めがねを作りました。", "target_word": "右", "complexity_tier": "T4", "furigana": "右[みぎ]の目[め]だけ視力[しりょく]が悪[わる]いので、めがねを作[つく]りました。", "sentence_source": "generated"}, {"text": "彼女は私の右に座って、静かに本を読んでいた。", "target_word": "右", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は私[わたし]の右[みぎ]に座[すわ]って、静[しず]かに本[ほん]を読[よ]んでいた。", "sentence_source": "generated"}, {"text": "右の肩をけがしたため、重い荷物は持てません。", "target_word": "右", "complexity_tier": "T4", "furigana": "右[みぎ]の肩[かた]をけがしたため、重[おも]い荷物[にもつ]は持[も]てません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "右", "label": "基本形"}], "register": "中立", "sense_fingerprint": "体の左手と反対の側。体の向きで示す側としての右。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: ねんざ (Zipf 1.93)','sentence 9 above tier T2: contains vocabulary far above tier T2: けがし (Zipf 2.18)']::text[], '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "「＿の足が痛い」に入り、体の右側を指す。"}, {"text": "上", "is_correct": false, "explanation": "「上の足」は体の側を表せず、文として不自然。"}, {"text": "中", "is_correct": false, "explanation": "「中の足」は体の左右を表せず、意味が通らない。"}, {"text": "外", "is_correct": false, "explanation": "「外の足」は体の右左を示せず、不自然。"}], "explanations": {"右": "「＿の足が痛い」に入り、体の右側を指す。", "上": "「上の足」は体の側を表せず、文として不自然。", "中": "「中の足」は体の左右を表せず、意味が通らない。", "外": "「外の足」は体の右左を示せず、不自然。"}, "sentence_index": 0, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その運動は右の立場から始まりました。", "explanation": "ここは〈右翼〉（政治的立場）の意味。体の右側を指す右とは別の意味なので、この文脈には合わない。"}, {"text": "その答えは右です。", "explanation": "ここは〈正しい〉の意味。右は体や方向の右側を指し、正しさは表さない。"}, {"text": "彼女の歌声は右に出る人がいないほど美しい。", "explanation": "ここは〈優れている〉の意味（慣用句）。体の右側を指す右とは違うので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "「＿の腕にけがをした」に入り、体の右側の腕を指す。"}, {"text": "下", "is_correct": false, "explanation": "「下の腕」は体の右左を示せず、不自然。"}, {"text": "奥", "is_correct": false, "explanation": "「奥の腕」は体の部位の説明にならず、意味が通らない。"}, {"text": "横", "is_correct": false, "explanation": "「横の腕」は体の右左を示さず、文として不自然。"}], "explanations": {"右": "「＿の腕にけがをした」に入り、体の右側の腕を指す。", "下": "「下の腕」は体の右左を示せず、不自然。", "奥": "「奥の腕」は体の部位の説明にならず、意味が通らない。", "横": "「横の腕」は体の右左を示さず、文として不自然。"}, "sentence_index": 6, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は右寄りの団体に入りました。", "explanation": "ここは〈右翼〉（政治的立場）の意味。体の右側を指す右とは別の用法で、この文脈には合わない。"}, {"text": "売り上げは右肩上がりに伸びています。", "explanation": "ここは〈上向き〉（数値が伸びる）の意味。体の右側を指す右とは違うので、この文脈には合わない。"}, {"text": "その提案には右に同じです。", "explanation": "ここは〈同上〉（前と同じという意味）の意味。体の右側を指す右とは違うので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "右に腕をけがしたので、字は左手で書いています。", "corrected_sentence": "右の腕をけがしたので、字は左手で書いています。", "error_description": "「右の腕」のように名詞を修飾するには「の」を使う。「右に腕」は誤りで、正しくは「右の腕」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39746, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "右へ肩を痛めたため、重い荷物は持てません。", "corrected_sentence": "右の肩を痛めたため、重い荷物は持てません。", "error_description": "「右」は後ろの「肩」を修飾するので「の」で続ける。「へ」は方向を示す助詞なので誤りで、正しくは「右の肩を痛めたため」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「右の方向」のように、「右の」で「方向」を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「右を方向」は目的語になり、名詞の修飾にならない。"}, {"text": "に", "is_correct": false, "explanation": "「右に方向」は位置を示すことになり、名詞の修飾にならない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「右で方向」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「右の方向」のように、「右の」で「方向」を修飾する。", "を": "「右を方向」は目的語になり、名詞の修飾にならない。", "に": "「右に方向」は位置を示すことになり、名詞の修飾にならない。", "で": "「で」は手段や場所を示すので、「右で方向」は意味が通らない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「右を行く」のように、移動の経路を「を」で示す。"}, {"text": "が", "is_correct": false, "explanation": "「右が行きましょう」では右が主語になり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すので、「右で行きましょう」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「右と行きましょう」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「右を行く」のように、移動の経路を「を」で示す。", "が": "「右が行きましょう」では右が主語になり、意味が通らない。", "で": "「で」は手段や場所を示すので、「右で行きましょう」は不自然。", "と": "「と」は並列や共同を示すので、「右と行きましょう」は意味が通らない。"}, "error_tags": {"が": "主語", "で": "場所・手段", "と": "共同・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "右とは、方向の一つで、東を向いた時に南にあたる側、または体の中心から見て、心臓がある側と反対の側を指します。", "primary_collocate": null, "pronunciation": "みぎ", "ipa": "migi", "syllable_count": 2, "sentences": [{"text": "駅を出たら、右に曲がってください。", "target_word": "右", "complexity_tier": "T2", "furigana": "駅[えき]を出[で]たら、右[みぎ]に曲[ま]がってください。", "sentence_source": "generated"}, {"text": "東を向くと、南は右の方向になります。", "target_word": "右", "complexity_tier": "T3", "furigana": "東[ひがし]を向[む]くと、南[みなみ]は右[みぎ]の方向[ほうこう]になります。", "sentence_source": "generated"}, {"text": "地図の右が東、左が西です。", "target_word": "右", "complexity_tier": "T3", "furigana": "地図[ちず]の右[みぎ]が東[ひがし]、左[ひだり]が西[にし]です。", "sentence_source": "generated"}, {"text": "心臓は体の中心から見て左にあり、肝臓は右にあります。", "target_word": "右", "complexity_tier": "T4", "furigana": "心臓[しんぞう]は体[からだ]の中心[ちゅうしん]から見[み]て左[ひだり]にあり、肝臓[かんぞう]は右[みぎ]にあります。", "sentence_source": "generated"}, {"text": "信号を右に曲がると、銀行が見えます。", "target_word": "右", "complexity_tier": "T3", "furigana": "信号[しんごう]を右[みぎ]に曲[ま]がると、銀行[ぎんこう]が見[み]えます。", "sentence_source": "generated"}, {"text": "右と左をまちがえて、反対の道に入ってしまった。", "target_word": "右", "complexity_tier": "T3", "furigana": "右[みぎ]と左[ひだり]をまちがえて、反対[はんたい]の道[みち]に入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "右から二番目の人が、新しい先生です。", "target_word": "右", "complexity_tier": "T3", "furigana": "右[みぎ]から二番目[にばんめ]の人[ひと]が、新[あたら]しい先生[せんせい]です。", "sentence_source": "generated"}, {"text": "左の道は行き止まりなので、右を行きましょう。", "target_word": "右", "complexity_tier": "T3", "furigana": "左[ひだり]の道[みち]は行[い]き止[ど]まりなので、右[みぎ]を行[い]きましょう。", "sentence_source": "generated"}, {"text": "右にハンドルを切って、ぶつかりそうな自転車をよけた。", "target_word": "右", "complexity_tier": "T4", "furigana": "右[みぎ]にハンドルを切[き]って、ぶつかりそうな自転車[じてんしゃ]をよけた。", "sentence_source": "generated"}, {"text": "右の方から大きな音が聞こえて、みんなが顔を向けた。", "target_word": "右", "complexity_tier": "T4", "furigana": "右[みぎ]の方[ほう]から大[おお]きな音[おと]が聞[き]こえて、みんなが顔[かお]を向[む]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "右", "label": "基本形"}], "register": "中立", "sense_fingerprint": "方向の一つとしての右。東を向いた時の南の側、心臓と反対の側。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5686e876-7255-4fbc-ab07-59fa143cf3df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "「駅を出たら、＿に曲がってください」に入り、方向を示す。"}, {"text": "直進", "is_correct": false, "explanation": "「直進に曲がる」は意味が通らず、不自然。"}, {"text": "橋", "is_correct": false, "explanation": "「橋に曲がる」は方向の表現として成り立たない。"}, {"text": "窓", "is_correct": false, "explanation": "「窓に曲がる」は道の方向を示せず、意味が通らない。"}], "explanations": {"右": "「駅を出たら、＿に曲がってください」に入り、方向を示す。", "直進": "「直進に曲がる」は意味が通らず、不自然。", "橋": "「橋に曲がる」は方向の表現として成り立たない。", "窓": "「窓に曲がる」は道の方向を示せず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の絵の腕前は右に出る者がいません。", "explanation": "ここは〈優れている〉の意味（慣用句）。方向の〈右〉とは違うので、この文脈には合わない。"}, {"text": "彼は右の政党に入りました。", "explanation": "ここは〈右翼〉（政治的立場）の意味。方向の〈右〉とは違うので、この文脈には合わない。"}, {"text": "その答えは右です。", "explanation": "ここは〈正しい〉の意味。方向の〈右〉は、正しさを表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "「＿から二番目の人」に入り、方向を示す。"}, {"text": "紙", "is_correct": false, "explanation": "「紙から二番目の人」は意味をなさず、並びの方向を示せない。"}, {"text": "中", "is_correct": false, "explanation": "「中から二番目」は並びの方向を示せず、意味が通らない。"}, {"text": "裏", "is_correct": false, "explanation": "「裏から二番目」は並びの方向を示せず、不自然。"}], "explanations": {"右": "「＿から二番目の人」に入り、方向を示す。", "紙": "「紙から二番目の人」は意味をなさず、並びの方向を示せない。", "中": "「中から二番目」は並びの方向を示せず、意味が通らない。", "裏": "「裏から二番目」は並びの方向を示せず、不自然。"}, "sentence_index": 6, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その問題の答えは右だと、みんなが言いました。", "explanation": "ここは〈正しい〉の意味。方向の〈右〉は、正しさを表さないので合わない。"}, {"text": "この道は右の政党が支える街です。", "explanation": "ここは〈右翼〉（政治的立場）の意味。方向の〈右〉とは違うので、この文脈には合わない。"}, {"text": "右利きの彼は、ペンを右手で持ちます。", "explanation": "ここは〈利き手〉（体の右手）の意味。方向の〈右〉とは違うので、この文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "港を出たら、右で曲がってください。", "corrected_sentence": "港を出たら、右に曲がってください。", "error_description": "「曲がる」の方向は「に」で示す。「で」は手段や場所を示すので誤りで、正しくは「右に曲がってください」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "向こうは行き止まりなので、右を曲がってください。", "corrected_sentence": "向こうは行き止まりなので、右に曲がってください。", "error_description": "「曲がる」の方向は「に」で示す。「を」は誤りで、正しくは「右に曲がってください」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f43d567-7d3b-4b06-8741-a64ccdb9a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
