INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39748, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「取り方」を教え込む対象を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。対象を示す位置には合わない。"}, {"text": "に", "is_correct": false, "explanation": "相手を示す助詞。「取り方に教え込む」とは言えない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞。この文では対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「取り方」を教え込む対象を示す格助詞。", "へ": "方向の助詞。対象を示す位置には合わない。", "に": "相手を示す助詞。「取り方に教え込む」とは言えない。", "より": "比較の助詞。この文では対象を示せない。"}, "error_tags": {"へ": "方向", "に": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39748, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "教え込むとは、人がわかるように、何度も何度も言ったり練習させたりすることです。", "primary_collocate": null, "pronunciation": "おしえこむ", "ipa": "oɕiekomɯ", "syllable_count": 5, "sentences": [{"text": "先生は生徒に、あいさつの仕方を何度も教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、あいさつの仕方[しかた]を何度[なんど]も教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "父は私に、時間を守ることを小さいころから教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "父[ちち]は私[わたし]に、時間[じかん]を守[まも]ることを小[ちい]さいころから教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "新しい店員には、お客さんへの話し方を教え込みます。", "target_word": "教え込みます", "complexity_tier": "T3", "furigana": "新[あたら]しい店員[てんいん]には、お客[きゃく]さんへの話[はな]し方[かた]を教[おし]え込[こ]みます。", "sentence_source": "generated"}, {"text": "犬に「お座り」を教え込むのに、一か月かかりました。", "target_word": "教え込む", "complexity_tier": "T3", "furigana": "犬[いぬ]に「お座[すわ]り」を教[おし]え込[こ]むのに、一[いっ]か月[げつ]かかりました。", "sentence_source": "generated"}, {"text": "母は子どもに、食事の前に手を洗う習慣を教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "母[はは]は子[こ]どもに、食事[しょくじ]の前[まえ]に手[て]を洗[あら]う習慣[しゅうかん]を教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "コーチは選手に基本の動きを毎日教え込んでいます。", "target_word": "教え込んでいます", "complexity_tier": "T3", "furigana": "コーチは選手[せんしゅ]に基本[きほん]の動[うご]きを毎日[まいにち]教[おし]え込[こ]んでいます。", "sentence_source": "generated"}, {"text": "祖母は孫に、昔の歌を一つずつ教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "祖母[そぼ]は孫[まご]に、昔[むかし]の歌[うた]を一[ひと]つずつ教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "先輩が電話の取り方を教え込んでくれたので、すぐ慣れました。", "target_word": "教え込んで", "complexity_tier": "T3", "furigana": "先輩[せんぱい]が電話[でんわ]の取[と]り方[かた]を教[おし]え込[こ]んでくれたので、すぐ慣[な]れました。", "sentence_source": "generated"}, {"text": "姉は弟に、自転車の乗り方を何日もかけて教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "姉[あね]は弟[おとうと]に、自転車[じてんしゃ]の乗[の]り方[かた]を何日[なんにち]もかけて教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "会社では、新入社員にルールを教え込む時間が必要です。", "target_word": "教え込む", "complexity_tier": "T3", "furigana": "会社[かいしゃ]では、新入社員[しんにゅうしゃいん]にルールを教[おし]え込[こ]む時間[じかん]が必要[ひつよう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教え込む", "label": "辞書形"}, {"form": "教え込みます", "label": "丁寧形"}, {"form": "教え込んで", "label": "て形"}, {"form": "教え込んだ", "label": "た形"}, {"form": "教え込まない", "label": "ない形"}, {"form": "教え込まれる", "label": "受身形"}], "register": "中立（丁寧体）", "sense_fingerprint": "相手がわかるまで、何度も言ったり練習させたりして教える", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39748, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教え込みました", "is_correct": true, "explanation": "「何度も」と合う、繰り返し教える意味の正しい形。"}, {"text": "思い込みました", "is_correct": false, "explanation": "強く信じる意味で、教える行為には合わない。"}, {"text": "植え込みました", "is_correct": false, "explanation": "植物を植える意味で、人への指導には合わない。"}, {"text": "書き込みました", "is_correct": false, "explanation": "文字を書き加える意味で、「あいさつの仕方」を生徒に伝える文とは合わない。"}], "explanations": {"教え込みました": "「何度も」と合う、繰り返し教える意味の正しい形。", "思い込みました": "強く信じる意味で、教える行為には合わない。", "植え込みました": "植物を植える意味で、人への指導には合わない。", "書き込みました": "文字を書き加える意味で、「あいさつの仕方」を生徒に伝える文とは合わない。"}, "sentence_index": 0, "correct_answer": "教え込みました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は生徒に、あいさつを一度だけ教え込みました。", "explanation": "ここは〈教える〉の意味。〈教え込む〉は何度も繰り返す指導を表すので、「一度だけ」とは合わない。"}, {"text": "先生は手帳に、あいさつの予定を教え込みました。", "explanation": "ここは〈書き込む〉の意味。〈教え込む〉は人を相手にするので、手帳には使えない。"}, {"text": "先生は生徒の机を何度も教え込みました。", "explanation": "ここは〈磨く〉の意味。〈教え込む〉は人を相手にする指導の語で、机の手入れには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39748, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教え込みました", "is_correct": true, "explanation": "「一つずつ」と合う、繰り返し教える意味の正しい形。"}, {"text": "差し込みました", "is_correct": false, "explanation": "中に入れる意味で、歌を教える文には合わない。"}, {"text": "組み込みました", "is_correct": false, "explanation": "部品として取り入れる意味で、人への指導には合わない。"}, {"text": "踏み込みました", "is_correct": false, "explanation": "足を踏み入れる意味で、教える行為には合わない。"}], "explanations": {"教え込みました": "「一つずつ」と合う、繰り返し教える意味の正しい形。", "差し込みました": "中に入れる意味で、歌を教える文には合わない。", "組み込みました": "部品として取り入れる意味で、人への指導には合わない。", "踏み込みました": "足を踏み入れる意味で、教える行為には合わない。"}, "sentence_index": 6, "correct_answer": "教え込みました"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社の車に、ルールを教え込む時間が必要です。", "explanation": "ここは〈積み込む〉の意味。〈教え込む〉は人を相手にする語で、車には使えない。"}, {"text": "会社では、新入社員の写真を教え込む時間が必要です。", "explanation": "ここは〈撮る〉の意味。〈教え込む〉は知識や技術を相手にする語なので、写真を撮る行為には使えない。"}, {"text": "会社では、書類にルールを教え込む時間が必要です。", "explanation": "ここは〈書き込む〉の意味。〈教え込む〉は人を相手にするので、書類には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39748, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は弟に、食事の前に手を洗う習慣に教え込みました。", "corrected_sentence": "母は弟に、食事の前に手を洗う習慣を教え込みました。", "error_description": "格助詞の誤り。「教え込む」の対象には「を」が必要で、「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "教え込みました", "is_correct": true, "explanation": "丁寧な過去形。文中の形と一致する。"}, {"text": "教え込む", "is_correct": false, "explanation": "辞書形。丁寧な過去の文では使えない。"}, {"text": "教え込んで", "is_correct": false, "explanation": "て形。文末の丁寧な過去には合わない。"}, {"text": "教え込まない", "is_correct": false, "explanation": "否定形。教えた事実を述べる文と逆になる。"}], "correct_form": "教え込みました", "base_form": "教え込む", "form_label": "丁寧形（過去）", "sentence_index": 1, "explanations": {"教え込みました": "丁寧な過去形。文中の形と一致する。", "教え込む": "辞書形。丁寧な過去の文では使えない。", "教え込んで": "て形。文末の丁寧な過去には合わない。", "教え込まない": "否定形。教えた事実を述べる文と逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39748, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先輩が電話の取り方を教え込むでくれたので、すぐに慣れました。", "corrected_sentence": "先輩が電話の取り方を教え込んでくれたので、すぐに慣れました。", "error_description": "活用の誤り。「教え込んで」の「ん」が「む」になっており、て形が正しくない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "教え込んで", "is_correct": true, "explanation": "て形。「くれた」につながる形で、文中の形と一致する。"}, {"text": "教え込んだ", "is_correct": false, "explanation": "た形。「くれた」の前の接続には合わない。"}, {"text": "教え込まれる", "is_correct": false, "explanation": "受身形。教える側が主語の文では使えない。"}, {"text": "教え込みます", "is_correct": false, "explanation": "丁寧形。「くれたので」の前には入らない。"}], "correct_form": "教え込んで", "base_form": "教え込む", "form_label": "て形", "sentence_index": 7, "explanations": {"教え込んで": "て形。「くれた」につながる形で、文中の形と一致する。", "教え込んだ": "た形。「くれた」の前の接続には合わない。", "教え込まれる": "受身形。教える側が主語の文では使えない。", "教え込みます": "丁寧形。「くれたので」の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「礼儀作法」を教え込む対象を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向の助詞。対象を示す位置には合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の助詞。対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体の助詞。「礼儀作法の厳しく教え込む」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「礼儀作法」を教え込む対象を示す格助詞。", "へ": "方向の助詞。対象を示す位置には合わない。", "より": "比較の助詞。対象を示せない。", "の": "連体の助詞。「礼儀作法の厳しく教え込む」は不自然。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体（所属）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "教え込む（おしえこむ）は、知識や技術を何度も繰り返し教えて、完全に覚えさせることを意味します。", "primary_collocate": null, "pronunciation": "おしえこむ", "ipa": "oɕiekomɯ", "syllable_count": 5, "sentences": [{"text": "師匠は弟子に、料理の技を何年もかけて教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "師匠[ししょう]は弟子[でし]に、料理[りょうり]の技[わざ]を何年[なんねん]もかけて教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "この塾では、英語の文法を徹底的に教え込みます。", "target_word": "教え込みます", "complexity_tier": "T3", "furigana": "この塾[じゅく]では、英語[えいご]の文法[ぶんぽう]を徹底的[てっていてき]に教[おし]え込[こ]みます。", "sentence_source": "generated"}, {"text": "彼は後輩に、仕事の手順を完全に覚えるまで教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "彼[かれ]は後輩[こうはい]に、仕事[しごと]の手順[てじゅん]を完全[かんぜん]に覚[おぼ]えるまで教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "監督は選手に作戦を体で覚えるまで教え込んでいます。", "target_word": "教え込んでいます", "complexity_tier": "T3", "furigana": "監督[かんとく]は選手[せんしゅ]に作戦[さくせん]を体[からだ]で覚[おぼ]えるまで教[おし]え込[こ]んでいます。", "sentence_source": "generated"}, {"text": "母に漢字を教え込まれたおかげで、書き取りは得意です。", "target_word": "教え込まれた", "complexity_tier": "T3", "furigana": "母[はは]に漢字[かんじ]を教[おし]え込[こ]まれたおかげで、書[か]き取[と]りは得意[とくい]です。", "sentence_source": "generated"}, {"text": "職人は若い人に、木を削る技術を教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "職人[しょくにん]は若[わか]い人[ひと]に、木[き]を削[けず]る技術[ぎじゅつ]を教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "先生は計算の方法を繰り返し教え込んだので、全員が覚えました。", "target_word": "教え込んだ", "complexity_tier": "T3", "furigana": "先生[せんせい]は計算[けいさん]の方法[ほうほう]を繰[く]り返[かえ]し教[おし]え込[こ]んだので、全員[ぜんいん]が覚[おぼ]えました。", "sentence_source": "generated"}, {"text": "礼儀作法を厳しく教え込む学校もあります。", "target_word": "教え込む", "complexity_tier": "T3", "furigana": "礼儀作法[れいぎさほう]を厳[きび]しく教[おし]え込[こ]む学校[がっこう]もあります。", "sentence_source": "generated"}, {"text": "祖父は私に、将棋の基本を一つずつ教え込みました。", "target_word": "教え込みました", "complexity_tier": "T3", "furigana": "祖父[そふ]は私[わたし]に、将棋[しょうぎ]の基本[きほん]を一[ひと]つずつ教[おし]え込[こ]みました。", "sentence_source": "generated"}, {"text": "ピアノの先生が指の動かし方を教え込んでくれました。", "target_word": "教え込んで", "complexity_tier": "T3", "furigana": "ピアノの先生[せんせい]が指[ゆび]の動[うご]かし方[かた]を教[おし]え込[こ]んでくれました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "教え込む", "label": "辞書形"}, {"form": "教え込みます", "label": "丁寧形"}, {"form": "教え込んで", "label": "て形"}, {"form": "教え込んだ", "label": "た形"}, {"form": "教え込まない", "label": "ない形"}, {"form": "教え込まれる", "label": "受身形"}], "register": "中立（丁寧体）", "sense_fingerprint": "知識や技術を繰り返し教えて、完全に身につけさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '438a3813-d323-450c-8344-633dda48e388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教え込みました", "is_correct": true, "explanation": "「何年もかけて」と合う、繰り返し教える意味の正しい形。"}, {"text": "思い込みました", "is_correct": false, "explanation": "強く信じる意味で、教える行為には合わない。"}, {"text": "植え込みました", "is_correct": false, "explanation": "植物を植える意味で、技の指導には合わない。"}, {"text": "書き込みました", "is_correct": false, "explanation": "文字を書き加える意味で、料理の技とは合わない。"}], "explanations": {"教え込みました": "「何年もかけて」と合う、繰り返し教える意味の正しい形。", "思い込みました": "強く信じる意味で、教える行為には合わない。", "植え込みました": "植物を植える意味で、技の指導には合わない。", "書き込みました": "文字を書き加える意味で、料理の技とは合わない。"}, "sentence_index": 0, "correct_answer": "教え込みました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "コーチは選手に、作戦を一度話しただけで教え込みました。", "explanation": "ここは〈伝える〉の意味。〈教え込む〉は繰り返して身につけさせる指導なので、一度話しただけの場面には合わない。"}, {"text": "この机は生徒に英語を教え込みます。", "explanation": "ここは〈教える〉の意味。〈教え込む〉は人が人に行う指導の語で、机を教える主体にはできない。"}, {"text": "作戦を選手のノートに教え込んでいます。", "explanation": "ここは〈書き込む〉の意味。〈教え込む〉は人を相手にするので、ノートには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教え込んだ", "is_correct": true, "explanation": "「繰り返し」と合う、た形の正しい形。"}, {"text": "差し込んだ", "is_correct": false, "explanation": "中に入れる意味で、計算の方法を教える文には合わない。"}, {"text": "組み込んだ", "is_correct": false, "explanation": "部品として取り入れる意味で、人への指導には合わない。"}, {"text": "踏み込んだ", "is_correct": false, "explanation": "足を踏み入れる意味で、教える行為には合わない。"}], "explanations": {"教え込んだ": "「繰り返し」と合う、た形の正しい形。", "差し込んだ": "中に入れる意味で、計算の方法を教える文には合わない。", "組み込んだ": "部品として取り入れる意味で、人への指導には合わない。", "踏み込んだ": "足を踏み入れる意味で、教える行為には合わない。"}, "sentence_index": 6, "correct_answer": "教え込んだ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアノの音色が部屋に教え込んでいます。", "explanation": "ここは〈しみ込む〉の意味。〈教え込む〉は人を相手にする指導の語で、音色が部屋に広がる場面には使えない。"}, {"text": "先生は指の動かし方を、楽譜に教え込みました。", "explanation": "ここは〈書き込む〉の意味。〈教え込む〉は人を相手にするので、楽譜には使えない。"}, {"text": "ピアノの先生が庭に花を教え込んでくれました。", "explanation": "ここは〈植え込む〉の意味。〈教え込む〉は人を相手にする語で、庭の花の植え付けには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "職人は弟子に、木を削る技術へ教え込みました。", "corrected_sentence": "職人は弟子に、木を削る技術を教え込みました。", "error_description": "格助詞の誤り。「教え込む」の対象には「を」が必要で、「へ」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "教え込みます", "is_correct": true, "explanation": "丁寧形。文中の形と一致する。"}, {"text": "教え込む", "is_correct": false, "explanation": "辞書形。丁寧形の文では使えない。"}, {"text": "教え込んで", "is_correct": false, "explanation": "て形。文末の丁寧形には合わない。"}, {"text": "教え込まない", "is_correct": false, "explanation": "否定形。教える事実を述べる文と合わない。"}], "correct_form": "教え込みます", "base_form": "教え込む", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"教え込みます": "丁寧形。文中の形と一致する。", "教え込む": "辞書形。丁寧形の文では使えない。", "教え込んで": "て形。文末の丁寧形には合わない。", "教え込まない": "否定形。教える事実を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39749, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖父は孫に、将棋の基本を一つずつ教え込んました。", "corrected_sentence": "祖父は孫に、将棋の基本を一つずつ教え込みました。", "error_description": "活用の誤り。「教え込みました」の「み」が抜けて「んました」となっており、丁寧な過去形が正しくない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "教え込む", "is_correct": true, "explanation": "辞書形。名詞「学校」を修飾する文の形と一致する。"}, {"text": "教え込もう", "is_correct": false, "explanation": "意向の形。名詞「学校」を修飾する位置には合わない。"}, {"text": "教え込まれる", "is_correct": false, "explanation": "受身形。学校が主体となる文では不自然。"}, {"text": "教え込みません", "is_correct": false, "explanation": "丁寧な否定形。名詞を修飾する位置には合わない。"}], "correct_form": "教え込む", "base_form": "教え込む", "form_label": "辞書形", "sentence_index": 7, "explanations": {"教え込む": "辞書形。名詞「学校」を修飾する文の形と一致する。", "教え込もう": "意向の形。名詞「学校」を修飾する位置には合わない。", "教え込まれる": "受身形。学校が主体となる文では不自然。", "教え込みません": "丁寧な否定形。名詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4fc4c7-4576-4f81-b8d9-c5b617eca30b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39750, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「テストで間違えた」の「で」。間違える場面を示す正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「テストに間違えた」は成り立たない。「間違える」は場面に「で」を取る。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」はここでは意味が通らず、「テストへ間違えた」は不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「テストより間違えた」と続かず、場面を表さない。"}], "correct_answer": "で", "explanations": {"で": "「テストで間違えた」の「で」。間違える場面を示す正しい助詞。", "に": "「テストに間違えた」は成り立たない。「間違える」は場面に「で」を取る。", "へ": "方向を表す「へ」はここでは意味が通らず、「テストへ間違えた」は不自然。", "より": "比較の「より」は「テストより間違えた」と続かず、場面を表さない。"}, "error_tags": {"に": "場所・対象（誤用）", "へ": "方向（誤用）", "より": "比較（誤用）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '866af367-6a96-4546-afd0-a3b1bb8bf9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
